    constexpr uint32_t kWarpSize = 32;
    constexpr uint32_t kWarps = 8;
    const uint32_t lane = threadIdx.x % kWarpSize;
    const uint32_t warp = threadIdx.x / kWarpSize;
#pragma unroll
    for (uint32_t offset = kWarpSize / 2; offset > 0; offset >>= 1) {
        sum0 += __shfl_down_sync(0xffffffffU, sum0, offset);
        sum1 += __shfl_down_sync(0xffffffffU, sum1, offset);
    }
    __shared__ float warp_sums0[kWarps];
    __shared__ float warp_sums1[kWarps];
    if (lane == 0) {
        warp_sums0[warp] = sum0;
        warp_sums1[warp] = sum1;
    }
    __syncthreads();
    if (warp == 0) {
        sum0 = lane < kWarps ? warp_sums0[lane] : 0.0f;
        sum1 = lane < kWarps ? warp_sums1[lane] : 0.0f;
#pragma unroll
        for (uint32_t offset = kWarpSize / 2; offset > 0; offset >>= 1) {
            sum0 += __shfl_down_sync(0xffffffffU, sum0, offset);
            sum1 += __shfl_down_sync(0xffffffffU, sum1, offset);
        }
        if (lane == 0) {
            out0[row] = sum0;
            out1[row] = sum1;
        }
    }
}

__global__ void fp8_outer_scale_kernel(float *out,
                                       const float *unscaled,
                                       const float *activation_scales,
                                       const float *weight_scales,
                                       uint32_t batch,
                                       uint32_t rows,
                                       uint32_t output_stride) {
    const uint64_t index = static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(batch) * rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / rows);
    const uint32_t row = static_cast<uint32_t>(index % rows);
    out[static_cast<uint64_t>(item) * output_stride + row] =
        unscaled[index] * activation_scales[item] * weight_scales[row];
}

__global__ void fp8_outer_scale_add_kernel(float *out,
                                           const float *unscaled,
                                           const float *activation_scales,
                                           const float *weight_scales,
                                           uint32_t batch,
                                           uint32_t rows,
                                           uint32_t output_stride) {
    const uint64_t index = static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(batch) * rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / rows);
    const uint32_t row = static_cast<uint32_t>(index % rows);
    const uint64_t output_index =
        static_cast<uint64_t>(item) * output_stride + row;
    out[output_index] +=
        unscaled[index] * activation_scales[item] * weight_scales[row];
}

template <bool Add>
__global__ void fp8_outer_scale_bf16_kernel(
        __nv_bfloat16 *out,
        const float *unscaled,
        const float *activation_scales,
        const float *weight_scales,
        uint32_t batch,
        uint32_t rows,
        uint32_t output_stride) {
    const uint64_t index =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(batch) * rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / rows);
    const uint32_t row = static_cast<uint32_t>(index % rows);
    const uint64_t output_index =
        static_cast<uint64_t>(item) * output_stride + row;
    float value =
        unscaled[index] * activation_scales[item] * weight_scales[row];
    if constexpr (Add) {
        value += __bfloat162float(out[output_index]);
    }
    out[output_index] = __float2bfloat16_rn(value);
}

__global__ void fp8_outer_scale_fanout4_kernel(
        float *out0,
        float *out1,
        float *out2,
        float *out3,
        const float *unscaled,
        const float *activation_scales,
        const float *weight_scales0,
        const float *weight_scales1,
        const float *weight_scales2,
        const float *weight_scales3,
        uint32_t batch,
        uint32_t rows0,
        uint32_t rows1,
        uint32_t rows2,
        uint32_t rows3,
        uint32_t stride0,
        uint32_t stride1,
        uint32_t stride2,
        uint32_t stride3) {
    const uint64_t index =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count0 = static_cast<uint64_t>(batch) * rows0;
    const uint64_t count1 = static_cast<uint64_t>(batch) * rows1;
    const uint64_t count2 = static_cast<uint64_t>(batch) * rows2;
    const uint64_t count3 = static_cast<uint64_t>(batch) * rows3;
    if (index >= count0 + count1 + count2 + count3) return;

    float *out = out0;
    const float *weight_scales = weight_scales0;
    uint32_t rows = rows0;
    uint32_t stride = stride0;
    uint64_t local = index;
    if (local >= count0) {
        local -= count0;
        out = out1;
        weight_scales = weight_scales1;
        rows = rows1;
        stride = stride1;
        if (local >= count1) {
            local -= count1;
            out = out2;
            weight_scales = weight_scales2;
            rows = rows2;
            stride = stride2;
            if (local >= count2) {
                local -= count2;
                out = out3;
                weight_scales = weight_scales3;
                rows = rows3;
                stride = stride3;
            }
        }
    }

    const uint32_t item = static_cast<uint32_t>(local / rows);
    const uint32_t row = static_cast<uint32_t>(local % rows);
    out[static_cast<uint64_t>(item) * stride + row] =
        unscaled[index] * activation_scales[item] * weight_scales[row];
}

__global__ void fp8_outer_scale_silu_mul_kernel(
        float *gate_inout,
        const float *up_unscaled,
        const float *activation_scales,
        const float *up_weight_scales,
        uint32_t batch,
        uint32_t rows,
        uint32_t output_stride) {
    const uint64_t index = static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(batch) * rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / rows);
    const uint32_t row = static_cast<uint32_t>(index % rows);
    const uint64_t output_index =
        static_cast<uint64_t>(item) * output_stride + row;
    const float gate = gate_inout[output_index];
    const float up =
        up_unscaled[index] * activation_scales[item] * up_weight_scales[row];
    gate_inout[output_index] = (gate / (1.0f + expf(-gate))) * up;
}

__global__ void fp8_outer_scale_pair_silu_mul_kernel(
        float *out,
        const float *pair_unscaled,
        const float *activation_scales,
        const float *gate_weight_scales,
        const float *up_weight_scales,
        uint32_t batch,
        uint32_t rows,
        uint32_t output_stride) {
    const uint64_t index =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(batch) * rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / rows);
    const uint32_t row = static_cast<uint32_t>(index % rows);
    const float activation_scale = activation_scales[item];
    const uint64_t pair_stride = static_cast<uint64_t>(rows) * 2;
    const uint64_t pair_base = static_cast<uint64_t>(item) * pair_stride;
    const float gate =
        pair_unscaled[pair_base + row] *
        activation_scale * gate_weight_scales[row];
    const float up =
        pair_unscaled[pair_base + rows + row] *
        activation_scale * up_weight_scales[row];
    out[static_cast<uint64_t>(item) * output_stride + row] =
        (gate / (1.0f + expf(-gate))) * up;
}

__global__ void fp8_outer_scale_packed_pair_kernel(
        float *out0,
        float *out1,
        const float *pair_unscaled,
        const float *activation_scales,
        const float *weight_scales0,
        const float *weight_scales1,
        uint32_t batch,
        uint32_t rows0,
        uint32_t rows1,
        uint32_t stride0,
        uint32_t stride1) {
    const uint64_t index =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint32_t pair_rows = rows0 + rows1;
    const uint64_t count = static_cast<uint64_t>(batch) * pair_rows;
    if (index >= count) return;
    const uint32_t item = static_cast<uint32_t>(index / pair_rows);
    const uint32_t pair_row = static_cast<uint32_t>(index % pair_rows);
    const float activation_scale = activation_scales[item];
    if (pair_row < rows0) {
        out0[static_cast<uint64_t>(item) * stride0 + pair_row] =
            pair_unscaled[index] *
            activation_scale * weight_scales0[pair_row];
        return;
    }
    const uint32_t row = pair_row - rows0;
    out1[static_cast<uint64_t>(item) * stride1 + row] =
        pair_unscaled[index] *
        activation_scale * weight_scales1[row];
}

// Per-row causal softmax for the cuBLAS-based prefill attention path.
//
// LEGACY — sole caller is the TESTED-NEGATIVE cuBLAS prefill path
// (attention_prefill_cublas, opt-in via QW3_PREFILL_ATTN=cublas). Not used by
// the default FA2 v2 path. Kept intact alongside its caller.
//
// Layout: scores [n_groups, T, T_kv] row-major, FP16, group-major. Each
// (head_in_group, query_row) row holds T_kv scores in [0, base + q + 1) and
// garbage past my_max_kv. The kernel computes max-shift + exp + 1/sum + scale,
// with an in-place causal mask, and writes back the normalised probabilities
// in the same FP16 buffer.
//
// Grid:  (T, n_groups)
// Block: 256 threads, each handling ceil(T_kv / 256) score positions.
__global__ void softmax_causal_inplace_kernel(__half * __restrict__ scores,
                                              uint32_t T, uint32_t T_kv,
                                              uint32_t base_seq_len,
                                              uint32_t n_groups,
                                              float scale) {
    const uint32_t q       = blockIdx.x;
    const uint32_t group   = blockIdx.y;
    const uint32_t tid     = threadIdx.x;
    const uint32_t lane    = tid & 31;
    const uint32_t warp_id = tid >> 5;
    constexpr uint32_t BS  = 256;
    constexpr uint32_t NW  = BS / 32;

    if (q >= T) return;
    const uint32_t my_max_kv = base_seq_len + q + 1;       // exclusive
    __half *row = scores + (static_cast<uint64_t>(group) * T + q) * T_kv;

    // Pass 1: row max with -inf for masked positions.
    float local_max = -INFINITY;
    for (uint32_t k = tid; k < T_kv; k += BS) {
        if (k < my_max_kv) {
            const float s = __half2float(row[k]) * scale;
            if (s > local_max) local_max = s;
        }
    }

    // Block reduce-max via warp + shmem.
    __shared__ float s_warp_max[NW];
    {
        float v = local_max;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off, 32));
        }
        if (lane == 0) s_warp_max[warp_id] = v;
    }
    __syncthreads();
    float row_max = -INFINITY;
    if (warp_id == 0) {
        float v = (lane < NW) ? s_warp_max[lane] : -INFINITY;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off, 32));
        }
        if (lane == 0) s_warp_max[0] = v;
    }
    __syncthreads();
    row_max = s_warp_max[0];

    // Pass 2: write exp(s - row_max) to row, accumulate row_sum.
    float local_sum = 0.0f;
    for (uint32_t k = tid; k < T_kv; k += BS) {
        if (k < my_max_kv) {
            const float s   = __half2float(row[k]) * scale;
            const float e   = __expf(s - row_max);
            row[k]          = __float2half(e);
            local_sum      += e;
        } else {
            row[k] = __float2half(0.0f);
        }
    }

    __shared__ float s_warp_sum[NW];
    {
        float v = local_sum;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            v += __shfl_xor_sync(0xffffffffu, v, off, 32);
        }
        if (lane == 0) s_warp_sum[warp_id] = v;
    }
    __syncthreads();
    float row_sum = 0.0f;
    if (warp_id == 0) {
        float v = (lane < NW) ? s_warp_sum[lane] : 0.0f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            v += __shfl_xor_sync(0xffffffffu, v, off, 32);
        }
        if (lane == 0) s_warp_sum[0] = v;
    }
    __syncthreads();
    row_sum = s_warp_sum[0];

    // Pass 3: divide by row_sum.
    const float inv = (row_sum > 0.0f) ? (1.0f / row_sum) : 0.0f;
    for (uint32_t k = tid; k < T_kv; k += BS) {
        const float p = __half2float(row[k]) * inv;
        row[k]       = __float2half(p);
    }
}

// FP32 → FP16 conversion that walks Q strided by head: src is [T, n_heads, d]
// row-major (q_batch_stride = n_heads * d, q_stride = d) but we can just
// reuse the contiguous fp32_to_fp16_kernel since the source is contiguous in
// memory. The cuBLAS path interprets the head stride at GEMM time.

// Returns the largest dynamic shmem size we will reserve per Q8 matvec block.
// Caches the device's max-opt-in shmem size and (best effort) opts the
// shmem-staged matvec kernel into using it. Returns 0 if no kernel
// instantiation is currently available to opt in.
size_t q8_matvec_max_shmem(uint32_t warps_per_block);

DeviceStatus dequant_q8_to_f32(float **out_ptr, const CudaWeight &w, bool persistent_cache) {
    if (!out_ptr) return {false, "dequant_q8_to_f32 out_ptr is null"};
    const uint64_t n = w.rows * w.cols;
    float *target = nullptr;
    if (persistent_cache && w.q8_f32_cache) {
        *out_ptr = w.q8_f32_cache;
        return {};
    }
    if (auto st = cuda_status(cudaMalloc(&target, static_cast<size_t>(n) * sizeof(float)), "cuda q8_f32 alloc"); !st.ok) {
        return st;
    }
    q8_dequant_f32_kernel<<<static_cast<unsigned>((n + 255) / 256), 256>>>(
        target, static_cast<const uint8_t *>(w.ptr), w.rows, w.cols);
    if (auto st = launch_status("cuda q8_f32 dequant"); !st.ok) {
        cudaFree(target);
        return st;
    }
    if (persistent_cache) {
        const_cast<CudaWeight &>(w).q8_f32_cache = target;
    }
    *out_ptr = target;
    return {};
}

size_t q8_matvec_max_shmem() {
    static size_t cached = SIZE_MAX;
    if (cached != SIZE_MAX) return cached;
    int device = 0;
    if (cudaGetDevice(&device) != cudaSuccess) {
        cached = 48 * 1024;
        return cached;
    }
    int max_shmem_optin = 0;
    cudaDeviceGetAttribute(&max_shmem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
    const size_t budget = max_shmem_optin > 4096 ? static_cast<size_t>(max_shmem_optin) - 4096
                                                 : static_cast<size_t>(48 * 1024);
    auto opt_in = [&](const void *kernel) {
        cudaFuncSetAttribute(
            kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            static_cast<int>(budget));
    };
    opt_in(reinterpret_cast<const void *>(&q8_matvec_v2_kernel<8, true>));
    opt_in(reinterpret_cast<const void *>(&q8_matvec_v2_kernel<16, true>));
    opt_in(reinterpret_cast<const void *>(&q8_matvec_v2_kernel<32, true>));
    opt_in(reinterpret_cast<const void *>(&q8_matvec_dp4a_kernel<8>));
    opt_in(reinterpret_cast<const void *>(&q8_matvec_dp4a_kernel<16>));
    opt_in(reinterpret_cast<const void *>(&q8_matvec_dp4a_kernel<32>));
    // Tiled matmul kernels (BATCH_TILE x WARPS_PER_BLOCK) used by prefill.
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<8,  2>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<16, 2>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<32, 2>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<8,  4>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<16, 4>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<32, 4>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<8,  8>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<16, 8>));
    opt_in(reinterpret_cast<const void *>(&q8_matmul_tiled_dp4a_kernel<32, 8>));
    cached = budget;
    return cached;
}

DeviceStatus ensure_q8_f32_cache(CudaWeight &w) {
    if (w.q8_f32_cache) return {};
    if (w.type != WeightType::Q8_0) return {false, "ensure_q8_f32_cache requires Q8_0 weight"};
    float *ptr = nullptr;
    return dequant_q8_to_f32(&ptr, w, true);
}

// Dequant a Q8_0 weight into an FP16 scratch buffer. Caller owns the buffer
// and is expected to size it to the largest weight in the model. Bandwidth-
// bound (~470 GB/s Q8 read on Blackwell HBM3e) and runs on the same stream
// as the HGEMM that consumes it, so no sync needed.
DeviceStatus dequant_q8_to_f16_stream(__half *out, const CudaWeight &w, cudaStream_t stream) {
    if (w.type != WeightType::Q8_0) return {false, "dequant_q8_to_f16 requires Q8_0 weight"};
    const uint64_t n_blocks = w.rows * (w.cols / 32);
    constexpr unsigned BLOCKS_PER_CTA = 64;
    const unsigned threads = BLOCKS_PER_CTA * 4;     // 4 lanes per sub-block
    const unsigned blocks  = static_cast<unsigned>(
        (n_blocks + BLOCKS_PER_CTA - 1) / BLOCKS_PER_CTA);
    q8_dequant_f16_kernel<<<blocks, threads, 0, stream>>>(out, static_cast<const uint8_t *>(w.ptr), w.rows, w.cols);
    return launch_status("q8_dequant_f16_kernel");
}

DeviceStatus dequant_q8_to_f16(__half *out, const CudaWeight &w) {
    return dequant_q8_to_f16_stream(out, w, /*stream=*/0);
}

// Causal 1D conv (single token, kernel size K).
// Inputs:
//   proj[c]         : current frame, [conv_dim]
//   state[c, k]     : K-1 previous frames, [conv_dim, K-1] indexed (c*(K-1) + k)
//                     state[c, 0] is the OLDEST frame, state[c, K-2] is the most-recent.
//   conv_w[c, k]    : weights, [conv_dim, K] indexed (c*K + k); tap K-1 applies to current.
// Outputs:
//   out[c]          : silu(sum_k conv_w[c, k] * frame[c, k])  where frame[c, K-1]=proj[c]
//   state           : shifted left, last slot now holds proj[c]
__global__ void recurrent_conv_kernel(float *out,
                                      float *state,
                                      const float *proj,
                                      const float *conv_w,
                                      uint32_t conv_dim,
                                      uint32_t conv_k) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;
    const float *w = conv_w + c * conv_k;
    float *st = state + c * (conv_k - 1);
    float acc = 0.0f;
    // Older frames live in state[0..K-2], current frame is proj[c].
    for (uint32_t k = 0; k + 1 < conv_k; ++k) acc += w[k] * st[k];
    const float cur = proj[c];
    acc += w[conv_k - 1] * cur;
    out[c] = acc / (1.0f + expf(-acc));
    // Shift state window: drop oldest, append current at the end.
    for (uint32_t k = 0; k + 2 < conv_k; ++k) st[k] = st[k + 1];
    st[conv_k - 2] = cur;
}

__global__ void l2_norm_128_kernel(float *x, uint32_t blocks, uint32_t stride, float eps) {
    const uint32_t b = blockIdx.x;
    if (b >= blocks) return;
    __shared__ float scratch[128];
    const uint32_t tid = threadIdx.x;
    float *base = x + b * stride;
    scratch[tid] = base[tid] * base[tid];
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float scale = rsqrtf(scratch[0] + eps);
    base[tid] *= scale;
}

__global__ void deltanet_kernel(float *core,
                                float *state,
                                const float *conv,
                                const float *alpha,
                                const float *beta,
                                const float *ssm_a,
                                const float *dt_bias,
                                uint32_t num_k_heads,
                                uint32_t num_v_heads,
                                uint32_t head_k_dim,
                                uint32_t head_v_dim) {
    const uint32_t vh = blockIdx.x;
    const uint32_t j = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (vh >= num_v_heads || j >= head_v_dim || tid >= head_k_dim) return;

    __shared__ float scratch[128];
    float *row = state + (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim;
    const float *q = conv + (vh % num_k_heads) * head_k_dim;
    const float *k = conv + num_k_heads * head_k_dim + (vh % num_k_heads) * head_k_dim;
    const float *v = conv + 2 * num_k_heads * head_k_dim + vh * head_v_dim;
    const float g_raw = log1pf(expf(alpha[vh] + dt_bias[vh])) * ssm_a[vh];
    const float eg = expf(g_raw);
    const float b = 1.0f / (1.0f + expf(-beta[vh]));

    row[tid] *= eg;
    scratch[tid] = row[tid] * k[tid];
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float delta = (v[j] - scratch[0]) * b;
    row[tid] += delta * k[tid];
    scratch[tid] = row[tid] * q[tid];
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    if (tid == 0) core[vh * head_v_dim + j] = scratch[0] * rsqrtf(static_cast<float>(head_v_dim));
}

__global__ void recurrent_norm_gate_kernel(float *core, const float *gate, const float *norm_w, uint32_t num_v_heads, uint32_t head_v_dim, float eps) {
    const uint32_t vh = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (vh >= num_v_heads || tid >= head_v_dim) return;
    __shared__ float scratch[256];
    float *block = core + vh * head_v_dim;
    scratch[tid] = block[tid] * block[tid];
    __syncthreads();
    for (uint32_t s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float scale = rsqrtf(scratch[0] / static_cast<float>(head_v_dim) + eps);
    const float z = gate[vh * head_v_dim + tid];
    block[tid] = block[tid] * scale * norm_w[tid] * (z / (1.0f + expf(-z)));
}

// ---------------------------------------------------------------------------
// Batched recurrent kernels: process T tokens for a whole layer in O(1)
// kernel launches instead of O(T) launches.
//
// Prefill on Qwen 3.6 27B has 48 DeltaNet layers. The per-token loop above
// launched 5 small kernels per token, so 1322 tokens * 48 layers * 5 kernels
// = 317K launches per prefill. At ~10us launch overhead that's ~3s of pure
// overhead. The batched variants below do one launch per layer per sub-op,
// reducing the count to 48 * 4 = ~200 launches per prefill.

// Conv-batched: one thread runs T sequential conv steps for its channel,
// keeping the small (conv_k-1) state window in registers.
template <uint32_t CONV_K>
__global__ void recurrent_conv_batch_kernel(float *out,         // [T, *] stride out_stride
                                            float *state,       // [conv_dim, conv_k-1]
                                            const float *proj,  // [T, *] stride proj_stride
                                            const float *conv_w, // [conv_dim, conv_k]
                                            float *state_checkpoints,
                                            uint32_t T,
                                            uint32_t conv_dim,
                                            uint32_t proj_stride,
                                            uint32_t out_stride,
                                            uint32_t checkpoint_count) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;
    const float *w = conv_w + c * CONV_K;
    float *st = state + c * (CONV_K - 1);
    float st_buf[CONV_K - 1];
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) st_buf[i] = st[i];

    // Pre-load weights into registers (CONV_K <= 8 in practice).
    float w_buf[CONV_K];
    #pragma unroll
    for (uint32_t k = 0; k < CONV_K; ++k) w_buf[k] = w[k];

    for (uint32_t t = 0; t < T; ++t) {
        const float cur = proj[t * proj_stride + c];
        float acc = w_buf[CONV_K - 1] * cur;
        #pragma unroll
        for (uint32_t k = 0; k + 1 < CONV_K; ++k) acc += w_buf[k] * st_buf[k];
        out[t * out_stride + c] = acc / (1.0f + expf(-acc));
        // Shift state window.
        #pragma unroll
        for (uint32_t k = 0; k + 2 < CONV_K; ++k) st_buf[k] = st_buf[k + 1];
        st_buf[CONV_K - 2] = cur;
        if (state_checkpoints != nullptr && t < checkpoint_count) {
            const uint64_t checkpoint_stride =
                static_cast<uint64_t>(conv_dim) * (CONV_K - 1);
            float *ckpt = state_checkpoints +
                static_cast<uint64_t>(t) * checkpoint_stride +
                c * (CONV_K - 1);
            #pragma unroll
            for (uint32_t i = 0; i + 1 < CONV_K; ++i) ckpt[i] = st_buf[i];
        }
    }
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) st[i] = st_buf[i];
}

// Long-prefill causal conv. The recurrent implementation above assigns one
// thread to a channel and serializes the entire token dimension. This variant
// divides tokens into independent tiles because every output only reads the
// immutable input plus the initial (CONV_K-1)-token state.
template <uint32_t CONV_K, uint32_t TOKEN_TILE>
__global__ void recurrent_conv_prefill_parallel_kernel(
        float *out,             // [T, *] stride out_stride
        const float *state,     // initial [conv_dim, conv_k-1]
        const float *proj,      // [T, *] stride proj_stride
        const float *conv_w,    // [conv_dim, conv_k]
        uint32_t T,
        uint32_t conv_dim,
        uint32_t proj_stride,
        uint32_t out_stride) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;

    const uint32_t t_begin = blockIdx.y * TOKEN_TILE;
    const uint32_t t_end = min(T, t_begin + TOKEN_TILE);
    const float *w = conv_w + static_cast<uint64_t>(c) * CONV_K;
    const float *initial = state + static_cast<uint64_t>(c) * (CONV_K - 1);

    float w_buf[CONV_K];
    #pragma unroll
    for (uint32_t k = 0; k < CONV_K; ++k) w_buf[k] = w[k];

    for (uint32_t t = t_begin; t < t_end; ++t) {
        float acc = w_buf[CONV_K - 1] *
                    proj[static_cast<uint64_t>(t) * proj_stride + c];
        #pragma unroll
        for (uint32_t k = 0; k + 1 < CONV_K; ++k) {
            const int64_t source_t =
                static_cast<int64_t>(t) + k - (CONV_K - 1);
            const float x = source_t >= 0
                ? proj[static_cast<uint64_t>(source_t) * proj_stride + c]
                : initial[source_t + (CONV_K - 1)];
            acc += w_buf[k] * x;
        }
        out[static_cast<uint64_t>(t) * out_stride + c] =
            acc / (1.0f + expf(-acc));
    }
}

template <uint32_t CONV_K>
__global__ void recurrent_conv_prefill_state_kernel(
        float *state,
        const float *proj,
        uint32_t T,
        uint32_t conv_dim,
        uint32_t proj_stride) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;

    float *st = state + static_cast<uint64_t>(c) * (CONV_K - 1);
    // Ascending writes are safe when T < CONV_K-1: every old-state source has
    // a strictly larger index than its destination.
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) {
        const int64_t source_t =
            static_cast<int64_t>(T) - (CONV_K - 1) + i;
        st[i] = source_t >= 0
            ? proj[static_cast<uint64_t>(source_t) * proj_stride + c]
            : st[source_t + (CONV_K - 1)];
    }
}

__device__ __forceinline__ float recurrent_lazy_fp8_value(
        const float *raw,
        const float *activation_scales,
        const float *weight_scales,
        uint32_t raw_stride,
        uint32_t row_offset,
        uint32_t t,
        uint32_t c) {
    return raw[static_cast<uint64_t>(t) * raw_stride + row_offset + c] *
           activation_scales[t] * weight_scales[c];
}

template <uint32_t CONV_K, uint32_t TOKEN_TILE>
__global__ void recurrent_conv_prefill_parallel_lazy_fp8_kernel(
        float *out,
        const float *state,
        const float *raw,
        const float *activation_scales,
        const float *weight_scales,
        const float *conv_w,
        uint32_t T,
        uint32_t conv_dim,
        uint32_t raw_stride,
        uint32_t row_offset,
        uint32_t out_stride) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;

    const uint32_t t_begin = blockIdx.y * TOKEN_TILE;
    const uint32_t t_end = min(T, t_begin + TOKEN_TILE);
    const float *w = conv_w + static_cast<uint64_t>(c) * CONV_K;
    const float *initial =
        state + static_cast<uint64_t>(c) * (CONV_K - 1);

    float history[CONV_K - 1];
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) {
        const int64_t source_t =
            static_cast<int64_t>(t_begin) - (CONV_K - 1) + i;
        history[i] = source_t >= 0
            ? recurrent_lazy_fp8_value(
                  raw, activation_scales, weight_scales,
                  raw_stride, row_offset,
                  static_cast<uint32_t>(source_t), c)
            : initial[source_t + (CONV_K - 1)];
    }

    float w_buf[CONV_K];
    #pragma unroll
    for (uint32_t i = 0; i < CONV_K; ++i) w_buf[i] = w[i];

    for (uint32_t t = t_begin; t < t_end; ++t) {
        const float current = recurrent_lazy_fp8_value(
            raw, activation_scales, weight_scales,
            raw_stride, row_offset, t, c);
        float acc = w_buf[CONV_K - 1] * current;
        #pragma unroll
        for (uint32_t i = 0; i + 1 < CONV_K; ++i) {
            acc += w_buf[i] * history[i];
        }
        out[static_cast<uint64_t>(t) * out_stride + c] =
            acc / (1.0f + expf(-acc));
        #pragma unroll
        for (uint32_t i = 0; i + 2 < CONV_K; ++i) {
            history[i] = history[i + 1];
        }
        history[CONV_K - 2] = current;
    }
}

template <uint32_t CONV_K>
__global__ void recurrent_conv_prefill_state_lazy_fp8_kernel(
        float *state,
        const float *raw,
        const float *activation_scales,
        const float *weight_scales,
        uint32_t T,
        uint32_t conv_dim,
        uint32_t raw_stride,
        uint32_t row_offset) {
    const uint32_t c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= conv_dim) return;

    float *st = state + static_cast<uint64_t>(c) * (CONV_K - 1);
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) {
        const int64_t source_t =
            static_cast<int64_t>(T) - (CONV_K - 1) + i;
        st[i] = source_t >= 0
            ? recurrent_lazy_fp8_value(
                  raw, activation_scales, weight_scales,
                  raw_stride, row_offset,
                  static_cast<uint32_t>(source_t), c)
            : st[source_t + (CONV_K - 1)];
    }
}

#ifdef QW3_ENABLE_GDN_SM120_AOT
__global__ void recurrent_norm_pack_gdn_bf16_kernel(
        __nv_bfloat16 *q,
        __nv_bfloat16 *k,
        __nv_bfloat16 *v,
        const float *packed_qkv,
        uint32_t T,
        uint32_t num_k_heads,
        uint32_t num_v_heads,
        uint32_t head_dim,
        uint32_t packed_stride,
        float eps) {
    const uint32_t t = blockIdx.x;
    const uint32_t head = blockIdx.y;
    const uint32_t d = threadIdx.x;
    if (t >= T || head >= num_v_heads || d >= head_dim) return;

    const uint32_t q_width = num_k_heads * head_dim;
    const uint32_t v_width = num_v_heads * head_dim;
    const uint64_t packed_base =
        static_cast<uint64_t>(t) * packed_stride;

    if (head < num_k_heads) {
        __shared__ float q_sq[128];
        __shared__ float k_sq[128];
        const uint32_t head_offset = head * head_dim + d;
        const float q_value = packed_qkv[packed_base + head_offset];
        const float k_value =
            packed_qkv[packed_base + q_width + head_offset];
        q_sq[d] = q_value * q_value;
        k_sq[d] = k_value * k_value;
        __syncthreads();
        for (uint32_t step = 64; step > 0; step >>= 1) {
            if (d < step) {
                q_sq[d] += q_sq[d + step];
                k_sq[d] += k_sq[d + step];
            }
            __syncthreads();
        }
        const uint64_t output_offset =
            static_cast<uint64_t>(t) * q_width + head_offset;
        q[output_offset] =
            __float2bfloat16_rn(q_value * rsqrtf(q_sq[0] + eps));
        k[output_offset] =
            __float2bfloat16_rn(k_value * rsqrtf(k_sq[0] + eps));
    }

    const uint32_t v_offset = head * head_dim + d;
    v[static_cast<uint64_t>(t) * v_width + v_offset] =
        __float2bfloat16_rn(
            packed_qkv[packed_base + 2u * q_width + v_offset]);
}

__global__ void recurrent_pack_gdn_bf16_kernel(
        __nv_bfloat16 *q,
        __nv_bfloat16 *k,
        __nv_bfloat16 *v,
        const float *packed_qkv,
        uint32_t T,
        uint32_t q_elems_per_token,
        uint32_t k_elems_per_token,
        uint32_t v_elems_per_token,
        uint32_t packed_stride) {
    const uint32_t t = blockIdx.x;
    const uint32_t d = blockIdx.y * blockDim.x + threadIdx.x;
    const uint32_t packed_elems =
        q_elems_per_token + k_elems_per_token + v_elems_per_token;
    if (t >= T || d >= packed_elems) return;

    const float value =
        packed_qkv[static_cast<uint64_t>(t) * packed_stride + d];
    if (d < q_elems_per_token) {
        q[static_cast<uint64_t>(t) * q_elems_per_token + d] =
            __float2bfloat16(value);
    } else if (d < q_elems_per_token + k_elems_per_token) {
        const uint32_t kd = d - q_elems_per_token;
        k[static_cast<uint64_t>(t) * k_elems_per_token + kd] =
            __float2bfloat16(value);
    } else {
        const uint32_t vd = d - q_elems_per_token - k_elems_per_token;
        v[static_cast<uint64_t>(t) * v_elems_per_token + vd] =
            __float2bfloat16(value);
    }
}

__global__ void recurrent_unpack_gdn_bf16_kernel(
        float *out,
        const __nv_bfloat16 *in,
        uint32_t T,
        uint32_t width,
        uint32_t out_stride) {
    const uint64_t index =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t count = static_cast<uint64_t>(T) * width;
    if (index >= count) return;
    const uint32_t t = static_cast<uint32_t>(index / width);
    const uint32_t d = static_cast<uint32_t>(index - static_cast<uint64_t>(t) * width);
    out[static_cast<uint64_t>(t) * out_stride + d] =
        __bfloat162float(in[index]);
}

__global__ void recurrent_norm_gate_gdn_bf16_kernel(
        float *core,
        const __nv_bfloat16 *gdn_out,
        const float *gate,
        const float *gate_raw,
        const float *gate_activation_scales,
        const float *gate_weight_scales,
        const float *norm_w,
        uint32_t T,
        uint32_t num_v_heads,
        uint32_t head_v_dim,
        uint32_t core_stride,
        uint32_t gate_stride,
        uint32_t gate_raw_stride,
        uint32_t gate_row_offset,
        float eps) {
    const uint32_t t = blockIdx.x;
    const uint32_t vh = blockIdx.y;
    const uint32_t d = threadIdx.x;
    if (t >= T || vh >= num_v_heads || d >= head_v_dim) return;

    __shared__ float sq[256];
    const uint32_t width = num_v_heads * head_v_dim;
    const uint32_t head_offset = vh * head_v_dim + d;
    const float value = __bfloat162float(
        gdn_out[static_cast<uint64_t>(t) * width + head_offset]);
    sq[d] = value * value;
    __syncthreads();
    for (uint32_t step = blockDim.x / 2; step > 0; step >>= 1) {
        if (d < step) sq[d] += sq[d + step];
        __syncthreads();
    }

    const float scale =
        rsqrtf(sq[0] / static_cast<float>(head_v_dim) + eps);
    const float z = gate_raw
        ? gate_raw[static_cast<uint64_t>(t) * gate_raw_stride +
                   gate_row_offset + head_offset] *
              gate_activation_scales[t] *
              gate_weight_scales[head_offset]
        : gate[static_cast<uint64_t>(t) * gate_stride + head_offset];
    core[static_cast<uint64_t>(t) * core_stride + head_offset] =
        value * scale * norm_w[d] * (z / (1.0f + expf(-z)));
}

__global__ void recurrent_set_cu_seqlens_kernel(
        int64_t *cu_seqlens, uint32_t T) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        cu_seqlens[0] = 0;
        cu_seqlens[1] = T;
    }
}
#endif

template <uint32_t CONV_K>
__global__ void recurrent_conv_independent_batch_kernel(
                                            float *out,         // [B, *] stride out_stride
                                            float *state,       // [B, conv_state_stride]
                                            const float *proj,  // [B, *] stride proj_stride
                                            const float *conv_w, // [conv_dim, conv_k]
                                            uint32_t B,
                                            uint32_t conv_dim,
                                            uint32_t state_stride,
                                            uint32_t proj_stride,
                                            uint32_t out_stride) {
    const uint32_t b = blockIdx.x;
    const uint32_t c = blockIdx.y * blockDim.x + threadIdx.x;
    if (b >= B || c >= conv_dim) return;
    const float *w = conv_w + c * CONV_K;
    float *st = state + static_cast<uint64_t>(b) * state_stride + c * (CONV_K - 1);
    float acc = w[CONV_K - 1] * proj[static_cast<uint64_t>(b) * proj_stride + c];
    #pragma unroll
    for (uint32_t k = 0; k + 1 < CONV_K; ++k) acc += w[k] * st[k];
    out[static_cast<uint64_t>(b) * out_stride + c] =
        acc / (1.0f + expf(-acc));
    #pragma unroll
    for (uint32_t k = 0; k + 2 < CONV_K; ++k) st[k] = st[k + 1];
    st[CONV_K - 2] = proj[static_cast<uint64_t>(b) * proj_stride + c];
}

template <uint32_t CONV_K>
__global__ void recurrent_conv_ragged_batch_kernel(
                                            float *out,          // [total_q, *]
                                            float *state,        // [B, conv_state_stride]
                                            const float *proj,   // [total_q, *]
                                            const int32_t *q_indptr,
                                            const float *conv_w,
                                            float *state_checkpoints,
                                            uint32_t B,
                                            uint32_t conv_dim,
                                            uint32_t state_stride,
                                            uint32_t proj_stride,
                                            uint32_t out_stride,
                                            uint32_t checkpoint_count) {
    const uint32_t b = blockIdx.x;
    const uint32_t c = blockIdx.y * blockDim.x + threadIdx.x;
    if (b >= B || c >= conv_dim) return;
    const int32_t begin_i = q_indptr[b];
    const int32_t end_i = q_indptr[b + 1];
    if (begin_i < 0 || end_i < begin_i) return;
    const uint32_t begin = static_cast<uint32_t>(begin_i);
    const uint32_t end = static_cast<uint32_t>(end_i);
    const float *w = conv_w + c * CONV_K;
    float *st = state + static_cast<uint64_t>(b) * state_stride +
                c * (CONV_K - 1);
    float st_buf[CONV_K - 1];
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) st_buf[i] = st[i];
    float w_buf[CONV_K];
    #pragma unroll
    for (uint32_t k = 0; k < CONV_K; ++k) w_buf[k] = w[k];
    for (uint32_t t = begin; t < end; ++t) {
        const float cur = proj[static_cast<uint64_t>(t) * proj_stride + c];
        float acc = w_buf[CONV_K - 1] * cur;
        #pragma unroll
        for (uint32_t k = 0; k + 1 < CONV_K; ++k) acc += w_buf[k] * st_buf[k];
        out[static_cast<uint64_t>(t) * out_stride + c] =
            acc / (1.0f + expf(-acc));
        #pragma unroll
        for (uint32_t k = 0; k + 2 < CONV_K; ++k) st_buf[k] = st_buf[k + 1];
        st_buf[CONV_K - 2] = cur;
        const uint32_t local_t = t - begin;
        if (state_checkpoints != nullptr && local_t < checkpoint_count) {
            const uint64_t checkpoint_stride =
                static_cast<uint64_t>(conv_dim) * (CONV_K - 1);
            float *ckpt = state_checkpoints +
                (static_cast<uint64_t>(b) * checkpoint_count + local_t) *
                    checkpoint_stride +
                static_cast<uint64_t>(c) * (CONV_K - 1);
            #pragma unroll
            for (uint32_t i = 0; i + 1 < CONV_K; ++i) ckpt[i] = st_buf[i];
        }
    }
    #pragma unroll
    for (uint32_t i = 0; i + 1 < CONV_K; ++i) st[i] = st_buf[i];
}

// L2-norm batched: one block per (token, k_head) pair. Same per-head logic as
// l2_norm_128_kernel, fanned out over the time dimension via blockIdx.y.
__global__ void l2_norm_128_batch_kernel(float *x,             // base ptr
                                         uint32_t blocks,       // num k heads
                                         uint32_t stride,       // head_k_dim
                                         uint32_t T,            // batch
                                         uint32_t batch_stride, // conv_dim
                                         uint32_t base_offset,  // offset to Q or K region
                                         float eps) {
    const uint32_t t  = blockIdx.x;            // which timestep
    const uint32_t b  = blockIdx.y;            // which k_head
    if (b >= blocks || t >= T) return;
    __shared__ float scratch[128];
    const uint32_t tid = threadIdx.x;
    float *base = x + static_cast<uint64_t>(t) * batch_stride + base_offset + b * stride;
    scratch[tid] = base[tid] * base[tid];
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float scale = rsqrtf(scratch[0] + eps);
    base[tid] *= scale;
}

__global__ void l2_norm_128_qk_batch_kernel(float *x,
                                            uint32_t blocks,
                                            uint32_t stride,
                                            uint32_t T,
                                            uint32_t batch_stride,
                                            uint32_t q_offset,
                                            uint32_t k_offset,
                                            float eps) {
    const uint32_t t  = blockIdx.x;
    const uint32_t b  = blockIdx.y;
    if (b >= blocks || t >= T) return;
    __shared__ float scratch[128];
    const uint32_t tid = threadIdx.x;

    float *q_base = x + static_cast<uint64_t>(t) * batch_stride + q_offset + b * stride;
    scratch[tid] = q_base[tid] * q_base[tid];
    __syncthreads();
    for (uint32_t s_red = 64; s_red > 0; s_red >>= 1) {
        if (tid < s_red) scratch[tid] += scratch[tid + s_red];
        __syncthreads();
    }
    const float q_scale = rsqrtf(scratch[0] + eps);
    q_base[tid] *= q_scale;
    __syncthreads();

    float *k_base = x + static_cast<uint64_t>(t) * batch_stride + k_offset + b * stride;
    scratch[tid] = k_base[tid] * k_base[tid];
    __syncthreads();
    for (uint32_t s_red = 64; s_red > 0; s_red >>= 1) {
        if (tid < s_red) scratch[tid] += scratch[tid + s_red];
        __syncthreads();
    }
    const float k_scale = rsqrtf(scratch[0] + eps);
    k_base[tid] *= k_scale;
}

// DeltaNet batched: one block per (v_head, head_v_dim_pos), 128 threads/block,
// each thread holds one element of the row in a register. The block iterates
// over all T tokens, updating its slice of the state sequentially. Output
// `core` is [T, num_v_heads * head_v_dim] row-major.
__global__ void deltanet_batch_kernel(float *core,                  // [T, *] stride core_stride
                                      float *state,                 // [num_v_heads, head_v_dim, head_k_dim]
                                      const float *conv_batch,      // [T, *] stride conv_stride
                                      const float *alpha_batch,     // [T, *] stride alpha_stride
                                      const float *beta_batch,      // [T, *] stride beta_stride
                                      const float *ssm_a,           // [num_v_heads]
                                      const float *dt_bias,         // [num_v_heads]
                                      float *state_checkpoints,
                                      uint32_t T,
                                      uint32_t num_k_heads,
                                      uint32_t num_v_heads,
                                      uint32_t head_k_dim,
                                      uint32_t head_v_dim,
                                      uint32_t conv_stride,
                                      uint32_t alpha_stride,
                                      uint32_t beta_stride,
                                      uint32_t core_stride,
                                      uint32_t checkpoint_count,
                                      // DeltaNet retrieval block-boundary snapshot
                                      // (kvmem retrieval_method==deltanet). When
                                      // dn_snap != nullptr, the state row_val is
                                      // written into dn_snap at the LAST token of
                                      // every block (and the final partial block),
                                      // giving S_j per block. Layout of dn_snap
                                      // (already offset to this layer's slice):
                                      // [block, num_v_heads, head_v_dim, head_k_dim].
                                      float *dn_snap = nullptr,
                                      uint32_t dn_block_tokens = 0,
                                      uint32_t dn_base_pos = 0,
                                      uint32_t dn_n_blocks = 0) {
    const uint32_t vh = blockIdx.x;
    const uint32_t j  = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (vh >= num_v_heads || j >= head_v_dim || tid >= head_k_dim) return;

    __shared__ float scratch[128];
    float *row = state + (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim;

    // Cache the per-head constants used at every timestep.
    const uint32_t kh = vh % num_k_heads;
    const uint32_t q_offset = kh * head_k_dim;
    const uint32_t k_offset = num_k_heads * head_k_dim + kh * head_k_dim;
    const uint32_t v_offset = 2u * num_k_heads * head_k_dim + vh * head_v_dim;

    const float ssm_a_v = ssm_a[vh];
    const float dt_bias_v = dt_bias[vh];
    const float inv_hvd = rsqrtf(static_cast<float>(head_v_dim));
    const bool dn_capture = (dn_snap != nullptr && dn_block_tokens > 0);
    const uint64_t dn_row_stride =
        static_cast<uint64_t>(num_v_heads) * head_v_dim * head_k_dim;

    float row_val = row[tid];

    for (uint32_t t = 0; t < T; ++t) {
        const float *conv = conv_batch + static_cast<uint64_t>(t) * conv_stride;
        const float q = conv[q_offset + tid];
        const float k = conv[k_offset + tid];
        const float v_j = conv[v_offset + j];
        const float a_v = alpha_batch[t * alpha_stride + vh];
        const float b_v = beta_batch[t * beta_stride + vh];

        const float g_raw = log1pf(expf(a_v + dt_bias_v)) * ssm_a_v;
        const float eg = expf(g_raw);
        const float b = 1.0f / (1.0f + expf(-b_v));

        row_val *= eg;
        scratch[tid] = row_val * k;
        __syncthreads();
        for (uint32_t s = 64; s > 0; s >>= 1) {
            if (tid < s) scratch[tid] += scratch[tid + s];
            __syncthreads();
        }
        const float delta = (v_j - scratch[0]) * b;
        row_val += delta * k;
        scratch[tid] = row_val * q;
        __syncthreads();
        for (uint32_t s = 64; s > 0; s >>= 1) {
            if (tid < s) scratch[tid] += scratch[tid + s];
            __syncthreads();
        }
        if (tid == 0) {
            core[static_cast<uint64_t>(t) * core_stride + vh * head_v_dim + j] = scratch[0] * inv_hvd;
        }
        if (state_checkpoints != nullptr && t < checkpoint_count) {
            const uint64_t checkpoint_stride =
                static_cast<uint64_t>(num_v_heads) * head_v_dim * head_k_dim;
            state_checkpoints[static_cast<uint64_t>(t) * checkpoint_stride +
                              (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim + tid] =
                row_val;
        }
        if (dn_capture) {
            const uint32_t gpos = dn_base_pos + t;
            const bool block_end = ((gpos + 1) % dn_block_tokens == 0) || (t + 1 == T);
            if (block_end) {
                const uint32_t blk = gpos / dn_block_tokens;
                if (blk < dn_n_blocks) {
                    dn_snap[static_cast<uint64_t>(blk) * dn_row_stride +
                            (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim + tid] =
                        row_val;
                }
            }
        }
        __syncthreads();
    }
    row[tid] = row_val;
}

// DeltaNet retrieval: per-block cumulative in-block log-decay scan
// (kvmem retrieval_method==deltanet). g_raw[t,vh] = softplus(alpha+dt_bias)*ssm_a
// (identical to the delta kernel's decay), summed over the tokens of each block
// into decaysum[blk, vh]. Accumulates (+=) so multiple prefill chunks fold into
// the same per-block sum. alpha_batch is the RAW alpha [T, alpha_stride]; the
// caller runs this on the qw3 (non-ported) path where alpha is not overwritten.
// grid = (dn_n_blocks_chunk, num_v_heads); one thread per (block, vh).
__global__ void deltanet_decay_scan_kernel(const float *alpha_batch,
                                           const float *dt_bias,
                                           const float *ssm_a,
                                           float *decaysum,        // [blocks, num_v_heads] (offset to layer)
                                           uint32_t T,
                                           uint32_t num_v_heads,
                                           uint32_t alpha_stride,
                                           uint32_t block_tokens,
                                           uint32_t base_pos,
                                           uint32_t n_blocks) {
    const uint32_t blk_local = blockIdx.x;   // chunk-local block enumerated below
    const uint32_t vh = blockIdx.y * blockDim.x + threadIdx.x;
    if (vh >= num_v_heads) return;
    // First global block covered by this chunk (base_pos assumed block-aligned on
    // a fresh prefill; a misaligned suffix folds its partial leading block here).
    const uint32_t first_blk = base_pos / block_tokens;
    const uint32_t blk = first_blk + blk_local;
    if (blk >= n_blocks) return;
    const uint32_t blk_lo = blk * block_tokens;
    const uint32_t blk_hi = blk_lo + block_tokens;
    const float dtb = dt_bias[vh];
    const float a = ssm_a[vh];
    float sum = 0.0f;
    for (uint32_t gpos = blk_lo; gpos < blk_hi; ++gpos) {
        if (gpos < base_pos) continue;               // token not in this chunk
        const uint32_t t = gpos - base_pos;
        if (t >= T) break;
        const float a_v = alpha_batch[t * alpha_stride + vh];
        sum += log1pf(expf(a_v + dtb)) * a;
    }
    decaysum[static_cast<uint64_t>(blk) * num_v_heads + vh] += sum;
}

// DeltaNet retrieval: pack the in-span DeltaNet query rows for one layer.
// The conv output `cout` holds the L2-normalized DeltaNet Q in the first
// num_k_heads*head_k_dim of each row (row stride conv_stride). For the `cnt`
// in-span question tokens starting at chunk-local row r0, copy [num_k_heads,
// head_k_dim] into q_dst at (dst_row_base + r) row. grid = (cnt, num_k_heads),
// block = head_k_dim threads. No RoPE (DeltaNet queries are not rotated).
__global__ void deltanet_pack_query_kernel(float *q_dst,
                                           const float *cout,
                                           uint32_t conv_stride,
                                           uint32_t r0,
                                           uint32_t dst_row_base,
                                           uint32_t cnt,
                                           uint32_t num_k_heads,
                                           uint32_t head_k_dim) {
    const uint32_t r = blockIdx.x;
    const uint32_t kh = blockIdx.y;
    const uint32_t d = threadIdx.x;
    if (r >= cnt || kh >= num_k_heads || d >= head_k_dim) return;
    const float v = cout[static_cast<uint64_t>(r0 + r) * conv_stride +
                         kh * head_k_dim + d];
    q_dst[((static_cast<uint64_t>(dst_row_base + r) * num_k_heads) + kh) * head_k_dim + d] = v;
}

// DeltaNet retrieval: per (block, v-head) block score for one layer.
//   r[blk,vh] = TopKMean_t( d[blk,vh] * || (S_j - a_j S_{j-1})^T q_t ||_2 )
// S_j = dn_snap[blk], S_{j-1} = dn_snap[blk-1] (0 for blk 0), a_j = exp(decaysum
// [blk,vh]); d[blk,vh] is the precomputed post-block decay exp(G_M - G_j) (or 1).
// q rows are the L2-normalized DeltaNet queries [M, num_k_heads, head_k_dim] for
// this layer; v-head vh reads k-head vh%num_k_heads. grid = (n_blocks, num_v_heads),
// block = head_k_dim threads. Dynamic shmem: q_all[M*head_k_dim] + norm2[M].
__global__ void deltanet_block_score_kernel(float *r_out,           // [n_blocks, num_v_heads] (offset to layer)
                                            const float *dn_snap,   // [blocks, v_heads, d_v, d_k] (offset to layer)
                                            const float *decaysum,  // [blocks, v_heads] (offset to layer)
                                            const float *decay_d,   // [blocks, v_heads] (offset to layer)
                                            const float *q_layer,   // [M, num_k_heads, d_k] (offset to layer)
                                            uint32_t n_blocks,
                                            uint32_t num_k_heads,
                                            uint32_t num_v_heads,
                                            uint32_t head_v_dim,
                                            uint32_t head_k_dim,
                                            uint32_t M,
                                            uint32_t topk_q) {
    const uint32_t blk = blockIdx.x;
    const uint32_t vh = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (blk >= n_blocks || vh >= num_v_heads || tid >= head_k_dim) return;

    extern __shared__ float smem[];
    float *q_all = smem;                 // [M * head_k_dim]
    float *norm2 = smem + static_cast<uint64_t>(M) * head_k_dim;  // [M]
    __shared__ float scratch[128];

    const uint32_t kh = vh % num_k_heads;
    // Load this v-head's k-head query rows into shmem (de-RoPE'd + L2-normed).
    for (uint32_t t = 0; t < M; ++t) {
        q_all[t * head_k_dim + tid] =
            q_layer[(static_cast<uint64_t>(t) * num_k_heads + kh) * head_k_dim + tid];
        if (tid == 0) norm2[t] = 0.0f;
    }
    __syncthreads();

    const float a_j = expf(decaysum[static_cast<uint64_t>(blk) * num_v_heads + vh]);
    const uint64_t dn_row_stride =
        static_cast<uint64_t>(num_v_heads) * head_v_dim * head_k_dim;
    const float *S_j = dn_snap + static_cast<uint64_t>(blk) * dn_row_stride +
                       static_cast<uint64_t>(vh) * head_v_dim * head_k_dim;
    const float *S_prev = (blk > 0)
        ? dn_snap + static_cast<uint64_t>(blk - 1) * dn_row_stride +
              static_cast<uint64_t>(vh) * head_v_dim * head_k_dim
        : nullptr;

    // Reduction start: the next power of two >= head_k_dim, so the tree reduction
    // is correct for any head_k_dim (production is 128; smaller dims — tests — are
    // handled without reading past blockDim into uninitialized shared memory).
    uint32_t red0 = 1;
    while (red0 < head_k_dim) red0 <<= 1;
    red0 >>= 1;

    // Accumulate ||E_j^T q_t||^2 over the d_v rows of E_j = S_j - a_j S_{j-1}.
    for (uint32_t jrow = 0; jrow < head_v_dim; ++jrow) {
        const float sj = S_j[jrow * head_k_dim + tid];
        const float sp = S_prev ? S_prev[jrow * head_k_dim + tid] : 0.0f;
        const float e = sj - a_j * sp;
        for (uint32_t t = 0; t < M; ++t) {
            scratch[tid] = e * q_all[t * head_k_dim + tid];
            __syncthreads();
            for (uint32_t s = red0; s > 0; s >>= 1) {
                if (tid < s && tid + s < head_k_dim) scratch[tid] += scratch[tid + s];
                __syncthreads();
            }
            if (tid == 0) norm2[t] += scratch[0] * scratch[0];
            __syncthreads();
        }
    }

    if (tid == 0) {
        const float d = decay_d[static_cast<uint64_t>(blk) * num_v_heads + vh];
        // r_t = d * ||E_j^T q_t||. TopKMean over the top-`topk_q` tokens.
        float best[8];
        const uint32_t kq = topk_q < 8 ? (topk_q == 0 ? 1u : topk_q) : 8u;
        for (uint32_t i = 0; i < kq; ++i) best[i] = -1.0f;
        for (uint32_t t = 0; t < M; ++t) {
            const float r_t = d * sqrtf(norm2[t]);
            // Insert into the descending top-kq list.
            for (uint32_t i = 0; i < kq; ++i) {
                if (r_t > best[i]) {
                    for (uint32_t s = kq - 1; s > i; --s) best[s] = best[s - 1];
                    best[i] = r_t;
                    break;
                }
            }
        }
        float sum = 0.0f;
        uint32_t cnt = 0;
        for (uint32_t i = 0; i < kq && i < M; ++i) {
            if (best[i] >= 0.0f) { sum += best[i]; ++cnt; }
        }
        r_out[static_cast<uint64_t>(blk) * num_v_heads + vh] =
            cnt > 0 ? sum / static_cast<float>(cnt) : 0.0f;
    }
}

__global__ void deltanet_independent_batch_kernel(
                                      float *core,              // [B, *] stride core_stride
                                      float *state,             // [B, state_stride]
                                      const float *conv_batch,  // [B, *] stride conv_stride
                                      const float *alpha_batch, // [B, *] stride alpha_stride
                                      const float *beta_batch,  // [B, *] stride beta_stride
                                      const float *ssm_a,
                                      const float *dt_bias,
                                      uint32_t B,
                                      uint32_t num_k_heads,
                                      uint32_t num_v_heads,
                                      uint32_t head_k_dim,
                                      uint32_t head_v_dim,
                                      uint32_t conv_stride,
                                      uint32_t alpha_stride,
                                      uint32_t beta_stride,
                                      uint32_t core_stride,
                                      uint32_t state_stride) {
    const uint32_t b = blockIdx.x;
    const uint32_t vh = blockIdx.y;
    const uint32_t j = blockIdx.z;
    const uint32_t tid = threadIdx.x;
    if (b >= B || vh >= num_v_heads || j >= head_v_dim || tid >= head_k_dim) return;

    __shared__ float scratch[128];
    float *row = state + static_cast<uint64_t>(b) * state_stride +
                 (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim;

    const uint32_t kh = vh % num_k_heads;
    const uint32_t q_offset = kh * head_k_dim;
    const uint32_t k_offset = num_k_heads * head_k_dim + kh * head_k_dim;
    const uint32_t v_offset = 2u * num_k_heads * head_k_dim + vh * head_v_dim;

    const float *conv = conv_batch + static_cast<uint64_t>(b) * conv_stride;
    const float q = conv[q_offset + tid];
    const float k = conv[k_offset + tid];
    const float v_j = conv[v_offset + j];
    const float a_v = alpha_batch[static_cast<uint64_t>(b) * alpha_stride + vh];
    const float b_v = beta_batch[static_cast<uint64_t>(b) * beta_stride + vh];

    const float g_raw = log1pf(expf(a_v + dt_bias[vh])) * ssm_a[vh];
    const float eg = expf(g_raw);
    const float beta_sigmoid = 1.0f / (1.0f + expf(-b_v));
    float row_val = row[tid] * eg;

    scratch[tid] = row_val * k;
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float delta = (v_j - scratch[0]) * beta_sigmoid;
    row_val += delta * k;
    row[tid] = row_val;

    scratch[tid] = row_val * q;
    __syncthreads();
    for (uint32_t s = 64; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        const float inv_hvd = rsqrtf(static_cast<float>(head_v_dim));
        core[static_cast<uint64_t>(b) * core_stride + vh * head_v_dim + j] =
            scratch[0] * inv_hvd;
    }
}

__global__ void deltanet_ragged_batch_kernel(
                                      float *core,              // [total_q, *]
                                      float *state,             // [B, state_stride]
                                      const float *conv_batch,  // [total_q, *]
                                      const float *alpha_batch, // [total_q, *]
                                      const float *beta_batch,  // [total_q, *]
                                      const int32_t *q_indptr,
                                      const float *ssm_a,
                                      const float *dt_bias,
                                      float *state_checkpoints,
                                      uint32_t B,
                                      uint32_t num_k_heads,
                                      uint32_t num_v_heads,
                                      uint32_t head_k_dim,
                                      uint32_t head_v_dim,
                                      uint32_t conv_stride,
                                      uint32_t alpha_stride,
                                      uint32_t beta_stride,
                                      uint32_t core_stride,
                                      uint32_t state_stride,
                                      uint32_t checkpoint_count) {
    const uint32_t b = blockIdx.x;
    const uint32_t vh = blockIdx.y;
    const uint32_t j = blockIdx.z;
    const uint32_t tid = threadIdx.x;
    if (b >= B || vh >= num_v_heads || j >= head_v_dim ||
        tid >= head_k_dim) return;
    const int32_t begin_i = q_indptr[b];
    const int32_t end_i = q_indptr[b + 1];
    if (begin_i < 0 || end_i < begin_i) return;
    const uint32_t begin = static_cast<uint32_t>(begin_i);
    const uint32_t end = static_cast<uint32_t>(end_i);

    __shared__ float scratch[128];
    float *row = state + static_cast<uint64_t>(b) * state_stride +
                 (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim;

    const uint32_t kh = vh % num_k_heads;
    const uint32_t q_offset = kh * head_k_dim;
    const uint32_t k_offset = num_k_heads * head_k_dim + kh * head_k_dim;
    const uint32_t v_offset = 2u * num_k_heads * head_k_dim + vh * head_v_dim;
    const float ssm_a_v = ssm_a[vh];
    const float dt_bias_v = dt_bias[vh];
    const float inv_hvd = rsqrtf(static_cast<float>(head_v_dim));
    float row_val = row[tid];

    for (uint32_t t = begin; t < end; ++t) {
        const float *conv = conv_batch + static_cast<uint64_t>(t) * conv_stride;
        const float q = conv[q_offset + tid];
        const float k = conv[k_offset + tid];
        const float v_j = conv[v_offset + j];
        const float a_v = alpha_batch[static_cast<uint64_t>(t) * alpha_stride + vh];
        const float b_v = beta_batch[static_cast<uint64_t>(t) * beta_stride + vh];

        const float g_raw = log1pf(expf(a_v + dt_bias_v)) * ssm_a_v;
        const float eg = expf(g_raw);
        const float beta_sigmoid = 1.0f / (1.0f + expf(-b_v));

        row_val *= eg;
        scratch[tid] = row_val * k;
        __syncthreads();
        for (uint32_t s = 64; s > 0; s >>= 1) {
            if (tid < s) scratch[tid] += scratch[tid + s];
            __syncthreads();
        }
        const float delta = (v_j - scratch[0]) * beta_sigmoid;
        row_val += delta * k;
        scratch[tid] = row_val * q;
        __syncthreads();
        for (uint32_t s = 64; s > 0; s >>= 1) {
            if (tid < s) scratch[tid] += scratch[tid + s];
            __syncthreads();
        }
        if (tid == 0) {
            core[static_cast<uint64_t>(t) * core_stride +
                 vh * head_v_dim + j] = scratch[0] * inv_hvd;
        }
        const uint32_t local_t = t - begin;
        if (state_checkpoints != nullptr && local_t < checkpoint_count) {
            const uint64_t checkpoint_stride =
                static_cast<uint64_t>(num_v_heads) * head_v_dim *
                head_k_dim;
            float *checkpoint_head =
                state_checkpoints +
                (static_cast<uint64_t>(b) * checkpoint_count + local_t) *
                    checkpoint_stride +
                (static_cast<uint64_t>(vh) * head_v_dim + j) * head_k_dim;
            checkpoint_head[tid] = row_val;
        }
        __syncthreads();
    }
    row[tid] = row_val;
}

// RMSnorm + gate, batched over T. Each block normalizes one (token, v_head)
// vector of length head_v_dim.
__global__ void recurrent_norm_gate_batch_kernel(float *core,            // [T, num_v_heads * head_v_dim]
                                                 const float *gate,       // [T, num_v_heads * head_v_dim]
                                                 const float *norm_w,     // [head_v_dim]
                                                 uint32_t T,
                                                 uint32_t num_v_heads,
                                                 uint32_t head_v_dim,
                                                 uint32_t core_stride,
                                                 uint32_t gate_stride,
                                                 float eps) {
    const uint32_t t  = blockIdx.x;
    const uint32_t vh = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (vh >= num_v_heads || t >= T || tid >= head_v_dim) return;
    __shared__ float scratch[256];
    float *block = core + static_cast<uint64_t>(t) * core_stride + vh * head_v_dim;
    const float *gblock = gate + static_cast<uint64_t>(t) * gate_stride + vh * head_v_dim;
    scratch[tid] = block[tid] * block[tid];
    __syncthreads();
    for (uint32_t s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float scale = rsqrtf(scratch[0] / static_cast<float>(head_v_dim) + eps);
    const float z = gblock[tid];
    block[tid] = block[tid] * scale * norm_w[tid] * (z / (1.0f + expf(-z)));
}

__global__ void rmsnorm_per_head_kernel(float *x,
                                        const float *w,
                                        uint32_t n_units,
                                        uint32_t per_unit_stride,
                                        uint32_t head_dim,
                                        uint32_t batch_stride,
                                        float eps) {
    const uint32_t b    = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (unit >= n_units) return;
    __shared__ float scratch[256];
    float *base = x + static_cast<uint64_t>(b) * batch_stride + unit * per_unit_stride;
    float sum = 0.0f;
    for (uint32_t i = tid; i < head_dim; i += blockDim.x) sum += base[i] * base[i];
    scratch[tid] = sum;
    __syncthreads();
    for (uint32_t s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float scale = rsqrtf(scratch[0] / static_cast<float>(head_dim) + eps);
    for (uint32_t i = tid; i < head_dim; i += blockDim.x) base[i] = base[i] * scale * w[i];
}

__global__ void rmsnorm_per_head_lazy_fp8_kernel(
        float *out,
        const float *raw,
        const float *activation_scales,
        const float *linear_weight_scales,
        const float *norm_weight,
        uint32_t batch,
        uint32_t batch_stride,
        uint32_t n_units,
        uint32_t per_unit_stride,
        uint32_t head_dim,
        uint32_t raw_stride,
        uint32_t row_offset,
        float eps) {
    const uint32_t token = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (token >= batch || unit >= n_units) return;

    __shared__ float sums[256];
    const uint32_t unit_offset = unit * per_unit_stride;
    float sum = 0.0f;
    for (uint32_t i = tid; i < head_dim; i += blockDim.x) {
        const uint32_t channel = unit_offset + i;
        const float value =
            raw[static_cast<uint64_t>(token) * raw_stride +
                row_offset + channel] *
            activation_scales[token] * linear_weight_scales[channel];
        sum += value * value;
    }
    sums[tid] = sum;
    __syncthreads();
    for (uint32_t step = blockDim.x / 2; step > 0; step >>= 1) {
        if (tid < step) sums[tid] += sums[tid + step];
        __syncthreads();
    }
    const float norm_scale =
        rsqrtf(sums[0] / static_cast<float>(head_dim) + eps);

    for (uint32_t i = tid; i < per_unit_stride; i += blockDim.x) {
        const uint32_t channel = unit_offset + i;
        float value =
            raw[static_cast<uint64_t>(token) * raw_stride +
                row_offset + channel] *
            activation_scales[token] * linear_weight_scales[channel];
        if (i < head_dim) value *= norm_scale * norm_weight[i];
        out[static_cast<uint64_t>(token) * batch_stride + channel] = value;
    }
}

__global__ void rope_partial_kernel(float *x,
                                    uint32_t n_units,
                                    uint32_t per_unit_stride,
                                    uint32_t rope_dim,
                                    uint32_t base_pos,
                                    uint32_t batch_stride,
                                    float theta) {
    const uint32_t b    = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t i = threadIdx.x;
    if (unit >= n_units) return;
    const uint32_t half = rope_dim / 2;
    if (i >= half) return;
    float *base = x + static_cast<uint64_t>(b) * batch_stride + unit * per_unit_stride;
    const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) / static_cast<float>(rope_dim));
    const float angle = static_cast<float>(base_pos + b) * inv_freq;
    float c, s;
    __sincosf(angle, &s, &c);
    const float x0 = base[i];
    const float x1 = base[i + half];
    base[i]        = x0 * c - x1 * s;
    base[i + half] = x0 * s + x1 * c;
}

__global__ void rmsnorm_rope_qk_kernel(float *q,
                                       float *k,
                                       const float *q_weight,
                                       const float *k_weight,
                                       uint32_t n_q_heads,
                                       uint32_t n_kv_heads,
                                       uint32_t q_head_stride,
                                       uint32_t k_head_stride,
                                       uint32_t head_dim,
                                       uint32_t rope_dim,
                                       uint32_t pos,
                                       float theta,
                                       float eps) {
    const uint32_t unit = blockIdx.x;
    const bool is_q = unit < n_q_heads;
    const uint32_t head = is_q ? unit : unit - n_q_heads;
    if ((!is_q && head >= n_kv_heads) || threadIdx.x >= 256) return;

    float *base = is_q
        ? q + static_cast<uint64_t>(head) * q_head_stride
        : k + static_cast<uint64_t>(head) * k_head_stride;
    const float *weight = is_q ? q_weight : k_weight;
    __shared__ float scratch[256];
    const uint32_t tid = threadIdx.x;

    float sum = 0.0f;
    for (uint32_t i = tid; i < head_dim; i += blockDim.x) {
        sum += base[i] * base[i];
    }
    scratch[tid] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) scratch[tid] += scratch[tid + stride];
        __syncthreads();
    }
    const float norm_scale =
        rsqrtf(scratch[0] / static_cast<float>(head_dim) + eps);
    for (uint32_t i = tid; i < head_dim; i += blockDim.x) {
        base[i] = base[i] * norm_scale * weight[i];
    }
    __syncthreads();

    const uint32_t half = rope_dim / 2;
    if (tid >= half) return;
    const float inv_freq =
        __powf(theta,
               -2.0f * static_cast<float>(tid) /
                   static_cast<float>(rope_dim));
    float sin_value;
    float cos_value;
    __sincosf(static_cast<float>(pos) * inv_freq,
              &sin_value, &cos_value);
    const float x0 = base[tid];
    const float x1 = base[tid + half];
    base[tid] = x0 * cos_value - x1 * sin_value;
    base[tid + half] = x0 * sin_value + x1 * cos_value;
}

__global__ void rope_partial_positions_kernel(float *x,
                                              uint32_t n_units,
                                              uint32_t per_unit_stride,
                                              uint32_t rope_dim,
                                              const int32_t *positions,
                                              uint32_t batch_stride,
                                              float theta) {
    const uint32_t b    = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t i = threadIdx.x;
    if (unit >= n_units) return;
    const uint32_t half = rope_dim / 2;
    if (i >= half) return;
    float *base = x + static_cast<uint64_t>(b) * batch_stride + unit * per_unit_stride;
    const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) / static_cast<float>(rope_dim));
    const float angle = static_cast<float>(positions[b]) * inv_freq;
    float c, s;
    __sincosf(angle, &s, &c);
    const float x0 = base[i];
    const float x1 = base[i + half];
    base[i]        = x0 * c - x1 * s;
    base[i + half] = x0 * s + x1 * c;
}

// Re-RoPE delta rotation for block-sparse KV reuse. A cached K row was baked
// with RoPE at its original absolute position (k_stored = R(p_orig·f)·k_raw).
// To reuse it at a remapped position p_new we apply a single delta rotation
// R((p_new-p_orig)·f), since RoPE composes: R(a)·R(b) = R(a+b). All tokens in
// a contiguous block share the same delta = p_new_start - p_orig_start, so the
// rotation angle depends only on the freq channel i and the constant delta.
// Operates on fp32 rows (a staging copy of the block's K), in place.
//   grid = (n_tokens, n_units[=n_kv_heads]), block = rope_dim/2 threads.
__global__ void rope_block_remap_kernel(float *x,
                                        uint32_t n_units,
                                        uint32_t per_unit_stride,
                                        uint32_t rope_dim,
                                        int32_t orig_base,
                                        int32_t new_base,
                                        uint32_t row_stride,
                                        float theta) {
    const uint32_t tok  = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t i = threadIdx.x;
    if (unit >= n_units) return;
    const uint32_t half = rope_dim / 2;
    if (i >= half) return;
    float *base = x + static_cast<uint64_t>(tok) * row_stride + unit * per_unit_stride;
    // Re-RoPE by de-rotating the original bake and re-rotating at the new
    // window position. Both rotations use the SAME __powf/__sincosf production
    // uses (rope_partial_kernel), so this reproduces a fresh bake at new_base
    // to fp ULP. Crucially the de-rotation reuses the SAME (sin,cos) as the
    // original bake (applied as the transpose, R(θ)^T·R(θ)=I), so __sincosf's
    // range-reduction error at a huge orig position (~1M for a block pulled
    // from a long context) CANCELS instead of being left stale in the key.
    const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) / static_cast<float>(rope_dim));
    const float ang_o = static_cast<float>(orig_base + static_cast<int32_t>(tok)) * inv_freq;
    const float ang_n = static_cast<float>(new_base + static_cast<int32_t>(tok)) * inv_freq;
    float so, co, sn, cn;
    __sincosf(ang_o, &so, &co);
    __sincosf(ang_n, &sn, &cn);
    const float x0 = base[i];
    const float x1 = base[i + half];
    // De-rotate by orig (transpose of R(ang_o)): undo the stored bake.
    const float d0 =  x0 * co + x1 * so;
    const float d1 = -x0 * so + x1 * co;
    // Re-rotate at the new window position.
    base[i]        = d0 * cn - d1 * sn;
    base[i + half] = d0 * sn + d1 * cn;
}

// Paged, in-place re-RoPE on the STORED KV cache (block-sparse assembly, #39).
//
// Unlike rope_block_remap_kernel (contiguous fp32, used by the #38 math gold
// standard), this operates on the live paged cache exactly where the K is
// stored: dtype is fp16 or fp32, and each window token maps to a physical slot
// through the page table (kv_physical_pos_from_pages), mirroring
// kv_append_paged_kernel_f16's indexing byte-for-byte. The block occupies
// logical window positions [win_base .. win_base+n_tokens) in the page table;
// the key there was baked at original position orig_base+tok and is rotated to
// new_base+tok. De-rotate/re-rotate with the SAME __sincosf as the bake so the
// huge-orig range-reduction error cancels (see rope_block_remap_kernel comment).
//
// Per (token, kv_head) row layout in the cache slot is [n_kv_heads, head_dim];
// RoPE touches only the first rope_dim of each head. grid = (n_tokens, n_units),
// block = rope_dim/2 threads.
__device__ __forceinline__ uint32_t kv_physical_pos_from_pages(
        uint32_t logical_pos, const int32_t *page_indices, uint32_t page_size);
template <typename T>
__global__ void rope_block_remap_paged_kernel(T *cache,
                                              uint32_t per_pos_size,
                                              uint32_t head_dim,
                                              uint32_t rope_dim,
                                              uint32_t win_base,
                                              int32_t orig_base,
                                              int32_t new_base,
                                              const int32_t *page_indices,
                                              uint32_t page_size,
                                              float theta) {
    const uint32_t tok  = blockIdx.x;   // 0..n_tokens-1 within the block
    const uint32_t unit = blockIdx.y;   // kv head
    const uint32_t i = threadIdx.x;
    const uint32_t half = rope_dim / 2;
    if (i >= half) return;
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(win_base + tok, page_indices, page_size);
    T *base = cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
              static_cast<uint64_t>(unit) * head_dim;
    const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) / static_cast<float>(rope_dim));
    const float ang_o = static_cast<float>(orig_base + static_cast<int32_t>(tok)) * inv_freq;
    const float ang_n = static_cast<float>(new_base + static_cast<int32_t>(tok)) * inv_freq;
    float so, co, sn, cn;
    __sincosf(ang_o, &so, &co);
    __sincosf(ang_n, &sn, &cn);
    const float x0 = static_cast<float>(base[i]);
    const float x1 = static_cast<float>(base[i + half]);
    const float d0 =  x0 * co + x1 * so;
    const float d1 = -x0 * so + x1 * co;
    base[i]        = static_cast<T>(d0 * cn - d1 * sn);
    base[i + half] = static_cast<T>(d0 * sn + d1 * cn);
}

// Batched re-RoPE: one launch handles all moved blocks for a layer. grid =
// (max_n_tokens, n_kv_heads, n_blocks); blockIdx.z selects the block and pulls
// its window slot (to_base), original bake (from_base) and token count from
// device arrays. The per-(tok,unit,i) math is identical to the scalar kernel, so
// the result is byte-for-byte the same as issuing it once per block.
template <typename T>
__global__ void rope_block_remap_paged_batched_kernel(
        T *cache, uint32_t per_pos_size, uint32_t head_dim, uint32_t rope_dim,
        const int32_t *to_base, const int32_t *from_base,
        const int32_t *n_tokens, const int32_t *page_indices,
        uint32_t page_size, float theta) {
    const uint32_t bz   = blockIdx.z;   // which moved block
    const uint32_t tok  = blockIdx.x;   // token within the block
    const uint32_t unit = blockIdx.y;   // kv head
    const uint32_t i = threadIdx.x;
    const uint32_t half = rope_dim / 2;
    if (i >= half) return;
    if (tok >= static_cast<uint32_t>(n_tokens[bz])) return;  // partial-block guard
    const int32_t orig_base = from_base[bz];
    const int32_t new_base  = to_base[bz];
    if (orig_base == new_base) return;  // already at target slot: skip (no write)
    const uint32_t win_base = static_cast<uint32_t>(new_base);
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(win_base + tok, page_indices, page_size);
    T *base = cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
              static_cast<uint64_t>(unit) * head_dim;
    const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) / static_cast<float>(rope_dim));
    const float ang_o = static_cast<float>(orig_base + static_cast<int32_t>(tok)) * inv_freq;
    const float ang_n = static_cast<float>(new_base + static_cast<int32_t>(tok)) * inv_freq;
    float so, co, sn, cn;
    __sincosf(ang_o, &so, &co);
    __sincosf(ang_n, &sn, &cn);
    const float x0 = static_cast<float>(base[i]);
    const float x1 = static_cast<float>(base[i + half]);
    const float d0 =  x0 * co + x1 * so;
    const float d1 = -x0 * so + x1 * co;
    base[i]        = static_cast<T>(d0 * cn - d1 * sn);
    base[i + half] = static_cast<T>(d0 * sn + d1 * cn);
}

// Rebuild paged K from an unrotated packed source. Unlike the delta-remap
// kernel above, this writes every head dimension: the RoPE prefix is rotated
// directly from raw values and the non-RoPE suffix is copied unchanged.
template <typename T>
__global__ void raw_k_scatter_rope_paged_batched_kernel(
        T *cache, const T *raw_k, uint64_t raw_element_offset,
        uint64_t raw_block_stride_elements,
        uint32_t max_n_tokens, uint32_t per_pos_size, uint32_t head_dim,
        uint32_t rope_dim, const int32_t *to_base, const int32_t *n_tokens,
        const int32_t *page_indices, uint32_t page_size, float theta) {
    const uint32_t bz = blockIdx.z;
    const uint32_t tok = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t d = threadIdx.x;
    if (tok >= static_cast<uint32_t>(n_tokens[bz]) || d >= head_dim) return;

    const uint64_t block_stride = raw_block_stride_elements != 0
        ? raw_block_stride_elements
        : static_cast<uint64_t>(max_n_tokens) * per_pos_size;
    const uint64_t src_row =
        static_cast<uint64_t>(bz) * block_stride +
        static_cast<uint64_t>(tok) * per_pos_size +
        static_cast<uint64_t>(unit) * head_dim;
    const T *src = raw_k + raw_element_offset + src_row;
    const uint32_t logical_pos =
        static_cast<uint32_t>(to_base[bz]) + tok;
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(logical_pos, page_indices, page_size);
    T *dst = cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
             static_cast<uint64_t>(unit) * head_dim;

    if (d >= rope_dim) {
        dst[d] = src[d];
        return;
    }
    const uint32_t half = rope_dim / 2;
    const uint32_t pair = d < half ? d : d - half;
    const float x0 = static_cast<float>(src[pair]);
    const float x1 = static_cast<float>(src[pair + half]);
    const float inv_freq = __powf(
        theta, -2.0f * static_cast<float>(pair) /
                   static_cast<float>(rope_dim));
    float s, c;
    __sincosf(static_cast<float>(logical_pos) * inv_freq, &s, &c);
    const float out = d < half ? (x0 * c - x1 * s)
                               : (x0 * s + x1 * c);
    dst[d] = static_cast<T>(out);
}

// Persistent KVMem assembly table. Each entry is the exact FP32 result of the
// legacy per-element powf/sincosf sequence:
//   [position, rope_pair] -> {sin(position * inv_freq), cos(...)}.
// Keeping FP32 values preserves the old rotation arithmetic while allowing all
// heads and all standard-attention layers to share the transcendental work.
__global__ void build_rope_sincos_table_kernel(
        float2 *table, uint32_t positions, uint32_t half, uint32_t rope_dim,
        float theta) {
    const uint64_t linear =
        static_cast<uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const uint64_t total = static_cast<uint64_t>(positions) * half;
    if (linear >= total) return;
    const uint32_t pair = static_cast<uint32_t>(linear % half);
    const uint32_t pos = static_cast<uint32_t>(linear / half);
    const float inv_freq = __powf(
        theta, -2.0f * static_cast<float>(pair) /
                   static_cast<float>(rope_dim));
    float s, c;
    __sincosf(static_cast<float>(pos) * inv_freq, &s, &c);
    table[linear] = make_float2(s, c);
}

template <typename T>
__global__ void rope_block_remap_paged_batched_table_kernel(
        T *cache, uint32_t per_pos_size, uint32_t head_dim,
        uint32_t rope_dim, const int32_t *to_base,
        const int32_t *from_base, const int32_t *n_tokens,
        const int32_t *page_indices, uint32_t page_size,
        const float2 *rope_sincos, uint32_t rope_table_positions) {
    const uint32_t bz = blockIdx.z;
    const uint32_t tok = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t pair = threadIdx.x;
    const uint32_t half = rope_dim / 2;
    if (pair >= half ||
        tok >= static_cast<uint32_t>(n_tokens[bz])) return;
    const int32_t orig_base = from_base[bz];
    const int32_t new_base = to_base[bz];
    if (orig_base == new_base) return;
    const int64_t orig_pos64 = static_cast<int64_t>(orig_base) + tok;
    const int64_t new_pos64 = static_cast<int64_t>(new_base) + tok;
    // The executor validates these ranges and promotes an out-of-table move to
    // immutable raw refresh. Retain a defensive guard for direct launcher use.
    if (orig_pos64 < 0 || new_pos64 < 0 ||
        static_cast<uint64_t>(orig_pos64) >= rope_table_positions ||
        static_cast<uint64_t>(new_pos64) >= rope_table_positions) {
        return;
    }
    const uint32_t new_pos = static_cast<uint32_t>(new_pos64);
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(new_pos, page_indices, page_size);
    T *base = cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
              static_cast<uint64_t>(unit) * head_dim;
    const float2 old_sc =
        rope_sincos[static_cast<uint64_t>(orig_pos64) * half + pair];
    const float2 new_sc =
        rope_sincos[static_cast<uint64_t>(new_pos) * half + pair];
    const float so = old_sc.x;
    const float co = old_sc.y;
    const float sn = new_sc.x;
    const float cn = new_sc.y;
    const float x0 = static_cast<float>(base[pair]);
    const float x1 = static_cast<float>(base[pair + half]);
    const float d0 = x0 * co + x1 * so;
    const float d1 = -x0 * so + x1 * co;
    base[pair] = static_cast<T>(d0 * cn - d1 * sn);
    base[pair + half] = static_cast<T>(d0 * sn + d1 * cn);
}

template <typename T>
__global__ void raw_k_scatter_rope_paged_batched_table_kernel(
        T *cache, const T *raw_k, uint64_t raw_element_offset,
        uint64_t raw_block_stride_elements,
        uint32_t max_n_tokens, uint32_t per_pos_size, uint32_t head_dim,
        uint32_t rope_dim, const int32_t *to_base, const int32_t *n_tokens,
        const int32_t *page_indices, uint32_t page_size,
        const float2 *rope_sincos, uint32_t rope_table_positions) {
    const uint32_t bz = blockIdx.z;
    const uint32_t tok = blockIdx.x;
    const uint32_t unit = blockIdx.y;
    const uint32_t lane = threadIdx.x;
    if (tok >= static_cast<uint32_t>(n_tokens[bz])) return;

    const uint64_t block_stride = raw_block_stride_elements != 0
        ? raw_block_stride_elements
        : static_cast<uint64_t>(max_n_tokens) * per_pos_size;
    const uint64_t src_row =
        static_cast<uint64_t>(bz) * block_stride +
        static_cast<uint64_t>(tok) * per_pos_size +
        static_cast<uint64_t>(unit) * head_dim;
    const T *src = raw_k + raw_element_offset + src_row;
    const int64_t logical_pos64 =
        static_cast<int64_t>(to_base[bz]) + tok;
    if (logical_pos64 < 0 ||
        static_cast<uint64_t>(logical_pos64) >= rope_table_positions) {
        return;
    }
    const uint32_t logical_pos = static_cast<uint32_t>(logical_pos64);
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(logical_pos, page_indices, page_size);
    T *dst = cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
             static_cast<uint64_t>(unit) * head_dim;

    const uint32_t half = rope_dim / 2;
    if (lane < half) {
        const float x0 = static_cast<float>(src[lane]);
        const float x1 = static_cast<float>(src[lane + half]);
        const float2 sc =
            rope_sincos[static_cast<uint64_t>(logical_pos) * half + lane];
        dst[lane] =
            static_cast<T>(x0 * sc.y - x1 * sc.x);
        dst[lane + half] =
            static_cast<T>(x0 * sc.x + x1 * sc.y);
    }
    // General partial-RoPE support. Qwen3.6 has head_dim=rope_dim, but keeping
    // this loop makes the table path equivalent for models with a suffix.
    for (uint32_t d = rope_dim + lane; d < head_dim; d += blockDim.x) {
        dst[d] = src[d];
    }
}

// ---- Block-sparse cumulative-attention selection signal (#40) -----------
//
// Low-intrusion: instead of materializing the attention score matrix (the
// FlashInfer decode kernel is online-softmax and never forms it), we keep a
// per-window-block representative K vector (the block's mean baked K) and, each
// decode step, score every window block by q . k̄ summed over query heads. This
// is a cheap monotone proxy for "how much this block is attended to" — it does
// NOT touch the attention kernel or alter its output, and runs as one extra
// global launch per step at a single representative attention layer.
//
// block_kmean_paged_kernel: per window block w and kv head h, average the baked
// K over the block's tokens. grid = (n_blocks_w, n_kv_heads), block = head_dim
// threads (each thread owns one dim d). win_base[w]/blk_tokens[w] give the
// block's window position range; physical slots come through the window page
// table exactly like rope_block_remap_paged_kernel. Output kbar is fp32,
// layout [n_blocks_w, n_kv_heads, head_dim].
__device__ __forceinline__ uint32_t kv_physical_pos_from_pages(
        uint32_t logical_pos, const int32_t *page_indices, uint32_t page_size);
template <typename T, typename KbarT>
__global__ void block_kmean_paged_kernel(const T *k_cache,
                                         KbarT *kbar,
                                         uint32_t per_pos_size,
                                         uint32_t head_dim,
                                         const int32_t *win_base,
                                         const int32_t *blk_tokens,
                                         const int32_t *page_indices,
                                         uint32_t page_size) {
    const uint32_t w = blockIdx.x;     // window block index
    const uint32_t h = blockIdx.y;     // kv head
    const uint32_t d = threadIdx.x;    // dim within head
    if (d >= head_dim) return;
    const uint32_t base = static_cast<uint32_t>(win_base[w]);
    const uint32_t n = static_cast<uint32_t>(blk_tokens[w]);
    float acc = 0.0f;
    for (uint32_t tok = 0; tok < n; ++tok) {
        const uint32_t physical_pos =
            kv_physical_pos_from_pages(base + tok, page_indices, page_size);
        const T *row = k_cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
                       static_cast<uint64_t>(h) * head_dim;
        acc += static_cast<float>(row[d]);
    }
    const float inv = (n > 0) ? (1.0f / static_cast<float>(n)) : 0.0f;
    kbar[(static_cast<uint64_t>(w) * gridDim.y + h) * head_dim + d] =
        static_cast<KbarT>(acc * inv);
}

// block_attn_score_step_kernel: for the current decode token's RoPE-baked Q,
// add to each window block's accumulator the sum over query heads of
// max(0, scale * (q_head . k̄_block[kv_head])). One CUDA block per window block
// (no cross-block atomics needed; each writes its own accum slot). blockDim =
// head_dim threads doing a shared-memory dot reduction per head.
template <typename KbarT>
__global__ void block_attn_score_step_kernel(float *accum,
                                             const float *q,
                                             const KbarT *kbar,
                                             uint32_t q_stride,
                                             uint32_t n_heads,
                                             uint32_t n_kv_heads,
                                             uint32_t head_dim,
                                             float scale) {
    extern __shared__ float red[];
    const uint32_t w = blockIdx.x;
    const uint32_t d = threadIdx.x;
    const uint32_t group = n_heads / n_kv_heads;
    float block_score = 0.0f;
    for (uint32_t qh = 0; qh < n_heads; ++qh) {
        const uint32_t kvh = qh / group;
        const float qv = (d < head_dim) ? q[qh * q_stride + d] : 0.0f;
        const float kv = (d < head_dim)
            ? static_cast<float>(
                  kbar[(static_cast<uint64_t>(w) * n_kv_heads + kvh) *
                           head_dim +
                       d])
            : 0.0f;
        red[d] = qv * kv;
        __syncthreads();
        for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (d < s) red[d] += red[d + s];
            __syncthreads();
        }
        if (d == 0) {
            const float dot = red[0] * scale;
            block_score += dot > 0.0f ? dot : 0.0f;
        }
        __syncthreads();
    }
    if (d == 0) accum[w] += block_score;
}

// block_attn_score_softmax_pages_kernel: one CUDA block per (layer,token). For
// each query head it computes logit[w] = scale·(q[l,t,h]·k̄[l,w,h/group]) for every
// page w, softmaxes those logits OVER PAGES, then atomicAdds (1/(L·H))·softmax_w
// into the global score[w]. Summed across the (L·n_tokens) grid this gives
//   score[w] = Σ_t mean_l mean_h softmax_w(scale·(q·k̄)),
// the accumulated attention mass each page receives. score must be pre-zeroed.
// Page logits live in dynamic shared memory s_logit[n_blocks]; the per-head
// max/sum reductions are serialized on thread 0 (n_blocks is small, ~hundreds).
// reduce_max (default 0): with n_subblocks>1, score each block by its best
// sub-block's mass (max over sub-blocks) instead of the sum, so score[w] =
// Σ_t mean_l mean_h max_sb softmax(scale·(q·k̄_{w,sb})) — MaxSim late interaction.
// reduce_max is a no-op at n_subblocks==1 (single sub-block => max == sum).
template <typename QueryT, typename KbarT>
__global__ void block_attn_score_softmax_pages_kernel(
                                                      float *score,
                                                      const QueryT *q_multi,
                                                      const KbarT *kbar_multi,
                                                      const int32_t *group_begin,
                                                      const int32_t *group_end,
                                                      uint32_t n_groups,
                                                      uint32_t n_layers,
                                                      uint32_t n_tokens,
                                                      uint32_t q_layer_stride,
                                                      uint32_t n_blocks,
                                                      uint32_t kbar_layer_stride,
                                                      uint32_t n_heads,
                                                      uint32_t n_kv_heads,
                                                      uint32_t head_dim,
                                                      float scale,
                                                      uint32_t excl_lo_end,
                                                      uint32_t excl_hi_begin,
                                                      uint32_t n_subblocks,
                                                      uint32_t reduce_max) {
    const uint32_t lt = blockIdx.x;
    const uint32_t l = lt / n_tokens;
    const uint32_t t = lt % n_tokens;
    if (l >= n_layers) return;
    extern __shared__ float s_logit[];   // [n_blocks * n_subblocks]
    __shared__ float s_max;
    __shared__ float s_sum;
    const uint32_t tid = threadIdx.x;
    const uint32_t nthreads = blockDim.x;
    const uint32_t group = n_heads / n_kv_heads;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    // Softmax runs at SUB-BLOCK granularity: total = n_blocks*n_subblocks logits.
    // logit index p maps to block w = p/n_subblocks, sub-block sb = p%n_subblocks.
    // A block's sub-block masses are summed back into score[w] at the end, so a
    // concentrated relevant sub-region keeps its mass instead of being diluted by
    // the block mean. n_subblocks==1 (plain mean-k) => total==n_blocks, p==w,
    // byte-identical to the pre-sub-block path.
    const uint32_t total = n_blocks * n_subblocks;
    // Per-layer base uses kbar_layer_stride (in blocks) × n_subblocks. The stride
    // may exceed n_blocks when g_kbar_multi_ is allocated at a fixed session stride
    // (ctx_blocks) so preserved [0,D) slices stay valid as the block count grows.
    // n_blocks remains the loop/count bound. Callers that don't fix-stride pass
    // kbar_layer_stride == n_blocks (byte-identical).
    const KbarT *kbar_l =
        kbar_multi +
        static_cast<uint64_t>(l) * kbar_layer_stride * n_subblocks * n_kv_heads *
            head_dim;
    const QueryT *q_l =
        q_multi + static_cast<uint64_t>(l) * q_layer_stride * qrow;
    // Per-head weight: each (layer,token) contributes mean over heads, and the
    // grid sum over layers must end up as a mean over L. n_tokens is summed (not
    // averaged) so the final score accumulates one unit of mass per query token.
    const float head_w = 1.0f / (static_cast<float>(n_layers) *
                                 static_cast<float>(n_heads));
    for (uint32_t qh = 0; qh < n_heads; ++qh) {
        const uint32_t kvh = qh / group;
        const QueryT *qr =
            q_l + (static_cast<uint64_t>(t) * n_heads + qh) * head_dim;
        // logit[p] = scale * dot(q[l,t,qh], k̄[l,w,sb,kvh]) for every sub-block.
        // Sub-blocks of a block in the always-kept sink/recent bands
        // [0,excl_lo_end) / [excl_hi_begin,n_blocks) are masked to -inf so their
        // softmax mass redistributes onto the retrievable middle (they are pinned).
        for (uint32_t p = tid; p < total; p += nthreads) {
            const uint32_t w = p / n_subblocks;
            if (w < excl_lo_end || w >= excl_hi_begin) {
                s_logit[p] = -INFINITY;
                continue;
            }
            const KbarT *kbar_row =
                kbar_l + (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; ++d) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kbar_row[d]);
            }
            s_logit[p] = dot * scale;
        }
        __syncthreads();
        if (tid == 0) {
            float m = -INFINITY;
            for (uint32_t p = 0; p < total; ++p) m = fmaxf(m, s_logit[p]);
            s_max = m;
        }
        __syncthreads();
        const float m = s_max;
        for (uint32_t p = tid; p < total; p += nthreads) {
            s_logit[p] = __expf(s_logit[p] - m);
        }
        __syncthreads();
        if (tid == 0) {
            float sum = 0.0f;
            for (uint32_t p = 0; p < total; ++p) sum += s_logit[p];
            s_sum = sum > 0.0f ? sum : 1.0f;
        }
        __syncthreads();
        const float inv = head_w / s_sum;
        if (n_groups > 0 && group_begin && group_end) {
            // Semantic retrieval: reduce the globally normalized attention
            // probabilities over each variable-length group. reduce_max keeps
            // the existing MaxSim behavior; zero produces true group mass.
            for (uint32_t g = tid; g < n_groups; g += nthreads) {
                const uint32_t p0 = static_cast<uint32_t>(
                    max(group_begin[g], 0));
                const uint32_t p1 = min(
                    static_cast<uint32_t>(max(group_end[g], 0)), total);
                float mass = 0.0f;
                for (uint32_t p = p0; p < p1; ++p) {
                    mass = reduce_max
                        ? fmaxf(mass, s_logit[p])
                        : mass + s_logit[p];
                }
                atomicAdd(&score[g], mass * inv);
            }
        } else if (reduce_max && n_subblocks > 1) {
            // MaxSim-style reduction: score each block by its single best
            // sub-block's softmax mass (max over the document side), still
            // summed across query tokens / heads / layers by the grid atomicAdd.
            // Counters the block mean's dilution of a concentrated sub-region.
            // Masked bands have s_logit==0 (post-exp of -inf) so a fully-masked
            // block contributes 0, matching the sum path. n_subblocks==1 falls
            // through to the sum branch (byte-identical, single sub-block/block).
            for (uint32_t w = tid; w < n_blocks; w += nthreads) {
                float mx = 0.0f;
                for (uint32_t sb = 0; sb < n_subblocks; ++sb)
                    mx = fmaxf(mx, s_logit[w * n_subblocks + sb]);
                atomicAdd(&score[w], mx * inv);
            }
        } else {
            for (uint32_t p = tid; p < total; p += nthreads) {
                atomicAdd(&score[p / n_subblocks], s_logit[p] * inv);
            }
        }
        __syncthreads();  // s_logit reused by the next head
    }
}

// Scalable exact softmax-over-pages path for n_blocks*n_subblocks > the fused
// kernel's shared-memory cap.  Softmax is global per (layer, token, query-head),
// so CTAs first produce tile-local log-sum-exp pairs, a second kernel merges the
// pairs, and a final kernel recomputes the dots and writes one score per block.
// Recomputing avoids materialising O(L*M*H*pages) logits in global memory.
//
// The final kernel assigns one thread to one output block.  It therefore needs
// no atomicAdd even though it accumulates every (layer,token,head) distribution.
// This is deliberately a correctness-first baseline; the old one-CTA fused
// kernel remains the fast path for small page counts.
constexpr uint32_t kSoftmaxPagesTile = 512;
constexpr uint32_t kSoftmaxPagesThreads = 128;

template <typename QueryT, typename KbarT>
__global__ void block_attn_softmax_pages_partial_lse_kernel(
        float *partial_max,
        float *partial_sum,
        const QueryT *q_multi,
        const KbarT *kbar_multi,
        uint32_t n_distributions,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t n_blocks,
        uint32_t kbar_layer_stride,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks) {
    const uint64_t job = blockIdx.x;
    const uint32_t dist = static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(job -
                                                static_cast<uint64_t>(dist) * n_tiles);
    if (dist >= n_distributions) return;

    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint32_t total = n_blocks * n_subblocks;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 = min(p0 + kSoftmaxPagesTile, total);
    const uint32_t tid = threadIdx.x;

    __shared__ float logits[kSoftmaxPagesTile];
    __shared__ float reduce[kSoftmaxPagesThreads];

    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *q_l =
        q_multi + static_cast<uint64_t>(l) * q_layer_stride * qrow;
    const QueryT *qr =
        q_l + (static_cast<uint64_t>(t) * n_heads + qh) * head_dim;
    const KbarT *kbar_l =
        kbar_multi +
        static_cast<uint64_t>(l) * kbar_layer_stride * n_subblocks *
            n_kv_heads * head_dim;

    float local_max = -INFINITY;
    for (uint32_t p = p0 + tid; p < p1; p += blockDim.x) {
        const uint32_t w = p / n_subblocks;
        float logit = -INFINITY;
        if (w >= excl_lo_end && w < excl_hi_begin) {
            const KbarT *kbar_row =
                kbar_l + (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; ++d) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kbar_row[d]);
            }
            logit = dot * scale;
        }
        logits[p - p0] = logit;
        local_max = fmaxf(local_max, logit);
    }
    reduce[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] = fmaxf(reduce[tid], reduce[tid + s]);
        __syncthreads();
    }
    const float tile_max = reduce[0];

    float local_sum = 0.0f;
    if (isfinite(tile_max)) {
        for (uint32_t p = p0 + tid; p < p1; p += blockDim.x) {
            local_sum += __expf(logits[p - p0] - tile_max);
        }
    }
    reduce[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        partial_max[job] = tile_max;
        partial_sum[job] = reduce[0];
    }
}

__global__ void block_attn_softmax_pages_merge_lse_kernel(
        float *global_max,
        float *global_sum,
        const float *partial_max,
        const float *partial_sum,
        uint32_t n_distributions,
        uint32_t n_tiles) {
    const uint32_t dist = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (dist >= n_distributions) return;
    __shared__ float reduce[kSoftmaxPagesThreads];

    float local_max = -INFINITY;
    const uint64_t base = static_cast<uint64_t>(dist) * n_tiles;
    for (uint32_t tile = tid; tile < n_tiles; tile += blockDim.x) {
        local_max = fmaxf(local_max, partial_max[base + tile]);
    }
    reduce[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] = fmaxf(reduce[tid], reduce[tid + s]);
        __syncthreads();
    }
    const float m = reduce[0];

    float local_sum = 0.0f;
    if (isfinite(m)) {
        for (uint32_t tile = tid; tile < n_tiles; tile += blockDim.x) {
            const float tm = partial_max[base + tile];
            if (isfinite(tm)) {
                local_sum += partial_sum[base + tile] * __expf(tm - m);
            }
        }
    }
    reduce[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        global_max[dist] = m;
        global_sum[dist] = reduce[0];
    }
}

// Single-dot scalable scorer. The old tiled path above computes every Q·K twice
// to avoid storing logits. That is memory-frugal but becomes the dominant cost
// for long retrieval queries. This path materializes only a bounded batch of
// distributions, normalizes it, accumulates its block mass, then reuses the
// same workspace for the next batch. Each dot is computed exactly once.
//
// Four warps cooperate on one 512-page tile. A warp owns one page at a time and
// reads its head_dim elements contiguously, unlike the correctness-first
// two-dot kernel where adjacent threads read different page rows. This keeps
// Kbar loads coalesced while preserving FP32 dot accumulation.
template <typename QueryT, typename KbarT>
__global__ void block_attn_softmax_pages_logits_kernel(
        float *logits,
        const QueryT *q_multi,
        const KbarT *kbar_multi,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t n_blocks,
        uint32_t kbar_layer_stride,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks) {
    const uint64_t job = blockIdx.x;
    const uint32_t local_dist =
        static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(
        job - static_cast<uint64_t>(local_dist) * n_tiles);
    if (local_dist >= distribution_count) return;

    const uint32_t dist = distribution_base + local_dist;
    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint32_t total = n_blocks * n_subblocks;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 = min(p0 + kSoftmaxPagesTile, total);
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    constexpr uint32_t kWarps =
        kSoftmaxPagesThreads / 32;

    const uint64_t qrow =
        static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *q_l =
        q_multi +
        static_cast<uint64_t>(l) * q_layer_stride * qrow;
    const QueryT *qr =
        q_l +
        (static_cast<uint64_t>(t) * n_heads + qh) * head_dim;
    const KbarT *kbar_l =
        kbar_multi +
        static_cast<uint64_t>(l) * kbar_layer_stride *
            n_subblocks * n_kv_heads * head_dim;
    float *out =
        logits + static_cast<uint64_t>(local_dist) * total;

    for (uint32_t p = p0 + warp; p < p1; p += kWarps) {
        const uint32_t w = p / n_subblocks;
        float dot = 0.0f;
        if (w >= excl_lo_end && w < excl_hi_begin) {
            const KbarT *kbar_row =
                kbar_l +
                (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                    head_dim;
            for (uint32_t d = lane; d < head_dim; d += 32) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kbar_row[d]);
            }
#pragma unroll
            for (uint32_t offset = 16; offset > 0; offset >>= 1) {
                dot += __shfl_down_sync(0xffffffffu, dot, offset);
            }
        }
        if (lane == 0) {
            out[p] =
                (w >= excl_lo_end && w < excl_hi_begin)
                    ? dot * scale : -INFINITY;
        }
    }
}

// One CTA computes the global row max and denominator. Logits remain unchanged;
// the accumulation kernel applies exp(logit-max)/sum once, so no second dot and
// no extra normalized-logit write are needed.
__global__ void block_attn_softmax_pages_norm_kernel(
        float *row_max,
        float *row_inv_sum,
        const float *logits,
        uint32_t distribution_count,
        uint32_t total) {
    const uint32_t dist = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (dist >= distribution_count) return;
    __shared__ float reduce[kSoftmaxPagesThreads];
    const float *row =
        logits + static_cast<uint64_t>(dist) * total;

    float local_max = -INFINITY;
    for (uint32_t p = tid; p < total; p += blockDim.x) {
        local_max = fmaxf(local_max, row[p]);
    }
    reduce[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            reduce[tid] =
                fmaxf(reduce[tid], reduce[tid + s]);
        }
        __syncthreads();
    }
    const float m = reduce[0];
    float local_sum = 0.0f;
    if (isfinite(m)) {
        for (uint32_t p = tid; p < total; p += blockDim.x) {
            local_sum += __expf(row[p] - m);
        }
    }
    reduce[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        row_max[dist] = m;
        row_inv_sum[dist] =
            reduce[0] > 0.0f ? 1.0f / reduce[0] : 0.0f;
    }
}

// One thread owns one output block, so batches accumulate deterministically
// without atomics. Threads in a warp read adjacent block logits for each
// distribution, giving coalesced global-memory access.
__global__ void block_attn_softmax_pages_accumulate_logits_kernel(
        float *score,
        const float *logits,
        const float *row_max,
        const float *row_inv_sum,
        uint32_t distribution_count,
        uint32_t n_blocks,
        uint32_t n_subblocks,
        uint32_t reduce_max,
        float distribution_weight,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin) {
    const uint32_t w =
        blockIdx.x * blockDim.x + threadIdx.x;
    if (w >= n_blocks || w < excl_lo_end ||
        w >= excl_hi_begin) {
        return;
    }
    const uint32_t total = n_blocks * n_subblocks;
    float accum = 0.0f;
    for (uint32_t dist = 0; dist < distribution_count; ++dist) {
        const float inv = row_inv_sum[dist];
        if (!(inv > 0.0f)) continue;
        const float m = row_max[dist];
        const float *row =
            logits + static_cast<uint64_t>(dist) * total +
            static_cast<uint64_t>(w) * n_subblocks;
        float mass = 0.0f;
        if (reduce_max && n_subblocks > 1) {
            for (uint32_t sb = 0; sb < n_subblocks; ++sb) {
                mass = fmaxf(
                    mass, __expf(row[sb] - m) * inv);
            }
        } else {
            for (uint32_t sb = 0; sb < n_subblocks; ++sb) {
                mass += __expf(row[sb] - m) * inv;
            }
        }
        accum += mass;
    }
    score[w] += accum * distribution_weight;
}

// Group-aware counterpart for semantic retrieval. The expensive dot and
// softmax normalization are shared with the ordinary scalable scorer. A 2-D
// grid assigns one CTA to (group, distribution-tile): each thread scans one
// distribution over that group's sub-blocks, then the CTA reduces the tile to
// one atomic add. This keeps a ~400-group / ~12K-distribution 1M-token request
// highly parallel; assigning one thread per group would launch only four CTAs
// and serialize all distributions inside them.
__global__ void block_attn_softmax_groups_accumulate_logits_kernel(
        float *score,
        const float *logits,
        const float *row_max,
        const float *row_inv_sum,
        uint32_t distribution_count,
        uint32_t total,
        const int32_t *group_begin,
        const int32_t *group_end,
        uint32_t n_groups,
        uint32_t group_reduce_mass,
        float distribution_weight) {
    const uint32_t g = blockIdx.x;
    if (g >= n_groups) return;
    const uint32_t dist =
        blockIdx.y * blockDim.x + threadIdx.x;
    const uint32_t p0 = static_cast<uint32_t>(
        max(group_begin[g], 0));
    const uint32_t p1 = min(
        static_cast<uint32_t>(max(group_end[g], 0)), total);
    float mass = 0.0f;
    if (dist < distribution_count && p0 < p1) {
        const float inv = row_inv_sum[dist];
        if (inv > 0.0f) {
            const float m = row_max[dist];
            const float *row =
                logits + static_cast<uint64_t>(dist) * total;
            for (uint32_t p = p0; p < p1; ++p) {
                const float probability =
                    __expf(row[p] - m) * inv;
                mass = group_reduce_mass
                    ? mass + probability
                    : fmaxf(mass, probability);
            }
        }
    }
    __shared__ float reduce[kSoftmaxPagesThreads];
    reduce[threadIdx.x] = mass;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            reduce[threadIdx.x] += reduce[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        atomicAdd(&score[g], reduce[0] * distribution_weight);
    }
}

// Exact bounded-memory scorer for a host-streamed mean-K index. One CTA owns
// one (layer,query-token,query-head) distribution. The current host tile is
// small enough to keep all tile logits in dynamic shared memory, so every dot
// is computed once in pass 1 and reduced into an online global LSE pair.
template <typename QueryT, typename KbarT>
__global__ void block_attn_stream_lse_kernel(
        float *global_max,
        float *global_sum,
        const QueryT *q_multi,
        const KbarT *kbar_tile,
        uint32_t n_distributions,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t tile_blocks,
        uint32_t kbar_layer_stride,
        uint32_t global_block_base,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks,
        uint32_t initialize) {
    const uint32_t dist = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (dist >= n_distributions) return;
    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint32_t ns = n_subblocks == 0 ? 1u : n_subblocks;
    const uint32_t total = tile_blocks * ns;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(l) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;
    const KbarT *kbar_l =
        kbar_tile +
        static_cast<uint64_t>(l) * kbar_layer_stride * ns *
            n_kv_heads * head_dim;

    extern __shared__ float logits[];
    __shared__ float reduce[kSoftmaxPagesThreads];
    float local_max = -INFINITY;
    for (uint32_t p = tid; p < total; p += blockDim.x) {
        const uint32_t global_w = global_block_base + p / ns;
        float logit = -INFINITY;
        if (global_w >= excl_lo_end && global_w < excl_hi_begin) {
            const KbarT *kr =
                kbar_l +
                (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                    head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; ++d) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kr[d]);
            }
            logit = dot * scale;
        }
        logits[p] = logit;
        local_max = fmaxf(local_max, logit);
    }
    reduce[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] = fmaxf(reduce[tid], reduce[tid + s]);
        __syncthreads();
    }
    const float tile_max = reduce[0];
    float local_sum = 0.0f;
    if (isfinite(tile_max)) {
        for (uint32_t p = tid; p < total; p += blockDim.x) {
            local_sum += __expf(logits[p] - tile_max);
        }
    }
    reduce[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        const float tile_sum = reduce[0];
        if (initialize) {
            global_max[dist] = tile_max;
            global_sum[dist] = tile_sum;
        } else {
            const float old_max = global_max[dist];
            const float old_sum = global_sum[dist];
            const float merged_max = fmaxf(old_max, tile_max);
            float merged_sum = 0.0f;
            if (isfinite(old_max)) {
                merged_sum += old_sum * __expf(old_max - merged_max);
            }
            if (isfinite(tile_max)) {
                merged_sum += tile_sum * __expf(tile_max - merged_max);
            }
            global_max[dist] = merged_max;
            global_sum[dist] = merged_sum;
        }
    }
}

// Pass 2 for ordinary block selection. One CTA owns one physical block and
// parallelizes the distribution dimension. Each block belongs to exactly one
// streamed tile, so no inter-tile atomics are required.
template <typename QueryT, typename KbarT>
__global__ void block_attn_stream_score_kernel(
        float *score,
        const QueryT *q_multi,
        const KbarT *kbar_tile,
        const float *global_max,
        const float *global_sum,
        uint32_t n_distributions,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t tile_blocks,
        uint32_t kbar_layer_stride,
        uint32_t global_block_base,
        uint32_t n_layers,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks,
        uint32_t reduce_max,
        uint32_t accumulate) {
    const uint32_t w = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (w >= tile_blocks) return;
    const uint32_t global_w = global_block_base + w;
    __shared__ float reduce[kSoftmaxPagesThreads];
    float local = 0.0f;
    if (global_w >= excl_lo_end && global_w < excl_hi_begin) {
        const uint32_t group = n_heads / n_kv_heads;
        const uint32_t ns = n_subblocks == 0 ? 1u : n_subblocks;
        const uint64_t qrow =
            static_cast<uint64_t>(n_heads) * head_dim;
        for (uint32_t dist = tid; dist < n_distributions;
             dist += blockDim.x) {
            const float denom = global_sum[dist];
            if (!(denom > 0.0f)) continue;
            const uint32_t qh = dist % n_heads;
            const uint32_t lt = dist / n_heads;
            const uint32_t t = lt % n_tokens;
            const uint32_t l = lt / n_tokens;
            const uint32_t kvh = qh / group;
            const QueryT *qr =
                q_multi +
                (static_cast<uint64_t>(l) * q_layer_stride + t) *
                    qrow +
                static_cast<uint64_t>(qh) * head_dim;
            const KbarT *kbar_l =
                kbar_tile +
                static_cast<uint64_t>(l) * kbar_layer_stride * ns *
                    n_kv_heads * head_dim;
            float block_mass = 0.0f;
            for (uint32_t sb = 0; sb < ns; ++sb) {
                const uint32_t p = w * ns + sb;
                const KbarT *kr =
                    kbar_l +
                    (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                        head_dim;
                float dot = 0.0f;
                for (uint32_t d = 0; d < head_dim; ++d) {
                    dot += static_cast<float>(qr[d]) *
                           static_cast<float>(kr[d]);
                }
                const float mass =
                    __expf(dot * scale - global_max[dist]) / denom;
                block_mass =
                    reduce_max && ns > 1
                        ? fmaxf(block_mass, mass)
                        : block_mass + mass;
            }
            local += block_mass;
        }
    }
    reduce[tid] = local;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        const float value =
            reduce[0] /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
        if (accumulate) score[global_w] += value;
        else score[global_w] = value;
    }
}

// Pass-2 semantic-group update. One thread owns one
// (group,distribution) pair for the current tile, so sequential tile launches
// can update group_dist without atomics.
template <typename QueryT, typename KbarT>
__global__ void block_attn_stream_group_update_kernel(
        float *group_dist,
        const QueryT *q_multi,
        const KbarT *kbar_tile,
        const float *global_max,
        const float *global_sum,
        const int32_t *group_begin,
        const int32_t *group_end,
        uint32_t n_groups,
        uint32_t n_distributions,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t tile_blocks,
        uint32_t kbar_layer_stride,
        uint32_t global_block_base,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks,
        uint32_t group_reduce_mass) {
    const uint32_t g = blockIdx.x;
    const uint32_t dist =
        blockIdx.y * blockDim.x + threadIdx.x;
    if (g >= n_groups || dist >= n_distributions) return;
    const uint32_t ns = n_subblocks == 0 ? 1u : n_subblocks;
    const uint32_t tile_p0 = global_block_base * ns;
    const uint32_t tile_p1 = tile_p0 + tile_blocks * ns;
    const uint32_t p0 = max(
        static_cast<uint32_t>(max(group_begin[g], 0)), tile_p0);
    const uint32_t p1 = min(
        static_cast<uint32_t>(max(group_end[g], 0)), tile_p1);
    if (p0 >= p1) return;
    const float denom = global_sum[dist];
    if (!(denom > 0.0f)) return;
    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t kvh = qh / (n_heads / n_kv_heads);
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(l) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;
    const KbarT *kbar_l =
        kbar_tile +
        static_cast<uint64_t>(l) * kbar_layer_stride * ns *
            n_kv_heads * head_dim;
    float mass = 0.0f;
    for (uint32_t gp = p0; gp < p1; ++gp) {
        const uint32_t global_w = gp / ns;
        if (global_w < excl_lo_end || global_w >= excl_hi_begin) {
            continue;
        }
        const uint32_t local_p = gp - tile_p0;
        const KbarT *kr =
            kbar_l +
            (static_cast<uint64_t>(local_p) * n_kv_heads + kvh) *
                head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += static_cast<float>(qr[d]) *
                   static_cast<float>(kr[d]);
        }
        const float probability =
            __expf(dot * scale - global_max[dist]) / denom;
        mass = group_reduce_mass
            ? mass + probability
            : fmaxf(mass, probability);
    }
    float &dst =
        group_dist[static_cast<uint64_t>(g) * n_distributions + dist];
    dst = group_reduce_mass ? dst + mass : fmaxf(dst, mass);
}

__global__ void block_attn_stream_group_finalize_kernel(
        float *score,
        const float *group_dist,
        uint32_t n_groups,
        uint32_t n_distributions,
        float distribution_weight,
        uint32_t accumulate) {
    const uint32_t g = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (g >= n_groups) return;
    __shared__ float reduce[kSoftmaxPagesThreads];
    const float *row =
        group_dist + static_cast<uint64_t>(g) * n_distributions;
    float local = 0.0f;
    for (uint32_t dist = tid; dist < n_distributions;
         dist += blockDim.x) {
        local += row[dist];
    }
    reduce[tid] = local;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        const float value = reduce[0] * distribution_weight;
        if (accumulate) score[g] += value;
        else score[g] = value;
    }
}

constexpr uint32_t kAdaptivePrototypeTile = 1024;

// Production one-dot path for the packed Adaptive index. The bounded logits
// workspace is indexed by a layer-local prototype id; layer_offsets translates
// that id to the global packed row. Four/eight warps cooperate on a prototype
// tile so K rows are read contiguously within each warp.
template <typename QueryT, typename KbarT>
__global__ void block_attn_adaptive_logits_kernel(
        float *logits,
        const QueryT *q_multi,
        const KbarT *prototypes,
        const int32_t *layer_offsets,
        const int32_t *prototype_blocks,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t max_layer_prototypes) {
    const uint64_t job = blockIdx.x;
    const uint32_t local_dist =
        static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(
        job - static_cast<uint64_t>(local_dist) * n_tiles);
    if (local_dist >= distribution_count) return;

    const uint32_t dist = distribution_base + local_dist;
    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint32_t layer_begin =
        static_cast<uint32_t>(max(layer_offsets[l], 0));
    const uint32_t layer_end =
        static_cast<uint32_t>(max(layer_offsets[l + 1], 0));
    const uint32_t layer_count = layer_end - layer_begin;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 =
        min(p0 + kSoftmaxPagesTile, max_layer_prototypes);
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    constexpr uint32_t kWarps = kSoftmaxPagesThreads / 32;
    const uint64_t qrow =
        static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(l) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;
    float *out =
        logits +
        static_cast<uint64_t>(local_dist) * max_layer_prototypes;

    for (uint32_t local_p = p0 + warp; local_p < p1;
         local_p += kWarps) {
        float dot = 0.0f;
        bool included = false;
        if (local_p < layer_count) {
            const uint32_t p = layer_begin + local_p;
            const uint32_t block =
                static_cast<uint32_t>(max(prototype_blocks[p], 0));
            included =
                block >= excl_lo_end && block < excl_hi_begin;
            if (included) {
                const KbarT *kr =
                    prototypes +
                    (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                        head_dim;
                for (uint32_t d = lane; d < head_dim; d += 32u) {
                    dot += static_cast<float>(qr[d]) *
                           static_cast<float>(kr[d]);
                }
#pragma unroll
                for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
                    dot += __shfl_down_sync(
                        0xffffffffu, dot, offset);
                }
            }
        }
        if (lane == 0) {
            out[local_p] = included ? dot * scale : -INFINITY;
        }
    }
}

// GQA-specialized variant of the one-dot logits pass. Query heads that share
// one KV head are contiguous in the distribution layout, so load each K
// prototype once and form all of that group's dot products together. Qwen3.6
// uses 24 Q heads / 8 KV heads (GqaGroup=3), eliminating two of every three
// packed-index reads without changing the logits or their storage layout.
template <typename QueryT, typename KbarT, uint32_t GqaGroup>
__global__ void block_attn_adaptive_logits_gqa_kernel(
        float *logits,
        const QueryT *q_multi,
        const KbarT *prototypes,
        const int32_t *layer_offsets,
        const int32_t *prototype_blocks,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t max_layer_prototypes) {
    static_assert(GqaGroup >= 2 && GqaGroup <= 4);
    const uint64_t job = blockIdx.x;
    const uint32_t local_group =
        static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(
        job - static_cast<uint64_t>(local_group) * n_tiles);
    const uint32_t local_dist0 = local_group * GqaGroup;
    if (local_dist0 + GqaGroup > distribution_count) return;

    const uint32_t dist0 = distribution_base + local_dist0;
    const uint32_t qh0 = dist0 % n_heads;
    const uint32_t lt = dist0 / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t kvh = qh0 / GqaGroup;
    if (kvh >= n_kv_heads || qh0 % GqaGroup != 0) return;
    const uint32_t layer_begin =
        static_cast<uint32_t>(max(layer_offsets[l], 0));
    const uint32_t layer_end =
        static_cast<uint32_t>(max(layer_offsets[l + 1], 0));
    const uint32_t layer_count = layer_end - layer_begin;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 =
        min(p0 + kSoftmaxPagesTile, max_layer_prototypes);
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    constexpr uint32_t kWarps = kSoftmaxPagesThreads / 32;
    const uint64_t qrow =
        static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr0 =
        q_multi +
        (static_cast<uint64_t>(l) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh0) * head_dim;

    for (uint32_t local_p = p0 + warp; local_p < p1;
         local_p += kWarps) {
        float dot[GqaGroup] = {};
        bool included = false;
        if (local_p < layer_count) {
            const uint32_t p = layer_begin + local_p;
            const uint32_t block =
                static_cast<uint32_t>(max(prototype_blocks[p], 0));
            included =
                block >= excl_lo_end && block < excl_hi_begin;
            if (included) {
                const KbarT *kr =
                    prototypes +
                    (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                        head_dim;
                for (uint32_t d = lane; d < head_dim; d += 32u) {
                    const float k = static_cast<float>(kr[d]);
#pragma unroll
                    for (uint32_t g = 0; g < GqaGroup; ++g) {
                        dot[g] +=
                            static_cast<float>(
                                qr0[static_cast<uint64_t>(g) *
                                        head_dim +
                                    d]) *
                            k;
                    }
                }
#pragma unroll
                for (uint32_t offset = 16u; offset > 0u;
                     offset >>= 1u) {
#pragma unroll
                    for (uint32_t g = 0; g < GqaGroup; ++g) {
                        dot[g] += __shfl_down_sync(
                            0xffffffffu, dot[g], offset);
                    }
                }
            }
        }
        if (lane == 0) {
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                logits[
                    static_cast<uint64_t>(local_dist0 + g) *
                        max_layer_prototypes +
                    local_p] =
                    included ? dot[g] * scale : -INFINITY;
            }
        }
    }
}

// Complete-layer variant used by CPU-offloaded one-pass streaming and by the
// per-layer GPU-resident arena. The staged prototype rows already exclude
// sink/recent blocks, so no parent-id filtering is needed. Keeping the query's
// original layer id preserves the [layer, token, head] capture layout while
// allowing the logits workspace to contain just one layer.
template <typename QueryT, typename KbarT>
__global__ void block_attn_adaptive_layer_logits_kernel(
        float *logits,
        const QueryT *q_multi,
        const KbarT *prototypes,
        uint32_t layer,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t prototype_count,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale) {
    const uint64_t job = blockIdx.x;
    const uint32_t local_dist =
        static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(
        job - static_cast<uint64_t>(local_dist) * n_tiles);
    if (local_dist >= distribution_count) return;

    const uint32_t dist = distribution_base + local_dist;
    const uint32_t qh = dist % n_heads;
    const uint32_t t = dist / n_heads;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 =
        min(p0 + kSoftmaxPagesTile, prototype_count);
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    constexpr uint32_t kWarps = kSoftmaxPagesThreads / 32;
    const uint64_t qrow =
        static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(layer) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;
    float *out =
        logits +
        static_cast<uint64_t>(local_dist) * prototype_count;

    for (uint32_t p = p0 + warp; p < p1; p += kWarps) {
        const KbarT *kr =
            prototypes +
            (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                head_dim;
        float dot = 0.0f;
        for (uint32_t d = lane; d < head_dim; d += 32u) {
            dot += static_cast<float>(qr[d]) *
                   static_cast<float>(kr[d]);
        }
#pragma unroll
        for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
            dot += __shfl_down_sync(0xffffffffu, dot, offset);
        }
        if (lane == 0) out[p] = dot * scale;
    }
}

template <typename QueryT, typename KbarT, uint32_t GqaGroup>
__global__ void block_attn_adaptive_layer_logits_gqa_kernel(
        float *logits,
        const QueryT *q_multi,
        const KbarT *prototypes,
        uint32_t layer,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tiles,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t prototype_count,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale) {
    static_assert(GqaGroup >= 2 && GqaGroup <= 4);
    const uint64_t job = blockIdx.x;
    const uint32_t local_group =
        static_cast<uint32_t>(job / n_tiles);
    const uint32_t tile = static_cast<uint32_t>(
        job - static_cast<uint64_t>(local_group) * n_tiles);
    const uint32_t local_dist0 = local_group * GqaGroup;
    if (local_dist0 + GqaGroup > distribution_count) return;

    const uint32_t dist0 = distribution_base + local_dist0;
    const uint32_t qh0 = dist0 % n_heads;
    const uint32_t t = dist0 / n_heads;
    const uint32_t kvh = qh0 / GqaGroup;
    if (kvh >= n_kv_heads || qh0 % GqaGroup != 0) return;
    const uint32_t p0 = tile * kSoftmaxPagesTile;
    const uint32_t p1 =
        min(p0 + kSoftmaxPagesTile, prototype_count);
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    constexpr uint32_t kWarps = kSoftmaxPagesThreads / 32;
    const uint64_t qrow =
        static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr0 =
        q_multi +
        (static_cast<uint64_t>(layer) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh0) * head_dim;

    for (uint32_t p = p0 + warp; p < p1; p += kWarps) {
        const KbarT *kr =
            prototypes +
            (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                head_dim;
        float dot[GqaGroup] = {};
        for (uint32_t d = lane; d < head_dim; d += 32u) {
            const float k = static_cast<float>(kr[d]);
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                dot[g] +=
                    static_cast<float>(
                        qr0[static_cast<uint64_t>(g) * head_dim + d]) *
                    k;
            }
        }
#pragma unroll
        for (uint32_t offset = 16u; offset > 0u; offset >>= 1u) {
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                dot[g] += __shfl_down_sync(
                    0xffffffffu, dot[g], offset);
            }
        }
        if (lane == 0) {
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                logits[
                    static_cast<uint64_t>(local_dist0 + g) *
                        prototype_count +
                    p] = dot[g] * scale;
            }
        }
    }
}

__global__ void block_attn_adaptive_layer_accumulate_logits_kernel(
        float *score,
        const float *logits,
        const float *row_max,
        const float *row_inv_sum,
        const int32_t *block_offsets,
        const int32_t *block_counts,
        uint32_t distribution_count,
        uint32_t block_count,
        uint32_t global_block_base,
        uint32_t prototype_count,
        float distribution_weight) {
    const uint32_t w =
        blockIdx.x * blockDim.x + threadIdx.x;
    if (w >= block_count) return;
    const uint32_t begin =
        static_cast<uint32_t>(max(block_offsets[w], 0));
    const uint32_t count =
        static_cast<uint32_t>(max(block_counts[w], 0));
    if (count == 0 || begin >= prototype_count ||
        count > prototype_count - begin) {
        return;
    }
    float accum = 0.0f;
    for (uint32_t local_dist = 0;
         local_dist < distribution_count; ++local_dist) {
        const float inv = row_inv_sum[local_dist];
        if (!(inv > 0.0f)) continue;
        const float *row =
            logits +
            static_cast<uint64_t>(local_dist) * prototype_count +
            begin;
        float block_max = -INFINITY;
        for (uint32_t i = 0; i < count; ++i) {
            block_max = fmaxf(block_max, row[i]);
        }
        if (isfinite(block_max)) {
            accum +=
                __expf(block_max - row_max[local_dist]) * inv;
        }
    }
    score[global_block_base + w] +=
        accum * distribution_weight;
}

// Reduce one bounded logits batch into logical block scores. A thread owns one
// block, so batches can accumulate in stream order without atomics. Dynamic
// block_offsets/counts replace Fixed-4's constant sub-block stride.
__global__ void block_attn_adaptive_accumulate_logits_kernel(
        float *score,
        const float *logits,
        const float *row_max,
        const float *row_inv_sum,
        const int32_t *layer_offsets,
        const int32_t *block_offsets,
        const int32_t *block_counts,
        uint32_t distribution_base,
        uint32_t distribution_count,
        uint32_t n_tokens,
        uint32_t n_blocks,
        uint32_t n_heads,
        uint32_t max_layer_prototypes,
        float distribution_weight,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin) {
    const uint32_t w =
        blockIdx.x * blockDim.x + threadIdx.x;
    if (w >= n_blocks || w < excl_lo_end ||
        w >= excl_hi_begin) {
        return;
    }
    float accum = 0.0f;
    for (uint32_t local_dist = 0;
         local_dist < distribution_count; ++local_dist) {
        const float inv = row_inv_sum[local_dist];
        if (!(inv > 0.0f)) continue;
        const uint32_t dist = distribution_base + local_dist;
        const uint32_t l = (dist / n_heads) / n_tokens;
        const uint32_t meta = l * n_blocks + w;
        const uint32_t count =
            static_cast<uint32_t>(max(block_counts[meta], 0));
        if (count == 0) continue;
        const uint32_t layer_begin =
            static_cast<uint32_t>(max(layer_offsets[l], 0));
        const uint32_t global_begin =
            static_cast<uint32_t>(max(block_offsets[meta], 0));
        if (global_begin < layer_begin) continue;
        const uint32_t local_begin = global_begin - layer_begin;
        if (local_begin >= max_layer_prototypes ||
            count > max_layer_prototypes - local_begin) {
            continue;
        }
        const float *row =
            logits +
            static_cast<uint64_t>(local_dist) *
                max_layer_prototypes +
            local_begin;
        const float m = row_max[local_dist];
        float block_max = -INFINITY;
        for (uint32_t i = 0; i < count; ++i) {
            block_max = fmaxf(block_max, row[i]);
        }
        if (isfinite(block_max)) {
            // max_i softmax(x_i) == softmax(max_i x_i): one exponential per
            // logical block/distribution instead of one per prototype.
            accum += __expf(block_max - m) * inv;
        }
    }
    score[w] += accum * distribution_weight;
}

// Pass 1 for the packed variable-count index. One job owns one
// (distribution,prototype-tile) pair. The layer offsets select only the
// prototypes belonging to the distribution's normal-attention layer.
template <typename QueryT, typename KbarT>
__global__ void block_attn_adaptive_partial_lse_kernel(
        float *partial_max, float *partial_sum,
        const QueryT *q_multi, const KbarT *prototypes,
        const int32_t *layer_offsets, const int32_t *prototype_blocks,
        uint32_t n_distributions, uint32_t n_tiles,
        uint32_t n_tokens, uint32_t q_layer_stride,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, uint32_t excl_lo_end, uint32_t excl_hi_begin) {
    const uint32_t job = blockIdx.x;
    const uint32_t dist = job / n_tiles;
    const uint32_t tile = job % n_tiles;
    const uint32_t tid = threadIdx.x;
    if (dist >= n_distributions) return;
    const uint32_t qh = dist % n_heads;
    const uint32_t lt = dist / n_heads;
    const uint32_t t = lt % n_tokens;
    const uint32_t l = lt / n_tokens;
    const uint32_t kvh = qh / (n_heads / n_kv_heads);
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(l) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;
    const uint32_t layer_begin =
        static_cast<uint32_t>(max(layer_offsets[l], 0));
    const uint32_t layer_end =
        static_cast<uint32_t>(max(layer_offsets[l + 1], 0));
    const uint32_t begin =
        min(layer_begin + tile * kAdaptivePrototypeTile, layer_end);
    const uint32_t end =
        min(begin + kAdaptivePrototypeTile, layer_end);

    __shared__ float reduce[kSoftmaxPagesThreads];
    float local_max = -INFINITY;
    for (uint32_t p = begin + tid; p < end; p += blockDim.x) {
        const uint32_t block =
            static_cast<uint32_t>(max(prototype_blocks[p], 0));
        if (block < excl_lo_end || block >= excl_hi_begin) continue;
        const KbarT *kr =
            prototypes +
            (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += static_cast<float>(qr[d]) *
                   static_cast<float>(kr[d]);
        }
        local_max = fmaxf(local_max, dot * scale);
    }
    reduce[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] = fmaxf(reduce[tid], reduce[tid + s]);
        __syncthreads();
    }
    const float tile_max = reduce[0];
    float local_sum = 0.0f;
    if (isfinite(tile_max)) {
        for (uint32_t p = begin + tid; p < end; p += blockDim.x) {
            const uint32_t block =
                static_cast<uint32_t>(max(prototype_blocks[p], 0));
            if (block < excl_lo_end || block >= excl_hi_begin) continue;
            const KbarT *kr =
                prototypes +
                (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; ++d) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kr[d]);
            }
            local_sum += __expf(dot * scale - tile_max);
        }
    }
    reduce[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        partial_max[job] = tile_max;
        partial_sum[job] = reduce[0];
    }
}

// Pass 2: one CTA owns one logical block and MaxSim-reduces exactly that
// block's selected prototypes for every query distribution.
template <typename QueryT, typename KbarT>
__global__ void block_attn_adaptive_score_kernel(
        float *score, const QueryT *q_multi, const KbarT *prototypes,
        const int32_t *block_offsets, const int32_t *block_counts,
        const float *global_max, const float *global_sum,
        uint32_t n_distributions, uint32_t n_layers,
        uint32_t n_tokens, uint32_t q_layer_stride,
        uint32_t n_blocks, uint32_t n_heads, uint32_t n_kv_heads,
        uint32_t head_dim, float scale,
        uint32_t excl_lo_end, uint32_t excl_hi_begin,
        uint32_t accumulate) {
    const uint32_t w = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (w >= n_blocks) return;
    __shared__ float reduce[kSoftmaxPagesThreads];
    float local = 0.0f;
    if (w >= excl_lo_end && w < excl_hi_begin) {
        const uint32_t group = n_heads / n_kv_heads;
        const uint64_t qrow =
            static_cast<uint64_t>(n_heads) * head_dim;
        for (uint32_t dist = tid; dist < n_distributions;
             dist += blockDim.x) {
            const float denom = global_sum[dist];
            if (!(denom > 0.0f)) continue;
            const uint32_t qh = dist % n_heads;
            const uint32_t lt = dist / n_heads;
            const uint32_t t = lt % n_tokens;
            const uint32_t l = lt / n_tokens;
            const uint32_t kvh = qh / group;
            const uint32_t meta = l * n_blocks + w;
            const uint32_t begin =
                static_cast<uint32_t>(max(block_offsets[meta], 0));
            const uint32_t count =
                static_cast<uint32_t>(max(block_counts[meta], 0));
            if (count == 0) continue;
            const QueryT *qr =
                q_multi +
                (static_cast<uint64_t>(l) * q_layer_stride + t) *
                    qrow +
                static_cast<uint64_t>(qh) * head_dim;
            float block_mass = 0.0f;
            for (uint32_t i = 0; i < count; ++i) {
                const uint32_t p = begin + i;
                const KbarT *kr =
                    prototypes +
                    (static_cast<uint64_t>(p) * n_kv_heads + kvh) *
                        head_dim;
                float dot = 0.0f;
                for (uint32_t d = 0; d < head_dim; ++d) {
                    dot += static_cast<float>(qr[d]) *
                           static_cast<float>(kr[d]);
                }
                const float mass =
                    __expf(dot * scale - global_max[dist]) / denom;
                block_mass = fmaxf(block_mass, mass);
            }
            local += block_mass;
        }
    }
    reduce[tid] = local;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        const float value =
            reduce[0] /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
        if (accumulate) score[w] += value;
        else score[w] = value;
    }
}

// CPU-offloaded Adaptive pass 1. A CTA owns one query distribution in one
// normal-attention layer and merges a block-aligned prototype tile into an
// online LSE. Each prototype dot is evaluated once; per-thread online LSEs are
// pairwise merged in shared memory.
template <typename QueryT, typename KbarT>
__global__ void block_attn_stream_adaptive_lse_kernel(
        float *global_max, float *global_sum,
        const QueryT *q_multi, const KbarT *prototype_tile,
        uint32_t layer, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t prototype_count,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, uint32_t initialize) {
    const uint32_t local_dist = blockIdx.x;
    const uint32_t local_distributions = n_tokens * n_heads;
    const uint32_t tid = threadIdx.x;
    if (layer >= n_layers || local_dist >= local_distributions) return;

    const uint32_t qh = local_dist % n_heads;
    const uint32_t t = local_dist / n_heads;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kvh = qh / group;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr =
        q_multi +
        (static_cast<uint64_t>(layer) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh) * head_dim;

    float local_max = -INFINITY;
    float local_sum = 0.0f;
    for (uint32_t p = tid; p < prototype_count; p += blockDim.x) {
        const KbarT *kr =
            prototype_tile +
            (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += static_cast<float>(qr[d]) *
                   static_cast<float>(kr[d]);
        }
        const float value = dot * scale;
        const float merged_max = fmaxf(local_max, value);
        local_sum =
            (isfinite(local_max)
                 ? local_sum * __expf(local_max - merged_max)
                 : 0.0f) +
            __expf(value - merged_max);
        local_max = merged_max;
    }

    __shared__ float reduce_max[kSoftmaxPagesThreads];
    __shared__ float reduce_sum[kSoftmaxPagesThreads];
    reduce_max[tid] = local_max;
    reduce_sum[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            const float a_max = reduce_max[tid];
            const float b_max = reduce_max[tid + s];
            const float merged_max = fmaxf(a_max, b_max);
            float merged_sum = 0.0f;
            if (isfinite(a_max)) {
                merged_sum +=
                    reduce_sum[tid] * __expf(a_max - merged_max);
            }
            if (isfinite(b_max)) {
                merged_sum +=
                    reduce_sum[tid + s] * __expf(b_max - merged_max);
            }
            reduce_max[tid] = merged_max;
            reduce_sum[tid] = merged_sum;
        }
        __syncthreads();
    }
    if (tid != 0) return;
    const uint32_t dist =
        layer * local_distributions + local_dist;
    const float tile_max = reduce_max[0];
    const float tile_sum = reduce_sum[0];
    if (initialize) {
        global_max[dist] = tile_max;
        global_sum[dist] = tile_sum;
        return;
    }
    const float old_max = global_max[dist];
    const float merged_max = fmaxf(old_max, tile_max);
    float merged_sum = 0.0f;
    if (isfinite(old_max)) {
        merged_sum += global_sum[dist] * __expf(old_max - merged_max);
    }
    if (isfinite(tile_max)) {
        merged_sum += tile_sum * __expf(tile_max - merged_max);
    }
    global_max[dist] = merged_max;
    global_sum[dist] = merged_sum;
}

// GQA-specialized CPU-offload pass 1. Query heads in one GQA group share the
// same K prototype row, so form all two/three/four logits while that row is in
// registers. This preserves the per-query-head LSE exactly while avoiding
// redundant prototype loads and CTA scheduling.
template <typename QueryT, typename KbarT, uint32_t GqaGroup>
__global__ void block_attn_stream_adaptive_lse_gqa_kernel(
        float *global_max, float *global_sum,
        const QueryT *q_multi, const KbarT *prototype_tile,
        uint32_t layer, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t prototype_count,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, uint32_t initialize) {
    static_assert(GqaGroup >= 2 && GqaGroup <= 4);
    const uint32_t local_group = blockIdx.x;
    const uint32_t local_groups = n_tokens * n_kv_heads;
    const uint32_t tid = threadIdx.x;
    if (layer >= n_layers || local_group >= local_groups) return;

    const uint32_t kvh = local_group % n_kv_heads;
    const uint32_t t = local_group / n_kv_heads;
    const uint32_t qh0 = kvh * GqaGroup;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    const QueryT *qr0 =
        q_multi +
        (static_cast<uint64_t>(layer) * q_layer_stride + t) * qrow +
        static_cast<uint64_t>(qh0) * head_dim;

    float local_max[GqaGroup];
    float local_sum[GqaGroup];
#pragma unroll
    for (uint32_t g = 0; g < GqaGroup; ++g) {
        local_max[g] = -INFINITY;
        local_sum[g] = 0.0f;
    }
    for (uint32_t p = tid; p < prototype_count; p += blockDim.x) {
        const KbarT *kr =
            prototype_tile +
            (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
        float dot[GqaGroup] = {};
        for (uint32_t d = 0; d < head_dim; ++d) {
            const float k = static_cast<float>(kr[d]);
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                dot[g] +=
                    static_cast<float>(
                        qr0[static_cast<uint64_t>(g) * head_dim + d]) *
                    k;
            }
        }
#pragma unroll
        for (uint32_t g = 0; g < GqaGroup; ++g) {
            const float value = dot[g] * scale;
            const float merged_max = fmaxf(local_max[g], value);
            local_sum[g] =
                (isfinite(local_max[g])
                     ? local_sum[g] *
                           __expf(local_max[g] - merged_max)
                     : 0.0f) +
                __expf(value - merged_max);
            local_max[g] = merged_max;
        }
    }

    __shared__ float reduce_max[
        GqaGroup * kSoftmaxPagesThreads];
    __shared__ float reduce_sum[
        GqaGroup * kSoftmaxPagesThreads];
#pragma unroll
    for (uint32_t g = 0; g < GqaGroup; ++g) {
        reduce_max[g * kSoftmaxPagesThreads + tid] =
            local_max[g];
        reduce_sum[g * kSoftmaxPagesThreads + tid] =
            local_sum[g];
    }
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                const uint32_t base =
                    g * kSoftmaxPagesThreads;
                const float a_max = reduce_max[base + tid];
                const float b_max = reduce_max[base + tid + s];
                const float merged_max = fmaxf(a_max, b_max);
                float merged_sum = 0.0f;
                if (isfinite(a_max)) {
                    merged_sum +=
                        reduce_sum[base + tid] *
                        __expf(a_max - merged_max);
                }
                if (isfinite(b_max)) {
                    merged_sum +=
                        reduce_sum[base + tid + s] *
                        __expf(b_max - merged_max);
                }
                reduce_max[base + tid] = merged_max;
                reduce_sum[base + tid] = merged_sum;
            }
        }
        __syncthreads();
    }
    if (tid != 0) return;
#pragma unroll
    for (uint32_t g = 0; g < GqaGroup; ++g) {
        const uint32_t dist =
            layer * n_tokens * n_heads +
            t * n_heads + qh0 + g;
        const uint32_t base = g * kSoftmaxPagesThreads;
        const float tile_max = reduce_max[base];
        const float tile_sum = reduce_sum[base];
        if (initialize) {
            global_max[dist] = tile_max;
            global_sum[dist] = tile_sum;
            continue;
        }
        const float old_max = global_max[dist];
        const float merged_max = fmaxf(old_max, tile_max);
        float merged_sum = 0.0f;
        if (isfinite(old_max)) {
            merged_sum +=
                global_sum[dist] *
                __expf(old_max - merged_max);
        }
        if (isfinite(tile_max)) {
            merged_sum +=
                tile_sum * __expf(tile_max - merged_max);
        }
        global_max[dist] = merged_max;
        global_sum[dist] = merged_sum;
    }
}

// CPU-offloaded Adaptive pass 2. Tiles are block-aligned, so one CTA owns one
// logical block and can MaxSim-reduce its variable prototype run without
// atomics. Layers and tiles execute in stream order and add their weighted
// contributions to the final score.
template <typename QueryT, typename KbarT>
__global__ void block_attn_stream_adaptive_score_kernel(
        float *score, const QueryT *q_multi,
        const KbarT *prototype_tile,
        const int32_t *block_offsets, const int32_t *block_counts,
        const float *global_max, const float *global_sum,
        uint32_t layer, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t tile_blocks,
        uint32_t global_block_base, uint32_t n_heads,
        uint32_t n_kv_heads, uint32_t head_dim, float scale) {
    const uint32_t local_block = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (layer >= n_layers || local_block >= tile_blocks) return;
    const uint32_t count =
        static_cast<uint32_t>(max(block_counts[local_block], 0));
    const uint32_t begin =
        static_cast<uint32_t>(max(block_offsets[local_block], 0));
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t local_distributions = n_tokens * n_heads;
    const uint32_t distribution_base =
        layer * local_distributions;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;

    float local = 0.0f;
    for (uint32_t local_dist = tid;
         local_dist < local_distributions;
         local_dist += blockDim.x) {
        const uint32_t dist = distribution_base + local_dist;
        const float denom = global_sum[dist];
        if (!(denom > 0.0f) || count == 0) continue;
        const uint32_t qh = local_dist % n_heads;
        const uint32_t t = local_dist / n_heads;
        const uint32_t kvh = qh / group;
        const QueryT *qr =
            q_multi +
            (static_cast<uint64_t>(layer) * q_layer_stride + t) * qrow +
            static_cast<uint64_t>(qh) * head_dim;
        float block_max = -INFINITY;
        for (uint32_t i = 0; i < count; ++i) {
            const KbarT *kr =
                prototype_tile +
                (static_cast<uint64_t>(begin + i) * n_kv_heads + kvh) *
                    head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; ++d) {
                dot += static_cast<float>(qr[d]) *
                       static_cast<float>(kr[d]);
            }
            block_max = fmaxf(block_max, dot * scale);
        }
        if (isfinite(block_max)) {
            local +=
                __expf(block_max - global_max[dist]) / denom;
        }
    }
    __shared__ float reduce[kSoftmaxPagesThreads];
    reduce[tid] = local;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        score[global_block_base + local_block] +=
            reduce[0] /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
    }
}

template <typename QueryT, typename KbarT, uint32_t GqaGroup>
__global__ void block_attn_stream_adaptive_score_gqa_kernel(
        float *score, const QueryT *q_multi,
        const KbarT *prototype_tile,
        const int32_t *block_offsets, const int32_t *block_counts,
        const float *global_max, const float *global_sum,
        uint32_t layer, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t tile_blocks,
        uint32_t global_block_base, uint32_t n_heads,
        uint32_t n_kv_heads, uint32_t head_dim, float scale) {
    static_assert(GqaGroup >= 2 && GqaGroup <= 4);
    const uint32_t local_block = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (layer >= n_layers || local_block >= tile_blocks) return;
    const uint32_t count =
        static_cast<uint32_t>(max(block_counts[local_block], 0));
    const uint32_t begin =
        static_cast<uint32_t>(max(block_offsets[local_block], 0));
    const uint32_t local_groups = n_tokens * n_kv_heads;
    const uint32_t distribution_base =
        layer * n_tokens * n_heads;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;

    float local = 0.0f;
    for (uint32_t local_group = tid;
         local_group < local_groups;
         local_group += blockDim.x) {
        if (count == 0) continue;
        const uint32_t kvh = local_group % n_kv_heads;
        const uint32_t t = local_group / n_kv_heads;
        const uint32_t qh0 = kvh * GqaGroup;
        const QueryT *qr0 =
            q_multi +
            (static_cast<uint64_t>(layer) * q_layer_stride + t) *
                qrow +
            static_cast<uint64_t>(qh0) * head_dim;
        float block_max[GqaGroup];
#pragma unroll
        for (uint32_t g = 0; g < GqaGroup; ++g) {
            block_max[g] = -INFINITY;
        }
        for (uint32_t i = 0; i < count; ++i) {
            const KbarT *kr =
                prototype_tile +
                (static_cast<uint64_t>(begin + i) * n_kv_heads + kvh) *
                    head_dim;
            float dot[GqaGroup] = {};
            for (uint32_t d = 0; d < head_dim; ++d) {
                const float k = static_cast<float>(kr[d]);
#pragma unroll
                for (uint32_t g = 0; g < GqaGroup; ++g) {
                    dot[g] +=
                        static_cast<float>(
                            qr0[static_cast<uint64_t>(g) *
                                    head_dim +
                                d]) *
                        k;
                }
            }
#pragma unroll
            for (uint32_t g = 0; g < GqaGroup; ++g) {
                block_max[g] =
                    fmaxf(block_max[g], dot[g] * scale);
            }
        }
#pragma unroll
        for (uint32_t g = 0; g < GqaGroup; ++g) {
            const uint32_t dist =
                distribution_base + t * n_heads + qh0 + g;
            const float denom = global_sum[dist];
            if (denom > 0.0f && isfinite(block_max[g])) {
                local +=
                    __expf(block_max[g] - global_max[dist]) /
                    denom;
            }
        }
    }
    __shared__ float reduce[kSoftmaxPagesThreads];
    reduce[tid] = local;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) reduce[tid] += reduce[tid + s];
        __syncthreads();
    }
    if (tid == 0) {
        score[global_block_base + local_block] +=
            reduce[0] /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
    }
}

template <typename QueryT, typename KbarT>
__global__ void block_attn_softmax_pages_recompute_kernel(
        float *score,
        const QueryT *q_multi,
        const KbarT *kbar_multi,
        const float *global_max,
        const float *global_sum,
        uint32_t n_layers,
        uint32_t n_tokens,
        uint32_t q_layer_stride,
        uint32_t n_blocks,
        uint32_t kbar_layer_stride,
        uint32_t n_heads,
        uint32_t n_kv_heads,
        uint32_t head_dim,
        float scale,
        uint32_t excl_lo_end,
        uint32_t excl_hi_begin,
        uint32_t n_subblocks,
        uint32_t reduce_max) {
    const uint32_t w = blockIdx.x * blockDim.x + threadIdx.x;
    if (w >= n_blocks) return;
    if (w < excl_lo_end || w >= excl_hi_begin) {
        return;
    }

    const uint32_t group = n_heads / n_kv_heads;
    const uint64_t qrow = static_cast<uint64_t>(n_heads) * head_dim;
    float accum = 0.0f;
    for (uint32_t l = 0; l < n_layers; ++l) {
        const QueryT *q_l =
            q_multi + static_cast<uint64_t>(l) * q_layer_stride * qrow;
        const KbarT *kbar_l =
            kbar_multi +
            static_cast<uint64_t>(l) * kbar_layer_stride * n_subblocks *
                n_kv_heads * head_dim;
        for (uint32_t t = 0; t < n_tokens; ++t) {
            for (uint32_t qh = 0; qh < n_heads; ++qh) {
                const uint32_t dist = (l * n_tokens + t) * n_heads + qh;
                const float denom = global_sum[dist];
                if (!(denom > 0.0f)) continue;
                const float m = global_max[dist];
                const uint32_t kvh = qh / group;
                const QueryT *qr =
                    q_l + (static_cast<uint64_t>(t) * n_heads + qh) * head_dim;
                float block_mass = 0.0f;
                for (uint32_t sb = 0; sb < n_subblocks; ++sb) {
                    const uint32_t p = w * n_subblocks + sb;
                    const KbarT *kbar_row =
                        kbar_l +
                        (static_cast<uint64_t>(p) * n_kv_heads + kvh) * head_dim;
                    float dot = 0.0f;
                    for (uint32_t d = 0; d < head_dim; ++d) {
                        dot += static_cast<float>(qr[d]) *
                               static_cast<float>(kbar_row[d]);
                    }
                    const float mass = __expf(dot * scale - m) / denom;
                    if (reduce_max && n_subblocks > 1)
                        block_mass = fmaxf(block_mass, mass);
                    else
                        block_mass += mass;
                }
                accum += block_mass;
            }
        }
    }
    score[w] += accum / (static_cast<float>(n_layers) *
                         static_cast<float>(n_heads));
}

__device__ __forceinline__ uint32_t kvmem_window_bucket_for_pos(
        uint32_t pos,
        const int32_t *win_base,
        const int32_t *blk_tokens,
        uint32_t n_window_blocks) {
    if (n_window_blocks == 0) return 0;
    uint32_t lo = 0;
    uint32_t hi = n_window_blocks;
    while (lo < hi) {
        const uint32_t mid = (lo + hi) >> 1;
        const uint32_t base = static_cast<uint32_t>(win_base[mid]);
        if (base <= pos) lo = mid + 1;
        else hi = mid;
    }
    if (lo == 0) return n_window_blocks;  // before first block: tail/unknown
    const uint32_t idx = lo - 1;
    const uint32_t base = static_cast<uint32_t>(win_base[idx]);
    const uint32_t n = static_cast<uint32_t>(blk_tokens[idx]);
    return (pos < base + n) ? idx : n_window_blocks;  // final slot = decode tail
}

template <typename T>
__global__ void block_attention_mass_paged_kernel(float *mass,
                                                  const float *q,
                                                  uint32_t q_stride,
                                                  const T *k_cache,
                                                  uint32_t n_window_blocks,
                                                  uint32_t n_heads,
                                                  uint32_t n_kv_heads,
                                                  uint32_t per_pos_size,
                                                  uint32_t head_dim,
                                                  const int32_t *win_base,
                                                  const int32_t *blk_tokens,
                                                  const int32_t *page_indices,
                                                  uint32_t page_size,
                                                  uint32_t seq_len,
                                                  float scale) {
    const uint32_t head = blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (head >= n_heads || seq_len == 0) return;
    const uint32_t group = n_heads / n_kv_heads;
    const uint32_t kv_head = head / group;
    const float *q_attn = q + static_cast<uint64_t>(head) * q_stride;

    __shared__ float scratch[256];
    float local_max = -INFINITY;
    for (uint32_t t = tid; t < seq_len; t += blockDim.x) {
        const uint32_t physical_pos =
            kv_physical_pos_from_pages(t, page_indices, page_size);
        const T *k_t = k_cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
                       static_cast<uint64_t>(kv_head) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += q_attn[d] * static_cast<float>(k_t[d]);
        }
        const float score = dot * scale;
        if (score > local_max) local_max = score;
    }
    scratch[tid] = local_max;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s && scratch[tid + s] > scratch[tid]) {
            scratch[tid] = scratch[tid + s];
        }
        __syncthreads();
    }
    const float row_max = scratch[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (uint32_t t = tid; t < seq_len; t += blockDim.x) {
        const uint32_t physical_pos =
            kv_physical_pos_from_pages(t, page_indices, page_size);
        const T *k_t = k_cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
                       static_cast<uint64_t>(kv_head) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += q_attn[d] * static_cast<float>(k_t[d]);
        }
        local_sum += __expf(dot * scale - row_max);
    }
    scratch[tid] = local_sum;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) scratch[tid] += scratch[tid + s];
        __syncthreads();
    }
    const float row_sum = scratch[0];
    if (row_sum <= 0.0f || !isfinite(row_sum)) return;
    const float inv_sum = 1.0f / row_sum;

    for (uint32_t t = tid; t < seq_len; t += blockDim.x) {
        const uint32_t physical_pos =
            kv_physical_pos_from_pages(t, page_indices, page_size);
        const T *k_t = k_cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
                       static_cast<uint64_t>(kv_head) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) {
            dot += q_attn[d] * static_cast<float>(k_t[d]);
        }
        const float weight = __expf(dot * scale - row_max) * inv_sum;
        const uint32_t bucket = kvmem_window_bucket_for_pos(
            t, win_base, blk_tokens, n_window_blocks);
        atomicAdd(mass + bucket, weight);
    }
}

// ---- Global content-frame KV retrieval index (#48) ----------------------
//
// The #40 signal above is window-local: a block must be IN the active window to
// accumulate heat, so it can only RETAIN heavy hitters, never RESURRECT a block
// that was already dropped. Global retrieval fixes this by maintaining a
// position-invariant CONTENT mean-Key for every historical block, then scoring
// the current (also de-RoPE'd) query against ALL of them each interval.
//
// block_kmean_content_paged_kernel: like block_kmean_paged_kernel but reads
// through the FULL repository page table at each block's TRUE positions and
// DE-RoPEs every token's K by (orig_base+tok) before averaging, recovering the
// raw (pre-RoPE) key so the mean is position-invariant content. De-rotation
// uses the SAME __sincosf as the original bake (rope_partial_kernel /
// rope_block_remap_paged_kernel), so the huge-position range-reduction error
// cancels exactly (see rope_block_remap_paged_kernel comment). RoPE touches only
// the first rope_dim of each head; dims beyond rope_dim pass through. Built ONCE
// from the pristine post-prefill cache (blocks baked at true positions) and then
// immutable — never rebuilt as blocks are re-RoPE'd into windows during assembly.
// grid = (n_blocks, n_kv_heads), block = head_dim threads. Accumulation is fp32;
// the persistent output follows the configured KV dtype.
template <typename T, typename KbarT>
__global__ void block_kmean_content_paged_kernel(const T *k_cache,
                                                 KbarT *kbar,
                                                 uint32_t per_pos_size,
                                                 uint32_t head_dim,
                                                 uint32_t rope_dim,
                                                 const int32_t *orig_base,
                                                 const int32_t *blk_tokens,
                                                 const int32_t *page_indices,
                                                 uint32_t page_size,
                                                 float theta) {
    const uint32_t w = blockIdx.x;     // block index (block_id)
    const uint32_t h = blockIdx.y;     // kv head
    const uint32_t d = threadIdx.x;    // dim within head
    if (d >= head_dim) return;
    const int32_t base = orig_base[w];
    const uint32_t n = static_cast<uint32_t>(blk_tokens[w]);
    const uint32_t half = rope_dim / 2;
    float acc = 0.0f;
    for (uint32_t tok = 0; tok < n; ++tok) {
        const uint32_t physical_pos = kv_physical_pos_from_pages(
            static_cast<uint32_t>(base) + tok, page_indices, page_size);
        const T *row = k_cache + static_cast<uint64_t>(physical_pos) * per_pos_size +
                       static_cast<uint64_t>(h) * head_dim;
        float deroped;
        if (d < half) {
            const float inv_freq = __powf(theta, -2.0f * static_cast<float>(d) /
                                                  static_cast<float>(rope_dim));
            const float ang = static_cast<float>(base + static_cast<int32_t>(tok)) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            const float x0 = static_cast<float>(row[d]);
            const float x1 = static_cast<float>(row[d + half]);
            deroped = x0 * c + x1 * s;       // de-rotate dim i
        } else if (d < rope_dim) {
            const uint32_t i = d - half;
            const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) /
                                                  static_cast<float>(rope_dim));
            const float ang = static_cast<float>(base + static_cast<int32_t>(tok)) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            const float x0 = static_cast<float>(row[d - half]);
            const float x1 = static_cast<float>(row[d]);
            deroped = -x0 * s + x1 * c;      // de-rotate dim i+half
        } else {
            deroped = static_cast<float>(row[d]);  // beyond rope_dim: untouched
        }
        acc += deroped;
    }
    const float inv = (n > 0) ? (1.0f / static_cast<float>(n)) : 0.0f;
    kbar[(static_cast<uint64_t>(w) * gridDim.y + h) * head_dim + d] =
        static_cast<KbarT>(acc * inv);
}

// block_kmean_content_batch_kernel (#91): build per-block content mean-Keys for
// one normal-attention layer directly from the freshly-RoPE'd prefill K batch,
// instead of re-reading the paged cache post-prefill. The paged builder can only
// run ONCE, from the pristine cache before any block is offloaded/re-RoPE'd into
// a window — so for histories larger than the GPU page pool it covers only the
// blocks resident at the first mid-prefill offload (the tail is never indexed,
// hence unselectable). This variant captures each block's content key the moment
// its K is produced during prefill, so EVERY block is indexed regardless of later
// offload/window state. k_batch is the contiguous [batch, n_kv_heads*head_dim]
// (row stride k_stride) K buffer for this chunk, RoPE-baked at `rope_base` (the
// window position when the window is active, the true position otherwise). Each
// block owns a contiguous run of up to blk_tokens rows; de-RoPE every row at the
// position it was actually baked at (rope_base + r), recovering the same
// position-invariant content frame the paged builder produces (identical
// de-rotate math, so the huge-position range-reduction error cancels). Chunks are
// block-aligned (chunk_size % blk_tokens == 0 and base_pos block-aligned), so a
// block never straddles two chunks; the final chunk's last block may be partial.
// grid = (n_blocks_chunk, n_kv_heads), block = head_dim threads. Writes the slot
// slice at global block (kbar_block_base + j), layout [.., n_kv_heads, head_dim].
template <typename KbarT>
__global__ void block_kmean_content_batch_kernel(const float *k_batch,
                                                 KbarT *kbar,
                                                 uint64_t kbar_block_base,
                                                 uint32_t k_stride,
                                                 uint32_t batch,
                                                 uint32_t blk_tokens,
                                                 uint32_t head_dim,
                                                 uint32_t rope_dim,
                                                 int32_t rope_base,
                                                 float theta,
                                                 uint32_t n_subblocks) {
    // grid.x enumerates (chunk-local block, sub-block); n_subblocks==1 (plain
    // mean-k) collapses to the original one-mean-per-block layout exactly.
    const uint32_t combined = blockIdx.x;
    const uint32_t j = combined / n_subblocks;   // chunk-local block index
    const uint32_t sb = combined % n_subblocks;  // sub-block within the block
    const uint32_t h = blockIdx.y;     // kv head
    const uint32_t d = threadIdx.x;    // dim within head
    if (d >= head_dim) return;
    const uint32_t sub_tokens = (blk_tokens + n_subblocks - 1) / n_subblocks;
    const uint32_t blk_lo = j * blk_tokens;
    const uint32_t r_lo = blk_lo + sb * sub_tokens;
    if (r_lo >= batch) return;
    uint32_t r_hi = r_lo + sub_tokens;
    const uint32_t blk_hi = blk_lo + blk_tokens;
    if (r_hi > blk_hi) r_hi = blk_hi;   // last sub-block stops at the block end
    if (r_hi > batch) r_hi = batch;
    const uint32_t half = rope_dim / 2;
    float acc = 0.0f;
    for (uint32_t r = r_lo; r < r_hi; ++r) {
        const float *row = k_batch + static_cast<uint64_t>(r) * k_stride +
                           static_cast<uint64_t>(h) * head_dim;
        const int32_t pos = rope_base + static_cast<int32_t>(r);
        float deroped;
        if (d < half) {
            const float inv_freq = __powf(theta, -2.0f * static_cast<float>(d) /
                                                  static_cast<float>(rope_dim));
            const float ang = static_cast<float>(pos) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            deroped = row[d] * c + row[d + half] * s;       // de-rotate dim i
        } else if (d < rope_dim) {
            const uint32_t i = d - half;
            const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) /
                                                  static_cast<float>(rope_dim));
            const float ang = static_cast<float>(pos) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            deroped = -row[d - half] * s + row[d] * c;      // de-rotate dim i+half
        } else {
            deroped = row[d];                               // beyond rope_dim: untouched
        }
        acc += deroped;
    }
    const uint32_t n = r_hi - r_lo;
    const float inv = (n > 0) ? (1.0f / static_cast<float>(n)) : 0.0f;
    const uint64_t blk = (kbar_block_base + j) * n_subblocks + sb;
    kbar[(blk * gridDim.y + h) * head_dim + d] =
        static_cast<KbarT>(acc * inv);
}

// Fixed-4 Key-direction prototype capture. Unlike equal-width sub-blocks, the
// four groups may contain non-contiguous tokens. Clustering is independent for
// each normal-attention layer and KV head, which is valid because the scorer
// compares each query head only with its mapped KV head before reducing the
// four prototype probabilities back to a logical block.
//
// The four directions are initialized deterministically:
//   1. token nearest the block's mean direction;
//   2..4. token farthest from its nearest existing seed.
// Every token is assigned to its nearest seed by cosine and each cluster's
// content-frame mean is written to the existing
// Hierarchical index layout:
//   [logical_block, slice32, prototype4, kv_head, head_dim].
// Each 32-token slice is clustered independently. Empty directions (possible
// for identical/partial inputs) duplicate seed 0 so every logical block exposes
// exactly (block_tokens/32)*4 logits to the max-reduction scorer.
template <typename KbarT>
__global__ void block_kdirection_fixed4_batch_kernel(
        const float *k_batch, KbarT *kbar, uint64_t kbar_block_base,
        uint32_t k_stride, uint32_t batch, uint32_t blk_tokens,
        uint32_t head_dim, uint32_t rope_dim, int32_t rope_base,
        float theta) {
    constexpr uint32_t kPrototypes = 4;
    constexpr uint32_t kSliceTokens = 32;
    const uint32_t n_slices = blk_tokens / kSliceTokens;
    const uint32_t slice_job = blockIdx.x;
    const uint32_t j = slice_job / n_slices;
    const uint32_t slice = slice_job % n_slices;
    const uint32_t h = blockIdx.y;
    const uint32_t d = threadIdx.x;
    const uint32_t blk_lo = j * blk_tokens;
    if (blk_lo >= batch || n_slices == 0 ||
        head_dim > blockDim.x) {
        return;
    }
    const uint32_t block_rows = min(blk_tokens, batch - blk_lo);
    // A partial final logical block may not reach its later 32-token slices.
    // Duplicate its first valid slice into those unused prototype slots. The
    // scorer performs a max reduction, so this keeps the fixed layout without
    // changing the block's ordering relative to other blocks.
    const uint32_t requested_slice_lo = slice * kSliceTokens;
    const uint32_t slice_lo =
        requested_slice_lo < block_rows ? requested_slice_lo : 0u;
    const uint32_t n =
        min(kSliceTokens, block_rows - slice_lo);
    const uint32_t half = rope_dim / 2;

    // Transposed [dim,token] layout lets the first warp compare all 32 tokens
    // without shared-memory bank conflicts.
    extern __shared__ float s_storage[];
    float *s_key = s_storage;
    float *s_mean =
        s_key + static_cast<uint64_t>(head_dim) * kSliceTokens;
    __shared__ float s_inv_norm[kSliceTokens];
    __shared__ float s_best[kSliceTokens];
    __shared__ float s_mean_inv_norm;
    __shared__ int s_seed[kPrototypes];
    __shared__ int s_assignment[kSliceTokens];
    __shared__ uint32_t s_count[kPrototypes];

    if (d < head_dim) {
        float mean = 0.0f;
        for (uint32_t t = 0; t < n; ++t) {
            const uint32_t r = blk_lo + slice_lo + t;
            const float *row =
                k_batch + static_cast<uint64_t>(r) * k_stride +
                static_cast<uint64_t>(h) * head_dim;
            const int32_t pos = rope_base + static_cast<int32_t>(r);
            float content;
            if (d < half) {
                const float inv_freq = __powf(
                    theta, -2.0f * static_cast<float>(d) /
                               static_cast<float>(rope_dim));
                float s, c;
                __sincosf(static_cast<float>(pos) * inv_freq, &s, &c);
                content = row[d] * c + row[d + half] * s;
            } else if (d < rope_dim) {
                const uint32_t i = d - half;
                const float inv_freq = __powf(
                    theta, -2.0f * static_cast<float>(i) /
                               static_cast<float>(rope_dim));
                float s, c;
                __sincosf(static_cast<float>(pos) * inv_freq, &s, &c);
                content = -row[d - half] * s + row[d] * c;
            } else {
                content = row[d];
            }
            s_key[static_cast<uint64_t>(d) * kSliceTokens + t] = content;
            mean += content;
        }
        s_mean[d] = mean / static_cast<float>(n);
    }
    __syncthreads();

    if (d < n) {
        float norm2 = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            const float value =
                s_key[static_cast<uint64_t>(x) * kSliceTokens + d];
            norm2 += value * value;
        }
        s_inv_norm[d] = rsqrtf(fmaxf(norm2, 1.0e-20f));
    }
    if (d == 0) {
        float norm2 = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            norm2 += s_mean[x] * s_mean[x];
        }
        s_mean_inv_norm = rsqrtf(fmaxf(norm2, 1.0e-20f));
    }
    __syncthreads();

    // Seed 0: the observed token closest to the block mean direction.
    if (d < n) {
        float dot = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            dot += s_key[static_cast<uint64_t>(x) * kSliceTokens + d] *
                   s_mean[x];
        }
        s_best[d] = dot * s_inv_norm[d] * s_mean_inv_norm;
    }
    __syncthreads();
    if (d == 0) {
        int best_token = 0;
        float best_value = s_best[0];
        for (uint32_t t = 1; t < n; ++t) {
            if (s_best[t] > best_value) {
                best_value = s_best[t];
                best_token = static_cast<int>(t);
            }
        }
        s_seed[0] = best_token;
    }
    __syncthreads();

    if (d < n) {
        float dot = 0.0f;
        const uint32_t seed = static_cast<uint32_t>(s_seed[0]);
        for (uint32_t x = 0; x < head_dim; ++x) {
            dot += s_key[static_cast<uint64_t>(x) * kSliceTokens + d] *
                   s_key[static_cast<uint64_t>(x) * kSliceTokens + seed];
        }
        s_best[d] = dot * s_inv_norm[d] * s_inv_norm[seed];
        s_assignment[d] = 0;
    }
    __syncthreads();

    for (uint32_t p = 1; p < kPrototypes; ++p) {
        if (d == 0) {
            int farthest = -1;
            float farthest_similarity = 3.402823466e+38F;
            for (uint32_t t = 0; t < n; ++t) {
                bool selected = false;
                for (uint32_t previous = 0; previous < p; ++previous) {
                    selected |= s_seed[previous] == static_cast<int>(t);
                }
                if (!selected && s_best[t] < farthest_similarity) {
                    farthest_similarity = s_best[t];
                    farthest = static_cast<int>(t);
                }
            }
            s_seed[p] = farthest >= 0 ? farthest : s_seed[0];
        }
        __syncthreads();
        if (d < n) {
            const uint32_t seed = static_cast<uint32_t>(s_seed[p]);
            float dot = 0.0f;
            for (uint32_t x = 0; x < head_dim; ++x) {
                dot += s_key[
                           static_cast<uint64_t>(x) * kSliceTokens + d] *
                       s_key[
                           static_cast<uint64_t>(x) * kSliceTokens + seed];
            }
            const float similarity =
                dot * s_inv_norm[d] * s_inv_norm[seed];
            if (similarity > s_best[d]) {
                s_best[d] = similarity;
                s_assignment[d] = static_cast<int>(p);
            }
        }
        __syncthreads();
    }

    if (d < kPrototypes) s_count[d] = 0;
    __syncthreads();
    if (d < n) atomicAdd(&s_count[s_assignment[d]], 1u);
    __syncthreads();

    if (d < head_dim) {
        for (uint32_t p = 0; p < kPrototypes; ++p) {
            float acc = 0.0f;
            for (uint32_t t = 0; t < n; ++t) {
                if (s_assignment[t] == static_cast<int>(p)) {
                    acc +=
                        s_key[static_cast<uint64_t>(d) * kSliceTokens + t];
                }
            }
            const uint32_t count = s_count[p];
            const float value =
                count > 0
                    ? acc / static_cast<float>(count)
                    : s_key[
                          static_cast<uint64_t>(d) * kSliceTokens +
                          static_cast<uint32_t>(s_seed[0])];
            const uint64_t prototype =
                (kbar_block_base + j) * (n_slices * kPrototypes) +
                slice * kPrototypes + p;
            kbar[(prototype * gridDim.y + h) * head_dim + d] =
                static_cast<KbarT>(value);
        }
    }
}

// Adaptive Key-direction candidate capture. Persistent storage is not written
// here: the seven rows are bounded scratch for one prefill chunk.
//
// Candidate slots per 32-token slice:
//   0      : exact one-cluster mean
//   1..2   : exact means after assigning to the first two farthest-first seeds
//   3..6   : exact means after assigning to all four seeds
//
// residual_scratch stores [E1,E2,E4] for every (block,slice,KV-head), where
// E(P)=mean_t(1-max_j cosine(k_t,seed_j)). Missing slices are marked -1.
template <typename KbarT>
__global__ void block_kdirection_adaptive_batch_kernel(
        const float *k_batch, KbarT *candidates, float *residuals,
        uint32_t k_stride, uint32_t batch, uint32_t blk_tokens,
        uint32_t head_dim, uint32_t rope_dim, int32_t rope_base,
        float theta) {
    constexpr uint32_t kCandidateRows = 7;
    constexpr uint32_t kPrototypes = 4;
    constexpr uint32_t kSliceTokens = 32;
    const uint32_t n_slices = blk_tokens / kSliceTokens;
    const uint32_t slice_job = blockIdx.x;
    const uint32_t j = slice_job / n_slices;
    const uint32_t slice = slice_job % n_slices;
    const uint32_t h = blockIdx.y;
    const uint32_t d = threadIdx.x;
    const uint32_t blk_lo = j * blk_tokens;
    if (blk_lo >= batch || n_slices == 0 || head_dim > blockDim.x) {
        return;
    }
    const uint32_t block_rows = min(blk_tokens, batch - blk_lo);
    const uint32_t slice_lo = slice * kSliceTokens;
    const uint64_t residual_base =
        (static_cast<uint64_t>(slice_job) * gridDim.y + h) * 3u;
    if (slice_lo >= block_rows) {
        if (d == 0) {
            residuals[residual_base + 0] = -1.0f;
            residuals[residual_base + 1] = -1.0f;
            residuals[residual_base + 2] = -1.0f;
        }
        return;
    }
    const uint32_t n = min(kSliceTokens, block_rows - slice_lo);
    const uint32_t half = rope_dim / 2;

    extern __shared__ float s_storage[];
    float *s_key = s_storage;
    float *s_mean =
        s_key + static_cast<uint64_t>(head_dim) * kSliceTokens;
    __shared__ float s_inv_norm[kSliceTokens];
    __shared__ float s_best[kSliceTokens];
    __shared__ float s_mean_inv_norm;
    __shared__ int s_seed[kPrototypes];
    __shared__ int s_assignment[kSliceTokens];
    __shared__ uint32_t s_count[kPrototypes];

    if (d < head_dim) {
        float mean = 0.0f;
        for (uint32_t t = 0; t < n; ++t) {
            const uint32_t r = blk_lo + slice_lo + t;
            const float *row =
                k_batch + static_cast<uint64_t>(r) * k_stride +
                static_cast<uint64_t>(h) * head_dim;
            const int32_t pos = rope_base + static_cast<int32_t>(r);
            float content;
            if (d < half) {
                const float inv_freq = __powf(
                    theta, -2.0f * static_cast<float>(d) /
                               static_cast<float>(rope_dim));
                float s, c;
                __sincosf(static_cast<float>(pos) * inv_freq, &s, &c);
                content = row[d] * c + row[d + half] * s;
            } else if (d < rope_dim) {
                const uint32_t i = d - half;
                const float inv_freq = __powf(
                    theta, -2.0f * static_cast<float>(i) /
                               static_cast<float>(rope_dim));
                float s, c;
                __sincosf(static_cast<float>(pos) * inv_freq, &s, &c);
                content = -row[d - half] * s + row[d] * c;
            } else {
                content = row[d];
            }
            s_key[static_cast<uint64_t>(d) * kSliceTokens + t] =
                content;
            mean += content;
        }
        s_mean[d] = mean / static_cast<float>(n);
    }
    __syncthreads();

    if (d < n) {
        float norm2 = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            const float value =
                s_key[static_cast<uint64_t>(x) * kSliceTokens + d];
            norm2 += value * value;
        }
        s_inv_norm[d] = rsqrtf(fmaxf(norm2, 1.0e-20f));
    }
    if (d == 0) {
        float norm2 = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            norm2 += s_mean[x] * s_mean[x];
        }
        s_mean_inv_norm = rsqrtf(fmaxf(norm2, 1.0e-20f));
    }
    __syncthreads();

    if (d < n) {
        float dot = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            dot += s_key[static_cast<uint64_t>(x) * kSliceTokens + d] *
                   s_mean[x];
        }
        s_best[d] = dot * s_inv_norm[d] * s_mean_inv_norm;
    }
    __syncthreads();
    if (d == 0) {
        int best_token = 0;
        float best_value = s_best[0];
        for (uint32_t t = 1; t < n; ++t) {
            if (s_best[t] > best_value) {
                best_value = s_best[t];
                best_token = static_cast<int>(t);
            }
        }
        s_seed[0] = best_token;
    }
    __syncthreads();

    if (d < n) {
        const uint32_t seed = static_cast<uint32_t>(s_seed[0]);
        float dot = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            dot += s_key[static_cast<uint64_t>(x) * kSliceTokens + d] *
                   s_key[static_cast<uint64_t>(x) * kSliceTokens + seed];
        }
        s_best[d] = dot * s_inv_norm[d] * s_inv_norm[seed];
        s_assignment[d] = 0;
    }
    __syncthreads();

    if (d == 0) {
        float residual = 0.0f;
        for (uint32_t t = 0; t < n; ++t) {
            residual += fmaxf(0.0f, 1.0f - fminf(1.0f, s_best[t]));
        }
        residuals[residual_base + 0] =
            residual / static_cast<float>(n);
    }
    if (d < head_dim) {
        const uint64_t candidate =
            static_cast<uint64_t>(slice_job) * kCandidateRows;
        candidates[(candidate * gridDim.y + h) * head_dim + d] =
            static_cast<KbarT>(s_mean[d]);
    }
    __syncthreads();

    // Add the second direction and materialize the exact P=2 clustering.
    if (d == 0) {
        int farthest = -1;
        float farthest_similarity = 3.402823466e+38F;
        for (uint32_t t = 0; t < n; ++t) {
            if (static_cast<int>(t) != s_seed[0] &&
                s_best[t] < farthest_similarity) {
                farthest_similarity = s_best[t];
                farthest = static_cast<int>(t);
            }
        }
        s_seed[1] = farthest >= 0 ? farthest : s_seed[0];
    }
    __syncthreads();
    if (d < n) {
        const uint32_t seed = static_cast<uint32_t>(s_seed[1]);
        float dot = 0.0f;
        for (uint32_t x = 0; x < head_dim; ++x) {
            dot += s_key[static_cast<uint64_t>(x) * kSliceTokens + d] *
                   s_key[static_cast<uint64_t>(x) * kSliceTokens + seed];
        }
        const float similarity =
            dot * s_inv_norm[d] * s_inv_norm[seed];
        if (similarity > s_best[d]) {
            s_best[d] = similarity;
            s_assignment[d] = 1;
        }
    }
    __syncthreads();
    if (d == 0) {
        float residual = 0.0f;
        for (uint32_t t = 0; t < n; ++t) {
            residual += fmaxf(0.0f, 1.0f - fminf(1.0f, s_best[t]));
        }
        residuals[residual_base + 1] =
            residual / static_cast<float>(n);
    }
    if (d < kPrototypes) s_count[d] = 0;
    __syncthreads();
    if (d < n) atomicAdd(&s_count[s_assignment[d]], 1u);
    __syncthreads();
    if (d < head_dim) {
        for (uint32_t p = 0; p < 2; ++p) {
            float acc = 0.0f;
            for (uint32_t t = 0; t < n; ++t) {
                if (s_assignment[t] == static_cast<int>(p)) {
                    acc += s_key[
                        static_cast<uint64_t>(d) * kSliceTokens + t];
                }
            }
            const float value =
                s_count[p] > 0
                    ? acc / static_cast<float>(s_count[p])
                    : s_mean[d];
            const uint64_t candidate =
                static_cast<uint64_t>(slice_job) * kCandidateRows +
                1u + p;
            candidates[(candidate * gridDim.y + h) * head_dim + d] =
                static_cast<KbarT>(value);
        }
    }
    __syncthreads();

    // Add directions three and four, then materialize P=4.
    for (uint32_t p = 2; p < kPrototypes; ++p) {
        if (d == 0) {
            int farthest = -1;
            float farthest_similarity = 3.402823466e+38F;
            for (uint32_t t = 0; t < n; ++t) {
                bool selected = false;
                for (uint32_t previous = 0; previous < p; ++previous) {
                    selected |=
                        s_seed[previous] == static_cast<int>(t);
                }
                if (!selected && s_best[t] < farthest_similarity) {
                    farthest_similarity = s_best[t];
                    farthest = static_cast<int>(t);
                }
            }
            s_seed[p] = farthest >= 0 ? farthest : s_seed[0];
        }
        __syncthreads();
        if (d < n) {
            const uint32_t seed = static_cast<uint32_t>(s_seed[p]);
            float dot = 0.0f;
            for (uint32_t x = 0; x < head_dim; ++x) {
                dot += s_key[
                           static_cast<uint64_t>(x) * kSliceTokens + d] *
                       s_key[
                           static_cast<uint64_t>(x) * kSliceTokens + seed];
            }
            const float similarity =
                dot * s_inv_norm[d] * s_inv_norm[seed];
            if (similarity > s_best[d]) {
                s_best[d] = similarity;
                s_assignment[d] = static_cast<int>(p);
            }
        }
        __syncthreads();
    }
    if (d == 0) {
        float residual = 0.0f;
        for (uint32_t t = 0; t < n; ++t) {
            residual += fmaxf(0.0f, 1.0f - fminf(1.0f, s_best[t]));
        }
        residuals[residual_base + 2] =
            residual / static_cast<float>(n);
    }
    if (d < kPrototypes) s_count[d] = 0;
    __syncthreads();
    if (d < n) atomicAdd(&s_count[s_assignment[d]], 1u);
    __syncthreads();
    if (d < head_dim) {
        for (uint32_t p = 0; p < kPrototypes; ++p) {
            float acc = 0.0f;
            for (uint32_t t = 0; t < n; ++t) {
                if (s_assignment[t] == static_cast<int>(p)) {
                    acc += s_key[
                        static_cast<uint64_t>(d) * kSliceTokens + t];
                }
            }
            const float value =
                s_count[p] > 0
                    ? acc / static_cast<float>(s_count[p])
                    : s_mean[d];
            const uint64_t candidate =
                static_cast<uint64_t>(slice_job) * kCandidateRows +
                3u + p;
            candidates[(candidate * gridDim.y + h) * head_dim + d] =
                static_cast<KbarT>(value);
        }
    }
}

// Exact incremental variant for a chunk whose first row begins inside an
// already-indexed logical block. `first_block_token_offset` rows of that block
// have previously contributed to kbar. Merge their existing mean with the new
// rows by exact prefix/new counts. An aligned replay passes offset=0, which
// overwrites every replayed block and invalidates stale first-pass means.
template <typename KbarT>
__global__ void block_kmean_content_batch_merge_kernel(
        const float *k_batch, KbarT *kbar, uint64_t kbar_block_base,
        uint32_t k_stride, uint32_t batch, uint32_t blk_tokens,
        uint32_t first_block_token_offset, uint32_t head_dim,
        uint32_t rope_dim, int32_t rope_base, float theta,
        uint32_t n_subblocks) {
    const uint32_t combined = blockIdx.x;
    const uint32_t j = combined / n_subblocks;
    const uint32_t sb = combined % n_subblocks;
    const uint32_t h = blockIdx.y;
    const uint32_t d = threadIdx.x;
    if (d >= head_dim) return;

    // Coordinates are relative to the first destination block; incoming row r
    // occupies coordinate first_block_token_offset+r.
    const uint32_t sub_tokens =
        (blk_tokens + n_subblocks - 1) / n_subblocks;
    const uint32_t sb_lo = j * blk_tokens + sb * sub_tokens;
    const uint32_t block_hi = (j + 1) * blk_tokens;
    const uint32_t sb_hi = min(sb_lo + sub_tokens, block_hi);
    const uint32_t incoming_lo = first_block_token_offset;
    const uint32_t incoming_hi = incoming_lo + batch;
    const uint32_t overlap_lo = max(sb_lo, incoming_lo);
    const uint32_t overlap_hi = min(sb_hi, incoming_hi);
    if (overlap_lo >= overlap_hi) return;

    // Only the first destination block can contain an existing prefix. This
    // generic intersection naturally yields zero for later blocks/sub-blocks.
    const uint32_t prefix_hi = min(first_block_token_offset, sb_hi);
    const uint32_t prior = prefix_hi > sb_lo ? prefix_hi - sb_lo : 0u;
    const uint32_t r_lo = overlap_lo - incoming_lo;
    const uint32_t r_hi = overlap_hi - incoming_lo;
    const uint32_t half = rope_dim / 2;
    float acc = 0.0f;
    for (uint32_t r = r_lo; r < r_hi; ++r) {
        const float *row = k_batch + static_cast<uint64_t>(r) * k_stride +
                           static_cast<uint64_t>(h) * head_dim;
        const int32_t pos = rope_base + static_cast<int32_t>(r);
        float deroped;
        if (d < half) {
            const float inv_freq = __powf(
                theta, -2.0f * static_cast<float>(d) /
                           static_cast<float>(rope_dim));
            const float ang = static_cast<float>(pos) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            deroped = row[d] * c + row[d + half] * s;
        } else if (d < rope_dim) {
            const uint32_t i = d - half;
            const float inv_freq = __powf(
                theta, -2.0f * static_cast<float>(i) /
                           static_cast<float>(rope_dim));
            const float ang = static_cast<float>(pos) * inv_freq;
            float s, c;
            __sincosf(ang, &s, &c);
            deroped = -row[d - half] * s + row[d] * c;
        } else {
            deroped = row[d];
        }
        acc += deroped;
    }
    const uint32_t added = r_hi - r_lo;
    const uint64_t blk = (kbar_block_base + j) * n_subblocks + sb;
    const uint64_t out = (blk * gridDim.y + h) * head_dim + d;
    const float prior_sum = prior > 0
        ? static_cast<float>(kbar[out]) * static_cast<float>(prior) : 0.0f;
    kbar[out] = static_cast<KbarT>(
        (prior_sum + acc) / static_cast<float>(prior + added));
}

// derope_store_content_batch_kernel (MaxSim, raw-key retrieval): like
// block_kmean_content_batch_kernel but STORES each de-RoPE'd K row instead of
// averaging — keeps the full per-token content-frame key so the scorer can take a
// MAX over a block's tokens rather than scoring one diluted mean key. Same
// de-rotate math (so the content frame matches the query capture and the huge-
// position range-reduction error cancels). k_batch is the chunk's fp32 [batch,
// n_kv_heads*head_dim] (row stride k_stride) RoPE-baked at rope_base; row r is
// de-RoPE'd at (rope_base + r) and written at global token (out_base_elem indexes
// the (slot,first-global-token) origin) row r, head h. grid = (batch, n_kv_heads),
// block = head_dim threads. Output layout [.., n_kv_heads, head_dim] fp32.
__global__ void derope_store_content_batch_kernel(const float *k_batch,
                                                  float *kraw,
                                                  uint64_t out_base_elem,
                                                  uint32_t k_stride,
                                                  uint32_t batch,
                                                  uint32_t n_kv_heads,
                                                  uint32_t head_dim,
                                                  uint32_t rope_dim,
                                                  int32_t rope_base,
                                                  float theta) {
    const uint32_t r = blockIdx.x;     // chunk-local row
    const uint32_t h = blockIdx.y;     // kv head
    const uint32_t d = threadIdx.x;    // dim within head
    if (d >= head_dim || r >= batch) return;
    const float *row = k_batch + static_cast<uint64_t>(r) * k_stride +
                       static_cast<uint64_t>(h) * head_dim;
    const int32_t pos = rope_base + static_cast<int32_t>(r);
    const uint32_t half = rope_dim / 2;
    float deroped;
    if (d < half) {
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(d) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = row[d] * c + row[d + half] * s;       // de-rotate dim i
    } else if (d < rope_dim) {
        const uint32_t i = d - half;
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = -row[d - half] * s + row[d] * c;      // de-rotate dim i+half
    } else {
        deroped = row[d];                               // beyond rope_dim: untouched
    }
    kraw[out_base_elem + (static_cast<uint64_t>(r) * n_kv_heads + h) * head_dim + d] =
        deroped;
}

// block_attn_score_exactmass_kernel (ExactMass, raw-key, AgentKV port): one CUDA
// block per (query token j, query head qh). The CTA softmaxes the per-token logit
// scale·(q[j,qh]·k_raw[t,kvh]) over ALL total_tokens key positions, then folds the
// per-block attention MASS into score[w] (+=, ACCUMULATES over the L per-layer
// launches). For block w:
//   score[w] += head_w · Σ_{t : t/bt==w} softmax_t( scale·(q[j,qh]·k_raw[t,kvh]) ),
// kvh = qh/group, head_w = 1/(L·M·n_heads). The key distinction from
// block_attn_score_softmax_pages (which softmaxes per-block MEAN keys → exp(mean),
// so a needle token is already diluted before the exp): here the exp is applied to
// every RAW token logit and THEN summed into blocks (Σexp), a faithful port of
// AgentKV's _stream_exact_mass_scores_pagewise, so a needle token's mass survives
// and blocks compete under one global softmax denominator.
//   q_layer [M, n_heads, head_dim]               fp32 (this layer slice; caller offsets ptr)
//   kraw    [total_tokens, n_kv_heads, head_dim] fp32 (this layer slice; caller offsets ptr)
//   score   [n_blocks]                            fp32 (+=, caller zeros once)
// grid = M·n_heads (or M·n_kv_heads when group_mean=1: strict AgentKV, see below),
// blockDim = 256. Dynamic shmem: q_vec[head_dim] + s_acc[n_blocks].
// Two dot-passes (global max, then exp); pass 3 has no dots. Efficiency deferred
// (correctness/utility first): kraw is re-read per (j,head) CTA.
//
// group_mean=0 (default): one CTA per (query token j, query head qh), heads kept
//   distinct, masses averaged AFTER the softmax (head_w = 1/(L·M·n_heads)).
// group_mean=1 (strict AgentKV): one CTA per (query token j, KV group g); the query
//   is the MEAN of group g's query heads formed BEFORE the softmax, matching
//   _full_layer_qk's q.view(Q,nkv,groups,hd).mean(dim=2). Caller sets
//   head_w = 1/(L·M·n_kv_heads) and grid = M·n_kv_heads.
__global__ void block_attn_score_exactmass_kernel(float *score,
                                                  const float *q_layer,
                                                  const float *kraw,
                                                  uint32_t M,
                                                  uint32_t total_tokens,
                                                  uint32_t n_blocks,
                                                  uint32_t block_tokens,
                                                  uint32_t n_heads,
                                                  uint32_t n_kv_heads,
                                                  uint32_t head_dim,
                                                  float scale,
                                                  float head_w,
                                                  uint32_t group_mean) {
    const uint32_t bid = blockIdx.x;
    const uint32_t group = (n_kv_heads > 0) ? (n_heads / n_kv_heads) : 1u;
    const uint32_t heads_dim = group_mean ? n_kv_heads : n_heads;
    const uint32_t j = bid / heads_dim;
    const uint32_t h = bid - j * heads_dim;   // strict: KV group g; else: query head qh
    if (j >= M) return;
    const uint32_t tid = threadIdx.x;
    const uint32_t nthreads = blockDim.x;
    const uint32_t lane = tid & 31u;
    const uint32_t wid = tid >> 5;
    const uint32_t nwarps = nthreads >> 5;
    const uint32_t kvh = group_mean ? h : (h / group);

    extern __shared__ float smem[];
    float *q_vec = smem;                 // [head_dim]
    float *s_acc = smem + head_dim;      // [n_blocks]
    __shared__ float s_max;
    __shared__ float s_sum;
    __shared__ float wred[32];

    // Load the query into shmem; zero the per-block mass accumulator. In strict
    // (group_mean) mode q_vec is the mean over KV group g's query heads
    // [g*group, g*group+group); else it is the single query head h.
    if (group_mean) {
        const uint32_t qh0 = h * group;
        for (uint32_t d = tid; d < head_dim; d += nthreads) {
            float acc = 0.0f;
            for (uint32_t r = 0; r < group; ++r) {
                const float *qr = q_layer +
                    (static_cast<uint64_t>(j) * n_heads + (qh0 + r)) * head_dim;
                acc += qr[d];
            }
            q_vec[d] = acc / static_cast<float>(group);
        }
    } else {
        const float *qr =
            q_layer + (static_cast<uint64_t>(j) * n_heads + h) * head_dim;
        for (uint32_t d = tid; d < head_dim; d += nthreads) q_vec[d] = qr[d];
    }
    for (uint32_t w = tid; w < n_blocks; w += nthreads) s_acc[w] = 0.0f;
    __syncthreads();

    // Pass 1: global max of logit[t] = scale·(q·k_raw[t,kvh]) over ALL tokens.
    float local_max = -INFINITY;
    for (uint32_t t = tid; t < total_tokens; t += nthreads) {
        const float *krow =
            kraw + (static_cast<uint64_t>(t) * n_kv_heads + kvh) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) dot += q_vec[d] * krow[d];
        const float logit = dot * scale;
        if (logit > local_max) local_max = logit;
    }
    {
        float v = local_max;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, off));
        if (lane == 0) wred[wid] = v;
        __syncthreads();
        if (wid == 0) {
            float t2 = (lane < nwarps) ? wred[lane] : -INFINITY;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                t2 = fmaxf(t2, __shfl_down_sync(0xffffffffu, t2, off));
            if (lane == 0) s_max = t2;
        }
        __syncthreads();
    }
    const float m = s_max;

    // Pass 2: exp(logit - m) per token; accumulate per-block mass (shared atomics)
    // and the global softmax denominator.
    float local_z = 0.0f;
    for (uint32_t t = tid; t < total_tokens; t += nthreads) {
        const float *krow =
            kraw + (static_cast<uint64_t>(t) * n_kv_heads + kvh) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; ++d) dot += q_vec[d] * krow[d];
        const float e = __expf(dot * scale - m);
        atomicAdd(&s_acc[t / block_tokens], e);
        local_z += e;
    }
    {
        float v = local_z;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            v += __shfl_down_sync(0xffffffffu, v, off);
        if (lane == 0) wred[wid] = v;
        __syncthreads();
        if (wid == 0) {
            float t2 = (lane < nwarps) ? wred[lane] : 0.0f;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                t2 += __shfl_down_sync(0xffffffffu, t2, off);
            if (lane == 0) s_sum = (t2 > 0.0f) ? t2 : 1.0f;
        }
        __syncthreads();
    }
    const float inv_z = head_w / s_sum;

    // Pass 3: fold the normalized per-block mass into the global score (+=).
    for (uint32_t w = tid; w < n_blocks; w += nthreads) {
        atomicAdd(&score[w], s_acc[w] * inv_z);
    }
}

// derope_query_kernel: de-RoPE the current decode token's RoPE-baked Q (baked at
// query_pos) into a contiguous content-frame query [n_heads, head_dim], so it
// can be dotted against the content-frame mean keys above (q_raw . k̄_raw is
// position-invariant content similarity). Same de-rotate math; the input Q has
// the [n_heads, 2, head_dim] layout (attn-Q is the first head_dim of each unit,
// per-unit stride q_stride). grid = (n_heads), block = head_dim threads.
__global__ void derope_query_kernel(float *q_content,
                                    const float *q,
                                    uint32_t q_stride,
                                    uint32_t head_dim,
                                    uint32_t rope_dim,
                                    int32_t query_pos,
                                    float theta) {
    const uint32_t qh = blockIdx.x;
    const uint32_t d = threadIdx.x;
    if (d >= head_dim) return;
    const float *row = q + static_cast<uint64_t>(qh) * q_stride;
    const uint32_t half = rope_dim / 2;
    float deroped;
    if (d < half) {
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(d) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(query_pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = row[d] * c + row[d + half] * s;
    } else if (d < rope_dim) {
        const uint32_t i = d - half;
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(query_pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = -row[d - half] * s + row[d] * c;
    } else {
        deroped = row[d];
    }
    q_content[static_cast<uint64_t>(qh) * head_dim + d] = deroped;
}

// derope_query_multi_kernel: batched variant of derope_query_kernel. De-RoPEs a
// contiguous run of `cnt` query tokens (the in-span question tokens captured
// during prefill) into a packed content-frame buffer [cnt, n_heads, head_dim].
// Input `q` points at the FIRST in-span token row; token r lives at
// q + r*q_token_stride, head qh at + qh*q_head_stride (attn-Q is the first
// head_dim of each 2*head_dim unit). Token r is RoPE-baked at start_pos+r.
// grid = (n_heads, cnt), block = head_dim threads.
__global__ void derope_query_multi_kernel(void *q_multi,
                                          const float *q,
                                          uint32_t q_token_stride,
                                          uint32_t q_head_stride,
                                          uint32_t n_heads,
                                          uint32_t head_dim,
                                          uint32_t rope_dim,
                                          int32_t start_pos,
                                          float theta,
                                          bool output_fp16) {
    const uint32_t r = blockIdx.y;
    const uint32_t qh = blockIdx.x;
    const uint32_t d = threadIdx.x;
    if (d >= head_dim) return;
    const float *row = q + static_cast<uint64_t>(r) * q_token_stride +
                       static_cast<uint64_t>(qh) * q_head_stride;
    const int32_t query_pos = start_pos + static_cast<int32_t>(r);
    const uint32_t half = rope_dim / 2;
    float deroped;
    if (d < half) {
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(d) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(query_pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = row[d] * c + row[d + half] * s;
    } else if (d < rope_dim) {
        const uint32_t i = d - half;
        const float inv_freq = __powf(theta, -2.0f * static_cast<float>(i) /
                                              static_cast<float>(rope_dim));
        const float ang = static_cast<float>(query_pos) * inv_freq;
        float s, c;
        __sincosf(ang, &s, &c);
        deroped = -row[d - half] * s + row[d] * c;
    } else {
        deroped = row[d];
    }
    const uint64_t out =
        (static_cast<uint64_t>(r) * n_heads + qh) * head_dim + d;
    if (output_fp16) {
        static_cast<__half *>(q_multi)[out] = __float2half_rn(deroped);
    } else {
        static_cast<float *>(q_multi)[out] = deroped;
    }
}

__global__ void kv_append_kernel(float *cache,
                                 const float *src,
                                 uint32_t base_pos,
                                 uint32_t per_pos_size,
                                 uint32_t src_stride) {
    const uint32_t b = blockIdx.x;
    const uint32_t i = blockIdx.y * blockDim.x + threadIdx.x;
    if (i >= per_pos_size) return;
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    cache[static_cast<uint64_t>(base_pos + b) * per_pos_size + i] = src_row[i];
}

__device__ __forceinline__ uint32_t kv_physical_pos_from_pages(
        uint32_t logical_pos,
        const int32_t *page_indices,
        uint32_t page_size) {
    const uint32_t logical_page = logical_pos / page_size;
    const uint32_t page_offset = logical_pos - logical_page * page_size;
    return static_cast<uint32_t>(page_indices[logical_page]) * page_size + page_offset;
}

__device__ __forceinline__ uint32_t kv_physical_pos_from_ragged_pages(
        uint32_t batch_row,
        uint32_t logical_pos,
        const int32_t *page_indices,
        const int32_t *page_indptr,
        uint32_t page_size) {
    const uint32_t logical_page = logical_pos / page_size;
    const uint32_t page_offset = logical_pos - logical_page * page_size;
    const uint32_t begin = static_cast<uint32_t>(page_indptr[batch_row]);
    return static_cast<uint32_t>(page_indices[begin + logical_page]) * page_size +
           page_offset;
}

__global__ void kv_append_paged_kernel(float *cache,
                                       const float *src,
                                       uint32_t base_logical_pos,
                                       uint32_t per_pos_size,
                                       uint32_t src_stride,
                                       const int32_t *page_indices,
                                       uint32_t page_size) {
    const uint32_t b = blockIdx.x;
    const uint32_t i = blockIdx.y * blockDim.x + threadIdx.x;
    if (i >= per_pos_size) return;
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(base_logical_pos + b, page_indices, page_size);
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    cache[static_cast<uint64_t>(physical_pos) * per_pos_size + i] = src_row[i];
}

__global__ void kv_append_paged_ragged_kernel(float *cache,
                                              const float *src,
                                              const int32_t *logical_positions,
                                              uint32_t per_pos_size,
                                              uint32_t src_stride,
                                              const int32_t *page_indices,
                                              const int32_t *page_indptr,
                                              uint32_t page_size) {
    const uint32_t b = blockIdx.x;
    const uint32_t i = blockIdx.y * blockDim.x + threadIdx.x;
    if (i >= per_pos_size) return;
    const uint32_t logical_pos = static_cast<uint32_t>(logical_positions[b]);
    const uint32_t physical_pos =
        kv_physical_pos_from_ragged_pages(b, logical_pos, page_indices,
                                          page_indptr, page_size);
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    cache[static_cast<uint64_t>(physical_pos) * per_pos_size + i] = src_row[i];
}

__global__ void kv_append_kernel_f16(__half *cache,
                                     const float *src,
                                     uint32_t base_pos,
                                     uint32_t per_pos_size,
                                     uint32_t src_stride) {
    const uint32_t b = blockIdx.x;
    const uint32_t i = blockIdx.y * blockDim.x + threadIdx.x;
    if (i >= per_pos_size) return;
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    cache[static_cast<uint64_t>(base_pos + b) * per_pos_size + i] =
        __float2half(src_row[i]);
}

