    if (i >= per_pos_size) return;
    const uint32_t logical_pos = static_cast<uint32_t>(logical_positions[b]);
    const uint32_t physical_pos =
        kv_physical_pos_from_ragged_pages(b, logical_pos, page_indices,
                                          page_indptr, page_size);
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    cache[static_cast<uint64_t>(physical_pos) * per_pos_size + i] =
        __float2half(src_row[i]);
}

// FP8 (e4m3) quantize-on-write. Raw e4m3, NO scale. Convert and store pairs
// with the native float2 -> fp8x2 operation; the odd tail remains scalar for
// generality even though supported attention dimensions are all even.
__global__ void kv_append_kernel_fp8(__nv_fp8_e4m3 *cache,
                                     const float *src,
                                     uint32_t base_pos,
                                     uint32_t per_pos_size,
                                     uint32_t src_stride) {
    const uint32_t b = blockIdx.x;
    const uint32_t i =
        2U * (blockIdx.y * blockDim.x + threadIdx.x);
    if (i >= per_pos_size) return;
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    __nv_fp8_e4m3 *dst =
        cache + static_cast<uint64_t>(base_pos + b) * per_pos_size + i;
    if (i + 1U < per_pos_size) {
        const float2 pair = make_float2(src_row[i], src_row[i + 1U]);
        *reinterpret_cast<__nv_fp8x2_storage_t *>(dst) =
            __nv_cvt_float2_to_fp8x2(pair, __NV_SATFINITE, __NV_E4M3);
    } else {
        dst[0] = __nv_fp8_e4m3(src_row[i]);
    }
}

__global__ void kv_append_paged_kernel_fp8(__nv_fp8_e4m3 *cache,
                                           const float *src,
                                           uint32_t base_logical_pos,
                                           uint32_t per_pos_size,
                                           uint32_t src_stride,
                                           const int32_t *page_indices,
                                           uint32_t page_size) {
    const uint32_t b = blockIdx.x;
    const uint32_t i =
        2U * (blockIdx.y * blockDim.x + threadIdx.x);
    if (i >= per_pos_size) return;
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(base_logical_pos + b, page_indices, page_size);
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    __nv_fp8_e4m3 *dst =
        cache + static_cast<uint64_t>(physical_pos) * per_pos_size + i;
    if (i + 1U < per_pos_size) {
        const float2 pair = make_float2(src_row[i], src_row[i + 1U]);
        *reinterpret_cast<__nv_fp8x2_storage_t *>(dst) =
            __nv_cvt_float2_to_fp8x2(pair, __NV_SATFINITE, __NV_E4M3);
    } else {
        dst[0] = __nv_fp8_e4m3(src_row[i]);
    }
}

__global__ void kv_append_lazy_linear_kernel_fp8(
        __nv_fp8_e4m3 *cache,
        const float *raw,
        const float *activation_scales,
        const float *weight_scales,
        uint32_t base_pos,
        uint32_t per_pos_size,
        uint32_t raw_stride,
        uint32_t row_offset) {
    const uint32_t token = blockIdx.x;
    const uint32_t i =
        2U * (blockIdx.y * blockDim.x + threadIdx.x);
    if (i >= per_pos_size) return;
    const uint64_t raw_base =
        static_cast<uint64_t>(token) * raw_stride + row_offset;
    const float activation_scale = activation_scales[token];
    __nv_fp8_e4m3 *dst =
        cache + static_cast<uint64_t>(base_pos + token) *
                    per_pos_size + i;
    const float value0 =
        raw[raw_base + i] * activation_scale * weight_scales[i];
    if (i + 1U < per_pos_size) {
        const float value1 =
            raw[raw_base + i + 1U] * activation_scale *
            weight_scales[i + 1U];
        *reinterpret_cast<__nv_fp8x2_storage_t *>(dst) =
            __nv_cvt_float2_to_fp8x2(
                make_float2(value0, value1),
                __NV_SATFINITE, __NV_E4M3);
    } else {
        dst[0] = __nv_fp8_e4m3(value0);
    }
}

__global__ void kv_append_paged_lazy_linear_kernel_fp8(
        __nv_fp8_e4m3 *cache,
        const float *raw,
        const float *activation_scales,
        const float *weight_scales,
        uint32_t base_logical_pos,
        uint32_t per_pos_size,
        uint32_t raw_stride,
        uint32_t row_offset,
        const int32_t *page_indices,
        uint32_t page_size) {
    const uint32_t token = blockIdx.x;
    const uint32_t i =
        2U * (blockIdx.y * blockDim.x + threadIdx.x);
    if (i >= per_pos_size) return;
    const uint32_t physical_pos =
        kv_physical_pos_from_pages(
            base_logical_pos + token, page_indices, page_size);
    const uint64_t raw_base =
        static_cast<uint64_t>(token) * raw_stride + row_offset;
    const float activation_scale = activation_scales[token];
    __nv_fp8_e4m3 *dst =
        cache + static_cast<uint64_t>(physical_pos) *
                    per_pos_size + i;
    const float value0 =
        raw[raw_base + i] * activation_scale * weight_scales[i];
    if (i + 1U < per_pos_size) {
        const float value1 =
            raw[raw_base + i + 1U] * activation_scale *
            weight_scales[i + 1U];
        *reinterpret_cast<__nv_fp8x2_storage_t *>(dst) =
            __nv_cvt_float2_to_fp8x2(
                make_float2(value0, value1),
                __NV_SATFINITE, __NV_E4M3);
    } else {
        dst[0] = __nv_fp8_e4m3(value0);
    }
}

__global__ void kv_append_paged_ragged_kernel_fp8(__nv_fp8_e4m3 *cache,
                                                  const float *src,
                                                  const int32_t *logical_positions,
                                                  uint32_t per_pos_size,
                                                  uint32_t src_stride,
                                                  const int32_t *page_indices,
                                                  const int32_t *page_indptr,
                                                  uint32_t page_size) {
    const uint32_t b = blockIdx.x;
    const uint32_t i =
        2U * (blockIdx.y * blockDim.x + threadIdx.x);
    if (i >= per_pos_size) return;
    const uint32_t logical_pos = static_cast<uint32_t>(logical_positions[b]);
    const uint32_t physical_pos =
        kv_physical_pos_from_ragged_pages(b, logical_pos, page_indices,
                                          page_indptr, page_size);
    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    __nv_fp8_e4m3 *dst =
        cache + static_cast<uint64_t>(physical_pos) * per_pos_size + i;
    if (i + 1U < per_pos_size) {
        const float2 pair = make_float2(src_row[i], src_row[i + 1U]);
        *reinterpret_cast<__nv_fp8x2_storage_t *>(dst) =
            __nv_cvt_float2_to_fp8x2(pair, __NV_SATFINITE, __NV_E4M3);
    } else {
        dst[0] = __nv_fp8_e4m3(src_row[i]);
    }
}

// Q8 quantize-on-write. One block per (token b, quant-row). A quant row is
// `row_elems` consecutive fp32 values (head_dim slice for one kv_head) that
// share a single symmetric int8 scale = max|x| / 127. Block size == row_elems
// (256), so each thread owns one element. Layout matches the fp16 path:
// element index = (base_pos+b)*per_pos_size + row*row_elems + lane.
__global__ void kv_append_kernel_q8(int8_t *cache,
                                    __half *scales,
                                    const float *src,
                                    uint32_t base_pos,
                                    uint32_t per_pos_size,
                                    uint32_t row_elems,
                                    uint32_t src_stride) {
    const uint32_t b   = blockIdx.x;
    const uint32_t row = blockIdx.y;            // 0 .. (per_pos_size/row_elems - 1)
    const uint32_t lane = threadIdx.x;          // 0 .. row_elems-1
    const uint32_t rows_per_pos = per_pos_size / row_elems;

    const float *src_row = src + static_cast<uint64_t>(b) * src_stride;
    const uint32_t elem_in_pos = row * row_elems + lane;
    const float x = (lane < row_elems) ? src_row[elem_in_pos] : 0.0f;

    // Block-wide max|x| reduction in shared memory.
    extern __shared__ float s_absmax[];
    s_absmax[lane] = fabsf(x);
    __syncthreads();
    for (uint32_t s = blockDim.x / 2; s > 0; s >>= 1) {
        if (lane < s) s_absmax[lane] = fmaxf(s_absmax[lane], s_absmax[lane + s]);
        __syncthreads();
    }
    const float absmax = s_absmax[0];
    const float scale = absmax / 127.0f;
    const float inv_scale = (absmax > 0.0f) ? (127.0f / absmax) : 0.0f;

    const uint64_t pos = static_cast<uint64_t>(base_pos + b);
    if (lane == 0) {
        scales[pos * rows_per_pos + row] = __float2half(scale);
    }
    // round-to-nearest, clamp to [-127,127].
    int q = __float2int_rn(x * inv_scale);
    q = q < -127 ? -127 : (q > 127 ? 127 : q);
    cache[pos * per_pos_size + elem_in_pos] = static_cast<int8_t>(q);
}

__global__ void kv_append_paged_kernel_q8(int8_t *cache,
                                          __half *scales,
                                          const float *src,
                                          uint32_t base_logical_pos,
                                          uint32_t per_pos_size,
                                          uint32_t row_elems,
                                          uint32_t src_stride,
                                          const int32_t *page_indices,
                                          uint32_t page_size) {
    const uint32_t b   = blockIdx.x;
    const uint32_t row = blockIdx.y;
