    static uint32_t fp8_fanout_custom_max_rows() {
        static const uint32_t threshold = []() {
            const char *value =
                std::getenv("QW3_FP8_FANOUT_CUSTOM_MAX_ROWS");
            if (!value || *value == '\0') return 2048U;
            char *end = nullptr;
            const unsigned long parsed = std::strtoul(value, &end, 10);
