    DeviceStatus fp8_matvec_f32_direct(float *out_ptr,
                                       const CudaWeight &w,
                                       const float *x_ptr,
                                       bool add,
                                       uint32_t threads_override = 0) {
        const dim3 grid(static_cast<uint32_t>(w.rows), 1);
        if (fp8_direct_vec2_enabled() && w.rows >= 4096 &&
            (w.cols % 2) == 0) {
            const uint32_t threads =
                threads_override ? threads_override : fp8_direct_threads();
            if (add) {
                fp8_weight_f32_matvec_vec2_kernel<true><<<
                    grid, threads, 0, exec_stream_>>>(
                    out_ptr,
                    static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                    static_cast<const float *>(w.scale), x_ptr,
                    static_cast<uint32_t>(w.rows),
                    static_cast<uint32_t>(w.cols),
                    1, static_cast<uint32_t>(w.cols),
                    static_cast<uint32_t>(w.rows));
            } else {
                fp8_weight_f32_matvec_vec2_kernel<false><<<
                    grid, threads, 0, exec_stream_>>>(
                    out_ptr,
                    static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                    static_cast<const float *>(w.scale), x_ptr,
                    static_cast<uint32_t>(w.rows),
                    static_cast<uint32_t>(w.cols),
                    1, static_cast<uint32_t>(w.cols),
                    static_cast<uint32_t>(w.rows));
            }
            return launch_status(add ? "FP8 direct vec2 matvec add"
                                     : "FP8 direct vec2 matvec");
        }
        if (add) {
            fp8_weight_f32_matvec_add_kernel<<<
                grid, 256, 0, exec_stream_>>>(
                out_ptr, static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                static_cast<const float *>(w.scale), x_ptr,
                static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                1, static_cast<uint32_t>(w.cols),
                static_cast<uint32_t>(w.rows));
        } else {
            fp8_weight_f32_matvec_kernel<<<
                grid, 256, 0, exec_stream_>>>(
                out_ptr, static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                static_cast<const float *>(w.scale), x_ptr,
                static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                1, static_cast<uint32_t>(w.cols),
                static_cast<uint32_t>(w.rows));
        }
        return launch_status(add ? "FP8 direct matvec add"
                                 : "FP8 direct matvec");
    }

    DeviceStatus fp8_matvec_bf16_direct(__nv_bfloat16 *out_ptr,
                                        const CudaWeight &w,
                                        const float *x_ptr,
                                        bool add,
                                        uint32_t threads_override = 0) {
        if ((w.cols % 2) != 0) {
            return {false, "FP8 BF16 direct matvec requires even cols"};
        }
        const dim3 grid(static_cast<uint32_t>(w.rows), 1);
        const uint32_t threads =
            threads_override ? threads_override : fp8_direct_threads();
        if (add) {
            fp8_weight_f32_matvec_bf16_vec2_kernel<true><<<
                grid, threads, 0, exec_stream_>>>(
                out_ptr,
                static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                static_cast<const float *>(w.scale), x_ptr,
                static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                1, static_cast<uint32_t>(w.cols),
                static_cast<uint32_t>(w.rows));
        } else {
            fp8_weight_f32_matvec_bf16_vec2_kernel<false><<<
                grid, threads, 0, exec_stream_>>>(
                out_ptr,
                static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                static_cast<const float *>(w.scale), x_ptr,
                static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                1, static_cast<uint32_t>(w.cols),
                static_cast<uint32_t>(w.rows));
        }
        return launch_status(add ? "FP8 direct BF16 matvec add"
                                 : "FP8 direct BF16 matvec");
    }

    DeviceStatus fp8_scale_fanout4(
            DeviceTensor *const *outs,
            const DeviceWeight *const *weights,
            const uint32_t *out_strides,
            const uint32_t *indices,
            const uint64_t *offsets,
            uint32_t count,
            uint32_t batch) {
        if (count < 2 || count > 4 || batch == 0) {
            return {false, "invalid FP8 scale fanout shape"};
        }
        float *out[4] = {nullptr, nullptr, nullptr, nullptr};
        const float *scales[4] = {nullptr, nullptr, nullptr, nullptr};
        uint32_t rows[4] = {0, 0, 0, 0};
        uint32_t strides[4] = {0, 0, 0, 0};
        uint64_t total = 0;
        for (uint32_t slot = 0; slot < count; ++slot) {
            const uint32_t index = indices[slot];
            const auto &w = as_weight(*weights[index]);
            out[slot] = as_tensor(*outs[index]).ptr;
            scales[slot] = static_cast<const float *>(w.scale);
            rows[slot] = static_cast<uint32_t>(w.rows);
            strides[slot] = out_strides[index];
            if (offsets[slot] != total) {
                return {false, "non-contiguous FP8 fanout scratch"};
            }
            total += static_cast<uint64_t>(batch) * rows[slot];
        }
        const unsigned threads = 256;
        const unsigned blocks =
            static_cast<unsigned>((total + threads - 1) / threads);
        fp8_outer_scale_fanout4_kernel<<<blocks, threads, 0, exec_stream_>>>(
            out[0], out[1], out[2], out[3],
            fp8_out_f32_, x_fp8_scales_,
            scales[0], scales[1], scales[2], scales[3],
            batch, rows[0], rows[1], rows[2], rows[3],
            strides[0], strides[1], strides[2], strides[3]);
        return launch_status("FP8 fused fanout output scaling");
    }

    DeviceStatus fp8_matmul_fanout_quantized(
            DeviceTensor *const *outs,
            const DeviceWeight *const *weights,
            const uint32_t *out_strides,
            uint32_t count,
            uint32_t batch) {
        if (count == 0 || batch == 0) return {};
        uint32_t total_rows = 0;
        for (uint32_t i = 0; i < count; ++i) {
            const auto &w = as_weight(*weights[i]);
            if (w.type != WeightType::FP8_E4M3) {
                return {false, "quantized FP8 fanout received non-FP8 weight"};
            }
            total_rows += static_cast<uint32_t>(w.rows);
        }
        const uint32_t cols =
            static_cast<uint32_t>(as_weight(*weights[0]).cols);
        if (auto st = ensure_fp8_linear_workspace(
                batch, cols, total_rows);
            !st.ok) {
            return st;
        }

        const bool fuse_scale =
            count >= 2 && count <= 4 &&
            fp8_fanout_scale_fusion_enabled();
        int32_t packed_first = -1;
        int32_t packed_second = -1;
        if (fuse_scale) {
            for (uint32_t i = 0; i < count; ++i) {
                const auto &first = as_weight(*weights[i]);
                if (!first.fp8_packed_second) continue;
                for (uint32_t j = 0; j < count; ++j) {
                    const auto &second = as_weight(*weights[j]);
                    if (&second == first.fp8_packed_second &&
                        first.fp8_packed_rows ==
                            first.rows + second.rows) {
                        packed_first = static_cast<int32_t>(i);
                        packed_second = static_cast<int32_t>(j);
                        break;
                    }
                }
                if (packed_first >= 0) break;
            }
        }

        if (packed_first >= 0) {
            const uint32_t first_index =
                static_cast<uint32_t>(packed_first);
            const uint32_t second_index =
                static_cast<uint32_t>(packed_second);
            const auto &first = as_weight(*weights[first_index]);
            const auto &second = as_weight(*weights[second_index]);
            if (auto st = cublaslt_fp8_matmul_view(
                    fp8_out_f32_, first.ptr, first.scale,
                    first.rows + second.rows, first.cols,
                    batch, 0.0f, false);
                !st.ok) {
                return st;
            }
            if (lazy_attention_fanout_requested_ && count == 3) {
                const uint32_t pair_rows =
                    static_cast<uint32_t>(first.rows + second.rows);
                as_tensor(*outs[first_index]).set_lazy_fp8_linear(
                    fp8_out_f32_, x_fp8_scales_,
                    static_cast<const float *>(first.scale),
                    batch, pair_rows, 0,
                    static_cast<uint32_t>(first.rows));
                as_tensor(*outs[second_index]).set_lazy_fp8_linear(
                    fp8_out_f32_, x_fp8_scales_,
                    static_cast<const float *>(second.scale),
                    batch, pair_rows, static_cast<uint32_t>(first.rows),
                    static_cast<uint32_t>(second.rows));

                uint64_t offset =
                    static_cast<uint64_t>(batch) * pair_rows;
                for (uint32_t i = 0; i < count; ++i) {
                    if (static_cast<int32_t>(i) == packed_first ||
                        static_cast<int32_t>(i) == packed_second) {
                        continue;
                    }
                    const auto &w = as_weight(*weights[i]);
                    float *raw = fp8_out_f32_ + offset;
                    if (auto st = cublaslt_fp8_matmul(
                            raw, w, batch, 0.0f, false); !st.ok) {
                        return st;
                    }
                    as_tensor(*outs[i]).set_lazy_fp8_linear(
                        raw, x_fp8_scales_,
                        static_cast<const float *>(w.scale),
                        batch, static_cast<uint32_t>(w.rows), 0,
                        static_cast<uint32_t>(w.rows));
                    offset += static_cast<uint64_t>(batch) * w.rows;
                }
                return {};
            }
            const uint64_t elements =
                static_cast<uint64_t>(batch) *
                (first.rows + second.rows);
            constexpr unsigned threads = 256;
            const unsigned blocks = static_cast<unsigned>(
                (elements + threads - 1) / threads);
            fp8_outer_scale_packed_pair_kernel<<<
                blocks, threads, 0, exec_stream_>>>(
                as_tensor(*outs[first_index]).ptr,
                as_tensor(*outs[second_index]).ptr,
                fp8_out_f32_, x_fp8_scales_,
                static_cast<const float *>(first.scale),
                static_cast<const float *>(second.scale),
                batch,
                static_cast<uint32_t>(first.rows),
                static_cast<uint32_t>(second.rows),
                out_strides[first_index],
                out_strides[second_index]);
            if (auto st = launch_status(
                    "FP8 packed pair batched output scaling");
                !st.ok) {
                return st;
            }
            for (uint32_t i = 0; i < count; ++i) {
                if (static_cast<int32_t>(i) == packed_first ||
                    static_cast<int32_t>(i) == packed_second) {
                    continue;
                }
                const auto &w = as_weight(*weights[i]);
                if (auto st = fp8_matmul_quantized(
                        as_tensor(*outs[i]).ptr, w, batch,
                        out_strides[i]);
                    !st.ok) {
                    return st;
                }
            }
            return {};
        }

        if (!fuse_scale) {
            for (uint32_t i = 0; i < count; ++i) {
                const auto &w = as_weight(*weights[i]);
                if (auto st = fp8_matmul_quantized(
                        as_tensor(*outs[i]).ptr, w, batch,
                        out_strides[i]);
                    !st.ok) {
                    return st;
                }
            }
            return {};
        }

        uint32_t indices[4] = {};
        uint64_t offsets[4] = {};
        uint64_t offset = 0;
        for (uint32_t i = 0; i < count; ++i) {
            const auto &w = as_weight(*weights[i]);
            indices[i] = i;
            offsets[i] = offset;
            if (auto st = cublaslt_fp8_matmul(
                    fp8_out_f32_ + offset, w, batch, 0.0f, false);
                !st.ok) {
                return st;
            }
            offset += static_cast<uint64_t>(batch) * w.rows;
        }
        return fp8_scale_fanout4(
            outs, weights, out_strides, indices, offsets, count, batch);
    }

    DeviceStatus fp8_bf16_matmul_fanout_quantized(
            DeviceTensor *const *outs,
            const DeviceWeight *const *weights,
            const uint32_t *out_strides,
            uint32_t count,
            uint32_t batch,
            uint32_t fp8_count,
            uint32_t bf16_count) {
        if (count == 0 || batch == 0) return {};
        if (fp8_count == 0 || fp8_count + bf16_count != count) {
            return {false, "invalid staged FP8/BF16 fanout"};
        }
        const bool fuse_scale =
            fp8_count >= 2 && fp8_count <= 4 &&
            fp8_fanout_scale_fusion_enabled();
        int32_t packed_first = -1;
        int32_t packed_second = -1;
        if (fuse_scale) {
            for (uint32_t i = 0; i < count; ++i) {
                const auto &first = as_weight(*weights[i]);
                if (first.type != WeightType::FP8_E4M3 ||
                    !first.fp8_packed_second) {
                    continue;
                }
                for (uint32_t j = 0; j < count; ++j) {
                    const auto &second = as_weight(*weights[j]);
                    if (second.type == WeightType::FP8_E4M3 &&
                        &second == first.fp8_packed_second &&
                        first.fp8_packed_rows ==
                            first.rows + second.rows) {
                        packed_first = static_cast<int32_t>(i);
                        packed_second = static_cast<int32_t>(j);
                        break;
                    }
                }
                if (packed_first >= 0) break;
            }
        }

        if (packed_first >= 0) {
            const uint32_t first_index =
                static_cast<uint32_t>(packed_first);
            const uint32_t second_index =
                static_cast<uint32_t>(packed_second);
            const auto &first = as_weight(*weights[first_index]);
            const auto &second = as_weight(*weights[second_index]);
            if (auto st = cublaslt_fp8_matmul_view(
                    fp8_out_f32_, first.ptr, first.scale,
                    first.rows + second.rows, first.cols,
                    batch, 0.0f, false);
                !st.ok) {
                return st;
            }
            if (lazy_recurrent_pair_requested_) {
                const uint32_t pair_rows =
                    static_cast<uint32_t>(first.rows + second.rows);
                as_tensor(*outs[first_index]).set_lazy_fp8_linear(
                    fp8_out_f32_, x_fp8_scales_,
                    static_cast<const float *>(first.scale),
                    batch, pair_rows, 0,
                    static_cast<uint32_t>(first.rows));
                as_tensor(*outs[second_index]).set_lazy_fp8_linear(
                    fp8_out_f32_, x_fp8_scales_,
                    static_cast<const float *>(second.scale),
                    batch, pair_rows, static_cast<uint32_t>(first.rows),
                    static_cast<uint32_t>(second.rows));
            } else {
                const uint64_t elements =
                    static_cast<uint64_t>(batch) *
                    (first.rows + second.rows);
                constexpr unsigned threads = 256;
                const unsigned blocks = static_cast<unsigned>(
                    (elements + threads - 1) / threads);
                fp8_outer_scale_packed_pair_kernel<<<
                    blocks, threads, 0, exec_stream_>>>(
                    as_tensor(*outs[first_index]).ptr,
                    as_tensor(*outs[second_index]).ptr,
                    fp8_out_f32_, x_fp8_scales_,
                    static_cast<const float *>(first.scale),
                    static_cast<const float *>(second.scale),
                    batch,
                    static_cast<uint32_t>(first.rows),
                    static_cast<uint32_t>(second.rows),
                    out_strides[first_index],
                    out_strides[second_index]);
                if (auto st = launch_status(
                        "FP8 packed pair batched output scaling");
                    !st.ok) {
                    return st;
                }
            }
        }

        uint32_t indices[4] = {};
        uint64_t offsets[4] = {};
        uint32_t slots = 0;
        uint64_t offset = 0;
        for (uint32_t i = 0; i < count; ++i) {
            const auto &w = as_weight(*weights[i]);
            auto &out = as_tensor(*outs[i]);
            if (w.type == WeightType::BF16) {
                if (auto st = bf16_matmul_converted(
                        out.ptr, w, batch,
                        static_cast<uint32_t>(w.cols),
                        out_strides[i]);
                    !st.ok) {
                    return st;
                }
                continue;
            }
            if (w.type != WeightType::FP8_E4M3) {
                return {false, "staged fanout received unsupported weight"};
            }
            if (static_cast<int32_t>(i) == packed_first ||
                static_cast<int32_t>(i) == packed_second) {
                continue;
            }
            if (packed_first >= 0 || !fuse_scale) {
                if (auto st = fp8_matmul_quantized(
                        out.ptr, w, batch, out_strides[i]);
                    !st.ok) {
                    return st;
                }
                continue;
            }
            indices[slots] = i;
            offsets[slots] = offset;
            if (auto st = cublaslt_fp8_matmul(
                    fp8_out_f32_ + offset, w, batch, 0.0f, false);
                !st.ok) {
                return st;
            }
            offset += static_cast<uint64_t>(batch) * w.rows;
            ++slots;
        }
        if (packed_first >= 0 || !fuse_scale) return {};
        return fp8_scale_fanout4(
            outs, weights, out_strides, indices, offsets, slots, batch);
    }

    DeviceStatus fp8_quantize_activation(const float *x_ptr,
                                         uint32_t batch,
                                         uint32_t cols,
                                         uint32_t in_stride,
                                         uint32_t max_rows,
                                         bool emit_bf16 = false) {
        if (auto st = ensure_fp8_linear_workspace(
                batch, cols, max_rows); !st.ok) {
            return st;
        }
        if (emit_bf16) {
            const uint64_t x_elems =
                static_cast<uint64_t>(batch) * in_stride;
            if (auto st = ensure_bf16_activation_workspace(x_elems);
                !st.ok) {
                return st;
            }
            fp32_to_fp8_bf16_per_row_kernel<<<
                batch, 256, 0, exec_stream_>>>(
                x_fp8_workspace_, x_fp8_scales_,
                x_bf16_workspace_, x_ptr,
                batch, cols, in_stride);
            return launch_status(
                "FP8 dynamic quantization with BF16 staging");
        }
        fp32_to_fp8_per_row_kernel<<<batch, 256, 0, exec_stream_>>>(
            x_fp8_workspace_, x_fp8_scales_, x_ptr,
            batch, cols, in_stride);
        return launch_status("FP8 dynamic activation quantization");
    }

    DeviceStatus fp8_scale_output(float *out_ptr,
                                  const CudaWeight &w,
                                  uint32_t batch,
                                  uint32_t out_stride,
                                  bool add) {
        const uint64_t out_count = static_cast<uint64_t>(batch) * w.rows;
        const unsigned threads = 256;
        const unsigned blocks =
            static_cast<unsigned>((out_count + threads - 1) / threads);
        if (add) {
            fp8_outer_scale_add_kernel<<<blocks, threads, 0, exec_stream_>>>(
                out_ptr, fp8_out_f32_, x_fp8_scales_,
                static_cast<const float *>(w.scale), batch,
                static_cast<uint32_t>(w.rows), out_stride);
        } else {
            fp8_outer_scale_kernel<<<blocks, threads, 0, exec_stream_>>>(
                out_ptr, fp8_out_f32_, x_fp8_scales_,
                static_cast<const float *>(w.scale), batch,
                static_cast<uint32_t>(w.rows), out_stride);
        }
        return launch_status(add ? "FP8 output scaling add"
                                 : "FP8 output scaling");
    }

    DeviceStatus fp8_scale_output_bf16(__nv_bfloat16 *out_ptr,
                                       const CudaWeight &w,
                                       uint32_t batch,
                                       uint32_t out_stride,
                                       bool add) {
        const uint64_t out_count = static_cast<uint64_t>(batch) * w.rows;
        const unsigned threads = 256;
        const unsigned blocks =
            static_cast<unsigned>((out_count + threads - 1) / threads);
        if (add) {
            fp8_outer_scale_bf16_kernel<true><<<
                blocks, threads, 0, exec_stream_>>>(
                out_ptr, fp8_out_f32_, x_fp8_scales_,
                static_cast<const float *>(w.scale), batch,
                static_cast<uint32_t>(w.rows), out_stride);
        } else {
            fp8_outer_scale_bf16_kernel<false><<<
                blocks, threads, 0, exec_stream_>>>(
                out_ptr, fp8_out_f32_, x_fp8_scales_,
                static_cast<const float *>(w.scale), batch,
                static_cast<uint32_t>(w.rows), out_stride);
        }
        return launch_status(add ? "FP8 BF16 output scaling add"
                                 : "FP8 BF16 output scaling");
    }

    DeviceStatus fp8_matmul_quantized(float *out_ptr,
                                      const CudaWeight &w,
                                      uint32_t batch,
                                      uint32_t out_stride,
                                      bool add = false) {
#if defined(QW3_ENABLE_NVFP4)
        if (!add &&
            batch > 256 &&
            out_stride == w.rows &&
            fp8_cutlass_f32_enabled() &&
            !fp8_cutlass_f32_failed_) {
            if (auto st = ensure_cublaslt_fp8(); !st.ok) {
                return st;
            }
            const bool launched = fp8_scaled_mm_adapter::launch_f32(
                out_ptr, x_fp8_workspace_, w.ptr,
                x_fp8_scales_, static_cast<const float *>(w.scale),
                batch, static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                cublaslt_workspace_, cublaslt_workspace_bytes_,
                exec_stream_);
            if (launched) {
                return launch_status("CUTLASS FP8 scaled FP32 matmul");
            }
            fp8_cutlass_f32_failed_ = true;
            (void) cudaGetLastError();
        }
#endif
        if (out_stride == w.rows && fp8_cublaslt_outer_scale_enabled()) {
            DeviceStatus direct = cublaslt_fp8_matmul(
                out_ptr, w, batch, add ? 1.0f : 0.0f, true);
            if (direct.ok) return direct;
            (void) cudaGetLastError();
        }
        if (auto st = cublaslt_fp8_matmul(w, batch); !st.ok) return st;
        return fp8_scale_output(out_ptr, w, batch, out_stride, add);
    }

    DeviceStatus fp8_matmul(float *out_ptr,
                            const CudaWeight &w,
                            const float *x_ptr,
                            uint32_t batch,
                            uint32_t in_stride,
                            uint32_t out_stride) {
        if (batch == 0) return {};
        if (!cublas_handle_ || !w.scale || in_stride < w.cols || out_stride < w.rows) {
            return {false, "invalid FP8 matmul state or strides"};
        }
        if (batch <= 8 && !fp8_small_cublaslt_enabled()) {
            const dim3 grid(static_cast<uint32_t>(w.rows), batch);
            fp8_weight_f32_matvec_kernel<<<grid, 256, 0, exec_stream_>>>(
                out_ptr, static_cast<const __nv_fp8_e4m3 *>(w.ptr),
                static_cast<const float *>(w.scale), x_ptr,
                static_cast<uint32_t>(w.rows), static_cast<uint32_t>(w.cols),
                batch, in_stride, out_stride);
            return launch_status("FP8 small-batch matvec");
        }
        if (auto st = fp8_quantize_activation(
                x_ptr, batch, static_cast<uint32_t>(w.cols), in_stride,
                static_cast<uint32_t>(w.rows)); !st.ok) {
            return st;
        }
        return fp8_matmul_quantized(out_ptr, w, batch, out_stride);
    }

    DeviceStatus fp8_matmul_bf16(__nv_bfloat16 *out_ptr,
                                 const CudaWeight &w,
                                 const float *x_ptr,
                                 uint32_t batch,
                                 uint32_t in_stride,
                                 uint32_t out_stride,
                                 bool add = false) {
        if (batch == 0) return {};
        if (!cublas_handle_ || !w.scale ||
            in_stride < w.cols || out_stride < w.rows) {
            return {false, "invalid FP8 BF16 matmul state or strides"};
        }
        if (batch <= 8 && !fp8_small_cublaslt_enabled() &&
            batch == 1 && in_stride == w.cols && out_stride == w.rows) {
            return fp8_matvec_bf16_direct(out_ptr, w, x_ptr, add);
        }
        if (auto st = fp8_quantize_activation(
                x_ptr, batch, static_cast<uint32_t>(w.cols), in_stride,
                static_cast<uint32_t>(w.rows)); !st.ok) {
            return st;
        }
#if defined(QW3_ENABLE_NVFP4)
        if (!add &&
            batch > 256 &&
            in_stride == w.cols &&
            out_stride == w.rows &&
            fp8_cutlass_bf16_enabled() &&
            !fp8_cutlass_bf16_failed_) {
            if (auto st = ensure_cublaslt_fp8(); !st.ok) {
                return st;
            }
            const bool launched = fp8_scaled_mm_adapter::launch_bf16(
                out_ptr, x_fp8_workspace_, w.ptr,
                x_fp8_scales_, static_cast<const float *>(w.scale),
                batch, static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols),
                cublaslt_workspace_, cublaslt_workspace_bytes_,
                exec_stream_);
            if (launched) {
                return launch_status("CUTLASS FP8 scaled BF16 matmul");
            }
            fp8_cutlass_bf16_failed_ = true;
            (void) cudaGetLastError();
        }
#endif
        if (out_stride == w.rows &&
            fp8_bf16_epilogue_enabled() &&
            !fp8_bf16_epilogue_failed_) {
            DeviceStatus direct = cublaslt_fp8_matmul_view(
                out_ptr, w.ptr, w.scale, w.rows, w.cols, batch,
                add ? 1.0f : 0.0f, true, CUDA_R_16BF);
            if (direct.ok) return direct;
            fp8_bf16_epilogue_failed_ = true;
            (void) cudaGetLastError();
        }
        if (auto st = cublaslt_fp8_matmul(w, batch); !st.ok) {
            return st;
        }
        return fp8_scale_output_bf16(
            out_ptr, w, batch, out_stride, add);
    }

    static bool nvfp4_small_mmvq_route_enabled(const char *name,
                                               bool default_value) {
        const char *value = std::getenv(name);
        if (!value || *value == '\0') {
            value = std::getenv("QW3_NVFP4_SMALL_MMVQ");
        }
        if (!value || *value == '\0') return default_value;
        return std::strcmp(value, "0") != 0 &&
               std::strcmp(value, "off") != 0 &&
               std::strcmp(value, "false") != 0;
    }

    static bool nvfp4_small_single_mmvq_enabled() {
        static const bool enabled = nvfp4_small_mmvq_route_enabled(
            "QW3_NVFP4_SMALL_SINGLE", false);
        return enabled;
    }

    static bool nvfp4_small_pair_mmvq_enabled() {
        static const bool enabled = nvfp4_small_mmvq_route_enabled(
            "QW3_NVFP4_SMALL_PAIR", true);
        return enabled;
    }

    static bool nvfp4_cutlass_pair_enabled() {
        static const bool enabled = []() {
            const char *value =
                std::getenv("QW3_NVFP4_FUSED_CUTLASS_PAIR");
            return !value ||
                   (std::strcmp(value, "0") != 0 &&
                    std::strcmp(value, "off") != 0 &&
                    std::strcmp(value, "false") != 0);
        }();
        return enabled;
    }

    DeviceStatus ensure_nvfp4_activation_workspace(uint32_t batch,
                                                   uint32_t cols) {
#ifndef QW3_ENABLE_NVFP4
        (void)batch;
        (void)cols;
        return {false, "NVFP4 requires an SM120a FlashInfer/CUTLASS build"};
#else
        const size_t packed_bytes =
            nvfp4_adapter::packed_activation_bytes(batch, cols);
        const size_t scale_bytes =
            nvfp4_adapter::activation_scale_bytes(batch, cols);
        if (x_fp4_workspace_capacity_ < packed_bytes) {
            if (x_fp4_workspace_) cudaFree(x_fp4_workspace_);
            if (auto st = cuda_status(cudaMalloc(&x_fp4_workspace_, packed_bytes),
                                      "NVFP4 activation alloc"); !st.ok) {
                x_fp4_workspace_ = nullptr;
                x_fp4_workspace_capacity_ = 0;
                return st;
            }
            x_fp4_workspace_capacity_ = packed_bytes;
        }
        if (x_fp4_scales_capacity_ < scale_bytes) {
            if (x_fp4_scales_) cudaFree(x_fp4_scales_);
            if (auto st = cuda_status(cudaMalloc(&x_fp4_scales_, scale_bytes),
                                      "NVFP4 activation scales alloc"); !st.ok) {
                x_fp4_scales_ = nullptr;
                x_fp4_scales_capacity_ = 0;
                return st;
            }
            x_fp4_scales_capacity_ = scale_bytes;
        }
        return {};
#endif
    }

    DeviceStatus quantize_nvfp4_activation(const CudaWeight &w,
                                           const float *x_ptr,
                                           uint32_t batch,
                                           uint32_t in_stride) {
#ifndef QW3_ENABLE_NVFP4
        (void)w;
        (void)x_ptr;
        (void)batch;
        (void)in_stride;
        return {false, "NVFP4 requires an SM120a FlashInfer/CUTLASS build"};
#else
        if (auto st = ensure_nvfp4_activation_workspace(
                batch, static_cast<uint32_t>(w.cols)); !st.ok) {
            return st;
        }
        if (!nvfp4_adapter::quantize_activation(
                x_fp4_workspace_, x_fp4_scales_, x_ptr, w.input_scale,
                batch, static_cast<uint32_t>(w.cols), in_stride,
                false, exec_stream_)) {
            return {false, "NVFP4 small-batch activation quantization failed"};
        }
        return {};
#endif
    }

    DeviceStatus ensure_nvfp4_gemm_workspace(uint32_t batch,
                                             uint32_t rows,
                                             uint32_t cols) {
#ifndef QW3_ENABLE_NVFP4
        (void)batch;
        (void)rows;
        (void)cols;
        return {false, "NVFP4 requires an SM120a FlashInfer/CUTLASS build"};
#else
        size_t required = 0;
        try {
            required = nvfp4_adapter::workspace_bytes(batch, rows, cols);
        } catch (const std::runtime_error &) {
            return {false, "FlashInfer rejected the NVFP4 GEMM shape"};
        }
        if (fp4_gemm_workspace_capacity_ < required) {
            if (fp4_gemm_workspace_) cudaFree(fp4_gemm_workspace_);
            if (auto st = cuda_status(
                    cudaMalloc(&fp4_gemm_workspace_, required),
                    "NVFP4 GEMM workspace alloc"); !st.ok) {
                fp4_gemm_workspace_ = nullptr;
                fp4_gemm_workspace_capacity_ = 0;
                return st;
            }
            fp4_gemm_workspace_capacity_ = required;
        }
        return {};
#endif
    }

    DeviceStatus ensure_nvfp4_pair_output(uint64_t count) {
        if (nvfp4_pair_out_f32_capacity_ >= count) return {};
        if (nvfp4_pair_out_f32_) cudaFree(nvfp4_pair_out_f32_);
        if (auto st = cuda_status(
                cudaMalloc(&nvfp4_pair_out_f32_,
                           static_cast<size_t>(count) * sizeof(float)),
                "NVFP4 pair output alloc"); !st.ok) {
            nvfp4_pair_out_f32_ = nullptr;
            nvfp4_pair_out_f32_capacity_ = 0;
            return st;
        }
        nvfp4_pair_out_f32_capacity_ = count;
        return {};
    }

    DeviceStatus nvfp4_matmul(float *out_ptr,
                              const CudaWeight &w,
                              const float *x_ptr,
                              uint32_t batch,
                              uint32_t in_stride,
                              uint32_t out_stride) {
#ifndef QW3_ENABLE_NVFP4
        (void)out_ptr; (void)w; (void)x_ptr; (void)batch;
        (void)in_stride; (void)out_stride;
        return {false, "NVFP4 requires an SM120a FlashInfer/CUTLASS build"};
#else
        if (batch == 0) return {};
        if (!w.scale || !w.input_scale || !w.global_scale ||
            in_stride < w.cols || out_stride < w.rows) {
            return {false, "invalid NVFP4 matmul state or strides"};
        }
        if (auto st = ensure_nvfp4_activation_workspace(
                batch, static_cast<uint32_t>(w.cols)); !st.ok) {
            return st;
        }
        if (batch == 1 && nvfp4_small_single_mmvq_enabled()) {
            if (auto st = quantize_nvfp4_activation(
                    w, x_ptr, batch, in_stride); !st.ok) return st;
            if (!nvfp4_adapter::launch_small_f32(
                    out_ptr, x_fp4_workspace_, x_fp4_scales_,
                    w.ptr, w.scale, w.global_scale,
                    batch, static_cast<uint32_t>(w.rows),
                    static_cast<uint32_t>(w.cols), out_stride,
                    false, exec_stream_)) {
                return {false, "NVFP4 small-batch MMVQ launch failed"};
            }
            return launch_status("NVFP4 small-batch MMVQ");
        }

        if (auto st = ensure_nvfp4_gemm_workspace(
                batch, static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols)); !st.ok) {
            return st;
        }
        if (batch == 1 && nvfp4_cutlass_bf16_output_enabled()) {
            if (auto st = ensure_mixed_bf16_output(w.rows); !st.ok) return st;
            if (!nvfp4_adapter::launch_bf16(
                    mixed_out_bf16_, x_fp4_workspace_, x_fp4_scales_,
                    fp4_gemm_workspace_, fp4_gemm_workspace_capacity_,
                    x_ptr, in_stride, w.ptr, w.scale, w.input_scale, w.global_scale,
                    batch, static_cast<uint32_t>(w.rows),
                    static_cast<uint32_t>(w.cols), exec_stream_)) {
                return {false, "FlashInfer NVFP4 BF16 GEMM launch failed"};
            }
            const unsigned threads = 256;
            const unsigned blocks =
                static_cast<unsigned>((w.rows + threads - 1) / threads);
            bf16_to_fp32_kernel<<<blocks, threads, 0, exec_stream_>>>(
                out_ptr, mixed_out_bf16_, w.rows);
        } else if (!nvfp4_adapter::launch(
                       out_ptr, x_fp4_workspace_, x_fp4_scales_,
                       fp4_gemm_workspace_, fp4_gemm_workspace_capacity_,
                       x_ptr, in_stride, w.ptr, w.scale, w.input_scale,
                       w.global_scale, batch, static_cast<uint32_t>(w.rows),
                       static_cast<uint32_t>(w.cols), exec_stream_)) {
            return {false, "FlashInfer NVFP4 quantization/GEMM launch failed"};
        }
        return launch_status("NVFP4 FP32 GEMM");
#endif
    }

    DeviceStatus nvfp4_matmul_bf16(__nv_bfloat16 *out_ptr,
                                   const CudaWeight &w,
                                   const float *x_ptr,
                                   uint32_t batch,
                                   uint32_t in_stride,
                                   uint32_t out_stride) {
#ifndef QW3_ENABLE_NVFP4
        (void)out_ptr; (void)w; (void)x_ptr; (void)batch;
        (void)in_stride; (void)out_stride;
        return {false, "NVFP4 requires an SM120a FlashInfer/CUTLASS build"};
#else
        if (batch == 0) return {};
        if (!out_ptr || !w.scale || !w.input_scale || !w.global_scale ||
            in_stride < w.cols || out_stride < w.rows) {
            return {false, "invalid NVFP4 BF16 matmul state or strides"};
        }
        if (auto st = ensure_nvfp4_activation_workspace(
                batch, static_cast<uint32_t>(w.cols)); !st.ok) {
            return st;
        }
        if (batch <= 8 && nvfp4_small_single_mmvq_enabled()) {
            if (auto st = quantize_nvfp4_activation(
                    w, x_ptr, batch, in_stride); !st.ok) {
                return st;
            }
            if (!nvfp4_adapter::launch_small_bf16(
                    out_ptr, x_fp4_workspace_, x_fp4_scales_,
                    w.ptr, w.scale, w.global_scale,
                    batch, static_cast<uint32_t>(w.rows),
                    static_cast<uint32_t>(w.cols), out_stride,
                    false, exec_stream_)) {
                return {false, "NVFP4 small-batch BF16 MMVQ launch failed"};
            }
            return launch_status("NVFP4 small-batch BF16 MMVQ");
        }
        if (auto st = ensure_nvfp4_gemm_workspace(
                batch, static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols)); !st.ok) {
            return st;
        }
        if (!nvfp4_adapter::launch_bf16(
                out_ptr, x_fp4_workspace_, x_fp4_scales_,
                fp4_gemm_workspace_, fp4_gemm_workspace_capacity_,
                x_ptr, in_stride, w.ptr, w.scale, w.input_scale,
                w.global_scale, batch, static_cast<uint32_t>(w.rows),
                static_cast<uint32_t>(w.cols), exec_stream_)) {
            return {false, "FlashInfer NVFP4 BF16 GEMM launch failed"};
        }
        return launch_status("NVFP4 BF16 GEMM");
#endif
    }

    DeviceStatus ensure_mixed_bf16_output(uint64_t count) {
        if (mixed_out_bf16_capacity_ >= count) return {};
        if (shared_linear_output_workspace_enabled()) {
            if (auto st = ensure_shared_linear_output_workspace(
                    static_cast<size_t>(count) *
                        sizeof(__nv_bfloat16));
                !st.ok) {
                return st;
            }
            mixed_out_bf16_capacity_ = count;
            return {};
        }
        if (mixed_out_bf16_) cudaFree(mixed_out_bf16_);
        if (auto st = cuda_status(
                cudaMalloc(&mixed_out_bf16_,
                           static_cast<size_t>(count) * sizeof(__nv_bfloat16)),
                "NVFP4 BF16 output alloc"); !st.ok) {
            mixed_out_bf16_ = nullptr;
            mixed_out_bf16_capacity_ = 0;
            return st;
        }
        mixed_out_bf16_capacity_ = count;
        return {};
    }

    static bool shared_linear_output_workspace_enabled() {
        static const bool enabled = []() {
            const char *value =
                std::getenv("QW3_SHARED_LINEAR_OUTPUT_WORKSPACE");
            return !value || !*value ||
                   (std::strcmp(value, "0") != 0 &&
                    std::strcmp(value, "off") != 0 &&
                    std::strcmp(value, "false") != 0);
        }();
        return enabled;
    }

    DeviceStatus ensure_shared_linear_output_workspace(size_t bytes) {
        if (linear_output_workspace_capacity_ < bytes) {
            if (linear_output_workspace_) cudaFree(linear_output_workspace_);
            linear_output_workspace_ = nullptr;
            linear_output_workspace_capacity_ = 0;
            mixed_out_bf16_ = nullptr;
            fp8_out_f32_ = nullptr;
            if (auto st = cuda_status(
                    cudaMalloc(&linear_output_workspace_, bytes),
                    "shared linear output workspace alloc"); !st.ok) {
                mixed_out_bf16_capacity_ = 0;
                fp8_out_f32_capacity_ = 0;
                return st;
            }
            linear_output_workspace_capacity_ = bytes;
        }
        mixed_out_bf16_ =
            static_cast<__nv_bfloat16 *>(linear_output_workspace_);
        fp8_out_f32_ = static_cast<float *>(linear_output_workspace_);
        return {};
    }

    static bool nvfp4_cutlass_bf16_output_enabled() {
        static const bool enabled = []() {
            const char *env =
                std::getenv("QW3_NVFP4_CUTLASS_OUTPUT_BF16");
            return env && std::string(env) != "0" &&
                   std::string(env) != "off";
        }();
        return enabled;
    }

    DeviceStatus ensure_kv_copy_stream() {
        if (!exec_stream_) {
            if (auto st = begin(); !st.ok) return st;
        }
        if (!kv_copy_stream_) {
            if (auto st = cuda_status(cudaStreamCreateWithFlags(&kv_copy_stream_,
                                                                cudaStreamNonBlocking),
                                      "KVMem copy stream");
                !st.ok) return st;
        }
        if (!kv_copy_exec_ready_) {
            if (auto st = cuda_status(cudaEventCreateWithFlags(
                                          &kv_copy_exec_ready_,
                                          cudaEventDisableTiming),
                                      "KVMem exec-ready event");
                !st.ok) return st;
        }
        return {};
    }

    // FP16 HGEMM for Q8_0 weights. On every call we dequant the weight into
    // a per-call FP16 scratch (no persistent mirror — keeps weight memory at
    // 8-bit only), then run cublasGemmEx with FP16 inputs and FP32 accum.
    //
    // Pipelined: two ping-pong scratch buffers and two CUDA streams let the
    // dequant of W_{n+1} run concurrently with the HGEMM of W_n. Events
    // synchronize buffer ownership:
    //   - dequant_done_[idx]: signals the dequant of buffer[idx] is finished
    //                         and HGEMM may consume it.
    //   - hgemm_done_[idx]:   signals HGEMM has finished reading buffer[idx]
    //                         and the next dequant may overwrite it.
    //
    // Layout:  O[b, r] = sum_c W[r, c] * X[b, c],  W (rows, cols) row-major,
    //          X (batch, cols) row-major, O (batch, rows) row-major.
    //
    // In cuBLAS column-major terms with A=W (CMV: cols x rows) and
    // B=X (CMV: cols x batch):  C(rows, batch) = A^T * B.
    DeviceStatus hgemm_q8(float *out_ptr, CudaWeight &w, const float *x_ptr, uint32_t batch) {
        if (auto st = ensure_dequant_pipeline(); !st.ok) return st;
        const uint64_t w_elems = w.rows * w.cols;
        if (w_fp16_capacity_ < w_elems) {
            // Resize both ping-pong buffers and clear pending events.
            for (int i = 0; i < 2; ++i) {
                if (w_fp16_workspace_[i]) cudaFree(w_fp16_workspace_[i]);
                w_fp16_workspace_[i] = nullptr;
            }
            for (int i = 0; i < 2; ++i) {
                if (auto st = cuda_status(cudaMalloc(&w_fp16_workspace_[i],
                                                     static_cast<size_t>(w_elems) * sizeof(__half)),
                                          "hgemm w_fp16 alloc"); !st.ok) {
                    w_fp16_capacity_ = 0;
                    return st;
                }
            }
            w_fp16_capacity_ = w_elems;
            w_fp16_idx_ = 0;
            // No prior in-flight dequants/HGEMMs to wait on after a resize.
        }

        const int idx = w_fp16_idx_;

        // When stream capture is active, the cross-stream ping-pong pipeline
        // can't be used: cudaStreamWaitEvent / cudaEventRecord on a stream
        // that isn't itself being captured trips the capture into an error
        // state. Fall back to dequant on exec_stream_ (no overlap with the
        // cuBLAS gemm of the previous matmul, but inside one chunk we lose
        // ~5% throughput; the capture replay recovers ~10-15% by amortizing
        // launch overhead across all 8/64/128/etc chunks of a prefill).
        const bool use_pipeline = !capture_active_;

        if (use_pipeline) {
            // Dequant runs on dequant_stream_; wait for the previous HGEMM that
            // read this buffer to finish before overwriting.
            cudaStreamWaitEvent(dequant_stream_, hgemm_done_[idx], 0);
            if (auto st = dequant_q8_to_f16_stream(w_fp16_workspace_[idx], w, dequant_stream_); !st.ok) return st;
            cudaEventRecord(dequant_done_[idx], dequant_stream_);
        } else {
            if (auto st = dequant_q8_to_f16_stream(w_fp16_workspace_[idx], w, exec_stream_); !st.ok) return st;
        }

        // Stage X (FP32 -> FP16) on the cuBLAS / default stream. This work
        // doesn't conflict with the dequant since they touch different
        // buffers (x_fp16_workspace_ vs w_fp16_workspace_[idx]).
        //
        // Cache: QKV and gate/up matmul pairs share the same x_ptr in
        // immediate succession. If the prior conversion was for the same
        // (x_ptr, x_elems), the FP16 staging buffer still holds it — no
        // intervening kernel writes to x_fp16_workspace_, and by invariant
        // no kernel writes to x_ptr's buffer between hgemm_q8 calls with
        // shared input. Skip the conversion launch on hit. Disable via
        // QW3_HGEMM_X_CACHE=0 for diagnostic / forced-recompute runs.
        const uint64_t x_elems = static_cast<uint64_t>(batch) * w.cols;
        if (x_fp16_capacity_ < x_elems) {
            if (x_fp16_workspace_) cudaFree(x_fp16_workspace_);
            if (auto st = cuda_status(cudaMalloc(&x_fp16_workspace_,
                                                 static_cast<size_t>(x_elems) * sizeof(__half)),
                                      "hgemm x_fp16 alloc"); !st.ok) {
                x_fp16_workspace_ = nullptr;
                x_fp16_capacity_ = 0;
                x_fp16_cached_src_ = nullptr;
                x_fp16_cached_elems_ = 0;
                return st;
            }
            x_fp16_capacity_ = x_elems;
            x_fp16_cached_src_ = nullptr;     // resize invalidates the cache
            x_fp16_cached_elems_ = 0;
        }
        const bool x_cache_disabled = []() {
            const char *e = std::getenv("QW3_HGEMM_X_CACHE");
            return e && (std::strcmp(e, "0") == 0 || std::strcmp(e, "off") == 0);
        }();
        const bool x_cache_hit = !x_cache_disabled
                              && x_fp16_cached_src_   == x_ptr
                              && x_fp16_cached_elems_ == x_elems;
        if (!x_cache_hit) {
            const unsigned threads = 256;
            // Vectorized kernel: 4 elements per thread.
            const uint64_t threads_total = (x_elems + 3) / 4;
            const unsigned blocks = static_cast<unsigned>((threads_total + threads - 1) / threads);
            fp32_to_fp16_kernel<<<blocks, threads, 0, exec_stream_>>>(x_fp16_workspace_, x_ptr, x_elems);
            if (auto st = launch_status("hgemm fp32->fp16"); !st.ok) {
                x_fp16_cached_src_ = nullptr;
                x_fp16_cached_elems_ = 0;
                return st;
            }
            x_fp16_cached_src_ = x_ptr;
            x_fp16_cached_elems_ = x_elems;
        }

        // cuBLAS waits for the matching dequant to complete before reading
        // buffer[idx]. cuBLAS handle is bound to exec_stream_; issue the
        // stream-wait there. (Skipped during capture: dequant ran on
        // exec_stream_, so it's already ordered.)
        if (use_pipeline) {
            cudaStreamWaitEvent(exec_stream_, dequant_done_[idx], 0);
        }

        const float alpha = 1.0f;
        const float beta = 0.0f;
        const int m = static_cast<int>(w.rows);
        const int n = static_cast<int>(batch);
        const int k = static_cast<int>(w.cols);
        // CUBLAS_COMPUTE_32F_FAST_16F: FP16 inputs, FP32 accumulator with the
        // FP16-fast-path tensor-core kernels. Tried CUBLAS_COMPUTE_16F (FP16
        // accumulator) for ~2x throughput; cuBLAS 13.x falls back to a non-
        // tensor-core path for our shapes (Q8 weight FP16 mirrors with K up
        // to ~17K), regressing prefill 25x. Stay on FAST_16F.
        if (auto st = cublas_status(
                cublasGemmEx(cublas_handle_,
                             CUBLAS_OP_T, CUBLAS_OP_N,
                             m, n, k,
                             &alpha,
                             w_fp16_workspace_[idx], CUDA_R_16F, k,
                             x_fp16_workspace_, CUDA_R_16F, k,
                             &beta,
                             out_ptr, CUDA_R_32F, m,
                             CUBLAS_COMPUTE_32F_FAST_16F,
                             CUBLAS_GEMM_DEFAULT_TENSOR_OP),
                "cublasGemmEx hgemm_q8"); !st.ok) {
            return st;
        }
        if (use_pipeline) {
            cudaEventRecord(hgemm_done_[idx], exec_stream_);
        }

        w_fp16_idx_ ^= 1;
        return {};
    }

    DeviceStatus ensure_dequant_pipeline() {
        if (dequant_stream_) return {};
        if (auto st = cuda_status(cudaStreamCreateWithFlags(&dequant_stream_, cudaStreamNonBlocking),
                                  "dequant stream"); !st.ok) return st;
        for (int i = 0; i < 2; ++i) {
            if (auto st = cuda_status(cudaEventCreateWithFlags(&dequant_done_[i], cudaEventDisableTiming),
                                      "dequant event"); !st.ok) return st;
            if (auto st = cuda_status(cudaEventCreateWithFlags(&hgemm_done_[i], cudaEventDisableTiming),
                                      "hgemm event"); !st.ok) return st;
            // Initial events are signalled so the first dequant doesn't
            // block waiting on a non-existent prior HGEMM.
            cudaEventRecord(dequant_done_[i], exec_stream_);
            cudaEventRecord(hgemm_done_[i],   exec_stream_);
        }
        return {};
    }

    // Lazy/owning allocator for the Q8_1 activation scratch shared by mmvq
    // matvec, mmq matmul, and the matvec_fanout fast path.
    DeviceStatus ensure_q8_1_scratch(uint32_t batch, uint32_t cols) {
        const size_t need = ported::q8_1_scratch_bytes(batch, cols);
        if (need > q8_1_scratch_capacity_) {
            if (q8_1_scratch_) cudaFree(q8_1_scratch_);
            if (auto st = cuda_status(cudaMalloc(&q8_1_scratch_, need),
                                      "q8_1 scratch alloc"); !st.ok) {
                q8_1_scratch_ = nullptr;
                q8_1_scratch_capacity_ = 0;
                return st;
            }
            q8_1_scratch_capacity_ = need;
        }
        return {};
    }

    DeviceStatus ensure_q8_1_mmq_scratch(uint32_t batch, uint32_t cols) {
        const size_t need = ported::q8_1_mmq_scratch_bytes(batch, cols);
        if (need > q8_1_mmq_scratch_capacity_) {
            if (q8_1_mmq_scratch_) cudaFree(q8_1_mmq_scratch_);
            if (auto st = cuda_status(cudaMalloc(&q8_1_mmq_scratch_, need),
                                      "q8_1_mmq scratch alloc"); !st.ok) {
                q8_1_mmq_scratch_ = nullptr;
                q8_1_mmq_scratch_capacity_ = 0;
                return st;
            }
            q8_1_mmq_scratch_capacity_ = need;
        }
        return {};
    }

    DeviceStatus ensure_q8_output_workspace(uint64_t count) {
        if (q8_out_f32_capacity_ >= count) return {};
        if (q8_out_f32_) cudaFree(q8_out_f32_);
        if (auto st = cuda_status(
                cudaMalloc(&q8_out_f32_, count * sizeof(float)),
                "Q8 FP32 output workspace alloc"); !st.ok) {
            q8_out_f32_ = nullptr;
            q8_out_f32_capacity_ = 0;
            return st;
        }
        q8_out_f32_capacity_ = count;
        return {};
    }

    DeviceStatus convert_q8_output_bf16(__nv_bfloat16 *out, uint64_t count) {
        const unsigned threads = 256;
        const unsigned blocks =
            static_cast<unsigned>((count + threads - 1) / threads);
        fp32_to_bf16_kernel<<<blocks, threads, 0, exec_stream_>>>(
            out, q8_out_f32_, count);
        return launch_status("Q8 FP32->BF16 output");
    }

    // Returns true when the activation needs to be staged in the
    // 144-byte block_q8_1_mmq layout (v4, v5, v7, v8 consume that format).
    // Default (no env set) is auto = v7/v8, both 144-B; default to true.
    static int mmq_version_env_value() {
        static const int v = []() {
            const char *e = std::getenv("QW3_MMQ_VERSION");
            if (!e || e[0] == 'a') return 0;
            if (e[0] >= '2' && e[0] <= '8') return e[0] - '0';
            return 0;
        }();
        return v;
    }

    static bool mmq_uses_mmq_y_layout(uint32_t rows, uint32_t cols, uint32_t batch) {
        const int version = mmq_version_env_value();
        if (version == 2 || version == 3 || version == 6) return false;
        if (version == 4) return (cols % 256 == 0) && rows >= 128 && batch >= 128;
        if (version == 5) return (cols % 256 == 0) && rows >= 128 && batch >= 64;
        if (version == 7) return (cols % 128 == 0) && rows >= 64 && batch >= 64;
        return (cols % 128 == 0) && rows >= 128;
    }

    // INT8 MMA Q8_0 x Q8_1 matmul (m16n8k32.s8.s8.s32). Uses the same
    // q8_1_scratch_ buffer as decode mmvq for the activation Q8_1 stage.
    // v4/v5 use the 144-byte block_q8_1_mmq layout via q8_1_mmq_scratch_ —
    // it's a tile-friendly format that lets the MMQ kernel read mmq_x*36
    // contiguous ints per K super-iter.
    DeviceStatus mmq_q8(float *out_ptr, CudaWeight &w, const float *x_ptr, uint32_t batch) {
        // Medium-batch vmed path: for batch in [vmed_min, 64] the v8/v7 tiles
        // (128/64-wide) are mostly empty and pay full-tile compute; vmed sizes
        // the N tile to the batch (16/32/64), 2-3x faster at M=16..64 (see
        // project_mtp_vmed_medium_batch_mma_kernel). Requires cols % 128 == 0
        // and the 144-B block_q8_1_mmq activation layout. Disable via
        // QW3_VMED=0. Falls through to the standard mmq path on any failure.
        if (batch >= vmed_min_batch() && batch <= 64 && vmed_enabled() && (w.cols % 128) == 0) {
            if (auto st = ensure_q8_1_mmq_scratch(batch, w.cols); st.ok) {
                if (ported::launch_quantize_mmq_q8_1(x_ptr, q8_1_mmq_scratch_,
                                                     batch, w.cols, /*stride_x_row=*/w.cols,
                                                     exec_stream_) &&
                    ported::launch_mmq_q8_0_medium(static_cast<const uint8_t *>(w.ptr),
                                                   q8_1_mmq_scratch_, out_ptr,
                                                   static_cast<uint32_t>(w.rows), w.cols,
                                                   batch, /*stride_dst_row=*/static_cast<uint32_t>(w.rows),
                                                   exec_stream_)) {
                    return launch_status("cuda q8_0_matmul vmed");
                }
            }
            // else: fall through to the standard mmq path below.
        }

        const bool use_mmq_y =
            mmq_uses_mmq_y_layout(static_cast<uint32_t>(w.rows), w.cols, batch);
        if (use_mmq_y) {
            if (auto st = ensure_q8_1_mmq_scratch(batch, w.cols); !st.ok) return st;
            if (!ported::launch_quantize_mmq_q8_1(x_ptr, q8_1_mmq_scratch_,
                                                   batch, w.cols, /*stride_x_row=*/w.cols,
                                                   exec_stream_)) {
                return {false, "mmq quantize_mmq_q8_1 launch failed"};
            }
            if (!ported::launch_mmq_q8_0(static_cast<const uint8_t *>(w.ptr),
                                         q8_1_mmq_scratch_, out_ptr,
                                         static_cast<uint32_t>(w.rows), w.cols,
                                         batch, /*stride_dst_row=*/static_cast<uint32_t>(w.rows),
                                         exec_stream_)) {
                return {false, "mmq launch failed (mmq_y)"};
            }
            return launch_status("cuda q8_0_matmul mmq mmq_y");
        }

        if (auto st = ensure_q8_1_scratch(batch, w.cols); !st.ok) return st;
        if (!ported::launch_quantize_q8_1(x_ptr, q8_1_scratch_,
                                          batch, w.cols, /*stride_x_row=*/w.cols,
                                          exec_stream_)) {
            return {false, "mmq quantize_q8_1 launch failed"};
        }
        if (!ported::launch_mmq_q8_0(static_cast<const uint8_t *>(w.ptr),
                                     q8_1_scratch_, out_ptr,
                                     static_cast<uint32_t>(w.rows), w.cols,
                                     batch, /*stride_dst_row=*/static_cast<uint32_t>(w.rows),
                                     exec_stream_)) {
            return {false, "mmq launch failed"};
        }
        return launch_status("cuda q8_0_matmul mmq");
    }

    DeviceStatus dispatch_q8_matvec(float *out_ptr,
                                    CudaWeight &w,
                                    const float *x_ptr,
                                    uint32_t batch,
                                    uint32_t in_stride,
                                    uint32_t out_stride) {
        // Ported path: quantize input to Q8_1, then DP4A matvec with Q8_1
        // activations. Selected via QW3_MATVEC=ported (the default).
        //
        // batch 1..8 use the column-batched MMVQ kernel (mul_mat_vec_q8_0_kernel
        // with NCOLS_DST==batch): one CTA grid covers all rows, each Q8 weight
        // block is loaded ONCE and reused across all `batch` activation columns
        // via the per-thread tmp[NCOLS_DST][...] register accumulator. This is
        // the kernel the MTP speculative VERIFY batch (chain+1 = 2..5 rows)
        // needs: decode/verify matvec is HBM-weight-bandwidth-bound, so
        // amortizing the single weight read across the verify columns makes
        // verify(N) cost ~one weight pass instead of N. The old per-row
        // q8_matvec_dp4a_kernel (grid.y=batch) re-read the weight N times,
        // which made verify as slow as N separate decodes and killed the
        // speculative speedup. The INT8-MMA tile (mmq_q8) is the wrong tool
        // here: its 64-wide tile is ~95% empty at batch 2..5 and runs ~2x
        // slower than this matvec.
        if (matvec_kernel_choice() == MatvecKernel::Ported &&
            (w.cols % 32) == 0 && batch >= 1 && batch <= 8) {
            if (auto st = ensure_q8_1_scratch(batch, w.cols); !st.ok) return st;
            // For batch==1 callers pass in_stride==0; the quantize kernel still
            // only walks row 0 there. For batch>1 (verify), in_stride is the
            // float stride between activation rows in x.
            const uint32_t qstride = (batch == 1) ? w.cols : in_stride;
            if (!ported::launch_quantize_q8_1(x_ptr, q8_1_scratch_,
                                              batch, w.cols, qstride, exec_stream_)) {
                return {false, "ported quantize_q8_1 launch failed"};
            }
            const uint32_t dst_stride = (batch == 1) ? w.rows : out_stride;
            if (!ported::launch_mmvq_q8_0(static_cast<const uint8_t *>(w.ptr),
                                          q8_1_scratch_, out_ptr,
                                          static_cast<uint32_t>(w.rows), w.cols,
                                          batch, dst_stride, exec_stream_)) {
                return {false, "ported mmvq_q8_0 launch failed"};
            }
            return launch_status("cuda q8_0_matvec ported");
        }

        // Shmem budget per layout:
        //   - DP4A path  : cols * 1 (i8) + blocks * 4 (f32 scale per block)
        //   - F32 fallback: cols * 4 (f32 staging)
        const size_t shmem_dp4a = static_cast<size_t>(w.cols) + static_cast<size_t>(w.cols / 32) * sizeof(float);
        const size_t shmem_f32  = static_cast<size_t>(w.cols) * sizeof(float);
        const size_t shmem_limit = q8_matvec_max_shmem();
        const uint64_t rows = w.rows;
        const bool use_dp4a = shmem_dp4a <= shmem_limit;
        const bool fits_f32_shmem = shmem_f32 <= shmem_limit;

        // Empirical: for Qwen 3.6 27B Q8_0 on Pro 6000 the per-batch kernel
        // already amortizes W reads through L2 (89 MB FFN weight fits the
        // ~128 MB L2), so the tiled kernel's higher shmem use and lower
        // occupancy made prefill *slower*. Keep it gated off for now.
        if (false && batch > 1 && use_dp4a) {
            const size_t dp4a8 = shmem_dp4a * 8;
            const size_t dp4a4 = shmem_dp4a * 4;
            const size_t dp4a2 = shmem_dp4a * 2;
            auto launch_tiled = [&](auto tile, auto warps) {
                constexpr uint32_t T = decltype(tile)::value;
                constexpr uint32_t W = decltype(warps)::value;
                const unsigned by = (batch + T - 1) / T;
                const unsigned bx = static_cast<unsigned>((rows + W - 1) / W);
                dim3 grid(bx, by);
                q8_matmul_tiled_dp4a_kernel<W, T>
                    <<<grid, W * 32, shmem_dp4a * T, exec_stream_>>>(
                        out_ptr, static_cast<const uint8_t *>(w.ptr), x_ptr,
                        rows, w.cols, batch, in_stride, out_stride);
            };
            const auto warps_for_rows = [&]() {
                if (rows >= 16384) return 32u;
                if (rows >= 2048) return 16u;
                return 8u;
            };
            const uint32_t W = warps_for_rows();
            if (dp4a8 <= shmem_limit && batch >= 8) {
                if (W == 32) launch_tiled(std::integral_constant<uint32_t, 8>{}, std::integral_constant<uint32_t, 32>{});
                else if (W == 16) launch_tiled(std::integral_constant<uint32_t, 8>{}, std::integral_constant<uint32_t, 16>{});
                else launch_tiled(std::integral_constant<uint32_t, 8>{}, std::integral_constant<uint32_t, 8>{});
                return launch_status("cuda q8_matmul tiled8");
            }
            if (dp4a4 <= shmem_limit && batch >= 4) {
                if (W == 32) launch_tiled(std::integral_constant<uint32_t, 4>{}, std::integral_constant<uint32_t, 32>{});
                else if (W == 16) launch_tiled(std::integral_constant<uint32_t, 4>{}, std::integral_constant<uint32_t, 16>{});
                else launch_tiled(std::integral_constant<uint32_t, 4>{}, std::integral_constant<uint32_t, 8>{});
                return launch_status("cuda q8_matmul tiled4");
            }
            if (dp4a2 <= shmem_limit) {
                if (W == 32) launch_tiled(std::integral_constant<uint32_t, 2>{}, std::integral_constant<uint32_t, 32>{});
                else if (W == 16) launch_tiled(std::integral_constant<uint32_t, 2>{}, std::integral_constant<uint32_t, 16>{});
                else launch_tiled(std::integral_constant<uint32_t, 2>{}, std::integral_constant<uint32_t, 8>{});
                return launch_status("cuda q8_matmul tiled2");
            }
            // Fall through to per-batch kernel below.
        }

        auto dispatch = [&](auto warps) {
            constexpr uint32_t W = decltype(warps)::value;
            const unsigned blocks_grid = static_cast<unsigned>((rows + W - 1) / W);
            dim3 grid(blocks_grid, batch);
            if (use_dp4a) {
                q8_matvec_dp4a_kernel<W>
                    <<<grid, W * 32, shmem_dp4a, exec_stream_>>>(
                        out_ptr, static_cast<const uint8_t *>(w.ptr), x_ptr,
                        rows, w.cols, in_stride, out_stride);
            } else if (fits_f32_shmem) {
                q8_matvec_v2_kernel<W, true>
                    <<<grid, W * 32, shmem_f32, exec_stream_>>>(
                        out_ptr, static_cast<const uint8_t *>(w.ptr), x_ptr,
                        rows, w.cols, in_stride, out_stride);
            } else {
                q8_matvec_v2_kernel<W, false>
                    <<<grid, W * 32, 0, exec_stream_>>>(
                        out_ptr, static_cast<const uint8_t *>(w.ptr), x_ptr,
                        rows, w.cols, in_stride, out_stride);
            }
        };
        if (rows >= 16384) {
            dispatch(std::integral_constant<uint32_t, 32>{});
        } else if (rows >= 2048) {
            dispatch(std::integral_constant<uint32_t, 16>{});
        } else {
            dispatch(std::integral_constant<uint32_t, 8>{});
        }
        return launch_status("cuda q8_0_matvec");
    }
public:

    DeviceStatus rms_norm(DeviceTensor &out, const DeviceTensor &x, const DeviceWeight &weight, float eps) override {
        auto &o = as_tensor(out);
        const auto &input = as_tensor(x);
        const auto &w = as_weight(weight);
        const uint64_t n = input.count;
        if (o.is_bf16()) {
            return {false, "cuda rms_norm BF16 output is not implemented"};
        }
        if (input.is_bf16()) {
            rms_norm_bf16_to_f32_kernel<1024><<<
                1, 1024, 0, exec_stream_>>>(
                o.ptr, input.ptr_bf16(),
                static_cast<const float *>(w.ptr), n, eps);
            return launch_status("cuda rms_norm bf16_to_f32");
        }
        // Vectorized path: float4-aligned and big enough to make a 1024-thread
        // block worth launching. Otherwise fall back to the scalar kernel.
        const bool can_vec = (n % 4 == 0)
            && ((reinterpret_cast<uintptr_t>(input.ptr) & 0xF) == 0)
            && ((reinterpret_cast<uintptr_t>(o.ptr) & 0xF) == 0)
            && ((reinterpret_cast<uintptr_t>(w.ptr) & 0xF) == 0)
            && n >= 256;
        if (can_vec) {
            rms_norm_kernel_vec<1024><<<1, 1024, 0, exec_stream_>>>(o.ptr, input.ptr,
                                                    static_cast<const float *>(w.ptr),
                                                    n, eps);
        } else {
            rms_norm_kernel<<<1, 256, 0, exec_stream_>>>(o.ptr, input.ptr,
                                        static_cast<const float *>(w.ptr), n, eps);
        }
        return launch_status("cuda rms_norm");
    }

    DeviceStatus rms_norm_batch(DeviceTensor &out,
                                const DeviceTensor &x,
                                const DeviceWeight &weight,
                                uint32_t batch,
                                uint32_t n,
                                float eps) override {
        auto &o = as_tensor(out);
        const auto &input = as_tensor(x);
        const auto &w = as_weight(weight);
        if (batch == 0) return {};
        if (o.is_bf16()) {
            return {false, "cuda rms_norm_batch BF16 output is not implemented"};
        }
        if (input.is_bf16()) {
            rms_norm_bf16_to_f32_kernel<1024><<<
                batch, 1024, 0, exec_stream_>>>(
                o.ptr, input.ptr_bf16(),
                static_cast<const float *>(w.ptr), n, eps);
            return launch_status("cuda rms_norm_batch bf16_to_f32");
        }
        // Prefer the vectorized 1024-thread kernel when alignment + size allow.
        // Same constraints as the single-row path; batch is handled via gridDim.x.
        const bool can_vec = (n % 4 == 0)
            && ((reinterpret_cast<uintptr_t>(input.ptr) & 0xF) == 0)
            && ((reinterpret_cast<uintptr_t>(o.ptr) & 0xF) == 0)
            && ((reinterpret_cast<uintptr_t>(w.ptr) & 0xF) == 0)
            && n >= 256;
        if (can_vec) {
            rms_norm_kernel_vec<1024><<<batch, 1024, 0, exec_stream_>>>(
                o.ptr, input.ptr, static_cast<const float *>(w.ptr), n, eps);
        } else {
            rms_norm_kernel<<<batch, 256, 0, exec_stream_>>>(
                o.ptr, input.ptr, static_cast<const float *>(w.ptr), n, eps);
        }
        return launch_status("cuda rms_norm_batch");
    }

    DeviceStatus add(DeviceTensor &out, const DeviceTensor &a, const DeviceTensor &b) override {
        auto &o = as_tensor(out);
        return add_n(out, a, b, o.count);
    }

    DeviceStatus add_n(DeviceTensor &out, const DeviceTensor &a, const DeviceTensor &b,
                       uint64_t count) override {
        auto &o = as_tensor(out);
        const auto &aa = as_tensor(a);
        const auto &bb = as_tensor(b);
        if (count > o.count || count > aa.count || count > bb.count) {
            return {false, "cuda add_n count exceeds tensor size"};
        }
        if (o.is_bf16() || aa.is_bf16() || bb.is_bf16()) {
            auto report_dtype_mismatch = [&]() {
                std::fprintf(
                    stderr,
                    "[qw3] add_n dtype mismatch: out=%s(%s) lhs=%s(%s) rhs=%s(%s)\n",
                    o.label.c_str(), o.is_bf16() ? "bf16" : "f32",
                    aa.label.c_str(), aa.is_bf16() ? "bf16" : "f32",
                    bb.label.c_str(), bb.is_bf16() ? "bf16" : "f32");
            };
            if (!o.is_bf16()) {
                report_dtype_mismatch();
                return {false, "cuda add_n BF16 input with FP32 output"};
            }
            if (!aa.is_bf16()) {
                report_dtype_mismatch();
                return {false, "cuda add_n BF16 output with FP32 lhs"};
            }
            if (!bb.is_bf16()) {
                report_dtype_mismatch();
                return {false, "cuda add_n BF16 output with FP32 rhs"};
            }
            const uint64_t pairs = (count + 1) / 2;
            const unsigned blocks =
                static_cast<unsigned>((pairs + 255) / 256);
            add_bf16_kernel<<<blocks, 256, 0, exec_stream_>>>(
                o.ptr_bf16(), aa.ptr_bf16(), bb.ptr_bf16(), count);
            return launch_status("cuda add bf16");
        }
        const uint64_t threads_total = (count + 3) / 4;
        const unsigned blocks = static_cast<unsigned>((threads_total + 255) / 256);
        add_kernel<<<blocks, 256, 0, exec_stream_>>>(o.ptr, aa.ptr, bb.ptr, count);
        return launch_status("cuda add");
    }

    DeviceStatus silu(DeviceTensor &out, const DeviceTensor &x) override {
        auto &o = as_tensor(out);
        const auto &input = as_tensor(x);
        silu_kernel<<<static_cast<unsigned>((o.count + 255) / 256), 256, 0, exec_stream_>>>(o.ptr, input.ptr, o.count);
        return launch_status("cuda silu");
    }

    DeviceStatus mul(DeviceTensor &out, const DeviceTensor &a, const DeviceTensor &b) override {
        auto &o = as_tensor(out);
        const auto &aa = as_tensor(a);
        const auto &bb = as_tensor(b);
        mul_kernel<<<static_cast<unsigned>((o.count + 255) / 256), 256, 0, exec_stream_>>>(o.ptr, aa.ptr, bb.ptr, o.count);
        return launch_status("cuda mul");
    }

    DeviceStatus silu_mul(DeviceTensor &out, const DeviceTensor &gate, const DeviceTensor &up) override {
        auto &o = as_tensor(out);
        return silu_mul_n(out, gate, up, o.count);
    }

    DeviceStatus silu_mul_n(DeviceTensor &out,
                            const DeviceTensor &gate,
                            const DeviceTensor &up,
                            uint64_t count) override {
        auto &o = as_tensor(out);
        const auto &g = as_tensor(gate);
        const auto &u = as_tensor(up);
        if (count > o.count || count > g.count || count > u.count) {
            return {false, "cuda silu_mul_n count exceeds tensor size"};
        }
        // Vectorized: 4 elements per thread.
        const uint64_t threads_total = (count + 3) / 4;
        const unsigned blocks = static_cast<unsigned>((threads_total + 255) / 256);
        silu_mul_kernel<<<blocks, 256, 0, exec_stream_>>>(
            o.ptr, g.ptr, u.ptr, count);
        return launch_status("cuda silu_mul");
    }

    DeviceStatus recurrent_single_token(DeviceTensor &core,
                                        DeviceTensor &state,
                                        DeviceTensor &conv_state,
                                        DeviceTensor &conv_out,
                                        const DeviceTensor &proj,
                                        const DeviceTensor &gate,
                                        const DeviceTensor &alpha,
                                        const DeviceTensor &beta,
                                        const DeviceWeight &conv,
                                        const DeviceWeight &ssm_a,
                                        const DeviceWeight &dt_bias,
                                        const DeviceWeight &ssm_norm,
                                        uint32_t num_k_heads,
                                        uint32_t num_v_heads,
                                        uint32_t head_k_dim,
                                        uint32_t head_v_dim,
                                        uint32_t conv_kernel_size,
                                        float eps) override {
        auto &c = as_tensor(core);
        auto &s = as_tensor(state);
        auto &cs = as_tensor(conv_state);
        auto &cout = as_tensor(conv_out);
        const auto &p = as_tensor(proj);
        const auto &g = as_tensor(gate);
        const auto &a = as_tensor(alpha);
        const auto &b = as_tensor(beta);
        const auto &cw = as_weight(conv);
        const auto &aw = as_weight(ssm_a);
        const auto &dt = as_weight(dt_bias);
        const auto &nw = as_weight(ssm_norm);
        float *conv_buf = cout.ptr;
        recurrent_conv_kernel<<<static_cast<unsigned>((p.count + 255) / 256), 256, 0, exec_stream_>>>(
            conv_buf, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
            static_cast<uint32_t>(p.count), conv_kernel_size);
        static const bool fuse_qk_norm = []() {
            const char *value = std::getenv("QW3_FUSED_RECURRENT_QK_NORM");
            return !value ||
                   (std::strcmp(value, "0") != 0 &&
                    std::strcmp(value, "off") != 0 &&
                    std::strcmp(value, "false") != 0);
        }();
        if (fuse_qk_norm) {
            const dim3 qk_grid(1, num_k_heads);
            l2_norm_128_qk_batch_kernel<<<qk_grid, 128, 0, exec_stream_>>>(
                conv_buf, num_k_heads, head_k_dim,
                /*T=*/1, static_cast<uint32_t>(p.count),
                /*q_offset=*/0, num_k_heads * head_k_dim, eps);
        } else {
            l2_norm_128_kernel<<<num_k_heads, 128, 0, exec_stream_>>>(
                conv_buf, num_k_heads, head_k_dim, eps);
            l2_norm_128_kernel<<<num_k_heads, 128, 0, exec_stream_>>>(
                conv_buf + num_k_heads * head_k_dim,
                num_k_heads, head_k_dim, eps);
        }
        bool used_ported = false;
        if (recurrent_kernel_choice() == RecurrentKernel::Ported &&
            head_k_dim == head_v_dim) {
            auto &a_mut = const_cast<CudaTensor &>(a);
            auto &b_mut = const_cast<CudaTensor &>(b);
            used_ported = ported::launch_gated_delta_net(
                a_mut.ptr, b_mut.ptr,
                static_cast<const float *>(dt.ptr),
                static_cast<const float *>(aw.ptr),
                conv_buf,
                /*q_offset=*/0,
                /*k_offset=*/num_k_heads * head_k_dim,
                /*v_offset=*/2u * num_k_heads * head_k_dim,
                s.ptr, c.ptr,
                /*T=*/1,
                num_k_heads, num_v_heads, head_k_dim,
                static_cast<uint32_t>(p.count),
                num_v_heads,
                static_cast<uint32_t>(c.count),
                /*prep_decay=*/true,
                /*state_checkpoints=*/nullptr,
                /*checkpoint_count=*/0,
                exec_stream_);
        }
        if (!used_ported) {
            dim3 grid(num_v_heads, head_v_dim);
            deltanet_kernel<<<grid, 128, 0, exec_stream_>>>(
                c.ptr, s.ptr, conv_buf, a.ptr, b.ptr,
                static_cast<const float *>(aw.ptr),
                static_cast<const float *>(dt.ptr),
                num_k_heads, num_v_heads, head_k_dim, head_v_dim);
        }
        recurrent_norm_gate_kernel<<<num_v_heads, head_v_dim, 0, exec_stream_>>>(c.ptr, g.ptr, static_cast<const float *>(nw.ptr), num_v_heads, head_v_dim, eps);
        return launch_status("cuda recurrent_single_token");
    }

    DeviceStatus recurrent_single_token_at(DeviceTensor &core,
                                            DeviceTensor &state,
                                            DeviceTensor &conv_state,
                                            DeviceTensor &conv_out,
                                            const DeviceTensor &proj,
                                            const DeviceTensor &gate,
                                            const DeviceTensor &alpha,
                                            const DeviceTensor &beta,
                                            const DeviceWeight &conv,
                                            const DeviceWeight &ssm_a,
                                            const DeviceWeight &dt_bias,
                                            const DeviceWeight &ssm_norm,
                                            uint32_t num_k_heads,
                                            uint32_t num_v_heads,
                                            uint32_t head_k_dim,
                                            uint32_t head_v_dim,
                                            uint32_t conv_kernel_size,
                                            uint32_t proj_count,
                                            uint32_t proj_off,
                                            uint32_t gate_off,
                                            uint32_t alpha_off,
                                            uint32_t beta_off,
                                            uint32_t core_off,
                                            float eps) override {
        auto &c = as_tensor(core);
        auto &s = as_tensor(state);
        auto &cs = as_tensor(conv_state);
        auto &cout = as_tensor(conv_out);
        const auto &p = as_tensor(proj);
        const auto &g = as_tensor(gate);
        const auto &a = as_tensor(alpha);
        const auto &b = as_tensor(beta);
        const auto &cw = as_weight(conv);
        const auto &aw = as_weight(ssm_a);
        const auto &dt = as_weight(dt_bias);
        const auto &nw = as_weight(ssm_norm);
        float *conv_buf = cout.ptr;
        recurrent_conv_kernel<<<static_cast<unsigned>((proj_count + 255) / 256), 256, 0, exec_stream_>>>(
            conv_buf, cs.ptr, p.ptr + proj_off, static_cast<const float *>(cw.ptr),
            proj_count, conv_kernel_size);
        l2_norm_128_kernel<<<num_k_heads, 128, 0, exec_stream_>>>(conv_buf, num_k_heads, head_k_dim, eps);
        l2_norm_128_kernel<<<num_k_heads, 128, 0, exec_stream_>>>(conv_buf + num_k_heads * head_k_dim, num_k_heads, head_k_dim, eps);
        dim3 grid(num_v_heads, head_v_dim);
        deltanet_kernel<<<grid, 128, 0, exec_stream_>>>(c.ptr + core_off,
                                       s.ptr,
                                       conv_buf,
                                       a.ptr + alpha_off,
                                       b.ptr + beta_off,
                                       static_cast<const float *>(aw.ptr),
                                       static_cast<const float *>(dt.ptr),
                                       num_k_heads,
                                       num_v_heads,
                                       head_k_dim,
                                       head_v_dim);
        recurrent_norm_gate_kernel<<<num_v_heads, head_v_dim, 0, exec_stream_>>>(c.ptr + core_off, g.ptr + gate_off,
                                                                static_cast<const float *>(nw.ptr),
                                                                num_v_heads, head_v_dim, eps);
        return launch_status("cuda recurrent_single_token_at");
    }

    DeviceStatus recurrent_batch(DeviceTensor &core,
                                  DeviceTensor &state,
                                  DeviceTensor &conv_state,
                                  DeviceTensor &conv_out_buf,
                                  const DeviceTensor &proj,
                                  const DeviceTensor &gate,
                                  const DeviceTensor &alpha,
                                  const DeviceTensor &beta,
                                  const DeviceWeight &conv,
                                  const DeviceWeight &ssm_a,
                                  const DeviceWeight &dt_bias,
                                  const DeviceWeight &ssm_norm,
                                  uint32_t batch,
                                  uint32_t num_k_heads,
                                  uint32_t num_v_heads,
                                  uint32_t head_k_dim,
                                  uint32_t head_v_dim,
                                  uint32_t conv_kernel_size,
                                  uint32_t proj_count,
                                  uint32_t proj_stride,
                                  uint32_t gate_stride,
                                  uint32_t alpha_stride,
                                  uint32_t beta_stride,
                                  uint32_t core_stride,
                                  float eps,
                                  DeviceTensor *state_checkpoints,
                                  DeviceTensor *conv_state_checkpoints,
                                  uint32_t checkpoint_count,
                                  DeviceTensor *dn_state_snap,
                                  DeviceTensor *dn_decaysum,
                                  uint64_t dn_layer_snap_off,
                                  uint64_t dn_layer_decay_off,
                                  uint32_t dn_block_tokens,
                                  uint32_t dn_base_pos,
                                  uint32_t dn_n_blocks) override {
        if (batch == 0) return {};
        auto &c = as_tensor(core);
        auto &s = as_tensor(state);
        auto &cs = as_tensor(conv_state);
        auto &cout = as_tensor(conv_out_buf);
        const auto &p = as_tensor(proj);
        const auto &g = as_tensor(gate);
        const auto &a = as_tensor(alpha);
        const auto &b = as_tensor(beta);
        const auto &cw = as_weight(conv);
        const auto &aw = as_weight(ssm_a);
        const auto &dt = as_weight(dt_bias);
        const auto &nw = as_weight(ssm_norm);
        auto *state_ckpt = state_checkpoints ? &as_tensor(*state_checkpoints) : nullptr;
        auto *conv_ckpt = conv_state_checkpoints ? &as_tensor(*conv_state_checkpoints) : nullptr;
        const uint32_t effective_checkpoint_count = std::min<uint32_t>(checkpoint_count, batch);
        const bool want_checkpoint =
            state_ckpt != nullptr && conv_ckpt != nullptr && effective_checkpoint_count > 0;
        // DeltaNet retrieval capture: when requested, force the qw3 delta kernel
        // (which emits per-block state snapshots + accumulates in-block log-decay)
        // regardless of QW3_RECURRENT_KERNEL. The ported warp kernel does not
        // support the snapshot side-channel.
        auto *dn_snap = dn_state_snap ? &as_tensor(*dn_state_snap) : nullptr;
        auto *dn_decay = dn_decaysum ? &as_tensor(*dn_decaysum) : nullptr;
        const bool dn_capture =
            dn_snap != nullptr && dn_decay != nullptr && dn_block_tokens > 0;

        bool use_sm120_aot = false;
#ifdef QW3_ENABLE_GDN_SM120_AOT
        const uint32_t recurrent_q_width = num_k_heads * head_k_dim;
        const uint32_t recurrent_v_width = num_v_heads * head_v_dim;
        const uint32_t recurrent_qkv_width =
            2u * recurrent_q_width + recurrent_v_width;
        use_sm120_aot =
            recurrent_kernel_choice() == RecurrentKernel::Sm120Aot &&
            !want_checkpoint && !dn_capture && batch >= 64 &&
            head_k_dim == 128 && head_v_dim == 128 &&
            proj_count == recurrent_qkv_width &&
            alpha_stride == beta_stride;
#endif

        // 1. Conv. Checkpoint capture requires sequential state snapshots.
        //    Normal long prefill uses token tiles so the sequence dimension
        //    runs in parallel. Output row stride mirrors the proj layout.
        const unsigned conv_threads = 256;
        const unsigned conv_blocks = static_cast<unsigned>((proj_count + conv_threads - 1) / conv_threads);
        constexpr uint32_t conv_token_tile = 64;
        const dim3 parallel_conv_grid(
            conv_blocks, (batch + conv_token_tile - 1) / conv_token_tile);
        const bool use_parallel_conv =
            !want_checkpoint && parallel_prefill_conv_enabled();
        const bool lazy_pair =
            p.is_lazy_fp8_linear() && g.is_lazy_fp8_linear() &&
            p.lazy_fp8_raw == g.lazy_fp8_raw &&
            p.lazy_fp8_activation_scales ==
                g.lazy_fp8_activation_scales &&
            p.lazy_fp8_batch == batch && g.lazy_fp8_batch == batch &&
            p.lazy_fp8_rows == proj_count &&
            g.lazy_fp8_rows >= num_v_heads * head_v_dim;
        const bool consume_lazy_pair =
            lazy_pair && use_sm120_aot &&
            gdn_sm120_fused_io_enabled() && use_parallel_conv;
        const uintptr_t p_begin = reinterpret_cast<uintptr_t>(p.ptr);
        const uintptr_t p_end =
            p_begin + static_cast<uintptr_t>(p.count) * p.elem_size;
        const uintptr_t g_begin = reinterpret_cast<uintptr_t>(g.ptr);
        const uintptr_t g_end =
            g_begin + static_cast<uintptr_t>(g.count) * g.elem_size;
        const bool projection_storage_overlaps =
            p_begin < g_end && g_begin < p_end;
        if (!consume_lazy_pair && projection_storage_overlaps) {
            return {
                false,
                "recurrent compact projection views require lazy consumption"};
        }
        if (lazy_pair && !consume_lazy_pair) {
            const uint64_t elements =
                static_cast<uint64_t>(batch) *
                (p.lazy_fp8_rows + g.lazy_fp8_rows);
            constexpr unsigned threads = 256;
            const unsigned blocks = static_cast<unsigned>(
                (elements + threads - 1) / threads);
            fp8_outer_scale_packed_pair_kernel<<<
                blocks, threads, 0, exec_stream_>>>(
                p.ptr, g.ptr, p.lazy_fp8_raw,
                p.lazy_fp8_activation_scales,
                p.lazy_fp8_weight_scales,
                g.lazy_fp8_weight_scales,
                batch, p.lazy_fp8_rows, g.lazy_fp8_rows,
                proj_stride, gate_stride);
            if (auto st = launch_status(
                    "materialize lazy recurrent FP8 pair"); !st.ok) {
                return st;
            }
        }
        switch (conv_kernel_size) {
            case 3:
                if (use_parallel_conv) {
                    if (consume_lazy_pair) {
                        recurrent_conv_prefill_parallel_lazy_fp8_kernel<
                            3, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset, proj_stride);
                        recurrent_conv_prefill_state_lazy_fp8_kernel<3><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset);
                    } else {
                        recurrent_conv_prefill_parallel_kernel<
                            3, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, proj_stride, proj_stride);
                        recurrent_conv_prefill_state_kernel<3><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.ptr, batch, proj_count, proj_stride);
                    }
                } else {
                    recurrent_conv_batch_kernel<3>
                        <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                            want_checkpoint ? conv_ckpt->ptr : nullptr,
                            batch, proj_count, proj_stride, proj_stride,
                            effective_checkpoint_count);
                }
                break;
            case 4:
                if (use_parallel_conv) {
                    if (consume_lazy_pair) {
                        recurrent_conv_prefill_parallel_lazy_fp8_kernel<
                            4, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset, proj_stride);
                        recurrent_conv_prefill_state_lazy_fp8_kernel<4><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset);
                    } else {
                        recurrent_conv_prefill_parallel_kernel<
                            4, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, proj_stride, proj_stride);
                        recurrent_conv_prefill_state_kernel<4><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.ptr, batch, proj_count, proj_stride);
                    }
                } else {
                    recurrent_conv_batch_kernel<4>
                        <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                            want_checkpoint ? conv_ckpt->ptr : nullptr,
                            batch, proj_count, proj_stride, proj_stride,
                            effective_checkpoint_count);
                }
                break;
            case 5:
                if (use_parallel_conv) {
                    if (consume_lazy_pair) {
                        recurrent_conv_prefill_parallel_lazy_fp8_kernel<
                            5, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset, proj_stride);
                        recurrent_conv_prefill_state_lazy_fp8_kernel<5><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset);
                    } else {
                        recurrent_conv_prefill_parallel_kernel<
                            5, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, proj_stride, proj_stride);
                        recurrent_conv_prefill_state_kernel<5><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.ptr, batch, proj_count, proj_stride);
                    }
                } else {
                    recurrent_conv_batch_kernel<5>
                        <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                            want_checkpoint ? conv_ckpt->ptr : nullptr,
                            batch, proj_count, proj_stride, proj_stride,
                            effective_checkpoint_count);
                }
                break;
            case 7:
                if (use_parallel_conv) {
                    if (consume_lazy_pair) {
                        recurrent_conv_prefill_parallel_lazy_fp8_kernel<
                            7, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset, proj_stride);
                        recurrent_conv_prefill_state_lazy_fp8_kernel<7><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.lazy_fp8_raw,
                            p.lazy_fp8_activation_scales,
                            p.lazy_fp8_weight_scales,
                            batch, proj_count, p.lazy_fp8_raw_stride,
                            p.lazy_fp8_row_offset);
                    } else {
                        recurrent_conv_prefill_parallel_kernel<
                            7, conv_token_tile><<<
                            parallel_conv_grid, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr,
                            static_cast<const float *>(cw.ptr),
                            batch, proj_count, proj_stride, proj_stride);
                        recurrent_conv_prefill_state_kernel<7><<<
                            conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cs.ptr, p.ptr, batch, proj_count, proj_stride);
                    }
                } else {
                    recurrent_conv_batch_kernel<7>
                        <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                            cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                            want_checkpoint ? conv_ckpt->ptr : nullptr,
                            batch, proj_count, proj_stride, proj_stride,
                            effective_checkpoint_count);
                }
                break;
            default:
                return {false, "recurrent_batch: unsupported conv_kernel_size (expected 3/4/5/7)"};
        }
        if (auto st = launch_status(use_parallel_conv
                ? "recurrent_conv_prefill_parallel_kernel"
                : "recurrent_conv_batch_kernel"); !st.ok) return st;

        // 2. L2 norm for Q and K (batched across T). The SM120 path folds
        //    this into its BF16 input pack to avoid materializing normalized
        //    FP32 Q/K solely for the adapter.
        if (!use_sm120_aot || !gdn_sm120_fused_io_enabled()) {
            dim3 ln_grid(batch, num_k_heads);
            const uint32_t q_off = 0;
            const uint32_t k_off = num_k_heads * head_k_dim;
            if (want_checkpoint) {
                l2_norm_128_qk_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
                    cout.ptr, num_k_heads, head_k_dim,
                    batch, proj_stride, q_off, k_off, eps);
                if (auto st = launch_status(
                        "l2_norm_128_qk_batch_kernel"); !st.ok) {
                    return st;
                }
            } else {
                l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
                    cout.ptr, num_k_heads, head_k_dim, batch, proj_stride,
                    q_off, eps);
                l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
                    cout.ptr, num_k_heads, head_k_dim, batch, proj_stride,
                    k_off, eps);
                if (auto st = launch_status(
                        "l2_norm_128_batch_kernel"); !st.ok) {
                    return st;
                }
            }
        }

        // 3. DeltaNet (batched). The SM120 AOT path is a chunk-parallel
        //    FlashInfer CuTe-DSL kernel. It is currently restricted to normal
        //    prefill because KVMem capture needs per-block state snapshots.
        bool used_sm120_aot = false;
        bool used_sm120_fused_post = false;
#ifdef QW3_ENABLE_GDN_SM120_AOT
        if (use_sm120_aot) {
            if (auto st = ensure_gdn_sm120_workspace(
                    batch, num_k_heads, num_v_heads, head_k_dim);
                !st.ok) {
                return st;
            }

            __nv_bfloat16 *q_bf16 = gdn_sm120_bf16_;
            __nv_bfloat16 *k_bf16 =
                q_bf16 + static_cast<uint64_t>(batch) * recurrent_q_width;
            __nv_bfloat16 *v_bf16 =
                k_bf16 + static_cast<uint64_t>(batch) * recurrent_q_width;
            __nv_bfloat16 *out_bf16 =
                v_bf16 + static_cast<uint64_t>(batch) * recurrent_v_width;

            if (gdn_sm120_fused_io_enabled()) {
                const dim3 norm_pack_grid(batch, num_v_heads);
                recurrent_norm_pack_gdn_bf16_kernel<<<
                    norm_pack_grid, head_k_dim, 0, exec_stream_>>>(
                    q_bf16, k_bf16, v_bf16, cout.ptr,
                    batch, num_k_heads, num_v_heads, head_k_dim,
                    proj_stride, eps);
                if (auto st = launch_status(
                        "recurrent_norm_pack_gdn_bf16_kernel"); !st.ok) {
                    return st;
                }
            } else {
                const dim3 pack_grid(
                    batch, (recurrent_qkv_width + 255u) / 256u);
                recurrent_pack_gdn_bf16_kernel<<<
                    pack_grid, 256, 0, exec_stream_>>>(
                    q_bf16, k_bf16, v_bf16, cout.ptr,
                    batch, recurrent_q_width, recurrent_q_width,
                    recurrent_v_width, proj_stride);
                if (auto st = launch_status(
                        "recurrent_pack_gdn_bf16_kernel"); !st.ok) {
                    return st;
                }
            }

            if (!ported::launch_gdn_prep(
                    const_cast<CudaTensor &>(a).ptr,
                    const_cast<CudaTensor &>(b).ptr,
                    static_cast<const float *>(dt.ptr),
                    static_cast<const float *>(aw.ptr),
                    batch, num_v_heads, alpha_stride, beta_stride,
                    true, exec_stream_)) {
                return {false, "SM120 GDN alpha/beta prep failed"};
            }

            const uint64_t state_elems =
                static_cast<uint64_t>(num_v_heads) *
                head_v_dim * head_k_dim;
            if (auto st = cuda_status(
                    cudaMemcpyAsync(
                        gdn_sm120_initial_state_, s.ptr,
                        static_cast<size_t>(state_elems) * sizeof(float),
                        cudaMemcpyDeviceToDevice, exec_stream_),
                    "SM120 GDN initial-state copy"); !st.ok) {
                return st;
            }
            recurrent_set_cu_seqlens_kernel<<<1, 1, 0, exec_stream_>>>(
                gdn_sm120_cu_seqlens_, batch);
            if (auto st = launch_status(
                    "recurrent_set_cu_seqlens_kernel"); !st.ok) {
                return st;
            }

            const bool ok = gdn_sm120_aot::launch(
                out_bf16, s.ptr,
                q_bf16, k_bf16, v_bf16,
                gdn_sm120_initial_state_,
                const_cast<CudaTensor &>(a).ptr,
                const_cast<CudaTensor &>(b).ptr,
                gdn_sm120_cu_seqlens_,
                gdn_sm120_tensormaps_,
                gdn_sm120_tensormaps_capacity_,
                batch, num_k_heads, num_k_heads, num_v_heads,
                head_k_dim,
                rsqrtf(static_cast<float>(head_k_dim)),
                exec_stream_);
            if (!ok) return {false, "SM120 GDN AOT launch failed"};

            if (gdn_sm120_fused_io_enabled()) {
                const dim3 norm_gate_grid(batch, num_v_heads);
                recurrent_norm_gate_gdn_bf16_kernel<<<
                    norm_gate_grid, head_v_dim, 0, exec_stream_>>>(
                    c.ptr, out_bf16, g.ptr,
                    consume_lazy_pair ? g.lazy_fp8_raw : nullptr,
                    consume_lazy_pair
                        ? g.lazy_fp8_activation_scales : nullptr,
                    consume_lazy_pair
                        ? g.lazy_fp8_weight_scales : nullptr,
                    static_cast<const float *>(nw.ptr),
                    batch, num_v_heads, head_v_dim,
                    core_stride, gate_stride,
                    consume_lazy_pair ? g.lazy_fp8_raw_stride : 0,
                    consume_lazy_pair ? g.lazy_fp8_row_offset : 0,
                    eps);
                if (auto st = launch_status(
                        "recurrent_norm_gate_gdn_bf16_kernel"); !st.ok) {
                    return st;
                }
                used_sm120_fused_post = true;
            } else {
                const uint64_t out_elems =
                    static_cast<uint64_t>(batch) * recurrent_v_width;
                const uint32_t unpack_blocks =
                    static_cast<uint32_t>((out_elems + 255u) / 256u);
                recurrent_unpack_gdn_bf16_kernel<<<
                    unpack_blocks, 256, 0, exec_stream_>>>(
                    c.ptr, out_bf16, batch, recurrent_v_width, core_stride);
                if (auto st = launch_status(
                        "recurrent_unpack_gdn_bf16_kernel"); !st.ok) {
                    return st;
                }
            }
            used_sm120_aot = true;
        }
#endif

        // The ported fallback keeps one state column in a warp's registers
        // and iterates tokens sequentially. The original qw3 kernel uses
        // shared-memory reductions and also supports KVMem state capture.
        if (used_sm120_aot) {
            // Output and final state were produced above.
        } else if (recurrent_kernel_choice() == RecurrentKernel::Ported && !dn_capture) {
            // Ported kernel requires head_k_dim == head_v_dim (square state).
            if (head_k_dim != head_v_dim) {
                return {false, "recurrent_batch: ported kernel requires head_k_dim == head_v_dim"};
            }
            // Layout note: cout (conv output) row stride is proj_stride; q
            // starts at offset 0, k at num_k_heads*head_k_dim, v at
            // 2*num_k_heads*head_k_dim. alpha and beta share gb_row_stride
            // (= alpha_stride == beta_stride) per qw3's batched layout.
            if (alpha_stride != beta_stride) {
                return {false, "recurrent_batch: ported kernel requires alpha_stride == beta_stride"};
            }
            // alpha and beta are scratch (overwritten per-layer by the
            // projection step); the prep kernel rewrites them in place to
            // log_g and sigmoid_beta.
            auto &a_mut = const_cast<CudaTensor &>(as_tensor(alpha));
            auto &b_mut = const_cast<CudaTensor &>(as_tensor(beta));
            const uint32_t q_off_floats = 0;
            const uint32_t k_off_floats = num_k_heads * head_k_dim;
            const uint32_t v_off_floats = 2u * num_k_heads * head_k_dim;
            const bool ok = ported::launch_gated_delta_net(
                a_mut.ptr, b_mut.ptr,
                static_cast<const float *>(dt.ptr),
                static_cast<const float *>(aw.ptr),
                cout.ptr,
                q_off_floats, k_off_floats, v_off_floats,
                s.ptr, c.ptr,
                batch,
                num_k_heads, num_v_heads, head_k_dim,
                proj_stride, alpha_stride, core_stride,
                true,
                want_checkpoint ? state_ckpt->ptr : nullptr,
                effective_checkpoint_count,
                exec_stream_);
            if (!ok) return {false, "recurrent_batch: ported kernel rejected head_dim (only 16/32/64/128)"};
            if (auto st = launch_status("ported::gated_delta_net_kernel"); !st.ok) return st;
        } else {
            // Original qw3 kernel: one block per (vh, head_v_dim) iterates T
            // timesteps; reductions via __syncthreads() in shared memory. When
            // dn_capture is on, this kernel also emits per-block state snapshots
            // (S_j at each block boundary) into dn_snap, and a companion decay-scan
            // kernel accumulates each block's in-block log-decay into dn_decay.
            dim3 dn_grid(num_v_heads, head_v_dim);
            deltanet_batch_kernel<<<dn_grid, 128, 0, exec_stream_>>>(c.ptr,
                                                    s.ptr,
                                                    cout.ptr,
                                                    a.ptr,
                                                    b.ptr,
                                                    static_cast<const float *>(aw.ptr),
                                                    static_cast<const float *>(dt.ptr),
                                                    want_checkpoint ? state_ckpt->ptr : nullptr,
                                                    batch,
                                                    num_k_heads,
                                                    num_v_heads,
                                                    head_k_dim,
                                                    head_v_dim,
                                                    proj_stride,
                                                    alpha_stride,
                                                    beta_stride,
                                                    core_stride,
                                                    effective_checkpoint_count,
                                                    dn_capture ? dn_snap->ptr + dn_layer_snap_off : nullptr,
                                                    dn_capture ? dn_block_tokens : 0u,
                                                    dn_base_pos,
                                                    dn_n_blocks);
            if (auto st = launch_status("deltanet_batch_kernel"); !st.ok) return st;
            if (dn_capture) {
                // Accumulate this chunk's in-block log-decay per (block, vh). The
                // qw3 delta kernel reads RAW alpha (a.ptr), so alpha is intact here.
                const uint32_t first_blk = dn_base_pos / dn_block_tokens;
                const uint32_t last_gpos = dn_base_pos + batch;   // exclusive
                const uint32_t last_blk = (last_gpos + dn_block_tokens - 1) / dn_block_tokens;
                const uint32_t n_blk_chunk =
                    (last_blk > first_blk) ? (last_blk - first_blk) : 0u;
                if (n_blk_chunk > 0) {
                    const uint32_t vh_threads = 64;
                    dim3 ds_grid(n_blk_chunk, (num_v_heads + vh_threads - 1) / vh_threads);
                    deltanet_decay_scan_kernel<<<ds_grid, vh_threads, 0, exec_stream_>>>(
                        a.ptr,
                        static_cast<const float *>(dt.ptr),
                        static_cast<const float *>(aw.ptr),
                        dn_decay->ptr + dn_layer_decay_off,
                        batch, num_v_heads, alpha_stride, dn_block_tokens,
                        dn_base_pos, dn_n_blocks);
                    if (auto st = launch_status("deltanet_decay_scan_kernel"); !st.ok) return st;
                }
            }
        }

        // 4. RMSnorm + gate, batched over T.
        if (!used_sm120_fused_post) {
            dim3 ng_grid(batch, num_v_heads);
            recurrent_norm_gate_batch_kernel<<<
                ng_grid, head_v_dim, 0, exec_stream_>>>(
                c.ptr, g.ptr, static_cast<const float *>(nw.ptr),
                batch, num_v_heads, head_v_dim,
                core_stride, gate_stride, eps);
            return launch_status("recurrent_norm_gate_batch_kernel");
        }
        return {};
    }

    DeviceStatus recurrent_batch_independent(DeviceTensor &core,
                                             DeviceTensor &state_batch,
                                             DeviceTensor &conv_state_batch,
                                             DeviceTensor &conv_out_buf,
                                             const DeviceTensor &proj,
                                             const DeviceTensor &gate,
                                             const DeviceTensor &alpha,
                                             const DeviceTensor &beta,
                                             const DeviceWeight &conv,
                                             const DeviceWeight &ssm_a,
                                             const DeviceWeight &dt_bias,
                                             const DeviceWeight &ssm_norm,
                                             uint32_t batch,
                                             uint32_t num_k_heads,
                                             uint32_t num_v_heads,
                                             uint32_t head_k_dim,
                                             uint32_t head_v_dim,
                                             uint32_t conv_kernel_size,
                                             uint32_t proj_count,
                                             uint32_t proj_stride,
                                             uint32_t gate_stride,
                                             uint32_t alpha_stride,
                                             uint32_t beta_stride,
                                             uint32_t core_stride,
                                             uint32_t state_stride,
                                             uint32_t conv_state_stride,
                                             float eps) override {
        if (batch == 0) return {};
        auto &c = as_tensor(core);
        auto &s = as_tensor(state_batch);
        auto &cs = as_tensor(conv_state_batch);
        auto &cout = as_tensor(conv_out_buf);
        const auto &p = as_tensor(proj);
        const auto &g = as_tensor(gate);
        const auto &a = as_tensor(alpha);
        const auto &b = as_tensor(beta);
        const auto &cw = as_weight(conv);
        const auto &aw = as_weight(ssm_a);
        const auto &dt = as_weight(dt_bias);
        const auto &nw = as_weight(ssm_norm);
        if (head_k_dim != 128 || head_v_dim > 256) {
            return {false, "recurrent_batch_independent unsupported head dims"};
        }
        const uint64_t need_state =
            static_cast<uint64_t>(batch - 1) * state_stride +
            static_cast<uint64_t>(num_v_heads) * head_v_dim * head_k_dim;
        const uint64_t need_conv_state =
            static_cast<uint64_t>(batch - 1) * conv_state_stride +
            static_cast<uint64_t>(proj_count) * (conv_kernel_size - 1);
        if (s.count < need_state || cs.count < need_conv_state) {
            return {false, "recurrent_batch_independent state tensor too small"};
        }

        const unsigned conv_threads = 256;
        const unsigned conv_blocks =
            static_cast<unsigned>((proj_count + conv_threads - 1) / conv_threads);
        dim3 conv_grid(batch, conv_blocks);
        switch (conv_kernel_size) {
            case 3:
                recurrent_conv_independent_batch_kernel<3>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                        batch, proj_count, conv_state_stride, proj_stride, proj_stride);
                break;
            case 4:
                recurrent_conv_independent_batch_kernel<4>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                        batch, proj_count, conv_state_stride, proj_stride, proj_stride);
                break;
            case 5:
                recurrent_conv_independent_batch_kernel<5>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                        batch, proj_count, conv_state_stride, proj_stride, proj_stride);
                break;
            case 7:
                recurrent_conv_independent_batch_kernel<7>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, static_cast<const float *>(cw.ptr),
                        batch, proj_count, conv_state_stride, proj_stride, proj_stride);
                break;
            default:
                return {false, "recurrent_batch_independent unsupported conv_kernel_size"};
        }
        if (auto st = launch_status("recurrent_conv_independent_batch_kernel");
            !st.ok) return st;

        dim3 ln_grid(batch, num_k_heads);
        const uint32_t q_off = 0;
        const uint32_t k_off = num_k_heads * head_k_dim;
        l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
            cout.ptr, num_k_heads, head_k_dim, batch, proj_stride, q_off, eps);
        l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
            cout.ptr, num_k_heads, head_k_dim, batch, proj_stride, k_off, eps);
        if (auto st = launch_status("recurrent independent l2 norm"); !st.ok) {
            return st;
        }

        dim3 dn_grid(batch, num_v_heads, head_v_dim);
        deltanet_independent_batch_kernel<<<dn_grid, 128, 0, exec_stream_>>>(
            c.ptr, s.ptr, cout.ptr, a.ptr, b.ptr,
            static_cast<const float *>(aw.ptr),
            static_cast<const float *>(dt.ptr),
            batch, num_k_heads, num_v_heads, head_k_dim, head_v_dim,
            proj_stride, alpha_stride, beta_stride, core_stride, state_stride);
        if (auto st = launch_status("deltanet_independent_batch_kernel"); !st.ok) {
            return st;
        }

        dim3 ng_grid(batch, num_v_heads);
        recurrent_norm_gate_batch_kernel<<<ng_grid, head_v_dim, 0, exec_stream_>>>(
            c.ptr, g.ptr, static_cast<const float *>(nw.ptr),
            batch, num_v_heads, head_v_dim, core_stride, gate_stride, eps);
        return launch_status("recurrent independent norm gate");
    }

    DeviceStatus recurrent_batch_ragged(DeviceTensor &core,
                                        DeviceTensor &state_batch,
                                        DeviceTensor &conv_state_batch,
                                        DeviceTensor &conv_out_buf,
                                        const DeviceTensor &proj,
                                        const DeviceTensor &gate,
                                        const DeviceTensor &alpha,
                                        const DeviceTensor &beta,
                                        const DeviceTensor &q_indptr,
                                        const int32_t *q_indptr_host,
                                        const DeviceWeight &conv,
                                        const DeviceWeight &ssm_a,
                                        const DeviceWeight &dt_bias,
                                        const DeviceWeight &ssm_norm,
                                        uint32_t batch,
                                        uint32_t total_q,
                                        uint32_t num_k_heads,
                                        uint32_t num_v_heads,
                                        uint32_t head_k_dim,
                                        uint32_t head_v_dim,
                                        uint32_t conv_kernel_size,
                                        uint32_t proj_count,
                                        uint32_t proj_stride,
                                        uint32_t gate_stride,
                                        uint32_t alpha_stride,
                                        uint32_t beta_stride,
                                        uint32_t core_stride,
                                        uint32_t state_stride,
                                        uint32_t conv_state_stride,
                                        float eps,
                                        DeviceTensor *state_checkpoints,
                                        DeviceTensor *conv_state_checkpoints,
                                        uint32_t checkpoint_count) override {
        if (batch == 0 || total_q == 0) return {};
        auto &c = as_tensor(core);
        auto &s = as_tensor(state_batch);
        auto &cs = as_tensor(conv_state_batch);
        auto &cout = as_tensor(conv_out_buf);
        const auto &p = as_tensor(proj);
        const auto &g = as_tensor(gate);
        const auto &a = as_tensor(alpha);
        const auto &b = as_tensor(beta);
        const auto &qptr = as_tensor(q_indptr);
        const auto &cw = as_weight(conv);
        const auto &aw = as_weight(ssm_a);
        const auto &dt = as_weight(dt_bias);
        const auto &nw = as_weight(ssm_norm);
        auto *state_ckpt = state_checkpoints ? &as_tensor(*state_checkpoints) : nullptr;
        auto *conv_ckpt = conv_state_checkpoints ? &as_tensor(*conv_state_checkpoints) : nullptr;
        const uint32_t effective_checkpoint_count =
            std::min<uint32_t>(checkpoint_count, total_q);
        const bool want_checkpoint =
            state_ckpt != nullptr && conv_ckpt != nullptr &&
            effective_checkpoint_count > 0;
        if (qptr.elem_size != sizeof(int32_t) ||
            qptr.count < static_cast<uint64_t>(batch) + 1) {
            return {false, "recurrent_batch_ragged q_indptr must be i32[batch+1]"};
        }
        if (head_k_dim != 128 || head_v_dim > 256) {
            return {false, "recurrent_batch_ragged unsupported head dims"};
        }
        if (!q_indptr_host) {
            return {false, "recurrent_batch_ragged requires host q_indptr"};
        }
        if (q_indptr_host[0] != 0 ||
            q_indptr_host[batch] != static_cast<int32_t>(total_q)) {
            return {false, "recurrent_batch_ragged invalid host q_indptr"};
        }
        const uint64_t need_state =
            static_cast<uint64_t>(batch - 1) * state_stride +
            static_cast<uint64_t>(num_v_heads) * head_v_dim * head_k_dim;
        const uint64_t need_conv_state =
            static_cast<uint64_t>(batch - 1) * conv_state_stride +
            static_cast<uint64_t>(proj_count) * (conv_kernel_size - 1);
        const uint64_t need_proj =
            static_cast<uint64_t>(total_q - 1) * proj_stride + proj_count;
        const uint64_t need_core =
            static_cast<uint64_t>(total_q - 1) * core_stride +
            static_cast<uint64_t>(num_v_heads) * head_v_dim;
        if (s.count < need_state || cs.count < need_conv_state ||
            p.count < need_proj || cout.count < need_proj ||
            c.count < need_core) {
            return {false, "recurrent_batch_ragged tensor too small"};
        }

        if (recurrent_kernel_choice() == RecurrentKernel::Ported) {
            if (head_k_dim != head_v_dim) {
                return {false, "recurrent_batch_ragged ported kernel requires head_k_dim == head_v_dim"};
            }
            if (alpha_stride != beta_stride) {
                return {false, "recurrent_batch_ragged ported kernel requires alpha_stride == beta_stride"};
            }
            for (uint32_t req = 0; req < batch; ++req) {
                const int32_t begin_i = q_indptr_host[req];
                const int32_t end_i = q_indptr_host[req + 1];
                if (begin_i < 0 || end_i < begin_i) {
                    return {false, "recurrent_batch_ragged invalid request span"};
                }
                const uint32_t begin = static_cast<uint32_t>(begin_i);
                const uint32_t end = static_cast<uint32_t>(end_i);
                const uint32_t span = end - begin;
                if (span == 0) continue;
                const uint32_t req_checkpoint_count =
                    std::min<uint32_t>(effective_checkpoint_count, span);

                float *conv_state_row =
                    cs.ptr + static_cast<uint64_t>(req) * conv_state_stride;
                float *state_row =
                    s.ptr + static_cast<uint64_t>(req) * state_stride;
                const float *proj_row =
                    p.ptr + static_cast<uint64_t>(begin) * proj_stride;
                float *conv_out_row =
                    cout.ptr + static_cast<uint64_t>(begin) * proj_stride;

                const unsigned conv_threads = 256;
                const unsigned conv_blocks =
                    static_cast<unsigned>((proj_count + conv_threads - 1) /
                                          conv_threads);
                switch (conv_kernel_size) {
                    case 3:
                        recurrent_conv_batch_kernel<3>
                            <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                                conv_out_row, conv_state_row, proj_row,
                                static_cast<const float *>(cw.ptr),
                                want_checkpoint
                                    ? conv_ckpt->ptr +
                                          static_cast<uint64_t>(req) *
                                              effective_checkpoint_count *
                                              conv_state_stride
                                    : nullptr,
                                span, proj_count, proj_stride, proj_stride,
                                req_checkpoint_count);
                        break;
                    case 4:
                        recurrent_conv_batch_kernel<4>
                            <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                                conv_out_row, conv_state_row, proj_row,
                                static_cast<const float *>(cw.ptr),
                                want_checkpoint
                                    ? conv_ckpt->ptr +
                                          static_cast<uint64_t>(req) *
                                              effective_checkpoint_count *
                                              conv_state_stride
                                    : nullptr,
                                span, proj_count, proj_stride, proj_stride,
                                req_checkpoint_count);
                        break;
                    case 5:
                        recurrent_conv_batch_kernel<5>
                            <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                                conv_out_row, conv_state_row, proj_row,
                                static_cast<const float *>(cw.ptr),
                                want_checkpoint
                                    ? conv_ckpt->ptr +
                                          static_cast<uint64_t>(req) *
                                              effective_checkpoint_count *
                                              conv_state_stride
                                    : nullptr,
                                span, proj_count, proj_stride, proj_stride,
                                req_checkpoint_count);
                        break;
                    case 7:
                        recurrent_conv_batch_kernel<7>
                            <<<conv_blocks, conv_threads, 0, exec_stream_>>>(
                                conv_out_row, conv_state_row, proj_row,
                                static_cast<const float *>(cw.ptr),
                                want_checkpoint
                                    ? conv_ckpt->ptr +
                                          static_cast<uint64_t>(req) *
                                              effective_checkpoint_count *
                                              conv_state_stride
                                    : nullptr,
                                span, proj_count, proj_stride, proj_stride,
                                req_checkpoint_count);
                        break;
                    default:
                        return {false, "recurrent_batch_ragged unsupported conv_kernel_size"};
                }
                if (auto st = launch_status(
                        "recurrent_batch_ragged ported conv"); !st.ok) {
                    return st;
                }

                dim3 ln_grid(span, num_k_heads);
                const uint32_t q_off = 0;
                const uint32_t k_off = num_k_heads * head_k_dim;
                l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
                    conv_out_row, num_k_heads, head_k_dim, span, proj_stride,
                    q_off, eps);
                l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
                    conv_out_row, num_k_heads, head_k_dim, span, proj_stride,
                    k_off, eps);
                if (auto st = launch_status(
                        "recurrent_batch_ragged ported l2 norm"); !st.ok) {
                    return st;
                }

                auto &a_mut = const_cast<CudaTensor &>(as_tensor(alpha));
                auto &b_mut = const_cast<CudaTensor &>(as_tensor(beta));
                const uint32_t q_off_floats = 0;
                const uint32_t k_off_floats = num_k_heads * head_k_dim;
                const uint32_t v_off_floats =
                    2u * num_k_heads * head_k_dim;
                const bool ok = ported::launch_gated_delta_net(
                    a_mut.ptr + static_cast<uint64_t>(begin) * alpha_stride,
                    b_mut.ptr + static_cast<uint64_t>(begin) * beta_stride,
                    static_cast<const float *>(dt.ptr),
                    static_cast<const float *>(aw.ptr),
                    conv_out_row,
                    q_off_floats, k_off_floats, v_off_floats,
                    state_row,
                    c.ptr + static_cast<uint64_t>(begin) * core_stride,
                    span,
                    num_k_heads, num_v_heads, head_k_dim,
                    proj_stride, alpha_stride, core_stride,
                    true,
                    want_checkpoint
                        ? state_ckpt->ptr +
                              static_cast<uint64_t>(req) *
                                  effective_checkpoint_count *
                                  state_stride
                        : nullptr,
                    req_checkpoint_count, exec_stream_);
                if (!ok) {
                    return {false, "recurrent_batch_ragged ported kernel rejected head_dim"};
                }
                if (auto st = launch_status(
                        "recurrent_batch_ragged ported delta"); !st.ok) {
                    return st;
                }

                dim3 ng_grid(span, num_v_heads);
                recurrent_norm_gate_batch_kernel<<<ng_grid, head_v_dim, 0,
                                                    exec_stream_>>>(
                    c.ptr + static_cast<uint64_t>(begin) * core_stride,
                    g.ptr + static_cast<uint64_t>(begin) * gate_stride,
                    static_cast<const float *>(nw.ptr),
                    span, num_v_heads, head_v_dim, core_stride, gate_stride,
                    eps);
                if (auto st = launch_status(
                        "recurrent_batch_ragged ported norm gate"); !st.ok) {
                    return st;
                }
            }
            return {};
        }

        const unsigned conv_threads = 256;
        const unsigned conv_blocks =
            static_cast<unsigned>((proj_count + conv_threads - 1) / conv_threads);
        dim3 conv_grid(batch, conv_blocks);
        switch (conv_kernel_size) {
            case 3:
                recurrent_conv_ragged_batch_kernel<3>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, qptr.ptr_i32(),
                        static_cast<const float *>(cw.ptr),
                        want_checkpoint ? conv_ckpt->ptr : nullptr,
                        batch, proj_count, conv_state_stride, proj_stride,
                        proj_stride, effective_checkpoint_count);
                break;
            case 4:
                recurrent_conv_ragged_batch_kernel<4>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, qptr.ptr_i32(),
                        static_cast<const float *>(cw.ptr),
                        want_checkpoint ? conv_ckpt->ptr : nullptr,
                        batch, proj_count, conv_state_stride, proj_stride,
                        proj_stride, effective_checkpoint_count);
                break;
            case 5:
                recurrent_conv_ragged_batch_kernel<5>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, qptr.ptr_i32(),
                        static_cast<const float *>(cw.ptr),
                        want_checkpoint ? conv_ckpt->ptr : nullptr,
                        batch, proj_count, conv_state_stride, proj_stride,
                        proj_stride, effective_checkpoint_count);
                break;
            case 7:
                recurrent_conv_ragged_batch_kernel<7>
                    <<<conv_grid, conv_threads, 0, exec_stream_>>>(
                        cout.ptr, cs.ptr, p.ptr, qptr.ptr_i32(),
                        static_cast<const float *>(cw.ptr),
                        want_checkpoint ? conv_ckpt->ptr : nullptr,
                        batch, proj_count, conv_state_stride, proj_stride,
                        proj_stride, effective_checkpoint_count);
                break;
            default:
                return {false, "recurrent_batch_ragged unsupported conv_kernel_size"};
        }
        if (auto st = launch_status("recurrent_conv_ragged_batch_kernel");
            !st.ok) return st;

        dim3 ln_grid(total_q, num_k_heads);
        const uint32_t q_off = 0;
        const uint32_t k_off = num_k_heads * head_k_dim;
        l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
            cout.ptr, num_k_heads, head_k_dim, total_q, proj_stride, q_off, eps);
        l2_norm_128_batch_kernel<<<ln_grid, 128, 0, exec_stream_>>>(
            cout.ptr, num_k_heads, head_k_dim, total_q, proj_stride, k_off, eps);
        if (auto st = launch_status("recurrent ragged l2 norm"); !st.ok) {
            return st;
        }

        dim3 dn_grid(batch, num_v_heads, head_v_dim);
        deltanet_ragged_batch_kernel<<<dn_grid, 128, 0, exec_stream_>>>(
            c.ptr, s.ptr, cout.ptr, a.ptr, b.ptr, qptr.ptr_i32(),
            static_cast<const float *>(aw.ptr),
            static_cast<const float *>(dt.ptr),
            want_checkpoint ? state_ckpt->ptr : nullptr,
            batch, num_k_heads, num_v_heads, head_k_dim, head_v_dim,
            proj_stride, alpha_stride, beta_stride, core_stride, state_stride,
            effective_checkpoint_count);
        if (auto st = launch_status("deltanet_ragged_batch_kernel"); !st.ok) {
            return st;
        }

        dim3 ng_grid(total_q, num_v_heads);
        recurrent_norm_gate_batch_kernel<<<ng_grid, head_v_dim, 0, exec_stream_>>>(
            c.ptr, g.ptr, static_cast<const float *>(nw.ptr),
            total_q, num_v_heads, head_v_dim, core_stride, gate_stride, eps);
        return launch_status("recurrent ragged norm gate");
    }

    DeviceStatus zero_tensor(DeviceTensor &x) override {
        auto &t = as_tensor(x);
        return cuda_status(cudaMemsetAsync(t.ptr, 0, static_cast<size_t>(t.count) * t.elem_size,
                                           exec_stream_),
                            "zero_tensor");
    }

    DeviceStatus attention_single_token(DeviceTensor &mid,
                                        DeviceTensor &q,
                                        DeviceTensor &k,
                                        const DeviceTensor &v,
                                        const DeviceWeight &q_norm,
                                        const DeviceWeight &k_norm,
                                        uint32_t n_heads,
                                        uint32_t n_kv_heads,
                                        uint32_t head_dim,
                                        float eps) override {
        auto &m = as_tensor(mid);
        auto &qq = as_tensor(q);
        auto &kk = as_tensor(k);
        const auto &vv = as_tensor(v);
        const auto &qn = as_weight(q_norm);
        const auto &kn = as_weight(k_norm);
        attention_norm_mid_kernel<<<n_heads, head_dim, 0, exec_stream_>>>(m.ptr,
                                                         qq.ptr,
                                                         kk.ptr,
                                                         vv.ptr,
                                                         static_cast<const float *>(qn.ptr),
                                                         static_cast<const float *>(kn.ptr),
                                                         n_heads,
                                                         n_kv_heads,
                                                         head_dim,
                                                         eps);
        return launch_status("cuda attention_single_token");
    }

    DeviceStatus rmsnorm_per_head(DeviceTensor &x,
                                   const DeviceWeight &weight,
                                   uint32_t n_units,
                                   uint32_t per_unit_stride,
                                   uint32_t head_dim,
                                   float eps) override {
        auto &t = as_tensor(x);
        const auto &w = as_weight(weight);
        dim3 grid(1, n_units);
        rmsnorm_per_head_kernel<<<grid, 256, 0, exec_stream_>>>(t.ptr,
                                                static_cast<const float *>(w.ptr),
                                                n_units, per_unit_stride, head_dim, /*batch_stride=*/0, eps);
        return launch_status("cuda rmsnorm_per_head");
    }

    DeviceStatus rmsnorm_per_head_batch(DeviceTensor &x,
                                         const DeviceWeight &weight,
                                         uint32_t batch,
                                         uint32_t batch_stride,
                                         uint32_t n_units,
                                         uint32_t per_unit_stride,
                                         uint32_t head_dim,
                                         float eps) override {
        if (batch == 0) return {};
        auto &t = as_tensor(x);
        const auto &w = as_weight(weight);
        dim3 grid(batch, n_units);
        if (t.is_lazy_fp8_linear() &&
            t.lazy_fp8_batch == batch &&
            t.lazy_fp8_rows >= n_units * per_unit_stride &&
            batch_stride >= n_units * per_unit_stride) {
            rmsnorm_per_head_lazy_fp8_kernel<<<
                grid, 256, 0, exec_stream_>>>(
                t.ptr, t.lazy_fp8_raw,
                t.lazy_fp8_activation_scales,
                t.lazy_fp8_weight_scales,
                static_cast<const float *>(w.ptr),
                batch, batch_stride, n_units, per_unit_stride,
                head_dim, t.lazy_fp8_raw_stride,
                t.lazy_fp8_row_offset, eps);
            DeviceStatus status =
                launch_status("cuda lazy FP8 rmsnorm_per_head_batch");
            if (status.ok) t.clear_lazy_fp8_linear();
            return status;
        }
        rmsnorm_per_head_kernel<<<grid, 256, 0, exec_stream_>>>(t.ptr,
                                                static_cast<const float *>(w.ptr),
                                                n_units, per_unit_stride, head_dim, batch_stride, eps);
        return launch_status("cuda rmsnorm_per_head_batch");
    }

    DeviceStatus rope_partial(DeviceTensor &x,
                               uint32_t n_units,
                               uint32_t per_unit_stride,
                               uint32_t rope_dim,
                               uint32_t pos,
                               float theta) override {
        auto &t = as_tensor(x);
        const uint32_t half = rope_dim / 2;
        if (half == 0) return {};
        dim3 grid(1, n_units);
        rope_partial_kernel<<<grid, half, 0, exec_stream_>>>(t.ptr, n_units, per_unit_stride, rope_dim, pos, /*batch_stride=*/0, theta);
        return launch_status("cuda rope_partial");
    }

    DeviceStatus rmsnorm_rope_qk(DeviceTensor &q,
                                 DeviceTensor &k,
                                 const DeviceWeight &q_weight,
                                 const DeviceWeight &k_weight,
                                 uint32_t n_q_heads,
                                 uint32_t n_kv_heads,
                                 uint32_t q_head_stride,
                                 uint32_t k_head_stride,
                                 uint32_t head_dim,
                                 uint32_t rope_dim,
                                 uint32_t pos,
                                 float theta,
                                 float eps) override {
        static const bool enabled = []() {
            const char *value = std::getenv("QW3_FUSED_QK_NORM_ROPE");
            return !value ||
                   (std::strcmp(value, "0") != 0 &&
                    std::strcmp(value, "off") != 0 &&
                    std::strcmp(value, "false") != 0);
        }();
        if (!enabled || head_dim > 256 || rope_dim > head_dim ||
            (rope_dim & 1U) != 0) {
            return DeviceBackend::rmsnorm_rope_qk(
                q, k, q_weight, k_weight, n_q_heads, n_kv_heads,
                q_head_stride, k_head_stride, head_dim, rope_dim,
                pos, theta, eps);
        }
        auto &q_tensor = as_tensor(q);
        auto &k_tensor = as_tensor(k);
        const auto &qw = as_weight(q_weight);
        const auto &kw = as_weight(k_weight);
        rmsnorm_rope_qk_kernel<<<n_q_heads + n_kv_heads, 256, 0, exec_stream_>>>(
            q_tensor.ptr, k_tensor.ptr,
            static_cast<const float *>(qw.ptr),
            static_cast<const float *>(kw.ptr),
            n_q_heads, n_kv_heads, q_head_stride, k_head_stride,
            head_dim, rope_dim, pos, theta, eps);
        return launch_status("cuda rmsnorm_rope_qk");
    }

    DeviceStatus rope_partial_batch(DeviceTensor &x,
                                    uint32_t batch,
                                    uint32_t batch_stride,
                                    uint32_t n_units,
                                    uint32_t per_unit_stride,
                                    uint32_t rope_dim,
                                    uint32_t base_pos,
                                    float theta) override {
        if (batch == 0) return {};
        auto &t = as_tensor(x);
        const uint32_t half = rope_dim / 2;
        if (half == 0) return {};
        dim3 grid(batch, n_units);
        rope_partial_kernel<<<grid, half, 0, exec_stream_>>>(t.ptr, n_units, per_unit_stride, rope_dim, base_pos, batch_stride, theta);
        return launch_status("cuda rope_partial_batch");
    }

    DeviceStatus rope_partial_batch_positions(DeviceTensor &x,
                                              uint32_t batch,
                                              uint32_t batch_stride,
                                              uint32_t n_units,
                                              uint32_t per_unit_stride,
                                              uint32_t rope_dim,
                                              const DeviceTensor &positions,
                                              float theta) override {
        if (batch == 0) return {};
        auto &t = as_tensor(x);
        const auto &pos = as_tensor(positions);
        if (pos.elem_size != sizeof(int32_t) || pos.count < batch) {
            return {false, "rope_partial_batch_positions positions tensor invalid"};
        }
        const uint32_t half = rope_dim / 2;
        if (half == 0) return {};
        dim3 grid(batch, n_units);
        rope_partial_positions_kernel<<<grid, half, 0, exec_stream_>>>(
            t.ptr, n_units, per_unit_stride, rope_dim, pos.ptr_i32(),
            batch_stride, theta);
        return launch_status("cuda rope_partial_batch_positions");
    }

    DeviceStatus kv_append(DeviceTensor &cache,
                           const DeviceTensor &src,
                           uint32_t pos,
                           uint32_t per_pos_size) override {
        auto &c = as_tensor(cache);
        const auto &s = as_tensor(src);
        const unsigned threads = 256;
        const unsigned blocks = (per_pos_size + threads - 1) / threads;
        dim3 grid(1, blocks);
        if (c.is_q8_kv()) {
            const uint32_t row_elems = c.q8_row_elems;
            const uint32_t rows = per_pos_size / row_elems;
            dim3 qgrid(1, rows);
            kv_append_kernel_q8<<<qgrid, row_elems, row_elems * sizeof(float), exec_stream_>>>(
                c.ptr_i8(), c.scale, s.ptr, pos, per_pos_size, row_elems, /*src_stride=*/0);
        } else if (c.is_fp8_kv()) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_kernel_fp8<<<dim3(1, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.ptr, pos, per_pos_size, /*src_stride=*/0);
        } else if (c.is_fp16()) {
            kv_append_kernel_f16<<<grid, threads, 0, exec_stream_>>>(c.ptr_h(), s.ptr, pos, per_pos_size, /*src_stride=*/0);
        } else {
            kv_append_kernel<<<grid, threads, 0, exec_stream_>>>(c.ptr, s.ptr, pos, per_pos_size, /*src_stride=*/0);
        }
        return launch_status("cuda kv_append");
    }

    DeviceStatus kv_append_batch(DeviceTensor &cache,
                                 const DeviceTensor &src,
                                 uint32_t base_pos,
                                 uint32_t per_pos_size,
                                 uint32_t batch) override {
        if (batch == 0) return {};
        auto &c = as_tensor(cache);
        auto &s = const_cast<CudaTensor &>(as_tensor(src));
        const unsigned threads = 256;
        const unsigned blocks = (per_pos_size + threads - 1) / threads;
        dim3 grid(batch, blocks);
        if (c.is_q8_kv()) {
            const uint32_t row_elems = c.q8_row_elems;
            const uint32_t rows = per_pos_size / row_elems;
            dim3 qgrid(batch, rows);
            kv_append_kernel_q8<<<qgrid, row_elems, row_elems * sizeof(float), exec_stream_>>>(
                c.ptr_i8(), c.scale, s.ptr, base_pos, per_pos_size, row_elems, per_pos_size);
        } else if (c.is_fp8_kv() && s.is_lazy_fp8_linear() &&
                   s.lazy_fp8_batch == batch &&
                   s.lazy_fp8_rows >= per_pos_size) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_lazy_linear_kernel_fp8<<<
                dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.lazy_fp8_raw,
                s.lazy_fp8_activation_scales,
                s.lazy_fp8_weight_scales,
                base_pos, per_pos_size,
                s.lazy_fp8_raw_stride, s.lazy_fp8_row_offset);
            DeviceStatus status =
                launch_status("cuda lazy FP8 kv_append_batch");
            if (status.ok) s.clear_lazy_fp8_linear();
            return status;
        } else if (c.is_fp8_kv()) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_kernel_fp8<<<dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.ptr, base_pos, per_pos_size, per_pos_size);
        } else if (c.is_fp16()) {
            kv_append_kernel_f16<<<grid, threads, 0, exec_stream_>>>(c.ptr_h(), s.ptr, base_pos, per_pos_size, per_pos_size);
        } else {
            kv_append_kernel<<<grid, threads, 0, exec_stream_>>>(c.ptr, s.ptr, base_pos, per_pos_size, per_pos_size);
        }
        return launch_status("cuda kv_append_batch");
    }

    DeviceStatus ensure_kv_page_indices(const int32_t *page_indices,
                                        uint32_t n_pages) {
        if (!page_indices || n_pages == 0) {
            return {false, "paged KV requires a non-empty page table"};
        }
        if (n_pages > kv_page_indices_i32_capacity_) {
            if (kv_page_indices_i32_) cudaFree(kv_page_indices_i32_);
            kv_page_indices_i32_ = nullptr;
            if (auto st = cuda_status(cudaMalloc(&kv_page_indices_i32_,
                                                 static_cast<size_t>(n_pages) * sizeof(int32_t)),
                                      "kv page table malloc"); !st.ok) {
                kv_page_indices_i32_capacity_ = 0;
                return st;
            }
            kv_page_indices_i32_capacity_ = n_pages;
        }
        return cuda_status(cudaMemcpyAsync(kv_page_indices_i32_,
                                           page_indices,
                                           static_cast<size_t>(n_pages) * sizeof(int32_t),
                                           cudaMemcpyHostToDevice,
                                           exec_stream_),
                           "kv page table copy");
    }

    DeviceStatus kv_append_batch_paged(DeviceTensor &cache,
                                       const DeviceTensor &src,
                                       uint32_t base_logical_pos,
                                       uint32_t per_pos_size,
                                       uint32_t batch,
                                       const int32_t *page_indices,
                                       uint32_t n_pages,
                                       uint32_t page_size) override {
        if (batch == 0) return {};
        if (page_size == 0) return {false, "kv_append_batch_paged page_size=0"};
        const uint32_t need_pages =
            (base_logical_pos + batch + page_size - 1) / page_size;
        if (need_pages > n_pages) return {false, "kv_append_batch_paged page table too small"};
        if (auto st = ensure_kv_page_indices(page_indices, n_pages); !st.ok) return st;

        auto &c = as_tensor(cache);
        auto &s = const_cast<CudaTensor &>(as_tensor(src));
        const unsigned threads = 256;
        const unsigned blocks = (per_pos_size + threads - 1) / threads;
        dim3 grid(batch, blocks);
        if (c.is_q8_kv()) {
            const uint32_t row_elems = c.q8_row_elems;
            const uint32_t rows = per_pos_size / row_elems;
            dim3 qgrid(batch, rows);
            kv_append_paged_kernel_q8<<<qgrid, row_elems, row_elems * sizeof(float), exec_stream_>>>(
                c.ptr_i8(), c.scale, s.ptr, base_logical_pos, per_pos_size,
                row_elems, per_pos_size, kv_page_indices_i32_, page_size);
        } else if (c.is_fp8_kv() && s.is_lazy_fp8_linear() &&
                   s.lazy_fp8_batch == batch &&
                   s.lazy_fp8_rows >= per_pos_size) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_paged_lazy_linear_kernel_fp8<<<
                dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.lazy_fp8_raw,
                s.lazy_fp8_activation_scales,
                s.lazy_fp8_weight_scales,
                base_logical_pos, per_pos_size,
                s.lazy_fp8_raw_stride, s.lazy_fp8_row_offset,
                kv_page_indices_i32_, page_size);
            DeviceStatus status =
                launch_status("cuda lazy FP8 kv_append_batch_paged");
            if (status.ok) s.clear_lazy_fp8_linear();
            return status;
        } else if (c.is_fp8_kv()) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_paged_kernel_fp8<<<dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                kv_page_indices_i32_, page_size);
        } else if (c.is_fp16()) {
            kv_append_paged_kernel_f16<<<grid, threads, 0, exec_stream_>>>(
                c.ptr_h(), s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                kv_page_indices_i32_, page_size);
        } else {
            kv_append_paged_kernel<<<grid, threads, 0, exec_stream_>>>(
                c.ptr, s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                kv_page_indices_i32_, page_size);
        }
        return launch_status("cuda kv_append_batch_paged");
    }

    DeviceStatus kv_append_batch_paged_device(DeviceTensor &cache,
                                              const DeviceTensor &src,
                                              uint32_t base_logical_pos,
                                              uint32_t per_pos_size,
                                              uint32_t batch,
                                              const DeviceTensor &page_indices,
                                              uint32_t n_pages,
                                              uint32_t page_size) override {
        if (batch == 0) return {};
        if (page_size == 0) return {false, "kv_append_batch_paged_device page_size=0"};
        const uint32_t need_pages =
            (base_logical_pos + batch + page_size - 1) / page_size;
        if (need_pages > n_pages) return {false, "kv_append_batch_paged_device page table too small"};
        const auto &pages = as_tensor(page_indices);
        if (pages.elem_size != sizeof(int32_t)) return {false, "kv_append_batch_paged_device dtype mismatch"};
        if (pages.count < n_pages) return {false, "kv_append_batch_paged_device page tensor too small"};

        auto &c = as_tensor(cache);
        auto &s = const_cast<CudaTensor &>(as_tensor(src));
        const unsigned threads = 256;
        const unsigned blocks = (per_pos_size + threads - 1) / threads;
        dim3 grid(batch, blocks);
        if (c.is_q8_kv()) {
            const uint32_t row_elems = c.q8_row_elems;
            const uint32_t rows = per_pos_size / row_elems;
            dim3 qgrid(batch, rows);
            kv_append_paged_kernel_q8<<<qgrid, row_elems, row_elems * sizeof(float), exec_stream_>>>(
                c.ptr_i8(), c.scale, s.ptr, base_logical_pos, per_pos_size,
                row_elems, per_pos_size, pages.ptr_i32(), page_size);
        } else if (c.is_fp8_kv() && s.is_lazy_fp8_linear() &&
                   s.lazy_fp8_batch == batch &&
                   s.lazy_fp8_rows >= per_pos_size) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_paged_lazy_linear_kernel_fp8<<<
                dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.lazy_fp8_raw,
                s.lazy_fp8_activation_scales,
                s.lazy_fp8_weight_scales,
                base_logical_pos, per_pos_size,
                s.lazy_fp8_raw_stride, s.lazy_fp8_row_offset,
                pages.ptr_i32(), page_size);
            DeviceStatus status =
                launch_status("cuda lazy FP8 kv_append_batch_paged_device");
            if (status.ok) s.clear_lazy_fp8_linear();
            return status;
        } else if (c.is_fp8_kv()) {
            const unsigned fp8_blocks =
                ((per_pos_size + 1U) / 2U + threads - 1U) / threads;
            kv_append_paged_kernel_fp8<<<dim3(batch, fp8_blocks), threads, 0, exec_stream_>>>(
                c.ptr_fp8(), s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                pages.ptr_i32(), page_size);
        } else if (c.is_fp16()) {
            kv_append_paged_kernel_f16<<<grid, threads, 0, exec_stream_>>>(
                c.ptr_h(), s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                pages.ptr_i32(), page_size);
        } else {
            kv_append_paged_kernel<<<grid, threads, 0, exec_stream_>>>(
                c.ptr, s.ptr, base_logical_pos, per_pos_size, per_pos_size,
                pages.ptr_i32(), page_size);
        }
        return launch_status("cuda kv_append_batch_paged_device");
    }

    DeviceStatus rope_block_remap_paged_device(DeviceTensor &k_cache,
                                               uint32_t n_tokens,
                                               uint32_t n_kv_heads,
                                               uint32_t per_pos_size,
                                               uint32_t head_dim,
                                               uint32_t rope_dim,
                                               uint32_t win_base,
                                               int32_t from_base,
                                               int32_t to_base,
                                               const DeviceTensor &page_indices,
                                               uint32_t page_size,
                                               float theta) override {
        if (n_tokens == 0 || n_kv_heads == 0) return {};
        if (from_base == to_base) return {};  // already baked at the target slot
        if (page_size == 0) return {false, "rope_block_remap_paged_device page_size=0"};
        auto &c = as_tensor(k_cache);
        const auto &pages = as_tensor(page_indices);
        if (pages.elem_size != sizeof(int32_t)) {
            return {false, "rope_block_remap_paged_device page dtype mismatch"};
        }
        const bool is_fp16 = c.is_fp16();
        const bool is_fp8 = c.is_fp8_kv();
        const bool is_f32 = (c.elem_size == sizeof(float)) && !c.is_q8_kv() &&
                            !c.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false, "rope_block_remap_paged_device requires fp16, fp32, "
                           "or fp8 KV (q8 re-RoPE is unsupported)"};
        }
        void *ptr = is_fp16 ? static_cast<void *>(c.ptr_h())
                            : is_fp8 ? static_cast<void *>(c.ptr_fp8())
                                     : static_cast<void *>(c.ptr);
        const bool launched = is_fp8
            ? ported::launch_rope_block_remap_paged_fp8(
                  ptr, n_tokens, n_kv_heads, per_pos_size, head_dim, rope_dim,
                  win_base, from_base, to_base, pages.ptr_i32(), page_size,
                  theta, exec_stream_)
            : ported::launch_rope_block_remap_paged(
                  ptr, is_fp16, n_tokens, n_kv_heads, per_pos_size, head_dim,
                  rope_dim, win_base, from_base, to_base, pages.ptr_i32(),
                  page_size, theta, exec_stream_);
        if (!launched) {
            return {false, "rope_block_remap_paged launch failed"};
        }
        return launch_status("cuda rope_block_remap_paged_device");
    }

    DeviceStatus rope_block_remap_paged_batched_device(
            DeviceTensor &k_cache, uint32_t n_blocks, uint32_t max_n_tokens,
            uint32_t n_kv_heads, uint32_t per_pos_size, uint32_t head_dim,
            uint32_t rope_dim, const DeviceTensor &to_base,
            const DeviceTensor &from_base, const DeviceTensor &n_tokens,
            const DeviceTensor &page_indices, uint32_t page_size,
            float theta, const DeviceTensor *rope_sincos,
            uint32_t rope_table_positions) override {
        if (n_blocks == 0 || max_n_tokens == 0 || n_kv_heads == 0) return {};
        if (page_size == 0)
            return {false, "rope_block_remap_paged_batched_device page_size=0"};
        auto &c = as_tensor(k_cache);
        const auto &pages = as_tensor(page_indices);
        if (pages.elem_size != sizeof(int32_t)) {
            return {false, "rope_block_remap_paged_batched_device page dtype mismatch"};
        }
        const bool is_fp16 = c.is_fp16();
        const bool is_fp8 = c.is_fp8_kv();
        const bool is_f32 = (c.elem_size == sizeof(float)) && !c.is_q8_kv() &&
                            !c.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false, "rope_block_remap_paged_batched_device requires fp16, "
                           "fp32, or fp8 KV (q8 re-RoPE is unsupported)"};
        }
        void *ptr = is_fp16 ? static_cast<void *>(c.ptr_h())
                            : is_fp8 ? static_cast<void *>(c.ptr_fp8())
                                     : static_cast<void *>(c.ptr);
        const float *table_ptr = nullptr;
        if (rope_sincos) {
            const auto &table = as_tensor(*rope_sincos);
            const uint64_t needed =
                static_cast<uint64_t>(rope_table_positions) *
                (rope_dim / 2u) * 2u;
            if (table.elem_size != sizeof(float) || table.count < needed) {
                return {false, "KVMem RoPE table dtype/size mismatch"};
            }
            table_ptr = table.ptr;
        }
        const bool launched = table_ptr
            ? (is_fp8
                ? ported::launch_rope_block_remap_paged_batched_table_fp8(
                      ptr, n_blocks, max_n_tokens, n_kv_heads, per_pos_size,
                      head_dim, rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(from_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, table_ptr, rope_table_positions, exec_stream_)
                : ported::launch_rope_block_remap_paged_batched_table(
                      ptr, is_fp16, n_blocks, max_n_tokens, n_kv_heads,
                      per_pos_size, head_dim, rope_dim,
                      as_tensor(to_base).ptr_i32(),
                      as_tensor(from_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, table_ptr, rope_table_positions, exec_stream_))
            : (is_fp8
                ? ported::launch_rope_block_remap_paged_batched_fp8(
                      ptr, n_blocks, max_n_tokens, n_kv_heads, per_pos_size,
                      head_dim, rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(from_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, theta, exec_stream_)
                : ported::launch_rope_block_remap_paged_batched(
                      ptr, is_fp16, n_blocks, max_n_tokens, n_kv_heads,
                      per_pos_size, head_dim, rope_dim,
                      as_tensor(to_base).ptr_i32(),
                      as_tensor(from_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, theta, exec_stream_));
        if (!launched) {
            return {false, "rope_block_remap_paged_batched launch failed"};
        }
        return launch_status("cuda rope_block_remap_paged_batched_device");
    }

    DeviceStatus build_rope_sincos_table_device(
            DeviceTensor &table, uint32_t positions, uint32_t rope_dim,
            float theta) override {
        if (positions == 0 || rope_dim == 0 || (rope_dim % 2u) != 0) {
            return {false, "invalid KVMem RoPE table shape"};
        }
        auto &out = as_tensor(table);
        const uint64_t needed =
            static_cast<uint64_t>(positions) * (rope_dim / 2u) * 2u;
        if (out.elem_size != sizeof(float) || out.count < needed) {
            return {false, "KVMem RoPE table tensor is too small"};
        }
        if (!ported::launch_build_rope_sincos_table(
                out.ptr, positions, rope_dim, theta, exec_stream_)) {
            return {false, "KVMem RoPE table build launch failed"};
        }
        return launch_status("cuda build_rope_sincos_table_device");
    }

    DeviceStatus raw_k_scatter_rope_paged_batched_device(
            DeviceTensor &k_cache, const DeviceTensor &raw_k,
            uint64_t raw_element_offset, uint32_t n_blocks,
            uint32_t max_n_tokens, uint32_t n_kv_heads,
            uint32_t per_pos_size, uint32_t head_dim, uint32_t rope_dim,
            const DeviceTensor &to_base, const DeviceTensor &n_tokens,
            const DeviceTensor &page_indices, uint32_t page_size,
            float theta, const DeviceTensor *rope_sincos,
            uint32_t rope_table_positions,
            uint64_t raw_block_stride_elements) override {
        if (n_blocks == 0 || max_n_tokens == 0 || n_kv_heads == 0) return {};
        if (page_size == 0) {
            return {false,
                    "raw_k_scatter_rope_paged_batched_device page_size=0"};
        }
        auto &dst = as_tensor(k_cache);
        const auto &src = as_tensor(raw_k);
        const auto &pages = as_tensor(page_indices);
        if (dst.elem_size != src.elem_size ||
            dst.is_fp16() != src.is_fp16() ||
            dst.is_fp8_kv() != src.is_fp8_kv()) {
            return {false, "raw K/cache dtype mismatch"};
        }
        if (pages.elem_size != sizeof(int32_t)) {
            return {false, "raw K scatter page dtype mismatch"};
        }
        const bool is_fp16 = dst.is_fp16();
        const bool is_fp8 = dst.is_fp8_kv();
        const bool is_f32 = dst.elem_size == sizeof(float) &&
                            !dst.is_q8_kv() && !dst.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false,
                    "raw K scatter requires fp16, fp32, or fp8 KV"};
        }
        const uint64_t packed_block_elements =
            static_cast<uint64_t>(max_n_tokens) * per_pos_size;
        const uint64_t block_stride = raw_block_stride_elements != 0
            ? raw_block_stride_elements : packed_block_elements;
        if (block_stride < packed_block_elements) {
            return {false, "raw K scatter block stride is too small"};
        }
        const uint64_t needed =
            raw_element_offset +
            static_cast<uint64_t>(n_blocks - 1) * block_stride +
            packed_block_elements;
        if (needed > src.count) {
            return {false, "raw K scatter source is too small"};
        }
        void *dst_ptr = is_fp16 ? static_cast<void *>(dst.ptr_h())
                                : is_fp8 ? static_cast<void *>(dst.ptr_fp8())
                                         : static_cast<void *>(dst.ptr);
        const void *src_ptr =
            is_fp16 ? static_cast<const void *>(src.ptr_h())
                    : is_fp8 ? static_cast<const void *>(src.ptr_fp8())
                             : static_cast<const void *>(src.ptr);
        const float *table_ptr = nullptr;
        if (rope_sincos) {
            const auto &table = as_tensor(*rope_sincos);
            const uint64_t table_needed =
                static_cast<uint64_t>(rope_table_positions) *
                (rope_dim / 2u) * 2u;
            if (table.elem_size != sizeof(float) ||
                table.count < table_needed) {
                return {false, "KVMem raw scatter RoPE table mismatch"};
            }
            table_ptr = table.ptr;
        }
        const bool launched = table_ptr
            ? (is_fp8
                ? ported::launch_raw_k_scatter_rope_paged_batched_table_fp8(
                      dst_ptr, src_ptr, raw_element_offset, n_blocks,
                      max_n_tokens, n_kv_heads, per_pos_size, head_dim,
                      rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, table_ptr, rope_table_positions,
                      block_stride, exec_stream_)
                : ported::launch_raw_k_scatter_rope_paged_batched_table(
                      dst_ptr, src_ptr, is_fp16, raw_element_offset, n_blocks,
                      max_n_tokens, n_kv_heads, per_pos_size, head_dim,
                      rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, table_ptr, rope_table_positions,
                      block_stride, exec_stream_))
            : (is_fp8
                ? ported::launch_raw_k_scatter_rope_paged_batched_fp8(
                      dst_ptr, src_ptr, raw_element_offset, n_blocks,
                      max_n_tokens, n_kv_heads, per_pos_size, head_dim,
                      rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, theta, block_stride, exec_stream_)
                : ported::launch_raw_k_scatter_rope_paged_batched(
                      dst_ptr, src_ptr, is_fp16, raw_element_offset, n_blocks,
                      max_n_tokens, n_kv_heads, per_pos_size, head_dim,
                      rope_dim, as_tensor(to_base).ptr_i32(),
                      as_tensor(n_tokens).ptr_i32(), pages.ptr_i32(),
                      page_size, theta, block_stride, exec_stream_));
        if (!launched) return {false, "raw K scatter launch failed"};
        return launch_status("cuda raw_k_scatter_rope_paged_batched_device");
    }

    DeviceStatus block_kmean_paged_device(const DeviceTensor &k_cache,
                                          DeviceTensor &kbar,
                                          uint32_t n_blocks,
                                          uint32_t n_kv_heads,
                                          uint32_t per_pos_size,
                                          uint32_t head_dim,
                                          const DeviceTensor &win_base,
                                          const DeviceTensor &blk_tokens,
                                          const DeviceTensor &page_indices,
                                          uint32_t page_size) override {
        if (n_blocks == 0 || n_kv_heads == 0 || head_dim == 0) return {};
        if (page_size == 0) return {false, "block_kmean_paged_device page_size=0"};
        const auto &c = as_tensor(k_cache);
        const auto &pages = as_tensor(page_indices);
        const auto &wb = as_tensor(win_base);
        const auto &bt = as_tensor(blk_tokens);
        auto &kb = as_tensor(kbar);
        if (pages.elem_size != sizeof(int32_t) ||
            wb.elem_size != sizeof(int32_t) || bt.elem_size != sizeof(int32_t)) {
            return {false, "block_kmean_paged_device metadata dtype mismatch"};
        }
        const bool is_fp16 = c.is_fp16();
        const bool is_fp8 = c.is_fp8_kv();
        const bool is_f32 = (c.elem_size == sizeof(float)) && !c.is_q8_kv() &&
                            !c.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false, "block_kmean_paged_device requires fp16, fp32, or fp8 KV"};
        }
        const void *ptr = is_fp16 ? static_cast<const void *>(c.ptr_h())
                                  : is_fp8 ? static_cast<const void *>(c.ptr_fp8())
                                           : static_cast<const void *>(c.ptr);
        const ported::KbarDType kbar_dtype =
            kb.is_fp8_kv() ? ported::KbarDType::FP8
                           : kb.is_fp16() ? ported::KbarDType::F16
                                         : ported::KbarDType::F32;
        const bool launched = ported::launch_block_kmean_paged_typed(
            const_cast<void *>(ptr), is_fp16, is_fp8,
            static_cast<void *>(kb.ptr), kbar_dtype, n_blocks, n_kv_heads,
            per_pos_size, head_dim, wb.ptr_i32(), bt.ptr_i32(),
            pages.ptr_i32(), page_size, exec_stream_);
        if (!launched) {
            return {false, "block_kmean_paged launch failed"};
        }
        return launch_status("cuda block_kmean_paged_device");
    }

    DeviceStatus block_attn_score_step_device(DeviceTensor &accum,
                                              const DeviceTensor &q,
                                              const DeviceTensor &kbar,
                                              uint32_t q_stride,
                                              uint32_t n_blocks,
                                              uint32_t n_heads,
                                              uint32_t n_kv_heads,
                                              uint32_t head_dim,
                                              float scale) override {
        if (n_blocks == 0 || n_heads == 0 || head_dim == 0) return {};
        auto &a = as_tensor(accum);
        const auto &qt = as_tensor(q);
        const auto &kb = as_tensor(kbar);
        const ported::KbarDType kbar_dtype =
            kb.is_fp8_kv() ? ported::KbarDType::FP8
                           : kb.is_fp16() ? ported::KbarDType::F16
                                         : ported::KbarDType::F32;
        if (!ported::launch_block_attn_score_step_typed(
                a.ptr, qt.ptr, kb.ptr, kbar_dtype, q_stride, n_blocks,
                n_heads, n_kv_heads, head_dim, scale, exec_stream_)) {
            return {false, "block_attn_score_step launch failed"};
        }
