        const auto &kb = as_tensor(kbar_multi);
        const uint64_t q_row_elems =
            static_cast<uint64_t>(n_heads) * head_dim;
        const uint64_t q_rows_needed =
            static_cast<uint64_t>(n_layers - 1) * q_layer_stride +
            n_tokens;
