        const uint64_t kbar_block_elems =
            static_cast<uint64_t>(ns) * n_kv_heads * head_dim;
        const uint64_t kbar_blocks_needed =
            static_cast<uint64_t>(n_layers - 1) * kbar_layer_stride +
            n_blocks;
