        const uint64_t distributions =
            static_cast<uint64_t>(n_layers) * n_tokens * n_heads;
        const uint32_t ns = std::max(n_subblocks, 1u);
        if (gd.count < static_cast<uint64_t>(n_groups) * distributions ||
            gm.count < distributions || gs.count < distributions ||
            gb.elem_size != sizeof(int32_t) ||
            ge.elem_size != sizeof(int32_t) ||
            gb.count < n_groups || ge.count < n_groups) {
            return {false,
                    "block_attn_stream_group_update invalid tensor shape"};
        }
        const ported::KbarDType dtype =
            kb.is_fp8_kv() ? ported::KbarDType::FP8
                           : kb.is_fp16() ? ported::KbarDType::F16
                                         : ported::KbarDType::F32;
        if (!ported::launch_block_attn_stream_group_update_typed(
                gd.ptr, qm.ptr, qm.is_fp16(), kb.ptr, dtype,
                gm.ptr, gs.ptr, gb.ptr_i32(), ge.ptr_i32(), n_groups,
                n_layers, n_tokens, q_layer_stride, tile_blocks,
                kbar_layer_stride, global_block_base, n_heads,
                n_kv_heads, head_dim, scale, excl_lo_end,
                excl_hi_begin, ns, group_reduce_mass, exec_stream_)) {
            return {false,
                    "block_attn_stream_group_update launch failed"};
        }
        return launch_status(
            "cuda block_attn_stream_group_update_device");
    }

    DeviceStatus block_attn_stream_group_finalize_device(
            DeviceTensor &score,
            const DeviceTensor &group_dist,
            uint32_t n_groups,
            uint32_t n_distributions,
            float distribution_weight,
            uint32_t accumulate) override {
        auto &sc = as_tensor(score);
        const auto &gd = as_tensor(group_dist);
        if (sc.elem_size != sizeof(float) || sc.count < n_groups ||
            gd.elem_size != sizeof(float) ||
            gd.count <
                static_cast<uint64_t>(n_groups) * n_distributions) {
            return {false,
                    "block_attn_stream_group_finalize invalid tensor shape"};
        }
        if (!ported::launch_block_attn_stream_group_finalize(
                sc.ptr, gd.ptr, n_groups, n_distributions,
                distribution_weight, accumulate, exec_stream_)) {
            return {false,
                    "block_attn_stream_group_finalize launch failed"};
        }
        return launch_status(
            "cuda block_attn_stream_group_finalize_device");
    }

    DeviceStatus block_attention_mass_paged_device(
                                              DeviceTensor &mass,
                                              const DeviceTensor &q,
                                              uint32_t q_stride,
                                              const DeviceTensor &k_cache,
                                              uint32_t n_window_blocks,
                                              uint32_t n_heads,
                                              uint32_t n_kv_heads,
                                              uint32_t per_pos_size,
                                              uint32_t head_dim,
                                              const DeviceTensor &win_base,
                                              const DeviceTensor &blk_tokens,
                                              const DeviceTensor &page_indices,
                                              uint32_t n_pages,
                                              uint32_t page_size,
                                              uint32_t seq_len,
                                              float scale) override {
        if (n_heads == 0 || n_kv_heads == 0 || head_dim == 0 || seq_len == 0) {
            return {};
        }
        if (page_size == 0) return {false, "block_attention_mass_paged_device page_size=0"};
        const uint32_t need_pages = (seq_len + page_size - 1) / page_size;
        if (need_pages > n_pages) {
            return {false, "block_attention_mass_paged_device page table too small"};
        }
        auto &m = as_tensor(mass);
        const auto &qt = as_tensor(q);
        const auto &kc = as_tensor(k_cache);
        const auto &wb = as_tensor(win_base);
        const auto &bt = as_tensor(blk_tokens);
        const auto &pages = as_tensor(page_indices);
        const uint32_t buckets = n_window_blocks + 1;
        if (m.count < buckets) {
            return {false, "block_attention_mass_paged_device mass tensor too small"};
        }
        if (pages.elem_size != sizeof(int32_t) ||
            wb.elem_size != sizeof(int32_t) || bt.elem_size != sizeof(int32_t)) {
            return {false, "block_attention_mass_paged_device metadata dtype mismatch"};
        }
        const bool is_fp16 = kc.is_fp16();
        const bool is_fp8 = kc.is_fp8_kv();
        const bool is_f32 = (kc.elem_size == sizeof(float)) && !kc.is_q8_kv() &&
                            !kc.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false, "block_attention_mass_paged_device requires fp16, "
                           "fp32, or fp8 KV"};
        }
        if (auto st = cuda_status(cudaMemsetAsync(m.ptr, 0,
                            static_cast<size_t>(buckets) * sizeof(float),
                            exec_stream_),
                            "block_attention_mass memset"); !st.ok) {
            return st;
        }
        const void *ptr = is_fp16 ? static_cast<const void *>(kc.ptr_h())
                                  : is_fp8 ? static_cast<const void *>(kc.ptr_fp8())
                                           : static_cast<const void *>(kc.ptr);
        const bool launched = is_fp8
            ? ported::launch_block_attention_mass_paged_fp8(
                  const_cast<void *>(ptr), m.ptr, qt.ptr, q_stride,
                  n_window_blocks, n_heads, n_kv_heads, per_pos_size, head_dim,
                  wb.ptr_i32(), bt.ptr_i32(), pages.ptr_i32(), page_size,
                  seq_len, scale, exec_stream_)
            : ported::launch_block_attention_mass_paged(
                  const_cast<void *>(ptr), is_fp16, m.ptr, qt.ptr, q_stride,
                  n_window_blocks, n_heads, n_kv_heads, per_pos_size, head_dim,
                  wb.ptr_i32(), bt.ptr_i32(), pages.ptr_i32(), page_size,
                  seq_len, scale, exec_stream_);
        if (!launched) {
            return {false, "block_attention_mass_paged launch failed"};
        }
        return launch_status("cuda block_attention_mass_paged_device");
    }

    DeviceStatus block_kmean_content_paged_device(const DeviceTensor &k_cache,
                                                  DeviceTensor &kbar,
                                                  uint32_t n_blocks,
                                                  uint32_t n_kv_heads,
                                                  uint32_t per_pos_size,
                                                  uint32_t head_dim,
                                                  uint32_t rope_dim,
                                                  const DeviceTensor &orig_base,
                                                  const DeviceTensor &blk_tokens,
                                                  const DeviceTensor &page_indices,
                                                  uint32_t page_size,
                                                  float theta,
                                                  uint64_t out_elem_off = 0) override {
        if (n_blocks == 0 || n_kv_heads == 0 || head_dim == 0) return {};
        if (page_size == 0) return {false, "block_kmean_content_paged_device page_size=0"};
        const auto &c = as_tensor(k_cache);
        const auto &pages = as_tensor(page_indices);
        const auto &ob = as_tensor(orig_base);
        const auto &bt = as_tensor(blk_tokens);
        auto &kb = as_tensor(kbar);
        if (pages.elem_size != sizeof(int32_t) ||
            ob.elem_size != sizeof(int32_t) || bt.elem_size != sizeof(int32_t)) {
            return {false, "block_kmean_content_paged_device metadata dtype mismatch"};
        }
        const bool is_fp16 = c.is_fp16();
        const bool is_fp8 = c.is_fp8_kv();
        const bool is_f32 = (c.elem_size == sizeof(float)) && !c.is_q8_kv() &&
                            !c.is_fp8_kv();
        if (!is_fp16 && !is_fp8 && !is_f32) {
            return {false, "block_kmean_content_paged_device requires fp16, "
                           "fp32, or fp8 KV"};
        }
        const void *ptr = is_fp16 ? static_cast<const void *>(c.ptr_h())
                                  : is_fp8 ? static_cast<const void *>(c.ptr_fp8())
                                           : static_cast<const void *>(c.ptr);
        const ported::KbarDType kbar_dtype =
            kb.is_fp8_kv() ? ported::KbarDType::FP8
                           : kb.is_fp16() ? ported::KbarDType::F16
                                         : ported::KbarDType::F32;
        void *kbar_out = reinterpret_cast<uint8_t *>(kb.ptr) +
                         out_elem_off * kb.elem_size;
        const bool launched = ported::launch_block_kmean_content_paged_typed(
            const_cast<void *>(ptr), is_fp16, is_fp8, kbar_out, kbar_dtype,
            n_blocks, n_kv_heads, per_pos_size, head_dim, rope_dim,
            ob.ptr_i32(), bt.ptr_i32(), pages.ptr_i32(), page_size, theta,
            exec_stream_);
        if (!launched) {
            return {false, "block_kmean_content_paged launch failed"};
        }
        return launch_status("cuda block_kmean_content_paged_device");
    }

