    return launch_block_kmean_paged_output(
        static_cast<const float *>(k_cache), kbar, kbar_dtype, n_blocks,
        n_kv_heads, per_pos_size, head_dim, win_base, blk_tokens,
        page_indices, page_size, stream);
}

