template <typename KbarT>
bool launch_block_attn_score_step_impl(
        float *accum, const float *q, const KbarT *kbar,
        uint32_t q_stride, uint32_t n_blocks, uint32_t n_heads,
        uint32_t n_kv_heads, uint32_t head_dim, float scale,
        cudaStream_t stream) {
    if (n_blocks == 0 || n_heads == 0 || head_dim == 0) return true;
    // Round threads up to a power of two >= head_dim for the shared reduction.
    uint32_t threads = 1;
    while (threads < head_dim) threads <<= 1;
    const size_t shmem = static_cast<size_t>(threads) * sizeof(float);
    block_attn_score_step_kernel<KbarT><<<n_blocks, threads, shmem, stream>>>(
        accum, q, kbar, q_stride, n_heads, n_kv_heads, head_dim, scale);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_block_attn_score_step_typed(
        float *accum, const float *q, const void *kbar,
        KbarDType kbar_dtype, uint32_t q_stride, uint32_t n_blocks,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, cudaStream_t stream) {
    switch (kbar_dtype) {
        case KbarDType::F32:
            return launch_block_attn_score_step_impl(
                accum, q, static_cast<const float *>(kbar), q_stride,
                n_blocks, n_heads, n_kv_heads, head_dim, scale, stream);
        case KbarDType::F16:
            return launch_block_attn_score_step_impl(
                accum, q, static_cast<const __half *>(kbar), q_stride,
                n_blocks, n_heads, n_kv_heads, head_dim, scale, stream);
        case KbarDType::FP8:
            return launch_block_attn_score_step_impl(
                accum, q, static_cast<const __nv_fp8_e4m3 *>(kbar), q_stride,
                n_blocks, n_heads, n_kv_heads, head_dim, scale, stream);
    }
    return false;
}

bool launch_block_attn_score_step(float *accum, const float *q,
                                  const float *kbar, uint32_t q_stride,
                                  uint32_t n_blocks, uint32_t n_heads,
                                  uint32_t n_kv_heads, uint32_t head_dim,
                                  float scale, cudaStream_t stream) {
    return launch_block_attn_score_step_typed(
        accum, q, kbar, KbarDType::F32, q_stride, n_blocks, n_heads,
        n_kv_heads, head_dim, scale, stream);
}

template <typename QueryT, typename KbarT>
bool launch_block_attn_score_softmax_pages_impl(
                                           float *score,
                                           const QueryT *q_multi,
                                           const KbarT *kbar_multi,
                                           const int32_t *group_begin,
                                           const int32_t *group_end,
                                           uint32_t n_groups,
                                           uint32_t n_layers, uint32_t n_tokens,
                                           uint32_t q_layer_stride,
                                           uint32_t n_blocks,
                                           uint32_t kbar_layer_stride,
                                           uint32_t n_heads,
                                           uint32_t n_kv_heads, uint32_t head_dim,
                                           float scale, uint32_t excl_lo_end,
                                           uint32_t excl_hi_begin,
                                           uint32_t n_subblocks,
                                           uint32_t reduce_max,
                                           uint32_t accumulate,
                                           cudaStream_t stream) {
    if (n_blocks == 0 || n_layers == 0 || n_tokens == 0 || n_heads == 0 ||
        head_dim == 0) {
        return true;
    }
    const uint32_t ns = n_subblocks == 0 ? 1u : n_subblocks;
    // Sub-block logits live in dynamic shared memory in the original fast path;
    // cap the PRODUCT so it fits a conservative 48 KB budget. Larger requests
    // use an exact tiled two-dot path below instead of changing scorer semantics.
    constexpr uint32_t kMaxPages = 8192;
    const uint64_t total64 = static_cast<uint64_t>(n_blocks) * ns;
    if (total64 > UINT32_MAX) return false;
    const bool force_tiled = []() {
        const char *v = std::getenv("QW3_KVMEM_SOFTMAX_PAGES_FORCE_TILED");
        return v && *v && std::strcmp(v, "0") != 0 &&
               std::strcmp(v, "off") != 0 && std::strcmp(v, "false") != 0;
    }();
    const bool group_mode =
        group_begin != nullptr && group_end != nullptr && n_groups > 0;
    const uint32_t output_count = group_mode ? n_groups : n_blocks;
    // score[] is accumulated across the grid -> must start at zero. It stays
    // per-block on the ordinary path and per-group for semantic retrieval.
    if (!accumulate) {
        cudaMemsetAsync(score, 0,
                        static_cast<size_t>(output_count) * sizeof(float),
                        stream);
    }
    constexpr uint32_t threads = 128;
    if (total64 <= kMaxPages && !force_tiled) {
        const uint32_t grid = n_layers * n_tokens;
        const size_t shmem = static_cast<size_t>(total64) * sizeof(float);
        block_attn_score_softmax_pages_kernel<QueryT, KbarT>
            <<<grid, threads, shmem, stream>>>(
            score, q_multi, kbar_multi, group_begin, group_end, n_groups,
            n_layers, n_tokens, q_layer_stride,
            n_blocks, kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
            excl_lo_end, excl_hi_begin, ns, reduce_max);
        if (std::getenv("QW3_KVMEM_TRACE")) {
            std::fprintf(stderr,
                         "[bs-mean-softmax] scorer_path=fused pages=%llu blocks=%u\n",
                         static_cast<unsigned long long>(total64), n_blocks);
        }
        return cudaGetLastError() == cudaSuccess;
    }

    const uint32_t total = static_cast<uint32_t>(total64);
    const uint32_t n_tiles =
        (total + kSoftmaxPagesTile - 1) / kSoftmaxPagesTile;
    const uint64_t n_distributions64 =
        static_cast<uint64_t>(n_layers) * n_tokens * n_heads;
    if (n_distributions64 > UINT32_MAX) return false;
    const uint32_t n_distributions = static_cast<uint32_t>(n_distributions64);

    // Keep the original two-dot implementation as an explicit A/B baseline.
    // The production default materializes only a bounded distribution batch,
    // computes each dot once, then reuses the workspace.
    const bool use_two_dot = !group_mode && []() {
        const char *v =
            std::getenv("QW3_KVMEM_SOFTMAX_PAGES_SCALABLE");
        return v &&
               (std::strcmp(v, "two_dot") == 0 ||
                std::strcmp(v, "legacy") == 0);
    }();
    if (!use_two_dot) {
        uint64_t workspace_bytes = 64ull * 1024ull * 1024ull;
        if (const char *v =
                std::getenv("QW3_KVMEM_SOFTMAX_LOGITS_MIB")) {
            const unsigned long long mib = std::strtoull(v, nullptr, 10);
            if (mib > 0 && mib <= 4096) {
                workspace_bytes =
                    static_cast<uint64_t>(mib) * 1024ull * 1024ull;
            }
        }
        const uint64_t max_logits_floats =
            std::max<uint64_t>(total, workspace_bytes / sizeof(float));
        const uint32_t distributions_per_batch =
            static_cast<uint32_t>(std::max<uint64_t>(
                1, std::min<uint64_t>(
                       n_distributions,
                       max_logits_floats / total)));
        const uint64_t logits_floats =
            static_cast<uint64_t>(distributions_per_batch) * total;
        const uint64_t workspace_floats =
            logits_floats +
            2ull * distributions_per_batch;
        if (workspace_floats > SIZE_MAX / sizeof(float)) return false;
        float *workspace = nullptr;
        if (cudaMallocAsync(
                reinterpret_cast<void **>(&workspace),
                static_cast<size_t>(workspace_floats) * sizeof(float),
                stream) != cudaSuccess) {
            return false;
        }
        float *logits = workspace;
        float *row_max = logits + logits_floats;
        float *row_inv_sum =
            row_max + distributions_per_batch;
        const float distribution_weight =
            1.0f /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
        cudaError_t err = cudaSuccess;
        uint32_t batches = 0;
        for (uint32_t base = 0; base < n_distributions;) {
            const uint32_t count = std::min(
                distributions_per_batch,
                n_distributions - base);
            const uint64_t jobs =
                static_cast<uint64_t>(count) * n_tiles;
            if (jobs > 0x7fffffffu) {
                err = cudaErrorInvalidConfiguration;
                break;
            }
            block_attn_softmax_pages_logits_kernel<QueryT, KbarT><<<
                static_cast<uint32_t>(jobs),
                kSoftmaxPagesThreads, 0, stream>>>(
                logits, q_multi, kbar_multi, base, count,
                n_tiles, n_tokens, q_layer_stride, n_blocks,
                kbar_layer_stride, n_heads, n_kv_heads,
                head_dim, scale, excl_lo_end, excl_hi_begin, ns);
            err = cudaGetLastError();
            if (err != cudaSuccess) break;
            block_attn_softmax_pages_norm_kernel<<<
                count, kSoftmaxPagesThreads, 0, stream>>>(
                row_max, row_inv_sum, logits, count, total);
            err = cudaGetLastError();
            if (err != cudaSuccess) break;
            if (group_mode) {
                const dim3 group_grid(
                    n_groups,
                    (count + kSoftmaxPagesThreads - 1) /
                        kSoftmaxPagesThreads);
                block_attn_softmax_groups_accumulate_logits_kernel<<<
                    group_grid, kSoftmaxPagesThreads, 0, stream>>>(
                    score, logits, row_max, row_inv_sum, count, total,
                    group_begin, group_end, n_groups,
                    /*group_reduce_mass=*/reduce_max ? 0u : 1u,
                    distribution_weight);
            } else {
                const uint32_t score_grid =
                    (n_blocks + kSoftmaxPagesThreads - 1) /
                    kSoftmaxPagesThreads;
                block_attn_softmax_pages_accumulate_logits_kernel<<<
                    score_grid, kSoftmaxPagesThreads, 0, stream>>>(
                    score, logits, row_max, row_inv_sum, count,
                    n_blocks, ns, reduce_max, distribution_weight,
                    excl_lo_end, excl_hi_begin);
            }
            err = cudaGetLastError();
            if (err != cudaSuccess) break;
            base += count;
            ++batches;
        }
        const cudaError_t free_err =
            cudaFreeAsync(workspace, stream);
        if (std::getenv("QW3_KVMEM_TRACE")) {
            std::fprintf(
                stderr,
                "[bs-mean-softmax] scorer_path=tiled-one-dot "
                "pages=%u blocks=%u groups=%u distributions=%u tiles=%u "
                "distribution_batch=%u batches=%u workspace=%.2f MiB\n",
                total, n_blocks, group_mode ? n_groups : 0,
                n_distributions, n_tiles,
                distributions_per_batch, batches,
                static_cast<double>(
                    workspace_floats * sizeof(float)) /
                    (1024.0 * 1024.0));
        }
        return err == cudaSuccess && free_err == cudaSuccess;
    }

    const uint64_t n_jobs = n_distributions64 * n_tiles;
    if (n_jobs > 0x7fffffffu) return false;
    // [partial max, partial sum] per (distribution,tile), followed by the merged
    // [global max, global sum] per distribution. cudaMallocAsync keeps allocation
    // stream ordered and lets the CUDA pool reuse this ~few-MiB workspace.
    const uint64_t workspace_floats = 2 * n_jobs + 2 * n_distributions64;
    if (workspace_floats > SIZE_MAX / sizeof(float)) return false;
    float *workspace = nullptr;
    if (cudaMallocAsync(reinterpret_cast<void **>(&workspace),
                        static_cast<size_t>(workspace_floats) * sizeof(float),
                        stream) != cudaSuccess) {
        return false;
    }
    float *partial_max = workspace;
    float *partial_sum = partial_max + n_jobs;
    float *global_max = partial_sum + n_jobs;
    float *global_sum = global_max + n_distributions64;

        block_attn_softmax_pages_partial_lse_kernel<QueryT, KbarT><<<
        static_cast<uint32_t>(n_jobs), kSoftmaxPagesThreads, 0, stream>>>(
        partial_max, partial_sum, q_multi, kbar_multi, n_distributions,
        n_tiles, n_tokens, q_layer_stride, n_blocks, kbar_layer_stride,
        n_heads, n_kv_heads, head_dim, scale, excl_lo_end, excl_hi_begin, ns);
    cudaError_t err = cudaGetLastError();
    if (err == cudaSuccess) {
        block_attn_softmax_pages_merge_lse_kernel<<<
            n_distributions, kSoftmaxPagesThreads, 0, stream>>>(
            global_max, global_sum, partial_max, partial_sum,
            n_distributions, n_tiles);
        err = cudaGetLastError();
    }
    if (err == cudaSuccess) {
        const uint32_t score_grid =
            (n_blocks + kSoftmaxPagesThreads - 1) / kSoftmaxPagesThreads;
        block_attn_softmax_pages_recompute_kernel<QueryT, KbarT><<<
            score_grid, kSoftmaxPagesThreads, 0, stream>>>(
            score, q_multi, kbar_multi, global_max, global_sum, n_layers,
            n_tokens, q_layer_stride, n_blocks, kbar_layer_stride, n_heads,
            n_kv_heads, head_dim, scale, excl_lo_end, excl_hi_begin, ns,
            reduce_max);
        err = cudaGetLastError();
    }
    const cudaError_t free_err = cudaFreeAsync(workspace, stream);
    if (std::getenv("QW3_KVMEM_TRACE")) {
        std::fprintf(stderr,
                     "[bs-mean-softmax] scorer_path=tiled-two-dot pages=%u "
                     "blocks=%u distributions=%u tiles=%u workspace=%.2f MiB\n",
                     total, n_blocks, n_distributions, n_tiles,
                     static_cast<double>(workspace_floats * sizeof(float)) /
                         (1024.0 * 1024.0));
    }
    return err == cudaSuccess && free_err == cudaSuccess;
}

bool launch_block_attn_score_softmax_pages_typed(
        float *score, const void *q_multi, bool query_is_fp16,
        const void *kbar_multi, KbarDType kbar_dtype,
        uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t n_blocks,
        uint32_t kbar_layer_stride, uint32_t n_heads,
        uint32_t n_kv_heads, uint32_t head_dim, float scale,
        uint32_t excl_lo_end, uint32_t excl_hi_begin,
        uint32_t n_subblocks, uint32_t reduce_max, uint32_t accumulate,
        cudaStream_t stream) {
    if (query_is_fp16) {
        const auto *query = static_cast<const __half *>(q_multi);
        switch (kbar_dtype) {
            case KbarDType::F32:
                return launch_block_attn_score_softmax_pages_impl(
                    score, query, static_cast<const float *>(kbar_multi),
                    nullptr, nullptr, 0,
                    n_layers, n_tokens, q_layer_stride, n_blocks,
                    kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
                    excl_lo_end, excl_hi_begin, n_subblocks, reduce_max,
                    accumulate, stream);
            case KbarDType::F16:
                return launch_block_attn_score_softmax_pages_impl(
                    score, query, static_cast<const __half *>(kbar_multi),
                    nullptr, nullptr, 0,
                    n_layers, n_tokens, q_layer_stride, n_blocks,
                    kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
                    excl_lo_end, excl_hi_begin, n_subblocks, reduce_max,
                    accumulate, stream);
            case KbarDType::FP8:
                return launch_block_attn_score_softmax_pages_impl(
                    score, query,
                    static_cast<const __nv_fp8_e4m3 *>(kbar_multi),
                    nullptr, nullptr, 0,
                    n_layers, n_tokens, q_layer_stride, n_blocks,
                    kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
                    excl_lo_end, excl_hi_begin, n_subblocks, reduce_max,
                    accumulate, stream);
        }
        return false;
    }
    const auto *query = static_cast<const float *>(q_multi);
    switch (kbar_dtype) {
        case KbarDType::F32:
            return launch_block_attn_score_softmax_pages_impl(
                score, query, static_cast<const float *>(kbar_multi),
                nullptr, nullptr, 0,
                n_layers, n_tokens, q_layer_stride, n_blocks,
                kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
                excl_lo_end, excl_hi_begin, n_subblocks, reduce_max, accumulate,
                stream);
        case KbarDType::F16:
            return launch_block_attn_score_softmax_pages_impl(
                score, query, static_cast<const __half *>(kbar_multi),
                nullptr, nullptr, 0,
                n_layers, n_tokens, q_layer_stride, n_blocks,
                kbar_layer_stride, n_heads, n_kv_heads, head_dim, scale,
                excl_lo_end, excl_hi_begin, n_subblocks, reduce_max, accumulate,
                stream);
        case KbarDType::FP8:
            return launch_block_attn_score_softmax_pages_impl(
                score, query,
                static_cast<const __nv_fp8_e4m3 *>(kbar_multi),
                nullptr, nullptr, 0, n_layers,
                n_tokens, q_layer_stride, n_blocks, kbar_layer_stride,
                n_heads, n_kv_heads, head_dim, scale, excl_lo_end,
                excl_hi_begin, n_subblocks, reduce_max, accumulate, stream);
    }
    return false;
}

bool launch_block_attn_score_softmax_groups_typed(
        float *score, const void *q_multi, bool query_is_fp16,
        const void *kbar_multi, KbarDType kbar_dtype,
        const int32_t *group_begin, const int32_t *group_end,
        uint32_t n_groups, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t n_blocks,
        uint32_t kbar_layer_stride, uint32_t n_heads,
        uint32_t n_kv_heads, uint32_t head_dim, float scale,
        uint32_t excl_lo_end, uint32_t excl_hi_begin,
        uint32_t n_subblocks, uint32_t group_reduce_mass,
        uint32_t accumulate,
        cudaStream_t stream) {
    if (!group_begin || !group_end || n_groups == 0) return false;
#define QW3_LAUNCH_GROUPS(QUERY_TYPE, KBAR_TYPE)                         \
    return launch_block_attn_score_softmax_pages_impl(                  \
        score, static_cast<const QUERY_TYPE *>(q_multi),                 \
        static_cast<const KBAR_TYPE *>(kbar_multi),                      \
        group_begin, group_end, n_groups, n_layers, n_tokens,            \
        q_layer_stride, n_blocks, kbar_layer_stride, n_heads,            \
        n_kv_heads, head_dim, scale, excl_lo_end, excl_hi_begin,         \
        n_subblocks, /*reduce_max=*/group_reduce_mass ? 0u : 1u,           \
        accumulate, stream)
    if (query_is_fp16) {
        switch (kbar_dtype) {
            case KbarDType::F32:
                QW3_LAUNCH_GROUPS(__half, float);
            case KbarDType::F16:
                QW3_LAUNCH_GROUPS(__half, __half);
            case KbarDType::FP8:
                QW3_LAUNCH_GROUPS(__half, __nv_fp8_e4m3);
        }
    } else {
        switch (kbar_dtype) {
            case KbarDType::F32:
                QW3_LAUNCH_GROUPS(float, float);
            case KbarDType::F16:
                QW3_LAUNCH_GROUPS(float, __half);
            case KbarDType::FP8:
                QW3_LAUNCH_GROUPS(float, __nv_fp8_e4m3);
        }
    }
#undef QW3_LAUNCH_GROUPS
    return false;
}

template <typename QueryT, typename KbarT>
bool launch_block_attn_score_softmax_adaptive_impl(
        float *score, const QueryT *q_multi,
        const KbarT *packed_prototypes,
        const int32_t *layer_offsets, const int32_t *block_offsets,
        const int32_t *block_counts, const int32_t *prototype_blocks,
        uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t n_blocks,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, uint32_t excl_lo_end, uint32_t excl_hi_begin,
        uint32_t max_layer_prototypes, uint32_t accumulate,
        cudaStream_t stream) {
    if (n_layers == 0 || n_tokens == 0 || n_blocks == 0 ||
        n_heads == 0 || n_kv_heads == 0 || head_dim == 0 ||
        max_layer_prototypes == 0) {
        return n_blocks == 0 || n_tokens == 0;
    }
    const uint64_t distributions64 =
        static_cast<uint64_t>(n_layers) * n_tokens * n_heads;
    const uint32_t n_tiles =
        (max_layer_prototypes + kAdaptivePrototypeTile - 1) /
        kAdaptivePrototypeTile;
    if (distributions64 == 0 || distributions64 > UINT32_MAX ||
        n_tiles == 0) {
        return false;
    }
    const uint32_t distributions =
        static_cast<uint32_t>(distributions64);
    const char *scorer_mode =
        std::getenv("QW3_KVMEM_ADAPTIVE_SCORER");
    const bool use_two_dot =
        scorer_mode &&
        (std::strcmp(scorer_mode, "two_dot") == 0 ||
         std::strcmp(scorer_mode, "legacy") == 0);
    if (!use_two_dot) {
        uint64_t workspace_bytes = 64ull * 1024ull * 1024ull;
        const char *workspace_env =
            std::getenv("QW3_KVMEM_ADAPTIVE_LOGITS_MIB");
        if (!workspace_env || !*workspace_env) {
            workspace_env =
                std::getenv("QW3_KVMEM_SOFTMAX_LOGITS_MIB");
        }
        if (workspace_env && *workspace_env) {
            const unsigned long long mib =
                std::strtoull(workspace_env, nullptr, 10);
            if (mib > 0 && mib <= 4096) {
                workspace_bytes =
                    static_cast<uint64_t>(mib) *
                    1024ull * 1024ull;
            }
        }
        const uint64_t max_logits_floats =
            std::max<uint64_t>(
                max_layer_prototypes,
                workspace_bytes / sizeof(float));
        uint32_t distributions_per_batch =
            static_cast<uint32_t>(std::max<uint64_t>(
                1, std::min<uint64_t>(
                       distributions,
                       max_logits_floats /
                           max_layer_prototypes)));
        const uint32_t gqa_group = n_heads / n_kv_heads;
        const char *gqa_env =
            std::getenv("QW3_KVMEM_ADAPTIVE_GQA");
        const bool gqa_enabled =
            !(gqa_env && std::strcmp(gqa_env, "0") == 0);
        const bool fuse_gqa =
            gqa_enabled &&
            gqa_group >= 2u && gqa_group <= 4u &&
            n_heads % n_kv_heads == 0u &&
            distributions % gqa_group == 0u &&
            distributions_per_batch >= gqa_group;
        if (fuse_gqa) {
            distributions_per_batch =
                std::max<uint32_t>(
                    gqa_group,
                    (distributions_per_batch / gqa_group) *
                        gqa_group);
        }
        const uint64_t logits_floats =
            static_cast<uint64_t>(distributions_per_batch) *
            max_layer_prototypes;
        const uint64_t workspace_floats =
            logits_floats +
            2ull * distributions_per_batch;
        if (workspace_floats > SIZE_MAX / sizeof(float)) {
            return false;
        }
        float *workspace = nullptr;
        if (cudaMallocAsync(
                reinterpret_cast<void **>(&workspace),
                static_cast<size_t>(workspace_floats) * sizeof(float),
                stream) != cudaSuccess) {
            return false;
        }
        float *logits = workspace;
        float *row_max = logits + logits_floats;
        float *row_inv_sum =
            row_max + distributions_per_batch;
        const uint32_t logits_tiles =
            (max_layer_prototypes + kSoftmaxPagesTile - 1) /
            kSoftmaxPagesTile;
        const float distribution_weight =
            1.0f /
            (static_cast<float>(n_layers) *
             static_cast<float>(n_heads));
        cudaError_t err = cudaSuccess;
        if (!accumulate) {
            err = cudaMemsetAsync(
                score, 0, static_cast<size_t>(n_blocks) *
                              sizeof(float),
                stream);
        }
        uint32_t batches = 0;
        for (uint32_t base = 0;
             err == cudaSuccess && base < distributions;) {
            const uint32_t count = std::min(
                distributions_per_batch,
                distributions - base);
            const bool batch_fuse_gqa =
                fuse_gqa && base % gqa_group == 0u &&
                count % gqa_group == 0u;
            const uint64_t jobs =
                static_cast<uint64_t>(
                    batch_fuse_gqa
                        ? count / gqa_group
                        : count) *
                logits_tiles;
            if (jobs > 0x7fffffffu) {
                err = cudaErrorInvalidConfiguration;
                break;
            }
            if (batch_fuse_gqa && gqa_group == 2u) {
                block_attn_adaptive_logits_gqa_kernel<
                    QueryT, KbarT, 2u><<<
                    static_cast<uint32_t>(jobs),
                    kSoftmaxPagesThreads, 0, stream>>>(
                    logits, q_multi, packed_prototypes,
                    layer_offsets, prototype_blocks,
                    base, count, logits_tiles, n_tokens,
                    q_layer_stride, n_heads, n_kv_heads,
                    head_dim, scale, excl_lo_end, excl_hi_begin,
                    max_layer_prototypes);
            } else if (batch_fuse_gqa && gqa_group == 3u) {
                block_attn_adaptive_logits_gqa_kernel<
                    QueryT, KbarT, 3u><<<
                    static_cast<uint32_t>(jobs),
                    kSoftmaxPagesThreads, 0, stream>>>(
                    logits, q_multi, packed_prototypes,
                    layer_offsets, prototype_blocks,
                    base, count, logits_tiles, n_tokens,
                    q_layer_stride, n_heads, n_kv_heads,
                    head_dim, scale, excl_lo_end, excl_hi_begin,
                    max_layer_prototypes);
            } else if (batch_fuse_gqa && gqa_group == 4u) {
                block_attn_adaptive_logits_gqa_kernel<
                    QueryT, KbarT, 4u><<<
                    static_cast<uint32_t>(jobs),
                    kSoftmaxPagesThreads, 0, stream>>>(
                    logits, q_multi, packed_prototypes,
                    layer_offsets, prototype_blocks,
                    base, count, logits_tiles, n_tokens,
                    q_layer_stride, n_heads, n_kv_heads,
                    head_dim, scale, excl_lo_end, excl_hi_begin,
                    max_layer_prototypes);
            } else {
                block_attn_adaptive_logits_kernel<QueryT, KbarT><<<
                    static_cast<uint32_t>(jobs),
                    kSoftmaxPagesThreads, 0, stream>>>(
                    logits, q_multi, packed_prototypes,
                    layer_offsets, prototype_blocks,
                    base, count, logits_tiles, n_tokens,
                    q_layer_stride, n_heads, n_kv_heads,
                    head_dim, scale, excl_lo_end, excl_hi_begin,
                    max_layer_prototypes);
            }
            err = cudaGetLastError();
            if (err != cudaSuccess) break;
            block_attn_softmax_pages_norm_kernel<<<
                count, kSoftmaxPagesThreads, 0, stream>>>(
                row_max, row_inv_sum, logits, count,
                max_layer_prototypes);
            err = cudaGetLastError();
            if (err != cudaSuccess) break;
            const uint32_t score_grid =
                (n_blocks + kSoftmaxPagesThreads - 1) /
                kSoftmaxPagesThreads;
            block_attn_adaptive_accumulate_logits_kernel<<<
                score_grid, kSoftmaxPagesThreads, 0, stream>>>(
                score, logits, row_max, row_inv_sum,
                layer_offsets, block_offsets, block_counts,
                base, count, n_tokens, n_blocks, n_heads,
                max_layer_prototypes, distribution_weight,
                excl_lo_end, excl_hi_begin);
            err = cudaGetLastError();
            base += count;
            ++batches;
        }
        const cudaError_t free_err =
            cudaFreeAsync(workspace, stream);
        if (std::getenv("QW3_KVMEM_TRACE")) {
            std::fprintf(
                stderr,
                "[bs-adaptive-softmax] "
                "scorer_path=packed-tiled-one-dot "
                "prototypes_max_layer=%u blocks=%u "
                "distributions=%u tiles=%u "
                "distribution_batch=%u batches=%u "
                "gqa_group=%u gqa_fused=%u workspace=%.2f MiB\n",
                max_layer_prototypes, n_blocks,
                distributions, logits_tiles,
                distributions_per_batch, batches,
                gqa_group, fuse_gqa ? 1u : 0u,
                static_cast<double>(
                    workspace_floats * sizeof(float)) /
                    (1024.0 * 1024.0));
        }
        return err == cudaSuccess &&
               free_err == cudaSuccess;
    }
    const uint64_t jobs =
        distributions64 * static_cast<uint64_t>(n_tiles);
    if (jobs > 0x7fffffffu) return false;
    const uint64_t workspace_floats =
        2u * jobs + 2u * distributions64;
    if (workspace_floats > SIZE_MAX / sizeof(float)) return false;
    float *workspace = nullptr;
    if (cudaMallocAsync(
            reinterpret_cast<void **>(&workspace),
            static_cast<size_t>(workspace_floats) * sizeof(float),
            stream) != cudaSuccess) {
        return false;
    }
    float *partial_max = workspace;
    float *partial_sum = partial_max + jobs;
    float *global_max = partial_sum + jobs;
    float *global_sum = global_max + distributions64;
    block_attn_adaptive_partial_lse_kernel<QueryT, KbarT><<<
        static_cast<uint32_t>(jobs), kSoftmaxPagesThreads, 0, stream>>>(
        partial_max, partial_sum, q_multi, packed_prototypes,
        layer_offsets, prototype_blocks, distributions, n_tiles,
        n_tokens, q_layer_stride, n_heads, n_kv_heads, head_dim,
        scale, excl_lo_end, excl_hi_begin);
    cudaError_t err = cudaGetLastError();
    if (err == cudaSuccess) {
        block_attn_softmax_pages_merge_lse_kernel<<<
            distributions, kSoftmaxPagesThreads, 0, stream>>>(
            global_max, global_sum, partial_max, partial_sum,
            distributions, n_tiles);
        err = cudaGetLastError();
    }
    if (err == cudaSuccess) {
        block_attn_adaptive_score_kernel<QueryT, KbarT><<<
            n_blocks, kSoftmaxPagesThreads, 0, stream>>>(
            score, q_multi, packed_prototypes,
            block_offsets, block_counts, global_max, global_sum,
            distributions, n_layers, n_tokens, q_layer_stride,
            n_blocks, n_heads, n_kv_heads, head_dim, scale,
            excl_lo_end, excl_hi_begin, accumulate);
        err = cudaGetLastError();
    }
    const cudaError_t free_err = cudaFreeAsync(workspace, stream);
    if (std::getenv("QW3_KVMEM_TRACE")) {
        std::fprintf(
            stderr,
            "[bs-adaptive-softmax] scorer_path=packed-tiled-two-dot "
            "prototypes_max_layer=%u blocks=%u distributions=%u "
            "tiles=%u workspace=%.2f MiB\n",
            max_layer_prototypes, n_blocks, distributions, n_tiles,
            static_cast<double>(workspace_floats * sizeof(float)) /
                (1024.0 * 1024.0));
    }
    return err == cudaSuccess && free_err == cudaSuccess;
}

bool launch_block_attn_score_softmax_adaptive_typed(
        float *score, const void *q_multi, bool query_is_fp16,
        const void *packed_prototypes, KbarDType prototype_dtype,
        const int32_t *layer_offsets, const int32_t *block_offsets,
        const int32_t *block_counts, const int32_t *prototype_blocks,
        uint32_t n_layers, uint32_t n_tokens, uint32_t q_layer_stride,
        uint32_t n_blocks, uint32_t n_heads, uint32_t n_kv_heads,
        uint32_t head_dim, float scale, uint32_t excl_lo_end,
        uint32_t excl_hi_begin, uint32_t max_layer_prototypes,
        uint32_t accumulate, cudaStream_t stream) {
#define QW3_ADAPTIVE_SCORE(QT, KT)                                      \
    return launch_block_attn_score_softmax_adaptive_impl(               \
        score, static_cast<const QT *>(q_multi),                        \
        static_cast<const KT *>(packed_prototypes), layer_offsets,      \
        block_offsets, block_counts, prototype_blocks, n_layers,        \
        n_tokens, q_layer_stride, n_blocks, n_heads, n_kv_heads,        \
        head_dim, scale, excl_lo_end, excl_hi_begin,                    \
        max_layer_prototypes, accumulate, stream)
    if (query_is_fp16) {
        switch (prototype_dtype) {
            case KbarDType::F32: QW3_ADAPTIVE_SCORE(__half, float);
            case KbarDType::F16: QW3_ADAPTIVE_SCORE(__half, __half);
            case KbarDType::FP8:
                QW3_ADAPTIVE_SCORE(__half, __nv_fp8_e4m3);
        }
    } else {
        switch (prototype_dtype) {
            case KbarDType::F32: QW3_ADAPTIVE_SCORE(float, float);
            case KbarDType::F16: QW3_ADAPTIVE_SCORE(float, __half);
            case KbarDType::FP8:
                QW3_ADAPTIVE_SCORE(float, __nv_fp8_e4m3);
        }
    }
#undef QW3_ADAPTIVE_SCORE
    return false;
}

template <typename QueryT, typename KbarT>
bool launch_block_attn_score_adaptive_layer_impl(
        float *score, const QueryT *q_multi,
        const KbarT *prototype_layer,
        const int32_t *block_offsets,
        const int32_t *block_counts,
        uint32_t layer, uint32_t n_layers, uint32_t n_tokens,
        uint32_t q_layer_stride, uint32_t prototype_count,
        uint32_t block_count, uint32_t global_block_base,
        uint32_t n_heads, uint32_t n_kv_heads, uint32_t head_dim,
        float scale, cudaStream_t stream) {
    if (layer >= n_layers || n_tokens == 0 ||
        prototype_count == 0 || block_count == 0 ||
        n_heads == 0 || n_kv_heads == 0 || head_dim == 0 ||
        n_heads % n_kv_heads != 0) {
        return prototype_count == 0 || block_count == 0;
    }
    const uint64_t distributions64 =
        static_cast<uint64_t>(n_tokens) * n_heads;
    if (distributions64 == 0 || distributions64 > UINT32_MAX) {
        return false;
    }
    const uint32_t distributions =
        static_cast<uint32_t>(distributions64);
    uint64_t workspace_bytes = 64ull * 1024ull * 1024ull;
    const char *workspace_env =
        std::getenv("QW3_KVMEM_ADAPTIVE_LOGITS_MIB");
    if (!workspace_env || !*workspace_env) {
        workspace_env =
            std::getenv("QW3_KVMEM_SOFTMAX_LOGITS_MIB");
    }
    if (workspace_env && *workspace_env) {
        const unsigned long long mib =
            std::strtoull(workspace_env, nullptr, 10);
        if (mib > 0 && mib <= 4096) {
            workspace_bytes =
                static_cast<uint64_t>(mib) * 1024ull * 1024ull;
        }
    }
    const uint64_t max_logits_floats =
        std::max<uint64_t>(
            prototype_count, workspace_bytes / sizeof(float));
    uint32_t distributions_per_batch =
        static_cast<uint32_t>(std::max<uint64_t>(
            1, std::min<uint64_t>(
                   distributions,
                   max_logits_floats / prototype_count)));
    const uint32_t gqa_group = n_heads / n_kv_heads;
    const char *gqa_env =
        std::getenv("QW3_KVMEM_ADAPTIVE_GQA");
    const bool gqa_enabled =
        !(gqa_env && std::strcmp(gqa_env, "0") == 0);
    const bool fuse_gqa =
        gqa_enabled && gqa_group >= 2u && gqa_group <= 4u &&
        distributions_per_batch >= gqa_group;
    if (fuse_gqa) {
        distributions_per_batch =
            std::max<uint32_t>(
                gqa_group,
                (distributions_per_batch / gqa_group) *
                    gqa_group);
    }
    const uint64_t logits_floats =
        static_cast<uint64_t>(distributions_per_batch) *
        prototype_count;
    const uint64_t workspace_floats =
        logits_floats + 2ull * distributions_per_batch;
    if (workspace_floats > SIZE_MAX / sizeof(float)) return false;
    float *workspace = nullptr;
    if (cudaMallocAsync(
            reinterpret_cast<void **>(&workspace),
            static_cast<size_t>(workspace_floats) * sizeof(float),
            stream) != cudaSuccess) {
        return false;
    }
    float *logits = workspace;
    float *row_max = logits + logits_floats;
    float *row_inv_sum = row_max + distributions_per_batch;
    const uint32_t logits_tiles =
        (prototype_count + kSoftmaxPagesTile - 1) /
        kSoftmaxPagesTile;
    const float distribution_weight =
        1.0f /
        (static_cast<float>(n_layers) *
         static_cast<float>(n_heads));
    cudaError_t err = cudaSuccess;
    for (uint32_t base = 0;
         err == cudaSuccess && base < distributions;) {
        const uint32_t count = std::min(
            distributions_per_batch, distributions - base);
        const bool batch_fuse_gqa =
            fuse_gqa && base % gqa_group == 0u &&
            count % gqa_group == 0u;
        const uint64_t jobs =
            static_cast<uint64_t>(
                batch_fuse_gqa ? count / gqa_group : count) *
            logits_tiles;
        if (jobs > 0x7fffffffu) {
            err = cudaErrorInvalidConfiguration;
            break;
        }
#define QW3_ADAPTIVE_LAYER_LOGITS_GQA(G)                               \
        block_attn_adaptive_layer_logits_gqa_kernel<                   \
            QueryT, KbarT, G><<<                                       \
            static_cast<uint32_t>(jobs),                              \
            kSoftmaxPagesThreads, 0, stream>>>(                        \
            logits, q_multi, prototype_layer, layer, base, count,     \
            logits_tiles, n_tokens, q_layer_stride, prototype_count,  \
            n_heads, n_kv_heads, head_dim, scale)
        if (batch_fuse_gqa && gqa_group == 2u) {
            QW3_ADAPTIVE_LAYER_LOGITS_GQA(2u);
        } else if (batch_fuse_gqa && gqa_group == 3u) {
            QW3_ADAPTIVE_LAYER_LOGITS_GQA(3u);
        } else if (batch_fuse_gqa && gqa_group == 4u) {
            QW3_ADAPTIVE_LAYER_LOGITS_GQA(4u);
        } else {
            block_attn_adaptive_layer_logits_kernel<
                QueryT, KbarT><<<
                static_cast<uint32_t>(jobs),
                kSoftmaxPagesThreads, 0, stream>>>(
                logits, q_multi, prototype_layer, layer,
                base, count, logits_tiles, n_tokens,
                q_layer_stride, prototype_count, n_heads,
                n_kv_heads, head_dim, scale);
        }
#undef QW3_ADAPTIVE_LAYER_LOGITS_GQA
        err = cudaGetLastError();
        if (err != cudaSuccess) break;
        block_attn_softmax_pages_norm_kernel<<<
            count, kSoftmaxPagesThreads, 0, stream>>>(
            row_max, row_inv_sum, logits, count,
            prototype_count);
        err = cudaGetLastError();
        if (err != cudaSuccess) break;
        const uint32_t score_grid =
            (block_count + kSoftmaxPagesThreads - 1) /
            kSoftmaxPagesThreads;
        block_attn_adaptive_layer_accumulate_logits_kernel<<<
            score_grid, kSoftmaxPagesThreads, 0, stream>>>(
            score, logits, row_max, row_inv_sum,
            block_offsets, block_counts, count, block_count,
            global_block_base, prototype_count,
            distribution_weight);
        err = cudaGetLastError();
        base += count;
    }
    const cudaError_t free_err =
        cudaFreeAsync(workspace, stream);
    return err == cudaSuccess && free_err == cudaSuccess;
}

bool launch_block_attn_score_adaptive_layer_typed(
