template <typename KbarT>
bool launch_block_kmean_content_batch_merge_impl(
        const float *k_batch, KbarT *kbar, uint64_t kbar_block_base,
        uint32_t n_blocks_chunk, uint32_t k_stride, uint32_t batch,
        uint32_t blk_tokens, uint32_t first_block_token_offset,
        uint32_t n_kv_heads, uint32_t head_dim, uint32_t rope_dim,
        int32_t rope_base, float theta, uint32_t n_subblocks,
        cudaStream_t stream) {
    if (n_blocks_chunk == 0 || n_kv_heads == 0 || head_dim == 0 ||
        batch == 0) {
        return true;
    }
    if (first_block_token_offset >= blk_tokens) return false;
    const uint32_t ns = n_subblocks == 0 ? 1u : n_subblocks;
    dim3 grid(n_blocks_chunk * ns, n_kv_heads);
    block_kmean_content_batch_merge_kernel<KbarT>
        <<<grid, head_dim, 0, stream>>>(
        k_batch, kbar, kbar_block_base, k_stride, batch, blk_tokens,
        first_block_token_offset, head_dim, rope_dim, rope_base, theta, ns);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_block_kmean_content_batch_merge_typed(
        const float *k_batch, void *kbar, KbarDType kbar_dtype,
        uint64_t kbar_block_base, uint32_t n_blocks_chunk,
        uint32_t k_stride, uint32_t batch, uint32_t blk_tokens,
        uint32_t first_block_token_offset, uint32_t n_kv_heads,
        uint32_t head_dim, uint32_t rope_dim, int32_t rope_base,
        float theta, uint32_t n_subblocks, cudaStream_t stream) {
    switch (kbar_dtype) {
        case KbarDType::F32:
            return launch_block_kmean_content_batch_merge_impl(
                k_batch, static_cast<float *>(kbar), kbar_block_base,
                n_blocks_chunk, k_stride, batch, blk_tokens,
                first_block_token_offset, n_kv_heads, head_dim, rope_dim,
                rope_base, theta, n_subblocks, stream);
        case KbarDType::F16:
            return launch_block_kmean_content_batch_merge_impl(
                k_batch, static_cast<__half *>(kbar), kbar_block_base,
                n_blocks_chunk, k_stride, batch, blk_tokens,
                first_block_token_offset, n_kv_heads, head_dim, rope_dim,
                rope_base, theta, n_subblocks, stream);
        case KbarDType::FP8:
            return launch_block_kmean_content_batch_merge_impl(
                k_batch, static_cast<__nv_fp8_e4m3 *>(kbar),
                kbar_block_base, n_blocks_chunk, k_stride, batch, blk_tokens,
                first_block_token_offset, n_kv_heads, head_dim, rope_dim,
                rope_base, theta, n_subblocks, stream);
    }
    return false;
}

bool launch_block_kmean_content_batch_merge(
        const float *k_batch, float *kbar, uint64_t kbar_block_base,
        uint32_t n_blocks_chunk, uint32_t k_stride, uint32_t batch,
        uint32_t blk_tokens, uint32_t first_block_token_offset,
        uint32_t n_kv_heads, uint32_t head_dim, uint32_t rope_dim,
        int32_t rope_base, float theta, uint32_t n_subblocks,
        cudaStream_t stream) {
    return launch_block_kmean_content_batch_merge_typed(
        k_batch, kbar, KbarDType::F32, kbar_block_base, n_blocks_chunk,
        k_stride, batch, blk_tokens, first_block_token_offset, n_kv_heads,
        head_dim, rope_dim, rope_base, theta, n_subblocks, stream);
}

bool launch_derope_store_content_batch(const float *k_batch, float *kraw,
                                       uint64_t out_base_elem, uint32_t k_stride,
                                       uint32_t batch, uint32_t n_kv_heads,
                                       uint32_t head_dim, uint32_t rope_dim,
                                       int32_t rope_base, float theta,
                                       cudaStream_t stream) {
    if (batch == 0 || n_kv_heads == 0 || head_dim == 0) return true;
    dim3 grid(batch, n_kv_heads);
    derope_store_content_batch_kernel<<<grid, head_dim, 0, stream>>>(
        k_batch, kraw, out_base_elem, k_stride, batch, n_kv_heads, head_dim,
        rope_dim, rope_base, theta);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_block_attn_score_exactmass(float *score, const float *q_layer,
                                       const float *kraw, uint32_t M,
                                       uint32_t total_tokens, uint32_t n_blocks,
                                       uint32_t block_tokens, uint32_t n_heads,
                                       uint32_t n_kv_heads, uint32_t head_dim,
                                       float scale, float head_w,
                                       uint32_t group_mean,
                                       cudaStream_t stream) {
    if (n_blocks == 0 || M == 0 || n_heads == 0 || head_dim == 0 ||
        total_tokens == 0 || block_tokens == 0) {
        return true;
    }
    if (group_mean && n_kv_heads == 0) return false;
    // q_vec[head_dim] + s_acc[n_blocks] in dynamic shmem; cap to 48 KB so the
    // caller falls back to the mean/MaxSim scorer if n_blocks is too large.
    const size_t shmem =
        (static_cast<size_t>(head_dim) + n_blocks) * sizeof(float);
    if (shmem > 48u * 1024u) return false;
    constexpr uint32_t threads = 256;  // 8 warps
    const uint32_t grid = M * (group_mean ? n_kv_heads : n_heads);
    block_attn_score_exactmass_kernel<<<grid, threads, shmem, stream>>>(
        score, q_layer, kraw, M, total_tokens, n_blocks, block_tokens, n_heads,
        n_kv_heads, head_dim, scale, head_w, group_mean);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_derope_query(float *q_content, const float *q, uint32_t q_stride,
                         uint32_t n_heads, uint32_t head_dim, uint32_t rope_dim,
                         int32_t query_pos, float theta, cudaStream_t stream) {
    if (n_heads == 0 || head_dim == 0) return true;
    derope_query_kernel<<<n_heads, head_dim, 0, stream>>>(
        q_content, q, q_stride, head_dim, rope_dim, query_pos, theta);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_derope_query_multi(float *q_multi, const float *q,
                               uint32_t q_token_stride, uint32_t q_head_stride,
                               uint32_t cnt, uint32_t n_heads, uint32_t head_dim,
                               uint32_t rope_dim, int32_t start_pos, float theta,
                               cudaStream_t stream) {
    if (cnt == 0 || n_heads == 0 || head_dim == 0) return true;
    dim3 grid(n_heads, cnt);
    derope_query_multi_kernel<<<grid, head_dim, 0, stream>>>(
        q_multi, q, q_token_stride, q_head_stride, n_heads, head_dim, rope_dim,
        start_pos, theta, /*output_fp16=*/false);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_derope_query_multi_f16(void *q_multi, const float *q,
                                   uint32_t q_token_stride,
                                   uint32_t q_head_stride, uint32_t cnt,
                                   uint32_t n_heads, uint32_t head_dim,
                                   uint32_t rope_dim, int32_t start_pos,
                                   float theta, cudaStream_t stream) {
    if (cnt == 0 || n_heads == 0 || head_dim == 0) return true;
    dim3 grid(n_heads, cnt);
    derope_query_multi_kernel<<<grid, head_dim, 0, stream>>>(
        q_multi, q, q_token_stride, q_head_stride, n_heads, head_dim, rope_dim,
        start_pos, theta, /*output_fp16=*/true);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_deltanet_block_score(float *r_out, const float *dn_snap,
                                 const float *decaysum, const float *decay_d,
                                 const float *q_layer, uint32_t n_blocks,
                                 uint32_t num_k_heads, uint32_t num_v_heads,
                                 uint32_t head_v_dim, uint32_t head_k_dim,
                                 uint32_t M, uint32_t topk_q,
                                 cudaStream_t stream) {
    if (n_blocks == 0 || num_v_heads == 0 || head_k_dim == 0 || M == 0) return true;
    const dim3 grid(n_blocks, num_v_heads);
    const size_t shmem =
        (static_cast<size_t>(M) * head_k_dim + M) * sizeof(float);
    deltanet_block_score_kernel<<<grid, head_k_dim, shmem, stream>>>(
        r_out, dn_snap, decaysum, decay_d, q_layer, n_blocks, num_k_heads,
        num_v_heads, head_v_dim, head_k_dim, M, topk_q);
    return cudaGetLastError() == cudaSuccess;
}

bool launch_deltanet_pack_query(float *q_dst, const float *cout,
                                uint32_t conv_stride, uint32_t r0,
                                uint32_t dst_row_base, uint32_t cnt,
                                uint32_t num_k_heads, uint32_t head_k_dim,
                                cudaStream_t stream) {
    if (cnt == 0 || num_k_heads == 0 || head_k_dim == 0) return true;
    const dim3 grid(cnt, num_k_heads);
    deltanet_pack_query_kernel<<<grid, head_k_dim, 0, stream>>>(
        q_dst, cout, conv_stride, r0, dst_row_base, cnt, num_k_heads, head_k_dim);
    return cudaGetLastError() == cudaSuccess;
}
} // namespace ported

bool cuda_device_backend_available() {
    int count = 0;
    return cudaGetDeviceCount(&count) == cudaSuccess && count > 0;
}

std::unique_ptr<DeviceBackend> make_cuda_device_backend(LinearBackend linear_backend) {
    return std::make_unique<CudaDeviceBackend>(linear_backend);
}

